    sources["access.lua"] = function()
-- One session-bound source of administrator rights. Never persisted to disk.
local Access = {}
Access.__index = Access

local function trim(text) return (tostring(text or ''):match('^%s*(.-)%s*$')) end
local function fold(text)
    text = text:lower()
    local upper, lower = 'АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ', 'абвгдеёжзийклмнопрстуфхцчшщъыьэюя'
    for i = 1, #upper, 2 do text = text:gsub(upper:sub(i, i + 1), lower:sub(i, i + 1)) end
    return text:gsub('ё', 'е')
end
local function call(fn, ...)
    if type(fn) ~= 'function' then return nil end
    local ok, a, b = pcall(fn, ...)
    if ok then return a, b end
end
local roles = {
    ['администратор первого уровня'] = 1, ['администратор второго уровня'] = 2,
    ['администратор третьего уровня'] = 3, ['администратор четвертого уровня'] = 4,
    ['администратор пятого уровня'] = 5, ['администратор уровня s2'] = 4,
    ['администратор уровня s3'] = 4,
    ['главный администратор'] = 5, ['игрок'] = 0, ['обычный игрок'] = 0,
}

function Access.new(api)
    api = api or {}
    local convert = api.toUTF8
    if not convert and api.require then
        local encoding = call(api.require, 'encoding')
        if encoding and encoding.UTF8 then convert = function(text) return tostring(encoding.UTF8(text)) end end
    end
    local self = setmetatable({api = api, toUTF8 = convert or tostring,
        current = nil, serial = 0, reason = 'Уровень администратора ещё не подтверждён сервером.',
        initialized = false, refreshAttempted = false}, Access)
    self:sync()
    return self
end

function Access:reset(reason)
    self.current, self.role, self.pendingUntil = nil, nil, nil
    self.reason = reason or 'Уровень администратора ещё не подтверждён сервером.'
    self.serial = self.serial + 1
    self.refreshAttempted = false
    self.probeUntil=nil;self.probeHeader=false;self.probeTried=false;self.nextProbe=nil;self.probeHeaderUntil=nil;self.probeChief=false
end

function Access:sync()
    local api = self.api
    local available = call(api.isSampAvailable)
    local state = call(api.sampGetGamestate)
    local connected = available ~= false and (state == nil or state == 3)
    local address, port = call(api.sampGetCurrentServerAddress)
    local hasId, id = call(api.sampGetPlayerIdByCharHandle or api.sampGetPlayerIdByChar, api.PLAYER_PED)
    local nickname = hasId and call(api.sampGetPlayerNickname, id) or nil
    local identity = connected and table.concat({tostring(address or ''), tostring(port or ''),
        hasId and tostring(id) or '', tostring(nickname or '')}, '\0') or nil
    if self.initialized and (self.connected ~= connected or self.identity ~= identity) then
        self:reset(connected and 'Сессия или аккаунт изменились. Ожидается подтверждение уровня.' or 'Нет подключения к серверу.')
    end
    self.initialized, self.connected, self.identity = true, connected, identity
    local clock = api.getGameTimer and (call(api.getGameTimer) or 0) / 1000 or os.clock()
    -- User-requested local exception: an anonymous chief row is sufficient
    -- only when no own entry arrived during the list response window.
    if self.current == nil and self.probeChief and self.probeHeaderUntil
        and clock * 1000 > self.probeHeaderUntil then
        self:reset()
        self.current, self.role, self.reason = 5, 'server-chief-fallback', nil
    end
    if self.pendingUntil and clock >= self.pendingUntil then
        self.pendingUntil = nil
        self.reason = 'Сервер не подтвердил уровень администратора. Повторите вход в аккаунт.'
    end
end

function Access:level() self:sync(); return self.current end
function Access:revision() self:sync(); return self.serial end
function Access:can(minimum)
    local level = self:level()
    minimum = tonumber(minimum) or 1
    return level ~= nil and level >= minimum
end
function Access:require(minimum, notify)
    if self:can(minimum) then return true end
    local reason = self.current == nil and self.reason or ('Требуется %d-й уровень администратора.'):format(tonumber(minimum) or 1)
    if type(notify) == 'function' then notify(reason) end
    return false, reason
end

-- Only a verified server-specific protocol may be supplied by the host. No
-- guessed /a messages or per-module probes are sent to the server.
function Access:requestRefresh(explicit)
    self:sync()
    if not self.connected then return false, 'Нет подключения к серверу.' end
    if not explicit and self.current ~= nil then return true end
    if type(self.api.requestAdminLevel) ~= 'function' then
        return false, 'Сервер сообщает уровень при входе в аккаунт. Повторите вход для проверки прав.'
    end
    local clock = self.api.getGameTimer and (call(self.api.getGameTimer) or 0) / 1000 or os.clock()
    if self.pendingUntil or (not explicit and self.refreshAttempted) or (self.lastRefresh and clock - self.lastRefresh < 10) then
        return false, 'Подтверждение уровня уже запрошено.'
    end
    self:reset('Ожидается подтверждение уровня администратора.')
    self.refreshAttempted, self.lastRefresh, self.pendingUntil = true, clock, clock + 10
    local ok, err = pcall(self.api.requestAdminLevel)
    if not ok then self.pendingUntil = nil; return false, tostring(err) end
    return true
end

-- A fresh server reply also works when the script reloads inside a logged-in session.
function Access:probeCurrentSession()
    self:sync()
    local now=call(self.api.getGameTimer) or 0
    if self.current~=nil or (self.nextProbe and now<self.nextProbe) or not self.connected
        or call(self.api.sampIsLocalPlayerSpawned)~=true then return end
    self.probeTried=true;self.probeHeader=false;self.probeChief=false
    self.probeUntil=now+10000;self.nextProbe=now+30000
    call(self.api.sampSendChat,'/admins')
end

function Access:observe(event, ...)
    self:sync()
    if event == 'onInitGame' or event == 'onConnectionLost' or event == 'onConnectionClosed'
        or event == 'onConnectionRejected' or event == 'onConnectionAttemptFailed' then
        self:reset('Соединение изменилось. Ожидается подтверждение уровня администратора.')
        return true
    end
    if event == 'onShowDialog' then
        local id, _, title = ...
        local ok, decoded = pcall(self.toUTF8, title or '')
        if id == 1 and ok and fold(tostring(decoded)):find('авторизация', 1, true) then
            self:reset('Открыт вход в аккаунт. Права предыдущей сессии сброшены.')
            return true
        end
        return false
    end
    if event ~= 'onServerMessage' or not self.connected then return false end
    local color, raw = ...
    if self.probeTried and self.current==nil then
        local ok,value=pcall(self.toUTF8,raw or '')
        if ok then
            local text=trim(tostring(value):gsub('{%x+}',''))
            if fold(text):match('^админы онлайн:?$') then self.probeHeader=true;self.probeHeaderUntil=(call(self.api.getGameTimer) or 0)+10000;return false end
            if self.probeHeader and (call(self.api.getGameTimer) or 0)<=self.probeHeaderUntil then
                local chief=fold(text):gsub('%s+', ' ')
                if chief=='гл. администратор' or chief=='гл. администратор (невидимка)' then
                    self.probeChief=true
                    return false
                end
                local nick,id,level=text:match('^([%w_]+)%[(%d+)%]%s*%((S?%d+)%s+lvl?%)')
                local found,me=call(self.api.sampGetPlayerIdByCharHandle,self.api.PLAYER_PED)
                local own=found and call(self.api.sampGetPlayerNickname,me)
                local rank=({S2=4,S3=4})[level] or tonumber(level)
                if nick and nick==own and tonumber(id)==me and rank and rank>=1 and rank<=5 then
                    self:reset();self.current=rank;self.role='server-admin-list';self.reason=nil
                    return true
                end
            end
        end
    end
    -- Advance-RP sends this announcement in 0xFFFF00FF (signed -65281).
    -- Chat/player/admin quoted messages must never grant local permissions.
    if tonumber(color) ~= -65281 and tonumber(color) ~= 4294902015 then return false end
    local ok, decoded = pcall(self.toUTF8, raw or '')
    if not ok then return false end
    local line = fold(trim(tostring(decoded):gsub('{%x+}', ''):gsub('%s+', ' ')))
    local role = line:match('^вы вошли как (.-)[.!]?$')
    if role then
        self:reset()
        self.role, self.current = role, roles[role]
        self.reason = self.current == nil and 'Сервер сообщил неизвестную роль. Ограниченные действия недоступны.'
            or (self.current == 0 and 'В этой сессии нет прав администратора.' or nil)
        return true
    end
    if line:match('^вы больше не являетесь администратором[.!]?$')
        or line:match('^вы сняты с должности администратора[.!]?$') then
        self:reset('Права администратора сняты сервером.')
        self.current = 0
        return true
    end
    return false
end

return Access

    end
