local Auth={};Auth.__index=Auth
local function protect(bytes,decode)
    local ffi=require('ffi')
    if not pcall(ffi.typeof,'XT_AUTH_BLOB') then ffi.cdef[[
        typedef struct { unsigned long size; unsigned char *data; } XT_AUTH_BLOB;
        int __stdcall CryptProtectData(XT_AUTH_BLOB*, const wchar_t*, XT_AUTH_BLOB*, void*, void*, unsigned long, XT_AUTH_BLOB*);
        int __stdcall CryptUnprotectData(XT_AUTH_BLOB*, wchar_t**, XT_AUTH_BLOB*, void*, void*, unsigned long, XT_AUTH_BLOB*);
        void* __stdcall LocalFree(void*);
    ]] end
    local crypt=ffi.load('crypt32');local kernel=ffi.load('kernel32')
    local buffer=ffi.new('unsigned char[?]',#bytes);ffi.copy(buffer,bytes,#bytes)
    local input=ffi.new('XT_AUTH_BLOB',{#bytes,buffer});local output=ffi.new('XT_AUTH_BLOB')
    local fn=decode and crypt.CryptUnprotectData or crypt.CryptProtectData
    if fn(input,nil,nil,nil,nil,1,output)==0 then return nil end
    local result=ffi.string(output.data,output.size);kernel.LocalFree(output.data)
    return result
end
function Auth.new(rt)
    local path=rt.storage:path('settings','authenticator.ini')
    return setmetatable({rt=rt,path=path,secretPath=rt.storage:path('data','authenticator.dpapi'),
        data=rt.storage:loadIni({main={enabled=false,nickname=''}},path),status=''},Auth)
end
function Auth:nickname()
    local a=self.rt.api
    local found,id=a.sampGetPlayerIdByCharHandle(a.PLAYER_PED)
    return found and a.sampGetPlayerNickname(id) or nil
end
function Auth:save(secret)
    secret=self.rt:service('totp.lua').normalize(secret)
    if not secret then self.status='Нужен секретный ключ Base32, не шестизначный код.';return false end
    local nick=self:nickname()
    if not nick or nick=='' then self.status='Сначала войдите своим персонажем.';return false end
    local ok,encrypted=pcall(protect,secret,false)
    if not ok or not encrypted then self.status='Windows не смогла защитить ключ.';return false end
    if not self.rt.storage:write(self.secretPath,encrypted) then self.status='Не удалось сохранить ключ.';return false end
    self.data.main.nickname=nick
    self.rt.storage:saveIni(self.data,self.path)
    self.status='Ключ сохранён для текущего персонажа.';return true
end
function Auth:dialog(id,style,title,body)
    local rt=self.rt
    if id==1 and title=='Авторизация' and not body:find('Неверный',1,true) then self.attempted=false end
    if id~=88 or style~=1 or title~='Код с приложения' or not body:find('Authenticator',1,true) then return end
    if self.data.main.enabled~=true or self.attempted or not rt:serverSupports() then return end
    if self:nickname()~=self.data.main.nickname then return end
    local encrypted=rt.storage:read(self.secretPath);if not encrypted then return end
    local ok,secret=pcall(protect,encrypted,true);if not ok or not secret then self.status='Не удалось открыть ключ Windows.';return end
    local code=rt:service('totp.lua').code(secret,rt.api.os.time())
    if not code then return end
    self.attempted=true
    rt.api.sampSendDialogResponse(88,1,-1,code)
    return false
end
function Auth:draw(g)
    self.buffer=self.buffer or g.ImBuffer(160)
    local enabled=g.ImBool(self.data.main.enabled==true)
    if g.Checkbox('Google Auth: вводить код автоматически',enabled) then self.data.main.enabled=enabled.v;self.rt.storage:saveIni(self.data,self.path) end
    g.InputText('Ключ Google Auth##totp_secret',self.buffer,g.InputTextFlags.Password)
    if g.Button('Привязать ключ##totp_save') then if self:save(self.buffer.v) then self.buffer.v='' end end
    g.SameLine()
    if g.Button('Удалить ключ##totp_delete') then
        if not self.rt.storage:write(self.secretPath,'') then self.status='Не удалось удалить ключ.';return end
        self.rt.storage:remove(self.secretPath..'.bak');self.data.main.enabled=false;self.data.main.nickname=''
        self.rt.storage:saveIni(self.data,self.path);self.buffer.v='';self.status='Ключ удалён.'
    end
    g.TextWrapped('Секретный ключ из настройки Authenticator. Хранится для этого персонажа и пользователя Windows.')
    if self.status~='' then g.TextWrapped(self.status) end
end
return Auth

    end
    sources["avatar.lua"] = function()
-- The player's current stock GTA skin, loaded locally and clipped to a circle.
-- Asset provenance: assets/skins/sources.json. No network access at runtime.
local Avatar = {}
Avatar.__index = Avatar

local ffi = require 'ffi'
local SEGMENTS = 48
local ring = {}
for i = 0, SEGMENTS do
    local angle = i * (math.pi * 2 / SEGMENTS)
    ring[i + 1] = {math.cos(angle), math.sin(angle)}
end

local function stockSkin(id)
    return type(id) == 'number' and id == math.floor(id) and id >= 0 and id <= 311 and id ~= 74
end

local function pngSize(data)
    if type(data) ~= 'string' or #data < 24 or data:sub(1, 8) ~= '\137PNG\13\10\26\10' then return end
    local function integer(offset)
        local a, b, c, d = data:byte(offset, offset + 3)
        return ((a * 256 + b) * 256 + c) * 256 + d
    end
    local w, h = integer(17), integer(21)
    if w < 1 or h < 1 or w > 2048 or h > 2048 then return end
    return w, h
end

function Avatar.new(imgui, basePath, api)
    return setmetatable({
        imgui = imgui,
        api = api or _G,
        basePath = assert(basePath, 'avatar requires the admintools resource directory'):gsub('[/\\]+$', ''),
        model = nil, texture = nil, attempted = nil, error = nil,
    }, Avatar)
end

function Avatar:release()
    if self.texture then
        pcall(self.imgui.ReleaseTexture, self.texture)
        self.texture = nil
    end
end

function Avatar:currentModel()
    local api = self.api
    if type(api.getCharModel) ~= 'function' or api.PLAYER_PED == nil then return end
    if type(api.doesCharExist) == 'function' then
        local ok, exists = pcall(api.doesCharExist, api.PLAYER_PED)
        if not ok or not exists then return end
    end
    local ok, model = pcall(api.getCharModel, api.PLAYER_PED)
    if ok then return model end
end

-- Call before submitting this frame's avatar draw commands. At most one texture
-- exists: changing the skin releases the previous resource before loading once.
-- Failed loads are remembered too; a missing file must never cause frame I/O.
function Avatar:update(model)
    if model == nil then model = self:currentModel() end
    if self.model == model and self.attempted then return self.texture ~= nil end
    self:release()
    self.model, self.attempted, self.error = model, true, nil
    if not stockSkin(model) then return false end

    local path = self.basePath .. '/assets/skins/' .. model .. '.png'
    local file = io.open(path, 'rb')
    if not file then self.error = 'portrait file unavailable'; return false end
    local data = file:read('*a')
    file:close()
    local width, height = pngSize(data)
    if not width then self.error = 'invalid portrait PNG'; return false end

    -- Read through Lua's path handling, then send bytes to the renderer. The
    -- Direct3D helper never has to reinterpret a Cyrillic installation path.
    local address = tonumber(ffi.cast('uintptr_t', ffi.cast('const char*', data)))
    local ok, texture = pcall(self.imgui.CreateTextureFromMemory, address, #data)
    if not ok or texture == nil or texture == false or texture == 0 then
        self.error = 'portrait texture unavailable'
        return false
    end
    self.texture = texture
    -- A square head-and-shoulders crop, adjusted from the actual PNG dimensions.
    self.u0, self.u1 = 0.22, 0.78
    self.v0, self.v1 = 0.08, math.min(1, 0.08 + width * 0.56 / height)
    return true
end

-- Coordinates are screen-space and radius includes the portrait, not the ring.
-- MoonImGui 1.1.2 has no AddImageRounded; degenerate image quads form textured
-- triangles. UVs follow the same affine transform, so no square corners bleed.
function Avatar:draw(drawList, cx, cy, radius, background, border)
    local g, vec = self.imgui, self.imgui.ImVec2
    local centre = vec(cx, cy)
    drawList:AddCircleFilled(centre, radius + 3, background, SEGMENTS)
    if self.texture then
        local uc, vc = (self.u0 + self.u1) / 2, (self.v0 + self.v1) / 2
        local ur, vr = (self.u1 - self.u0) / 2, (self.v1 - self.v0) / 2
        local uvCentre = vec(uc, vc)
        for i = 1, SEGMENTS do
            local a, b = ring[i], ring[i + 1]
            drawList:AddImageQuad(self.texture,
                centre, vec(cx + a[1] * radius, cy + a[2] * radius),
                vec(cx + b[1] * radius, cy + b[2] * radius), centre,
                uvCentre, vec(uc + a[1] * ur, vc + a[2] * vr),
                vec(uc + b[1] * ur, vc + b[2] * vr), uvCentre, 0xFFFFFFFF)
        end
    else
        -- An explicit unavailable-avatar symbol rather than another player's
        -- skin when disconnected, using a custom model, or missing an asset.
        drawList:AddCircleFilled(vec(cx, cy - radius * 0.23), radius * 0.23, border, 24)
        drawList:AddCircle(vec(cx, cy + radius * 0.26), radius * 0.39, border, 32, 2)
    end
    drawList:AddCircle(centre, radius + 2, border, SEGMENTS, 1.5)
    return self.texture ~= nil
end

function Avatar:shutdown()
    self:release()
    self.model, self.attempted, self.error = nil, nil, nil
end

return Avatar

    end
    sources["capture_native.lua"] = function()
-- The integrated source patches are specific to SA-MP 0.3.7-R1.
-- Version marker: https://github.com/imring/SAMP-API.lua/blob/master/sampapi/init.lua
-- Opcode signatures were also checked against the user's original samp.dll / gta_sa.exe.
local M = {}
local function uint32(bytes)
    if type(bytes) ~= 'string' or #bytes ~= 4 then return nil end
    local a,b,c,d = bytes:byte(1,4)
    return a + b*256 + c*65536 + d*16777216
end
function M.check(read, sampBase, gameBase, feature, state)
    if not sampBase or sampBase == 0 then return false, 'SA-MP не загружен' end
    if read(sampBase,2) ~= 'MZ' then return false, 'Неизвестный модуль SA-MP' end
    local offset = uint32(read(sampBase+0x3C,4))
    if not offset or offset < 0x40 or offset > 0x1000 then return false, 'Неизвестный заголовок SA-MP' end
    if read(sampBase+offset,4) ~= 'PE\0\0' or uint32(read(sampBase+offset+0x28,4)) ~= 0x31DF13 then
        return false, 'Эта функция поддерживает SA-MP 0.3.7-R1'
    end
    state = state or {}
    if feature == 'nametags' then
        local call = state.renderNickHookInstalled and '\xE8' or '\xE8\xA0\x4C\x04\0\x8B\x46\x0B'
        local health = state.drawHealthBarPatchInstalled and '\xC3' or '\x55\x8B\xEC\x83\xE4\xF8\x83\xEC'
        if read(sampBase+0x70F4E,#call) ~= call or read(sampBase+0x6FC30,#health) ~= health then
            return false, 'Код никнеймов изменён другим модулем'
        end
    elseif feature == 'skeletal' then
        if gameBase ~= 0x400000 or read(gameBase+0x1E4280,8) ~= '\x8A\x44\x24\x0C\x83\xEC\x0C\x56' then
            return false, 'Версия GTA SA не поддерживает этот скелетный рендер'
        end
    else return false, 'Неизвестная функция' end
    return true
end
return M

    end
    sources["clock_settings.lua"] = function()
-- Convert PC wall-clock display to MSK; Unix timestamps and elapsed timers stay intact.
local M={}
function M.new(api,preferences)
    local self={}
    function self:offset()local p=preferences.data.main;return p.timezoneEnabled and (tonumber(p.timezoneMskOffset)or 0)*3600 or 0 end
    function self:date(format,timestamp)
        format=format or '%c'
        if format:sub(1,1)=='!'then return api.date(format,timestamp)end
        return api.date(format,(timestamp or api.time())-self:offset())
    end
    function self:time(value)
        if value==nil then return api.time()end
        local copy={};for k,v in pairs(value)do copy[k]=v end
        return api.time(copy)+self:offset()
    end
    function self:draw(g)
        local p=preferences.data.main
        if g.Button('Часовой пояс##timezone')then self.edit=not self.edit;self.input=g.ImInt(tonumber(p.timezoneMskOffset)or 0);self.error=nil end
        g.SameLine();g.Text(p.timezoneEnabled and string.format('ПК: МСК%+d; время модулей: МСК',p.timezoneMskOffset or 0)or 'Время ПК без коррекции')
        if self.edit then
            g.TextWrapped('Введите разницу часов вашего ПК с Москвой: +2, если часы опережают МСК на 2 часа; -6, если отстают на 6.')
            g.PushItemWidth(140);g.InputInt('Смещение от МСК##timezone_offset',self.input,0,0);g.PopItemWidth()
            if g.Button('Применить##timezone')then
                local n=tonumber(self.input.v)
                if n and n>=-15 and n<=11 and n==math.floor(n) then
                    p.timezoneEnabled=true;p.timezoneMskOffset=n;preferences:save();self.edit=false;self.error=nil
                else self.error='Введите целое число от -15 до +11.'end
            end
            g.SameLine();if g.Button('Без коррекции##timezone')then p.timezoneEnabled=false;preferences:save();self.edit=false end
            if self.error then g.TextWrapped(self.error)end
        end
    end
    return self
end
return M


    end
    sources["combo_settings.lua"] = function()
-- Import only the requested COMBO sections; legacy Lua is parsed as data, never run.
local M={}
function M.load(integration,kind,defaults)
    local storage=integration.storage
    local path=storage:path('settings',kind..'.ini')
    local exists=storage:exists(path)
    local data=storage:loadIni(defaults,path)
    if not exists then
        local legacy=storage:path('data','combo-import.lua',{integration.root..'/combo_report_assistant/settings.lua'})
        local old=storage:loadTable(legacy)
        if type(old)=='table' then
            local main=old[kind=='autostart' and 'autostart' or 'report']
            if type(main)=='table' then for key,value in pairs(defaults.main) do if type(main[key])==type(value) then data.main[key]=main[key] end end end
            for key,section in pairs(old) do
                local n=tonumber(tostring(key):match(kind=='autostart' and '^autostart_cmd_(%d+)$' or '^report_bind_(%d+)$'))
                if n and n>=1 and n<=(kind=='autostart' and 20 or 100) and type(section)=='table' then
                    local target={}
                    for k,v in pairs(section) do if type(v)=='string' or type(v)=='boolean' or type(v)=='number' then target[k]=v end end
                    data['row'..n]=target
                end
            end
        end
        storage:saveIni(data,path)
    end
    return data,path
end
function M.integer(g,label,data,key,default,min,max)
    local current=g.ImInt(tonumber(data[key]) or default)
    if g.InputInt(label,current,0,0) then data[key]=math.max(min,math.min(max,current.v));return true end
end
function M.toggle(g,label,data,key)
    local current=g.ImBool(data[key]==true)
    if g.Checkbox(label,current) then data[key]=current.v;return true end
end
function M.limit(value,default,min,max)
    local number=tonumber(value)
    if not number or number~=number then number=default end
    return math.max(min,math.min(max,number))
end
return M

    end
    sources["dependencies.lua"] = function()
-- Installs only missing files from the release-pinned library catalogue.
local M={}
function M.new(api,catalog,hash,notify)
    local self={busy=false,status='Нажмите «Проверить библиотеки».',missing={}}
    local root=api.getWorkingDirectory():gsub('\\','/')..'/lib'
    local function exists(path)local f=api.io.open(path,'rb');if f then f:close();return true end;return false end
    local function read(path)local f=assert(api.io.open(path,'rb'));local b=f:read('*a');f:close();return b end
    local function ensure(path)
        if api.doesDirectoryExist(path) then return end
        local parent=path:match('^(.*)/[^/]+$');if parent then ensure(parent)end
        api.createDirectory(path);assert(api.doesDirectoryExist(path),'Cannot create '..path)
    end
    local seen={}
    for _,f in ipairs(catalog.files)do
        assert(type(f.path)=='string' and f.path:match('^[%w_./%-]+$') and not f.path:find('..',1,true)
            and f.path:sub(1,1)~='/' and not seen[f.path:lower()],'Invalid dependency path')
        assert(type(f.bytes)=='number' and f.bytes>0 and type(f.offset)=='number' and f.offset>=0
            and f.offset+f.bytes<=catalog.bytes and #f.sha256==64,'Invalid dependency descriptor')
        seen[f.path:lower()]=true
    end
    function self:check()
        self.missing={}
        for _,f in ipairs(catalog.files)do if not exists(root..'/'..f.path)then self.missing[#self.missing+1]=f end end
        self.status=#self.missing==0 and 'Все файлы комплекта библиотек присутствуют.' or ('Отсутствует файлов: '..#self.missing)
        return #self.missing
    end
    function self:install()
        if self.busy then return end
        if self:check()==0 then notify(self.status);return end
        self.busy=true;self.status='Скачивание библиотек…'
        api.lua_thread.create(function()
            local temp
            local ok,err=pcall(function()
                ensure(root)
                repeat temp=root..'/xt-libraries-'..tostring(api.getGameTimer())..'-'..tostring(math.random(100000,999999))..'.tmp' until not exists(temp)
                local finished=false
                api.downloadUrlToFile(catalog.url,temp,function(_,status)if status==6 or status==58 then finished=true end end)
                local deadline=api.getGameTimer()+120000
                while not finished and api.getGameTimer()<deadline do api.wait(100)end
                assert(finished,'Download timeout')
                local bytes=read(temp)
                assert(#bytes==catalog.bytes and hash(bytes)==catalog.sha256,'Library package checksum mismatch')
                -- Validate every missing file before committing any of them.
                for _,f in ipairs(self.missing)do
                    assert(hash(bytes:sub(f.offset+1,f.offset+f.bytes))==f.sha256,'Library checksum mismatch: '..f.path)
                    api.wait(0)
                end
                local installed=0
                for _,f in ipairs(self.missing)do
                    local path=root..'/'..f.path
                    if not exists(path)then
                        ensure(path:match('^(.*)/[^/]+$'))
                        local stage=path..'.xt-new'
                        assert(not exists(stage),'Staging file exists: '..stage)
                        local output=assert(api.io.open(stage,'wb'))
                        assert(output:write(bytes:sub(f.offset+1,f.offset+f.bytes)));assert(output:close())
                        assert(hash(read(stage))==f.sha256,'Written library checksum mismatch')
                        if exists(path)then api.os.remove(stage)
                        else assert(api.os.rename(stage,path));installed=installed+1 end
                    end
                    api.wait(0)
                end
                self:check();self.status='Добавлено файлов: '..installed..'. Перезапустите игру.'
            end)
            if temp then api.os.remove(temp)end
            self.busy=false
            if not ok then self.status='Библиотеки не установлены полностью: '..tostring(err)end
            notify(self.status)
        end)
    end
    function self:draw(g)
        g.Separator();g.TextWrapped('Библиотеки X-Tools');g.TextWrapped(self.status)
        if not self.busy then
            if g.Button('Проверить библиотеки##xt_dependencies')then self:check()end
            if #self.missing>0 and g.Button('Скачать недостающие библиотеки##xt_dependencies_install')then self:install()end
        end
        g.TextWrapped('Существующие файлы сохраняются. Наличие файлов не гарантирует совместимость установленных версий. После установки перезапустите игру.')
    end
    return self
end
return M

    end
    sources["discord_transport.lua"] = function()
-- LuaSec 0.6-compatible HTTPS with chain AND DNS identity validation.
-- Primary API: https://github.com/lunarmodules/luasec/wiki/LuaSec-0.6
-- SAN layout: cert:extensions()['2.5.29.17'].dNSName (LuaSec src/x509.c).
local M = {}

function M.hostnameMatches(host, name)
    if type(host) ~= 'string' or type(name) ~= 'string' or name:find('%z') then return false end
    host, name = host:lower(), name:lower()
    if host == name then return true end
    local suffix = name:match('^%*%.([%w%-]+%.[%w%.%-]+)$')
    if not suffix then return false end
    local label, rest = host:match('^([%w%-]+)%.(.+)$')
    return label ~= nil and rest == suffix
end

function M.verifyHostname(certificate, host)
    if not certificate then return false end
    local ok, extensions = pcall(function() return certificate:extensions() end)
    if not ok or type(extensions) ~= 'table' then return false end
    local san = extensions['2.5.29.17']
    if type(san) ~= 'table' or type(san.dNSName) ~= 'table' then return false end
    for _, name in ipairs(san.dNSName) do
        if M.hostnameMatches(host, name) then return true end
    end
    -- Public Discord certificates must contain DNS SANs; no CN fallback.
    return false
end

function M.request(method, address, headers, payload, caFile)
    local host = type(address) == 'string' and address:match('^https://([^/]+)/api/webhooks/%d+/[%w_%-]+$')
    if host ~= 'discord.com' and host ~= 'discordapp.com' then
        return false, 0, '', '', 'Only HTTPS Discord webhooks are supported'
    end
    return M.perform(method,address,headers,payload,caFile,host,4*1024*1024)
end

-- The release service supplies a configured, direct HTTPS URL. Redirects are
-- deliberately not followed, so certificate and host checks cover every byte.
function M.get(address, caFile, maxBytes)
    local host,path
    if type(address)=='string' then host,path=address:match('^https://([%w%.%-]+)(/[%w%._/%-]+)$') end
    if not host or not path or path:find('..',1,true) then return false,0,'','','Invalid release URL' end
    if type(maxBytes)~='number' or maxBytes<1 or maxBytes>64*1024*1024 then return false,0,'','','Invalid download limit' end
    return M.perform('GET',address,{['User-Agent']='CasualTool'},'',caFile,host,maxBytes)
end

function M.perform(method, address, headers, payload, caFile, host, maxBytes)
    local socket = require('socket')
    local ssl = require('ssl')
    local http = require('socket.http')
    local ltn12 = require('ltn12')
    if http.PROXY then return false, 0, '', '', 'HTTPS proxy is not supported' end
    local response,received = {},0
    local function sink(chunk,err)
        if err then return nil,err end
        if chunk then
            received=received+#chunk
            if received>maxBytes then return nil,'Response exceeds release size limit' end
            response[#response+1]=chunk
        end
        return 1
    end
    local function create()
        local conn = {sock = socket.try(socket.tcp())}
        local checked = false
        local try = socket.newtry(function() pcall(function() conn.sock:close() end) end)
        function conn:settimeout() return self.sock:settimeout(12) end
        function conn:close() return self.sock:close() end
        function conn:connect(connectHost, port)
            try(connectHost == host and tonumber(port) == 443, 'Unexpected HTTPS endpoint')
            try(self.sock:connect(host, 443))
            self.sock = try(ssl.wrap(self.sock, {
                mode = 'client', protocol = 'tlsv1_2', verify = 'peer', cafile = caFile,
                options = {'all', 'no_sslv2', 'no_sslv3', 'no_tlsv1', 'no_tlsv1_1'}
            }))
            try(self.sock:settimeout(12))
            self.sock:sni(host)
            try(self.sock:dohandshake())
            try(M.verifyHostname(self.sock:getpeercertificate(), host), 'TLS certificate hostname mismatch')
            checked = true
            return 1
        end
        setmetatable(conn, {__index = function(_, name)
            return function(self, ...)
                try(checked, 'TLS identity has not been verified')
                return self.sock[name](self.sock, ...)
            end
        end})
        return conn
    end
    local ok, code, _, status = http.request({url = address, port = 443, method = method,
        headers = headers, source = ltn12.source.string(payload), sink = sink,
        create = create, redirect = false})
    local body = table.concat(response)
    if ok then return true, tonumber(code) or 0, body, tostring(status or ''), '' end
    return false, tonumber(code) or 0, body, tostring(status or ''), tostring(code or 'HTTPS failed')
end

return M

    end
    sources["family_question.lua"] = function()
local M={}
local function lower(text)
    text=text:lower()
    local upper,small='АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ','абвгдеёжзийклмнопрстуфхцчшщъыьэюя'
    for i=1,#upper,2 do text=text:gsub(upper:sub(i,i+1),small:sub(i,i+1)) end
    return text
end
function M.target(text)
    text=tostring(text or ''):match('^%s*(.-)%s*$')
    if text:match('^%d+$') then return text end
    text=text:gsub('%s+','_')
    if #text>24 or not text:match('^[A-Za-z0-9_]+$') or text:find('__',1,true) or text:sub(1,1)=='_' or text:sub(-1)=='_' then return end
    local count=0;for _ in text:gmatch('[^_]+') do count=count+1 end
    if count>=1 and count<=3 then return text end
end
M.defaults={'в какой фаме','какая фама','в какой семье','какая семья','фама','семья','family'}
function M.parse(question,keywords)
    local original=tostring(question or ''):gsub('{%x%x%x%x%x%x}',''):gsub('%s+',' '):match('^%s*(.-)%s*$')
    original=original:gsub('[%?%!%.,]+$',''):match('^%s*(.-)%s*$')
    local text=lower(original)
    for _,word in ipairs(keywords or M.defaults) do
        local suffix=lower(tostring(word)):gsub('%s+',' '):match('^%s*(.-)%s*$')
        if suffix~='' and text:sub(-#suffix)==suffix then
            local prefix=original:sub(1,#original-#suffix)
            if prefix:match('%s$')then
                local subject=M.target(prefix)
                if subject then return subject end
            end
        end
    end
end
return M

    end
    sources["far_chat.lua"] = function()
-- sp_plus ChatBox: native text overlay, original message/nickname colours, no window.
local M={}
function M.new(a,p,save)
    local u8=a.require('encoding').UTF8;local bit=a.require('bit')
    local self={rows={},offset=0,moving=false,width=200,height=20}
    local font,size
    local function release()if font then a.renderReleaseFont(font);font=nil end end
    function self:clear()self.rows={};self.offset=0 end
    function self:stop()self.moving=false;release()end
    function self:add(id,color,text)
        local rgba=tonumber(color)or -1
        local msgColor=bit.bor(bit.lshift(bit.band(bit.rshift(rgba,8),255),16),bit.lshift(bit.band(bit.rshift(rgba,16),255),8),bit.band(bit.rshift(rgba,24),255))
        local nickColor=bit.band(a.sampGetPlayerColor(id),0xFFFFFF)
        local line=string.format('{E4E4E4}[%s] {%06X}%s{D4D4D4}({EEEEEE}%d{D4D4D4}): {%06X}%s',a.os.date('%H:%M:%S'),nickColor,a.sampGetPlayerNickname(id),id,msgColor,u8:decode(text))
        self.rows[#self.rows+1]=line;if #self.rows>500 then table.remove(self.rows,1)end
        if self.offset>0 then self.offset=math.min(self.offset+1,math.max(0,#self.rows-p.lines))end
    end
    function self:draw()
        if not p.enabled then self:stop();return end
        if not font or size~=p.font then release();size=p.font;font=a.renderCreateFont('Verdana',size,5,true)end
        if not font then return end
        local sw,sh=a.getScreenResolution();local lineHeight=a.renderGetFontDrawHeight(font)
        local count=math.max(1,math.min(p.lines,math.floor((sh-40)/math.max(1,lineHeight))-1))
        p.x=math.max(0,math.min(p.x,sw-120));p.y=math.max(0,math.min(p.y,sh-(count+1)*lineHeight))
        local interactive=a.sampIsChatInputActive()or a.sampIsDialogActive()or self.moving
        if interactive then
            local x,y=a.getCursorPos()
            if a.wasKeyPressed(2) and (self.moving or x>=p.x and x<=p.x+self.width and y>=p.y and y<=p.y+self.height)then self.moving=not self.moving;if not self.moving then save()end end
            if self.moving then
                p.x=math.max(0,math.min(x,sw-120));p.y=math.max(0,math.min(y,sh-(count+1)*lineHeight))
                if a.wasKeyPressed(1)then self.moving=false;save()end
            end
            if a.wasKeyPressed(33)then self.offset=math.min(math.max(0,#self.rows-count),self.offset+count)end
            if a.wasKeyPressed(34)then self.offset=math.max(0,self.offset-count)end
        end
        self.width=120;local y=p.y
        local function draw(text)
            a.renderFontDrawText(font,text,p.x,y,0xFFE4D8CC);y=y+lineHeight
            self.width=math.max(self.width,math.min(sw-p.x,a.renderGetFontDrawTextLength(font,text)))
        end
        draw(u8:decode(self.moving and 'Дальний чат · ЛКМ — сохранить' or 'Дальний чат'))
        local last=#self.rows-self.offset
        for i=math.max(1,last-count+1),last do draw(self.rows[i])end
        self.height=y-p.y
    end
    return self
end
return M

    end
    sources["fastconnect.lua"] = function()
-- Fast_connect.cs by gumball3000: write uint16 zero at samp.dll + 0x2D3C45.
-- Verified against the supplied CLEO bytecode and the user's 0.3.7 DLL.
local M={}
function M.check(read,base)
    if not base or base==0 or read(base,2)~=0x5A4D then return false end
    local pe=read(base+60,4)
    if pe<64 or pe>4096 or read(base+pe,4)~=0x4550 then return false end
    if read(base+pe+8,4)~=0x5542F47A or read(base+pe+40,4)~=0x31DF13 or read(base+pe+80,4)~=0x330000 then return false end
    local address=base+0x2D3C45
    local value=read(address,2)
    return read(address-1,1)==0x3D and (value==3000 or value==0) and read(address+2,2)==0 and read(address+4,1)==0x9C
end
function M.start(api)
    local state={stopped=false}
    api.lua_thread.create(function()
        while not state.stopped do
            local base=api.getModuleHandle('samp.dll')
            if base and base~=0 then
                local ok,supported=pcall(M.check,function(a,n) return api.readMemory(a,n,false) end,base)
                if ok and supported then
                    local address=base+0x2D3C45
                    if api.readMemory(address,2,false)==3000 then
                        state.address=address;api.writeMemory(address,2,0,true)
                    end
                end
            end
            api.wait(0)
        end
    end)
    function state:stop()
        self.stopped=true
        if self.address and api.readMemory(self.address,2,false)==0 then api.writeMemory(self.address,2,3000,true) end
    end
    return state
end
return M

    end
    sources["goodgame_event.lua"] = function()
-- Only server announcements, never quoted report/chat text.
local M={}
function M.parse(text)
    text=tostring(text or ''):gsub('{%x%x%x%x%x%x}',''):gsub('^%[%d%d:%d%d:%d%d%]%s*','')
    local nick,id=text:match('^Гос%. новости:%s*([%w_]+)%[(%d+)%]')
    if id then return 'news',tonumber(id),nick end
    local prefix,tail=text:match('^(.-) сменил имя на%s+(.+)$')
    if not prefix then prefix,tail=text:match('^(.-) сменила имя на%s+(.+)$')end
    if not prefix then return end
    prefix=prefix:gsub('^Игрок%s+','')
    local old,number=prefix:match('^([%w_]+)%[(%d+)%]$')
    if not old then old=prefix:match('^([%w_]+)$')end
    local name=tail:match('^([%w_]+)[%.!]?%s*$')
    if old and name then return 'nickname',tonumber(number),name end
end
return M

    end
    sources["help.lua"] = function()
-- User-facing guide. The in-game reference and USER_GUIDE.md share this source.
local Help = {}
Help.sections = {
    {id='start',title='Начало работы',page='home',intro={
        'Выберите нужную задачу в левом меню. Рабочие действия и настройки находятся в одном разделе; общие права, данные и обновление — в «Системе».',
        'В справке ID означает текущий номер игрока на сервере, ник — имя аккаунта. Заменяйте параметры своими значениями. Квадратные скобки обозначают необязательный параметр; сами скобки вводить не нужно.'
    },topics={
        {'Выключение X-Tools','Кнопка питания под логотипом останавливает функции, HUD и автоматические команды. Повторное нажатие включает их с сохранёнными настройками. /at и клавиша меню остаются доступны. Отменённые очереди автоматически не продолжаются.'},
        {'Часовой пояс','Главная → Настройки (значок ползунков) → Основные → Часовой пояс. Введите разницу времени ПК с МСК: +2 для опережения, -6 для отставания. Общая служба приводит локальное время модулей к МСК. Unix-время, длительности, Google Auth и расписание в UTC не сдвигаются.'},
        {'Первый запуск','В левом меню выберите нужный модуль и его вкладку «Настройки». Горячие клавиши основы находятся в Основные инструменты → Настройки → Клавиши. Разовые действия выполняются кнопками или командами.'},
        {'Перед отправкой','Проверьте подтверждённый уровень в «Система», затем игрока, срок и причину. Пока уровень неизвестен, команды скрипта не отправляются. Сообщение об отправке означает передачу запроса; результат зависит от ответа сервера.'}
    },commands={
        {'/at','Открыть или закрыть главное окно X-Tools.'},
        {'/athelp','Открыть этот справочник.'},
        {'/atinput','Записать диагностику курсора и блокировки ввода в moonloader.log.','После команды закройте чат; запись выполняется несколько раз с интервалом.'},
        {'/atmodules','Показать в чате состояние всех частей X-Tools.','Статус загрузки не заменяет галочку включения функции в настройках.'}
    }},
    {id='tools',title='Инструменты',page='core',intro={
        'Телепортация, мероприятия, временное лидерство и серверная погода находятся в «Основные инструменты → Функции». Доступность действий зависит от уровня администратора.',
        'Локальная погода и время меняются только у вас. Их переключатели находятся в настройках; серверная погода меняется отдельно в инструментах.'
    },topics={
        {'Мероприятия','Выберите мероприятие, заполните его параметры и проверьте текст в предпросмотре. Для сообщения об окончании укажите победителя. Объявление отправляется кнопкой; раздел доступен с 4 уровня.'},
        {'Невидимость','Для 1–2 уровней /inv, бинд и включение при запуске используют механизм Bart4 через spectator-синхронизацию. Он приостанавливается в транспорте и при настоящей слежке. С 3 уровня отправляется серверная /inv. Статус отображается в общем индикаторе INVISIBLE.'},
        {'Дальний чат и TAB Жидкое стекло','Дальний чат выводит компактные строки с цветами ников и сообщений, включая шёпот в стриме. Откройте чат или диалог, нажмите ПКМ по дальнему чату, переместите и подтвердите ЛКМ. PageUp/PageDown листают историю. TAB Жидкое стекло заменяет прежний TAB: карточки игроков с ID, ником, уровнем и пингом, поиск, плавная прокрутка и выбор положения. ПКМ — копирование ника, двойной щелчок — стандартное действие сервера. При включённой опции удержание TAB дольше 0,7 секунды закрывает таблицу после отпускания.'},
        {'История попаданий','Траектории выстрелов → BulletSync: переключатель, настройки HUD и последние 50 попаданий из входящих и исходящих пакетов. Запись BulletSync не является подтверждением урона сервером.'},
        {'Дальность прорисовки','В игровых функциях включите дальность прорисовки и введите справа число от 0 до 3600. По умолчанию 1200. Выключение восстанавливает прежние параметры игры.'},
        {'Коррекция текста','Основные инструменты → Настройки → Чат. После включения доступны режим (до отправки, подсказка, копирование), автозаглавная буква с точкой и подсказка при входе. Ctrl+X исправляет открытый ввод, Ctrl+Z возвращает прежний, F2 применяет подсказку. Текст проверяется через Яндекс Спеллер; команды авторизации не передаются сервису.'},
        {'Ускорение транспорта и ClickWarp','Включаются в игровых функциях. Ускорение из sh.cs действует при удержании Shift + W за рулём; бинд переназначается. Для ClickWarp назначьте клавишу выбора точки, начните слежку и подтвердите маркер ЛКМ; Esc отменяет. Смена наблюдаемого игрока также отменяет перенос.'},
        {'AirBreak','Игровые функции → AirBreak. Ctrl+2 — включение и выключение, Ctrl+3 — выключение; Num 1/2/3 — скорость. WASD — движение, Q/E — высота пешком, стрелки вверх/вниз — высота транспорта, влево/вправо — поворот. Пешком повторяется Swim_Tread; выключение снимает анимацию.'},
        {'Телепортация','Выберите сохранённое место. Действия раздела доступны с 3 уровня. Перемещение игрока на дорогу выполняется отдельно командой /tr ID.'},
        {'Временное лидерство','Назначение временного лидера доступно с 4 уровня. Автоматическое назначение при входе и после зарплаты включается в основных настройках.'}
    },commands={
        {'/checkw','Проверить слово или предложение через Яндекс Спеллер.','Работает при включённой коррекции текста: /checkw текст.'},
        {'/metla','Включить или выключить полёт на метле.','Игровые функции → Метла: размер модели и назначение клавиши. W/S — наклон, A/D — поворот, Space — разгон, Shift — торможение. Доступно пешком, вне слежки. AirBreak выключается при запуске метлы.'},
        {'/tpm','Открыть общую страницу телепортации.','Внизу — «Интерьеры и площадки для мероприятий»: 15 точек. Интерьеры используют мир 555, открытые площадки — мир 0. Телепортация доступна с 3 уровня.'},
        {'/autostartnow','Запустить сохранённые команды при старте.','Основные инструменты → Функции → Команды при старте. Режимы: Авто, Локальная, Серверная. Первый запуск после спавна; повтор — только после переподключения.'},
        {'/lego','Открыть поиск LEGO при включённой замене команды.','Основные инструменты → Настройки → Игровые функции → Заменять /lego автоматически. /lego с названием работает как обычная команда.'},
        {'/legorefresh','Перечитать страницы LEGO с сервера при включённой замене.'},
        {'/tr ID','Переместить игрока на ближайшую дорогу.','Нужно право /gethere. Игрок должен быть в зоне прорисовки; администратор — вне интерьера. Нельзя выбрать себя.'},
        {'/getcar ID_транспорта','Переместить к себе транспорт без водителя.','Транспорт должен быть в зоне прорисовки. ID транспорта и ID модели — разные значения.'},
        {'/clearhospital ID [ID…]','Последовательно запросить перемещение указанных игроков к себе.','Между запросами — 1 секунда. Перед каждым запросом проверяется, что ID по-прежнему принадлежит тому же игроку.'},
        {'/clearhospital stop','Остановить оставшиеся перемещения.'},
        {'/rskin ID_скина радиус','Выдать один временный скин игрокам в указанном радиусе.','С 4 уровня. Скины: 1–311, кроме 74; радиус: 3–80 метров. Повторная команда во время выдачи останавливает её.'},
        {'/rskins ID_скина_1 ID_скина_2 радиус','Поочерёдно выдавать два временных скина игрокам рядом.','С 4 уровня. Те же ограничения, что у /rskin. Повторная команда останавливает выдачу.'},
        {'/carsp ряды машин_в_ряду модель цвет_1 цвет_2','Создать транспорт рядами.','С 4 уровня. Модель: 400–611; цвета: 0–255. Повторная /carsp останавливает создание.'},
        {'/apay ID сумма','Передать деньги игроку несколькими платежами.','Игрок должен находиться рядом. Повторная /apay останавливает передачу.'},
        {'/findd ID_организации','Собрать сведения об онлайне организации и показать результат.','ID организации: 1–13.'},
        {'/afindd ID_организации','Собрать сведения об онлайне организации и отправить отчёт в /a.','ID организации: 1–13.'},
        {'/guns','Запросить выдачу оружия себе.','Нужны серверные права на выдачу оружия.'},
        {'/forum','Получить последние темы раздела жалоб на администрацию.','Для загрузки нужен доступ к форуму.'},
        {'/reconn','Переподключиться к текущему серверу.','Текущие автоматические очереди при разрыве соединения отменяются.'}
    }},
    {id='rephelp',title='Биндер',page='rephelp',intro={
        'Редактируемые команды ответов из RepHelp. Включите модуль, выберите команду, измените текст и сохраните. «Новая команда» добавляет шаблон. В поле «Команда запуска» укажите, например, /gg. Каждая строка редактируется в отдельном поле; + добавляет строку, × удаляет. Слева — список команд, справа — редактор. Вызов: /имя ID.',
        'Одна строка — серверная команда или обычный ответ через /ans. Подстановки: {id}, {time}, {date}; время учитывает общую настройку часового пояса. Новые команды и изменения сохраняются.'
    },topics={{'Исходные команды','gg, gt, mpjail, tir, rm, pg, ych, nak, oft, zb, tra, liv, vch. /mpjail выполняет /jail на 20 минут и /unjail. Перед использованием проверьте шаблон.'}},commands={}},
    {id='reminders',title='Напоминание игрокам в msg',page='reminders',intro={
        'Кнопка «Создать новый набор» добавляет ваш набор: введите название, нажмите «Создать» и заполните текст. Название и текст сохраняются после перезапуска. Выберите набор: защита аккаунта, репорт, мошенники, технические работы или выборы. Проверьте текст и нажмите «Отправить набор». В поле «Режим / радиус» задайте 0 — стандартное сообщение всем, 1 — важное всем или одно число от 20 до 300 — радиус видимости. Например: /msg 200 текст. Интервал — не менее трёх секунд. Требуется 4 уровень.',
        'Правки наборов сохраняются. Кнопка восстановления возвращает исходные тексты. Отправка идёт по снимку выбранного набора; «Остановить», переподключение и изменение прав отменяют остаток очереди.'
    },commands={}},
    {id='autoreply',title='Автоответ',page='autoreply',settings='autoreply',intro={
        'Отдельные выключатели пожеланий на гос. новости и смену nickname работают независимо от правил обычного автоответа. Текст пожелания редактируется; повторные новости одного автора ограничены интервалом 90 секунд. Используются общие настройки задержки и защиты после AFK.',
        'Автоматические ответы на обращения по правилам из AutoSalamReport. Выберите правило слева: доступны создание, редактирование и удаление. Для нового профиля система выключена; прежние настройки COMBO импортируются один раз.'
    },topics={
        {'Правила','Ключи через запятую; частичное или точное совпадение без учёта регистра и пунктуации. До пяти случайных ответов. Подстановки: %id%, %text%, %time%, %date%.'},
        {'Настройки','Задержки ответа и после возврата в игру, интервалы по игроку и тексту, фильтр цвета, смещение времени и отладка. Ответ отменяется при отключении или смене игрока на ID.'}
    },commands={}},
    {id='punishments',title='Автовыдача',page='aegis',settings='aegis',intro={
        'В модуле «Автовыдача» проверяются запросы, их цель, срок и причина. Обработка сообщений и постоянные параметры находятся на вкладке «Настройки».',
        'Очередь из текстового файла находится в самостоятельном разделе. Её запуск и отметки результатов описаны в теме «Очередь из файла».'
    },topics={
        {'Обработка запросов','В «Автовыдача → Настройки» включите обработку сообщений из /a. Там же настраиваются ручные команды, уведомления игроку, звук и диагностика. Выключение обработки снимает ожидающий подтверждения запрос; уже поставленная очередь не очищается.'},
        {'Проверка offban','Перед отправкой X-Tools запрашивает /baninfo по точному нику. Сообщение сервера «Игрок с таким ником (или номером аккаунта) не найден в банлисте» разрешает выдачу без ожидания диалога. Оставшиеся дни прибавляются к новым, максимум — 30. При сроке от 30 дней, неполном ответе или таймауте наказание не отправляется.'},
        {'Защищённый список','В модуле «Автовыдача» нажмите «Обновить списки», чтобы перечитать сохранённые сведения об администраторах и лидерах из чекера.'},
        {'Команды банд','При первом запуске команды /gw и /gb выключены. Включите их общей галочкой в «Гетто → Настройки». Выбранное состояние сохраняется после перезапуска. Перед отправкой проверьте игрока и срок наказания.'}
    },commands={
        {'/gw ID','Выдать предупреждение за нарушение правил капта.','Включите команды в «Гетто → Настройки». Игрок должен быть онлайн. Если цвет банды распознан, её тег добавляется к причине.'},
        {'/gb ID дни','Запросить блокировку за читы.','Включите команды в «Гетто → Настройки». Дни — положительное целое число; игрок должен быть онлайн. Если цвет банды распознан, её тег добавляется к причине.'},
        {'/2warns ID причина','Последовательно выдать два предупреждения.','С 4 уровня. Причина обязательна.'},
        {'/mban ID_1 ID_2 [ID_3] [ID_4] дни причина','Запросить блокировку от двух до четырёх игроков.','С 3 уровня. Между запусками — не менее 60 секунд.'},
        {'/warnlast причина','Запросить офлайн-предупреждение последнему игроку из слежки.','С 4 уровня — напрямую; при меньшем уровне — запрос через /a.'},
        {'/banlast дни причина','Запросить офлайн-блокировку последнему игроку из слежки.','С 4 уровня — напрямую; при меньшем уровне — запрос через /a.'},
        {'/jaillast минуты причина','Запросить офлайн-заключение последнему игроку из слежки.','С 3 уровня — напрямую; при меньшем уровне — запрос через /a.'},
        {'/mutelast минуты причина','Запросить офлайн-ограничение чата последнему игроку из слежки.','С 3 уровня — напрямую; при меньшем уровне — запрос через /a.'},
    }},
    {id='checker',title='Чекер',page='adm',settings='adm',intro={
        'Чекер показывает администраторов, лидеров и друзей. Откройте «Чекер». Отображение списков, положение панели, шрифт и автоматическое получение данных настраиваются в «Чекер → Настройки».',
        'Все функции X-Tools, включая чекер, работают только на Advance RolePlay Blue (blue.adv-rp.com / 185.169.134.239) и Test (185.169.134.195), порт 7777. На других адресах программа останавливается.'
    },topics={
        {'Управление записями','Выберите список администраторов, лидеров или друзей. Используйте поиск, форму добавления и кнопки редактирования или удаления. Для администратора задаётся уровень, для лидера — фракция.'},
        {'Состояние и локальные списки','В рабочем разделе раскройте «Состояние чекера», чтобы посмотреть переключатели, положение панели, шрифт и количество записей. «Перечитать списки» загружает сохранённые записи администраторов, лидеров и друзей; запросов к серверу эта кнопка не отправляет.'},
        {'Получение списков с сервера','В «Чекер → Настройки» включите «Получать списки с сервера», затем нажмите «Обновить списки». Автоматическое получение данных включается отдельно. Это обновление содержимого чекера, а версия X-Tools проверяется в общей системе.'}
    }},
    {id='lookup',title='Проверка игрока',page='lookup',settings='lookup',intro={
        'Проверка игрока собирает профиль аккаунта, IP, связанные аккаунты, историю ников, авторизации и блокировки.',
        'Введите ник или номер аккаунта и нажмите «Проверить». Откроется подробное досье: профиль, статистика, блокировки, сравнение IP, связанные аккаунты, авторизации и наказания. Для продолжения сбора после профиля включите автосбор в настройках.'
    },topics={
        {'Уровень доступа','Основные запросы доступны с 3 уровня. /admget и /iplog требуют 5 уровня. Окончательное разрешение команды проверяет сервер.'},
        {'Работа с досье','Нажмите строку, чтобы скопировать её или открыть действия с IP и аккаунтом. В досье показаны все поля профиля; большие списки авторизаций, наказаний и аккаунтов открываются по кнопке «Все записи» / «Все аккаунты» или во вкладке. Там доступны поиск и страницы результатов. Длинные строки переносятся без обрезки.'},
        {'Очередь запросов','Проверку можно остановить кнопкой. Ручной ввод команды проверки отменяет оставшийся автосбор. Запросы /offst ждут завершения семейного запроса, чтобы не перепутать ответы.'},
        {'Экспорт и геоданные','Досье копируется или сохраняется по кнопке. Отправка сводки в /a — отдельное действие. Геоданные IP загружаются с ipwho.is и сохраняются в кэше; одинаковый IP сам по себе не доказывает принадлежность аккаунтов одному человеку.'}
    },commands={
        {'/cadm','Открыть проверку игрока.'},
        {'/cget ник_или_номер_аккаунта','Запустить полную проверку аккаунта.'},
        {'/cas ID','Запустить полную проверку игрока онлайн.'},
        {'/creg ID','Запросить регистрационные данные игрока онлайн.'},
        {'/offcreg ник_или_номер_аккаунта','Запросить регистрационные данные аккаунта независимо от онлайна.','','/coffreg ник_или_номер_аккаунта'},
        {'/cip IP','Запросить сведения об указанном IPv4-адресе.'},
        {'/clip IP','Запросить связанные с IPv4-адресом аккаунты.'},
        {'/namestore ник_или_ID','Запросить историю ников.','Числовой ID заменяется ником, если этот игрок подключён.'},
        {'/ilog ID','Показать последние административные действия над игроком.','С 2 уровня.'},
        {'/iskill ID','Показать навыки владения оружием у игрока.'}
    }},
    {id='observation',title='Наблюдение',page='core',settings='menu',intro={
        'Панели наблюдения включаются в основных инструментах. Траектории выстрелов имеют отдельный модуль, а контроль аптечек находится в «Гетто» и «Семьях».',
        'Траектория показывает данные выстрела, полученные от игры. Подозрение на сбив аптечки требует проверки; предупреждение выдаётся только вручную.'
    },topics={
        {'Панели наблюдения','В «Основные инструменты → Настройки → Игровые функции» включите замену серверного меню. Цель панели берётся из слежки; между игроками можно переходить стрелками. Там же находятся «Предпросмотр панелей» и «Сбросить позиции». Предпросмотр не отправляет игровые команды.'},
        {'Контроль аптечки','Включите контроль в модуле «Гетто» либо «Семьи»; одновременно активен один режим. По умолчанию Q+E запрашивает слежку за последним подозреваемым. После подтверждения цели сервером H позволяет вручную выдать предупреждение в течение 10 секунд. Клавиши не работают при открытом меню или вводе текста.'},
        {'Горячие клавиши слежки','Основные клавиши смены цели настраиваются в «Горячих клавишах». Переключатели клавиш контроля аптечки и помощника каптов находятся в настройках соответствующих функций.'}
    },commands={
        {'/menumove','Перемещать открытые панели наблюдения за заголовки.','Повторная команда завершает перемещение и сохраняет позиции.','/movemenu'},
        {'/btrack','Открыть настройки траекторий выстрелов.'},
        {'/klist','Открыть список убийств текущего капта, который ведёт основа.'},
        {'/rk ID','Проверить, встречался ли игрок в списке погибших текущего капта.'}
    }},
    {id='capture',title='Капты',page='capture',settings='capture',intro={
        'В модуле «Гетто» собираются фраги, наказания и онлайн банд во время капта. Сначала включите функции гетто в заголовке раздела; затем выберите текущий захват, онлайн или восстановление.',
        'Discord по умолчанию выключен. Чтобы отправлять отчёты, включите отправку в настройках и сохраните webhook нужного канала.'
    },topics={
        {'Поздний вход','Если капт уже идёт, выберите «Начать сбор после старта». Этот режим собирает доступную статистику без автоматических Discord-логов капта.'},
        {'Восстановление','При отключении сохраняется состояние незавершённого капта. После входа откройте восстановление и выберите сохранение. Удаление сохранения также прекращает текущий сбор.'},
        {'Никнеймы и скелеты','Дополнительные подписи и скелеты включаются в настройках каптов. Для них требуется поддерживаемая версия SA-MP/GTA SA; при несовпадении версии функция отключается с объяснением.'}
    },commands={
