local function admin_level_color(level)
    level = normalize_admin_level(level)

    if level == "S1" then
        return 0xFFFF6A6A
    elseif level == "S2" then
        return 0xFFFF3F3F
    elseif level == "S3" then
        return 0xFFFF1010
    elseif level == "7" then
        return 0xFFFF0000
    elseif level == "6" then
        return 0xFF36B90E
    elseif level == "5" then
        return 0xFF4FF87B
    elseif level == "4" then
        return 0xFF436EEE
    elseif level == "3" then
        return 0xFFA73ADA
    elseif level == "2" or level == "1" then
        return 0xFF00BFFF
    end

    return 0xFFFFFFFF
end

