draw_admins = function(x, y, add_gap)
    local count = 0
    local line_height = renderGetFontDrawHeight(font)

    if add_gap then
        y = y + line_height * 1.3
    end

    draw_line("Администраторы в сети:", x, y, 0xFAFFFFFF)
    y = y + 0.5

    for index, player_id in ipairs(admins_id) do
        if player_id ~= -1 then
            count = count + 1

            local nickname = admins_nick[index]
            local level = admins_lvl[index]
            local line_color = admin_level_color(level)
            local display_nickname = format_display_nickname(nickname)
            local suffix = build_admin_suffix(index, level)

            if is_youtube_level(level) then
                display_nickname = format_youtube_nickname(nickname, level)
            end

            local line = build_overlay_line(count, display_nickname, player_id, "", suffix)
            if sampIsPlayerPaused(player_id) then
                line = line .. " {FF0000}[AFK]"
            end

            y = y + line_height
            if player_has_character(player_id) then
                line = line .. " {808080}[#]"
            end

            if is_youtube_level(level) then
                draw_line(line, x, y, 0xFFFFFFFF)
            else
                draw_line(line, x, y, line_color)
            end
        end
    end

    if count == 0 then
        y = y + line_height
        draw_line("Администраторов в сети нет", x, y, 0x64FFFFFF)
    end

    return y
end

local directory_views = {}
local function draw_directory_list(kind, names, selection, label_for, select_record)
    local view = directory_views[kind]
    if not view then
        view = {search = imgui.ImBuffer(128), page = 1}
        directory_views[kind] = view
    end
    imgui.TextColored(integration.color(integration.palette.accent), 'Игроки · ' .. #names)
    imgui.PushItemWidth(-1)
    imgui.TextDisabled('Поиск по нику')
    if imgui.InputText('##directory_search_' .. kind, view.search) then view.page = 1 end
    imgui.PopItemWidth()
    local matching = {}
    local query = trim(view.search.v):lower():gsub('_', ' ')
    for index, nickname in ipairs(names) do
        if query == '' or tostring(nickname):lower():gsub('_', ' '):find(query, 1, true) then matching[#matching + 1] = index end
    end
    local page_size = 8
    local pages = math.max(1, math.ceil(#matching / page_size))
    view.page = math.max(1, math.min(view.page, pages))
    if imgui.Button('Добавить игрока##' .. kind .. '_add_new', imgui.ImVec2(imgui.GetContentRegionAvailWidth(), 34)) then select_record(-1) end
    imgui.Spacing()
    if pages > 1 then
        if imgui.Button('<##directory_prev_' .. kind, imgui.ImVec2(36, 32)) then view.page = math.max(1, view.page - 1) end
        imgui.SameLine();imgui.Text(view.page .. ' / ' .. pages);imgui.SameLine()
        if imgui.Button('>##directory_next_' .. kind, imgui.ImVec2(36, 32)) then view.page = math.min(pages, view.page + 1) end
        imgui.Spacing()
    end
    if #matching == 0 then imgui.TextDisabled(query == '' and 'Список пока пуст' or 'Ничего не найдено') end
    for position = (view.page - 1) * page_size + 1, math.min(view.page * page_size, #matching) do
        local index = matching[position]
        local label = label_for(index)
        local width = math.max(1, imgui.GetContentRegionAvailWidth() - 12)
        local text_height = imgui.CalcTextSize(label, false, width).y
        local height = math.max(34, text_height + 12)
        local x, y = imgui.GetCursorPosX(), imgui.GetCursorPosY()
        if imgui.Selectable('##directory_record_' .. kind .. '_' .. names[index], selection.v == index - 1, 0, imgui.ImVec2(width + 12, height)) then
            select_record(index - 1)
        end
        local next_y = imgui.GetCursorPosY()
        imgui.SetCursorPosX(x + 6); imgui.SetCursorPosY(y + 6)
        imgui.PushTextWrapPos(x + width)
        imgui.TextWrapped(label)
        imgui.PopTextWrapPos()
        imgui.SetCursorPosX(x)
        imgui.SetCursorPosY(math.max(next_y, imgui.GetCursorPosY() + 6))
    end
end

