local function draw_toggle_row(label, value)
    return imgui.Checkbox(label, imgui.ImBool(value))
end

draw_inline_toggle = function(label, id, value)
    return imgui.Checkbox(label .. id, imgui.ImBool(value))
end

local function settings_section(title)
    imgui.Spacing()
    imgui.TextColored(integration.color(integration.palette.accent), title)
    imgui.Separator()
end

local function config_checkbox(label, category, key)
    if draw_toggle_row(label .. '##checker_' .. key, config[category][key]) then
        config[category][key] = not config[category][key]
        save_config()
    end
end

local function friend_notify_button(label, value, width)
    local selected = config.checker.friend_notify_mode == value
    if selected then imgui.PushStyleColor(imgui.Col.Button, integration.color(integration.palette.selection)) end
    if imgui.Button(label .. '##friend_notify_' .. value, imgui.ImVec2(width, 28)) then
        config.checker.friend_notify_mode = value
        save_config()
    end
    if selected then imgui.PopStyleColor(1) end
end

local function draw_record_preferences()
    local groups = {
        {name='Администратор', id='admin', names=admins_nick, selection=selected_admin, select=select_admin,
            notify=admins_notify, sound=admins_sound_notify, save=save_admins, soundKey='sound_notify_admins'},
        {name='Лидер', id='leader', names=leaders_nick, selection=selected_leader, select=select_leader,
            notify=leaders_notify, sound=leaders_sound_notify, save=save_leaders, soundKey='sound_notify_leaders'},
        {name='Друг', id='friend', names=friends_nick, selection=selected_friend, select=select_friend,
            notify=friends_notify, sound=friends_sound_notify, save=save_friends, soundKey='sound_notify_friends'}
    }
    imgui.TextWrapped('Выберите запись, чтобы настроить её отдельно. Добавление и удаление игроков — в разделе «Чекер».')
    for _, group in ipairs(groups) do
        imgui.Spacing()
        imgui.TextColored(integration.color(integration.palette.accent), group.name)
        if #group.names == 0 then
            imgui.TextDisabled('В списке пока нет записей.')
        else
            imgui.PushItemWidth(-1)
            if imgui.Combo('##checker_record_' .. group.id, group.selection, table.concat(group.names, '\0') .. '\0\0') then
                group.select(group.selection.v)
            end
            imgui.PopItemWidth()
            local index = group.selection.v + 1
            if group.names[index] then
                local notify = imgui.ImBool(group.notify[index] ~= false)
                if imgui.Checkbox('Уведомлять в чате##checker_record_' .. group.id .. '_notify', notify) then
                    group.notify[index] = notify.v
                    group.save()
                end
                local sound = imgui.ImBool(group.sound[index] == true)
                if imgui.Checkbox('Звук##checker_record_' .. group.id .. '_sound', sound) then
                    group.sound[index] = sound.v
                    if sound.v then
                        config.checker.sound_notify_enabled = true
                        config.checker[group.soundKey] = true
                        save_config()
                    end
                    group.save()
                end
                if group.id == 'admin' then
                    local locked = imgui.ImBool(admins_locked[index] == true)
                    if imgui.Checkbox('Сохранять данные при обновлении##checker_record_admin_locked', locked) then
                        admins_locked[index] = locked.v
                        save_admins()
                    end
                elseif group.id == 'friend' then
                    local best = imgui.ImBool(friends_best[index] == true)
                    if imgui.Checkbox('Лучший друг##checker_record_friend_best', best) then
                        friends_best[index], friend_best_toggle.v = best.v, best.v
                        save_friends()
                    end
                end
            else
                imgui.TextDisabled('Выберите игрока в поле выше.')
            end
        end
    end
end

