    if columns then
        imgui.Columns(wide and 3 or 2, 'checker_preferences', false)
        imgui.SetColumnWidth(0, width / (wide and 3 or 2))
    end
    settings_section('Показывать на экране')
    config_checkbox('Администраторы', 'checker', 'admins_checker_status')
    config_checkbox('Лидеры', 'checker', 'leaders_checker_status')
    config_checkbox('Друзья', 'checker', 'friends_checker_status')
    settings_section('Внешний вид списка')
    config_checkbox('Уровень администратора', 'overlay', 'admin_show_level')
    config_checkbox('Должность', 'overlay', 'admin_show_role')
    config_checkbox('Фон', 'overlay', 'show_background')
    config_checkbox('Нумерация', 'overlay', 'show_numbering')
    config_checkbox('ID игроков', 'overlay', 'show_ids')
    settings_section('Обновление данных')
    config_checkbox('Получать списки с сервера', 'checker', 'source_updates_enabled')
    config_checkbox('Обновлять администраторов по /admins', 'checker', 'admin_checker_auto_update')
    if imgui.Button('Обновить списки', imgui.ImVec2(180, 30)) then
        if config.checker.source_updates_enabled == false then
            message('Обновление списков с сервера выключено. Включение: Настройки → Чекер.')
        else
            refresh_server_lists()
        end
    end
    if columns then imgui.NextColumn() end
    settings_section('Уведомления в чате')
    config_checkbox('Об администраторах', 'checker', 'notify_admin_events')
    config_checkbox('О лидерах', 'checker', 'notify_leader_events')
    config_checkbox('О скрытых лидерах', 'checker', 'notify_hidden_leader_events')
    config_checkbox('О друзьях', 'checker', 'notify_friend_events')
    imgui.Spacing()
    imgui.TextDisabled('Каких друзей включать в уведомления')
    friend_notify_button('Всех', 'all', 90)
    imgui.SameLine()
    friend_notify_button('Только лучших', 'best', 140)
    if wide then imgui.NextColumn() end
    settings_section('Шрифт')
    imgui.PushItemWidth(-1)
    imgui.TextWrapped('Общий шрифт выбирается на главной X-Tools.')
    imgui.PopItemWidth()
    imgui.TextDisabled('Размер текста')
    imgui.PushItemWidth(112)
    if imgui.InputInt('##checker_font_size', font_size_value) then
        font_size_value.v = math.max(6, math.min(20, font_size_value.v))
        config.overlay.font_size = font_size_value.v
        save_config()
        reload_font()
    end
    imgui.PopItemWidth()

    settings_section('Звук при подключении')
    config_checkbox('Включить звуковые оповещения', 'checker', 'sound_notify_enabled')
    config_checkbox('Администраторы', 'checker', 'sound_notify_admins')
    config_checkbox('Лидеры', 'checker', 'sound_notify_leaders')
    config_checkbox('Друзья', 'checker', 'sound_notify_friends')
    if columns then imgui.Columns(1) end

    imgui.Spacing()
    imgui.Separator()
    imgui.TextDisabled('Изменения сохраняются автоматически.')
    if imgui.CollapsingHeader('Положение списка##checker_appearance') then
    local advancedColumns = integration.layout.begin('checker_position_font', 740)
    settings_section('Положение списка')
    imgui.PushItemWidth(112)
    if imgui.InputInt('X##checker_position_x', position_x_value) then
        position_x_value.v = math.max(0, math.min(640, position_x_value.v))
        config.overlay.xpos = position_x_value.v
        save_config()
    end
    if imgui.InputInt('Y##checker_position_y', position_y_value) then
        position_y_value.v = math.max(0, math.min(448, position_y_value.v))
        config.overlay.ypos = position_y_value.v
        save_config()
    end
    imgui.PopItemWidth()
    if imgui.Button('Сбросить положение##checker_position_reset') then
        config.overlay.xpos, config.overlay.ypos = defaults.overlay.xpos, defaults.overlay.ypos
        overlay_drag_active = false
        save_config()
        refresh_gui_buffers()
    end
    if imgui.Button('Переместить список##checker') then
        overlay_move_mode.v = true
        integration.beginPlacement(function()overlay_move_mode.v=false;overlay_drag_active=false;save_config()end)
        overlay_drag_active = false
        overlay_drag_saved = false
    end
    if overlay_move_mode.v then
        imgui.TextWrapped('Для перемещения нужен заголовок списка. Новое положение сохранится после отпускания мыши.')
    end
    integration.layout.next(advancedColumns)
    integration.layout.finish(advancedColumns)
    end
    do
        settings_section('Фракции лидеров')
        local organizations = collect_leader_org_options()
        if #organizations == 0 then
            imgui.TextDisabled('Список появится после /leaders.')
        else
            if imgui.Button('Показать все', imgui.ImVec2(132, 28)) then set_all_leader_orgs_visible(true) end
            imgui.SameLine()
            if imgui.Button('Скрыть все', imgui.ImVec2(132, 28)) then set_all_leader_orgs_visible(false) end
            imgui.Spacing()
            local count = width >= 1100 and 4 or (width >= 820 and 3 or (width >= 560 and 2 or 1))
            if count > 1 then imgui.Columns(count, 'leader_org_columns', false) end
            local chunk = math.ceil(#organizations / count)
            for column = 1, count do
                for index = (column - 1) * chunk + 1, math.min(column * chunk, #organizations) do
                    local title = organizations[index]
                    if draw_inline_toggle(title, '##leader_org_' .. index, is_leader_org_visible(title)) then
                        set_leader_org_visible(title, not is_leader_org_visible(title))
                    end
                end
                if column < count then imgui.NextColumn() end
            end
            if count > 1 then imgui.Columns(1) end
        end
    end
    if imgui.CollapsingHeader('Параметры отдельных записей##checker_record_preferences') then draw_record_preferences() end
end

draw_gui_page_buttons = function()
    local pages = {'Администраторы', 'Лидеры', 'Друзья'}
    local width = math.min(148, (imgui.GetContentRegionAvail().x - 16) / 3)
    for index, label in ipairs(pages) do
        if index > 1 then imgui.SameLine() end
        local selected = gui_page.v == index - 1
        if selected then imgui.PushStyleColor(imgui.Col.Button, integration.color(integration.palette.selection)) end
        if imgui.Button(label, imgui.ImVec2(width, 34)) then gui_page.v = index - 1; imgui.SetScrollY(0) end
        if selected then imgui.PopStyleColor(1) end
    end
end

imguiOnDrawFrame = function()
    if not imgui_loaded or config == nil then return end
    if imgui.Button('Перечитать списки##checker_reload') then
        load_all_lists()
        sync_online_ids()
        select_admin(-1); select_leader(-1); select_friend(-1)
        for _, view in pairs(directory_views) do view.page = 1 end
        message('Списки чекера загружены из сохранённых файлов.')
    end
    imgui.SameLine()
    if imgui.Button('Настройки##checker_settings') then integration.openSettings('adm') end
    imgui.SameLine()
    if imgui.Button('Справка##checker_help') then integration.openHelp('checker') end
    if imgui.CollapsingHeader('Состояние чекера##checker_status') then
        local function status(value) return value and 'вкл.' or 'выкл.' end
        imgui.TextWrapped(('На экране: администраторы — %s; лидеры — %s; друзья — %s.'):format(
            status(config.checker.admins_checker_status), status(config.checker.leaders_checker_status), status(config.checker.friends_checker_status)))
        imgui.TextWrapped(('Данные с сервера — %s; автообновление — %s.'):format(
            status(config.checker.source_updates_enabled), status(config.checker.admin_checker_auto_update)))
        imgui.TextWrapped(('Положение: X %s, Y %s. Шрифт: %s, размер %s.'):format(
            tostring(config.overlay.xpos), tostring(config.overlay.ypos), tostring(config.overlay.font), tostring(config.overlay.font_size)))
        imgui.TextDisabled(('Записей: администраторы — %d; лидеры — %d; друзья — %d.'):format(#admins_nick, #leaders_nick, #friends_nick))
    end
    imgui.Spacing()
    draw_gui_page_buttons()
    imgui.Separator()
    if gui_page.v == 0 then draw_admin_editor()
    elseif gui_page.v == 1 then draw_leader_editor()
    else draw_friend_editor() end
end
integration.draw = imguiOnDrawFrame
integration.drawSettings = function()
    if imgui_loaded and config then draw_settings_editor() end
end

integration.draw=function()
    if not imgui_loaded or not config then return end
    local labels={'Администраторы','Лидеры','Друзья'}
    integration.directoryPage=math.max(2, integration.directoryPage or 2)
    local available=imgui.GetContentRegionAvailWidth()
    local per_row=available>=540 and 3 or (available>=360 and 2 or 1)
    local width=math.min(200,(available-(per_row-1)*8)/per_row)
    if not integration.externalNavigation then
    for i,label in ipairs(labels) do
        if (i-1)%per_row~=0 then imgui.SameLine() end
        local selected=integration.directoryPage==i+1
        if selected then imgui.PushStyleColor(imgui.Col.Button,integration.color(integration.palette.selection)) end
        if imgui.Button(label..'##checker_page',imgui.ImVec2(width,34)) then integration.directoryPage=i+1;imgui.SetScrollY(0) end
        if selected then imgui.PopStyleColor(1) end
    end
    imgui.Separator()
    end
    if integration.directoryPage==2 then draw_admin_editor()
    elseif integration.directoryPage==3 then draw_leader_editor()
    else draw_friend_editor() end
end

parse_admin_line = function(text)
    if text == nil or text == "" then
        return nil, nil, nil
    end

    local parsed_text = cp1251_to_utf8(text)
    local nickname, tracked_id, level = string.match(parsed_text, "([%w_]+)%[(%d+)%]%s*%((S?%d+)%s+lvl%)")
    if nickname == nil then
        nickname, tracked_id, level = string.match(parsed_text, "([%w_]+)%[(%d+)%]%s*%((S%d)%s+lvl%)")
    end

    tracked_id = tonumber(tracked_id)
    level = normalize_admin_level(level)

    if nickname == nil or tracked_id == nil or level == "-1" then
        return nil, nil, nil
    end

    return nickname, tracked_id, level
end

update_admin_from_line = function(text, local_name)
    local nickname, tracked_id, level = parse_admin_line(text)
    if nickname == nil or same_name(local_name, nickname) then
        return false
    end

    local index = find_index_by_name(admins_nick, nickname)
    if index ~= nil and admins_locked[index] == true then
        return false
    end

    if index == nil then
        upsert_admin(nickname, level, tracked_id)
        message(string.format("В чекер добавлен администратор %s [%d], уровень %s.", nickname, tracked_id, level))
        return true
    end

    local old_level = normalize_admin_level(admins_lvl[index])
    local old_id = tonumber(admins_id[index]) or -1
    admins_id[index] = tracked_id

    if old_level ~= level then
        admins_lvl[index] = level
        save_admins()
        message(string.format("Обновлён уровень администратора %s: %s -> %s.", nickname, old_level, level))
        return true
    end

    -- Session IDs are transient: update silently without rewriting the nickname list.
    return old_id ~= tracked_id
end

refresh_s_admins_from_dialog = function(text)
    if text == nil or text == "" then
        return false
    end

    local parsed_text = cp1251_to_utf8(text)
    local parsed = 0
    local added = {}
    local seen = {}
    local removed = {}

    for line in string.gmatch(parsed_text, "[^\r\n]+") do
        local nickname, level = string.match(line, "^([^\t]+)\t([^\t]+)")
        if nickname ~= nil and level ~= nil then
            nickname = trim(nickname)
            level = normalize_admin_level(trim(level))

            if nickname ~= "" and nickname ~= "Ник" and is_youtube_level(level) then
                local key = string.lower(nickname)
                local existing_index = find_index_by_name(admins_nick, nickname)
                local was_known = existing_index ~= nil
                seen[key] = true
                if existing_index == nil or admins_locked[existing_index] ~= true then
                    upsert_admin(nickname, level, nil)
                end
                parsed = parsed + 1

                if not was_known then
                    table.insert(added, {
                        nickname = nickname,
                        level = level
                    })
                end
            end
        end
    end

    if parsed == 0 then
        return false
    end

    for index = #admins_nick, 1, -1 do
        local level = normalize_admin_level(admins_lvl[index])
        local nickname = admins_nick[index]
        local key = string.lower(nickname or "")

        if is_youtube_level(level) and admins_locked[index] ~= true and not seen[key] then
            table.insert(removed, {
                nickname = nickname,
                level = level
            })
            table.remove(admins_nick, index)
            table.remove(admins_lvl, index)
            table.remove(admins_id, index)
            table.remove(admins_role, index)
            table.remove(admins_notify, index)
            table.remove(admins_locked, index)
            table.remove(admins_sound_notify, index)
        end
    end

    if #removed > 0 then
        save_admins()
    end

    sync_online_ids()

    for _, item in ipairs(added) do
        message(string.format("В чекер добавлен S-администратор %s, уровень %s.", format_display_nickname(item.nickname), tostring(item.level)))
    end

    for _, item in ipairs(removed) do
        message(string.format("S-администратор %s удалён из чекера: его нет в /adms.", format_display_nickname(item.nickname)))
    end

    message(string.format("Список S-администраторов обновлён из диалога /adms. Записей: %d, новых: %d, удалено: %d.", parsed, #added, #removed))
    return true
end

refresh_leaders_from_dialog = function(text)
    if text == nil or text == "" then
        return false
    end

    local parsed_text = cp1251_to_utf8(text)
    local old_notify = {}
    local old_sound_notify = {}
    local old_known = {}
    for index, nickname in ipairs(leaders_nick) do
        local key = string.lower(nickname)
        old_notify[key] = leaders_notify[index] ~= false
        old_sound_notify[key] = leaders_sound_notify[index] == true
        old_known[key] = {
            nickname = nickname,
            organization = normalize_leader_org_title(leaders_org_name[index], leaders_org[index])
        }
    end

    local new_nick = {}
    local new_org = {}
    local new_org_name = {}
    local new_notify = {}
    local new_sound_notify = {}
    local new_seen = {}
    local added = {}
    local removed = {}
    local parsed = 0

    for line in string.gmatch(parsed_text, "[^\r\n]+") do
        local nickname, organization = string.match(line, "^([^\t]+)\t([^\t]+)")
        if nickname ~= nil and organization ~= nil then
            nickname = trim(nickname)
            organization = trim(organization)

            if is_valid_leader_row(nickname, organization) then
                local key = string.lower(nickname)
                parsed = parsed + 1
                new_seen[key] = true
                table.insert(new_nick, nickname)
                table.insert(new_org, leader_org_id_from_name(organization))
                table.insert(new_org_name, organization)
                table.insert(new_notify, old_known[key] ~= nil and old_notify[key] == true or true)
                table.insert(new_sound_notify, old_known[key] ~= nil and old_sound_notify[key] == true or false)

                if old_known[key] == nil then
                    table.insert(added, {
                        nickname = nickname,
                        organization = organization
                    })
                end
            end
        end
    end

    if parsed == 0 then
        return false
    end

    for key, item in pairs(old_known) do
        if not new_seen[key] then
            table.insert(removed, item)
        end
    end

    leaders_nick = new_nick
    leaders_org = new_org
    leaders_org_name = new_org_name
    leaders_notify = new_notify
    leaders_sound_notify = new_sound_notify
    leaders_id = {}

    for _ = 1, #leaders_nick do
        table.insert(leaders_id, -1)
    end

    save_leaders()
    sync_online_ids()

    for _, item in ipairs(added) do
        message(string.format("В чекер добавлен лидер %s, фракция: %s.", format_display_nickname(item.nickname), item.organization))
    end

    for _, item in ipairs(removed) do
        message(string.format("Лидер %s удалён из чекера: его нет в /leaders.", format_display_nickname(item.nickname)))
    end

    message(string.format("Список лидеров обновлён из диалога /leaders. Записей: %d, новых: %d, удалено: %d.", parsed, #added, #removed))
    return true
end

function sampOnPlayerJoin(player_id, _, _, nickname)
    nickname = cp1251_to_utf8(nickname)

    for index, tracked_name in ipairs(admins_nick) do
        if same_name(tracked_name, nickname) then
            admins_id[index] = player_id

            if sampIsLocalPlayerSpawned() then
                local level = normalize_admin_level(admins_lvl[index])
                local role_title = get_admin_role_title(index, level)
                local display_name = format_display_nickname(nickname)

                if should_notify_admin(index) then
                    if is_youtube_level(level) and role_title == "YouTube" then
                        message(string.format("%s %s %s подключился к серверу.", role_title, level, display_name))
                    else
                        message(string.format("%s %s подключился к серверу.", role_title, display_name))
                    end
                end

                if should_sound_notify_admin(index) then
                    play_join_notification_sound("admin")
                end
            end

            break
        end
    end

    for index, tracked_name in ipairs(leaders_nick) do
        if same_name(tracked_name, nickname) then
            leaders_id[index] = player_id

            if sampIsLocalPlayerSpawned() then
                local org_title = normalize_leader_org_title(leaders_org_name[index], leaders_org[index])
                if should_notify_leader(index) then
                    message(string.format("Лидер %s %s подключился к серверу.", org_title, format_display_nickname(nickname)))
                end
                if should_sound_notify_leader(index) then
                    play_join_notification_sound("leader")
                end
            end

            break
        end
    end

    for index, tracked_name in ipairs(friends_nick) do
        if same_name(tracked_name, nickname) then
            friends_id[index] = player_id

            if sampIsLocalPlayerSpawned() then
                local display_name = format_display_nickname(nickname)
                if should_notify_friend(index) then
                    if is_best_friend(index) then
                        message(string.format("Лучший друг %s подключился к серверу.", display_name))
                    else
                        message(string.format("Друг %s подключился к серверу.", display_name))
                    end
                end
                if should_sound_notify_friend(index) then
                    play_join_notification_sound("friend")
                end
            end

            break
        end
    end
end

function sampOnPlayerQuit(player_id, _)
    for index, tracked_id in ipairs(admins_id) do
        if tracked_id == player_id then
            admins_id[index] = -1
            if should_notify_admin(index) then
                local level = normalize_admin_level(admins_lvl[index])
                local role_title = get_admin_role_title(index, level)
                local display_name = format_display_nickname(admins_nick[index])

                if is_youtube_level(level) and role_title == "YouTube" then
                    message(string.format("%s %s %s[%d] отключился.", role_title, level, display_name, player_id))
                else
                    message(string.format("%s %s[%d] отключился.", role_title, display_name, player_id))
                end
            end
            break
        end
    end

    for index, tracked_id in ipairs(leaders_id) do
        if tracked_id == player_id then
            leaders_id[index] = -1
            if should_notify_leader(index) then
                local org_title = normalize_leader_org_title(leaders_org_name[index], leaders_org[index])
                message(string.format("Лидер %s %s покинул сервер.", org_title, format_display_nickname(leaders_nick[index])))
            end
            break
        end
    end

    for index, tracked_id in ipairs(friends_id) do
        if tracked_id == player_id then
            friends_id[index] = -1
            if should_notify_friend(index) then
                local display_name = format_display_nickname(friends_nick[index])
                if is_best_friend(index) then
                    message(string.format("Лучший друг %s покинул сервер.", display_name))
                else
                    message(string.format("Друг %s покинул сервер.", display_name))
                end
            end
            break
        end
    end
end

function sampOnServerMessage(color, text)
    if config == nil or not config.checker.admin_checker_auto_update then
        return
    end

    local parsed_text = cp1251_to_utf8(text)
    if string.find(parsed_text, "Админы онлайн", 1, true) then
        start_admin_refresh()
        return
    end

    local local_name = nil
    local ok, player_id = sampGetPlayerIdByCharHandle(PLAYER_PED)
    if ok then
        local_name = cp1251_to_utf8(sampGetPlayerNickname(player_id))
    end

    update_admin_from_line(text, local_name)

    if admin_refresh_active then
        local nickname = parse_admin_line(text)
        if nickname ~= nil then
            admin_refresh_seen_nicks[string.lower(nickname)] = true
            admin_refresh_last_line_at = os.clock()
        end
    end
end

function sampOnShowDialog(dialog_id, style, title, button1, button2, text)
    local raw_title = tostring(title or '')
    local parsed_title = cp1251_to_utf8(raw_title)
    local is_leaders_dialog = string.find(parsed_title, 'Лидеры', 1, true) or string.find(raw_title, 'Лидеры', 1, true)
    local handled_refresh_dialog = false

    if style == 5 and dialog_id == 424 and is_leaders_dialog then
        refresh_leaders_from_dialog(text)
        handled_refresh_dialog = true
    elseif style == 5 and dialog_id == 0 and string.find(parsed_title, "Администраторы S уровня", 1, true) then
        refresh_s_admins_from_dialog(text)
        handled_refresh_dialog = true
    end

    if auto_close_refresh_dialogs and handled_refresh_dialog then
        lua_thread.create(function()
            wait(80)
            close_current_dialog_safely()
        end)
    end
end

function integration.start()
    while not isSampAvailable() do
        wait(200)
    end

    while sampGetGamestate() ~= 3 do
        wait(500)
    end

    if not is_target_server() then
        unload_on_wrong_server()
        return
    end

    if doesFileExist("moonloader\\lib\\MoonImGui.dll") and doesFileExist("moonloader\\lib\\imgui.lua") then
        imgui = require("imgui")
        imgui.Process = false
        imgui.ShowCursor = false
        imgui_loaded = true
        init_imgui_state()
    end

    ensure_environment()
    load_config()
    load_all_lists()
    reload_font()
    refresh_gui_buffers()

    sync_online_ids()
    if not imgui_loaded then message("Интерфейс чекера недоступен: библиотека ImGui не найдена.") end

    while true do
        wait(0)

        if sampGetGamestate() ~= 3 then
            clear_online_ids()
        else
            if not is_target_server() then
                unload_on_wrong_server()
                return
            end

            if os.clock() - last_sync > 5 then
                sync_online_ids()
                last_sync = os.clock()
            end

            if admin_refresh_active and os.clock() - admin_refresh_last_line_at > 1.2 then
                finalize_admin_refresh()
            end

            if not isPauseMenuActive() then
                draw_overlay()
            end

            handle_overlay_drag()
        end
    end
end

integration.onDisconnect = function() clear_online_ids() end

integration.protectedLists = function(reload)
    if reload then load_all_lists() end
    local result={admins={},leaders={}}
    for _,name in ipairs(admins_nick) do result.admins[#result.admins+1]=name end
    for _,name in ipairs(leaders_nick) do result.leaders[#result.leaders+1]=name end
    return result
end

integration.isKnownAdmin = function(nickname)
    nickname = string.lower(nickname or '')
    for _, list in ipairs({admins_nick, leaders_nick}) do
        for _, name in ipairs(list) do if string.lower(name) == nickname then return true end end
    end
    return false
end

