    cachePlayerColorById(playerId, color, "live")
    requestCaptureOverlayRefresh()
end

function sampev.onPlayerStreamIn(playerId, team, model, position, rotation, color, fightingStyle)
    markPlayerOnlineById(playerId, true)
    cachePlayerColorById(playerId, color, "live")
    requestCaptureOverlayRefresh()
