        if index==math.ceil(#GANGS.list/2)+1 then integration.layout.next(columns) end
        imgui.TextWrapped(string.format('%s: %d', gang.display, tonumber(stats[gang.key]) or 0))
    end
    integration.layout.finish(columns)
    imgui.Spacing()
    APP.uiButton('Показать в моём чате', function() showGangStatsToMe(getOnlineGangStatsDirect()) end)
    if imgui.GetContentRegionAvailWidth() >= 460 then imgui.SameLine() end
    APP.uiButton('Отправить в /a', function() sendGangStatsToAdminChat(getOnlineGangStatsDirect()) end)
    APP.uiButton('Отправить онлайн в Discord', function()
        sendPreparedGangStatsToDiscord('Онлайн банд', nil, 'онлайн банд')
    end)
    APP.uiButton('Собрать исключения из диалога 66', startDialog66WhiteScan)
end

function APP.uiRecovery()
    local data = DATA.recoveryFileInfo
    imgui.TextWrapped(data and 'Есть сохранение незавершённого капта' or 'Нет сохранения незавершённого капта')
    if data then
        imgui.TextWrapped(data.start_line or '')
        imgui.Text('С начала капта: ' .. getRecoveryAgeText(data.start_at))
        imgui.Text('Фраги: ' .. tostring(data.total or 0))
    end
    imgui.Text('Последний капт: ' .. (DATA.lastCapture and 'сохранён' or 'нет данных'))
    APP.uiButton('Восстановить капт', resumeCaptureFromRecovery)
    if imgui.GetContentRegionAvailWidth() >= 480 then imgui.SameLine() end
    APP.uiButton('Обновить состояние', function()
        restoreRecoveryInfo()
        DATA.lastCapture = loadCaptureDataFromFile(PATHS.LAST_CAPTURE_STATE_FILE)
    end)
    imgui.Spacing()
    APP.uiButton('Сбросить сбор и удалить сохранение', dropCaptureRecovery)
    imgui.TextWrapped('Сброс останавливает текущий сбор и удаляет сохранение незавершённого капта. Отчёт о последнем завершённом капте сохраняется.')
end


function APP.uiWebhook(label, buffer, key)
    imgui.Text(label)
    imgui.PushItemWidth(math.min(540, imgui.GetContentRegionAvail().x - 12))
    local flags = type(imgui.InputTextFlags) == 'table' and imgui.InputTextFlags.Password or 0
