        local ok, why = sendDiscordEmbed(buffer.v, 'X-Tools — проверка канала',
            'Канал настроен и доступен.', 11507455, 'X-Tools')
        if not ok then chatError(tostring(why)) else chatInfo('Тестовое сообщение отправляется в Discord.') end
    end)
end

integration.draw = function()
    if not BOOLS.saveStatsBool then imgui.Text('Подготовка данных каптов…'); return end
    UI.section.v=math.max(0,math.min(3,UI.section.v))
    if imgui.Combo('Раздел##capture_page', UI.section, 'Текущий капт\0Онлайн банд\0Восстановление\0Справка\0\0') then
        imgui.SetScrollY(0)
    end
    imgui.Separator()
    if UI.section.v == 0 then APP.uiCapture()
    elseif UI.section.v == 1 then APP.uiOnline()
    elseif UI.section.v == 2 then APP.uiRecovery()
    else
        imgui.TextWrapped('Капты: фраги, наказания, онлайн и отчёты. При позднем входе начните сбор вручную; после обрыва связи используйте восстановление.')
        APP.uiButton('Открыть справку по каптам##capture_help', function() integration.openHelp('capture') end)
        APP.uiButton('Открыть настройки каптов##capture_settings_link', function() integration.openSettings('capture') end)
    end
end

integration.drawSettings = function()
    if not BOOLS.saveStatsBool then imgui.Text('Подготовка настроек каптов…'); return end
    UI.settingsSection.v=math.max(0,math.min(3,UI.settingsSection.v))
    if imgui.Combo('Параметры##capture_settings', UI.settingsSection, 'Основные\0Панели в игре\0Discord\0Слежка\0\0') then
