        APP.uiCheckbox('Уведомлять о сериях убийств', 'streakAlertsBool')
        APP.uiCheckbox('Начало, инициатор и итог капта', 'fragShowMessagesBool')
        APP.uiCheckbox('Показывать убийства во время капта', 'fragShowKillsBool')
        APP.uiCheckbox('Сообщать о записи наказания в журнал', 'punishShowInChatBool')
        integration.layout.finish(columns)
    elseif UI.settingsSection.v == 1 then
        APP.uiCheckbox('Показывать участников капта', 'captureOverlayEnabledBool')
        APP.uiCheckbox('Показывать топ-6 игроков по фрагам', 'captureTopOverlayEnabledBool')
        for _,panel in ipairs({{'Участники','captureOverlay'},{'Мини-топ','captureTopOverlay'}})do
            if imgui.Button('Переместить: '..panel[1]..'##capture')then
                local prefix=panel[2];local previous=DATA.overlayTestActive
                if not previous then toggleTestOverlay()end
                integration.beginPlacement(function()saveConfig();if not previous then toggleTestOverlay()end end,function()
                    local x,y=getCursorPos();local sw,sh=getScreenResolution()
                    INTS[prefix..'XBuffer'].v=math.max(0,math.min(x,sw-100))
                    INTS[prefix..'YBuffer'].v=math.max(0,math.min(y,sh-40))
                end)
            end
        end
        if imgui.CollapsingHeader('Расположение панелей##capture') then
            local sw, sh = getScreenResolution()
            APP.uiInt('Участники: X', 'captureOverlayXBuffer', 0, sw - 20)
            APP.uiInt('Участники: Y', 'captureOverlayYBuffer', 0, sh - 20)
            APP.uiInt('Ширина', 'captureOverlayWidthBuffer', 220, sw)
            APP.uiInt('Высота', 'captureOverlayHeightBuffer', 80, sh)
            APP.uiInt('Расстояние между столбцами', 'captureOverlayGapBuffer', 0, 300)
            APP.uiInt('Мини-топ: X', 'captureTopOverlayXBuffer', 0, sw - 20)
            APP.uiInt('Мини-топ: Y', 'captureTopOverlayYBuffer', 0, sh - 20)
        end
        APP.uiButton(DATA.overlayTestActive and 'Скрыть предпросмотр панели' or 'Показать предпросмотр панели', toggleTestOverlay)
    elseif UI.settingsSection.v == 2 then
        APP.uiCheckbox('Разрешить отправку в Discord', 'discordEnabledBool')
        imgui.TextWrapped('Включите отправку и укажите вебхуки нужных каналов. Кнопка «Отправить тест» отправляет настоящее сообщение в выбранный канал.')
        if not effil then imgui.TextWrapped('Discord недоступен: не установлена библиотека effil. Локальные функции доступны.') end
        local columns = integration.layout.begin('capture_discord', 780)
        integration.layout.heading('Что отправлять')
        APP.uiCheckbox('Онлайн автоматически на старте капта', 'autoOnlineOnCaptureStartBool')
        APP.uiCheckbox('Отправлять сводку капта', 'fragSendSummaryBool')
        APP.uiCheckbox('Отправлять топ по фрагам', 'fragSendTopBool')
        APP.uiCheckbox('Отправлять список убийств', 'fragSendDetailsBool')
        if imgui.CollapsingHeader('Оформление отчётов##capture') then
            APP.uiInt('Поправка времени отчётов, мин.', 'discordTimeOffsetBuffer', -1440, 1440)
            APP.uiInt('Цвет отчёта', 'fragEmbedColorBuffer', 0, 16777215)
            APP.uiInt('Цвет наказаний', 'punishEmbedColorBuffer', 0, 16777215)
            APP.uiInt('Цвет онлайна', 'onlineEmbedColorBuffer', 0, 16777215)
        end
        integration.layout.next(columns)
        integration.layout.heading('Каналы Discord')
        APP.uiWebhook('Вебхук отчётов о каптах', BUFF.fragWebhookBuffer, 'frag')
        APP.uiWebhook('Вебхук наказаний', BUFF.punishWebhookBuffer, 'punish')
        APP.uiWebhook('Вебхук онлайна банд', BUFF.onlineWebhookBuffer, 'online')
        integration.layout.finish(columns)
    elseif UI.settingsSection.v == 3 then
        APP.uiCheckbox('Предлагать слежку за убийцей', 'followEnabledBool')
        local columns = integration.layout.begin('capture_follow', 740)
        integration.layout.heading('Клавиша слежки')
        integration.keys:draw(imgui,'capture_follow')
        integration.layout.next(columns)
        integration.layout.heading('Предложение и команда')
        APP.uiInt('Показывать предложение, сек.', 'followPromptSecondsBuffer', 1, 60)
        imgui.TextWrapped('Шаблон команды слежки: %d заменяется на ID, %s — на ник игрока.')
        imgui.PushItemWidth(math.min(300, imgui.GetContentRegionAvailWidth()))
        if imgui.InputText('##capture_follow_command', BUFF.followCommandBuffer) then saveConfig() end
        imgui.PopItemWidth()
        integration.layout.finish(columns)
    end
end

integration.onDisconnect = function()
    persistActiveCaptureState()
    saveLastCaptureSnapshot()
    APP.session = APP.session + 1
    for id, worker in pairs(THREADS.active) do pcall(function() worker:cancel() end); THREADS.active[id] = nil end
    APP.shutdownSkeletal()
    APP.shutdownCustomNametags()
    DATA.customNametags.originalSettings = nil
    DATA.pendingDeathEvents = {}
    DATA.streaks = {}
    DATA.playerNamesById = {}
    DATA.onlinePlayersById = {}
    DATA.playerColorsById = {}
    DATA.playerColorSourceById = {}
    DATA.onlineStatsCollectActive = false
    DATA.onlineStatsCollectCallbacks = {}
    DATA.onlineStatsStabilized = false
    DATA.onlineWarmupUntil = os.clock() + CONST.ONLINE_INITIAL_WARMUP_SECONDS
    DATA.onlineSnapshotRefreshAt = 0
    DATA.deferredCaptureAutoSend = nil
    DATA.discordPendingRequests = 0
    DATA.discordSequenceWorkers = 0
    DATA.captureDiscordClosed = false
    DATA.overlayTestActive = false
    DATA.overlayTestEntries = {}
    resetDialog66WhiteScan()
    resetFollowPrompt()
    resetCapture()
    restoreRecoveryInfo()
end

integration.suspend = integration.onDisconnect

-- Compact read-only state for dashboard/diagnostics and offline regression tests.
integration.status = function()
    return {active = STATE.capture.active, frags = STATE.capture.total, punishments = #STATE.capture.punishes,
        discordEnabled = CFG.main.discord_enabled,
        recovery = DATA.recoveryFileInfo ~= nil, generation = APP.session}
end

function APP.checkNativeSupport(feature)
    APP.nativeGuard = APP.nativeGuard or integration.service('capture_native.lua')
    local read = function(address, length) return APP.ffi.string(APP.ffi.cast('const char*', address), length) end
    return APP.nativeGuard.check(read, getModuleHandle('samp.dll'), getModuleHandle('gta_sa.exe'), feature, DATA.customNametags)
end

function APP.rejectNativeFeature(feature, reason)
    if feature == 'nametags' then
        CFG.main.custom_nametags_enabled = false
        if BOOLS.customNametagsBool then BOOLS.customNametagsBool.v = false end
    else
        CFG.main.skeletal_enabled = false
        if BOOLS.skeletalBool then BOOLS.skeletalBool.v = false end
    end
    saveConfig()
    chatError(tostring(reason) .. '. Функция выключена.')
end

integration.drawVisualSettings=function()
    if not BOOLS.longRangeLabelsBool then return end
APP.uiCheckbox('Показывать 3D-текст на большом расстоянии', 'longRangeLabelsBool')
APP.uiCheckbox('Использовать свои подписи и полоски здоровья', 'customNametagsBool')
APP.uiCheckbox('Показывать скелеты игроков', 'skeletalBool')
end

    end
    sources["modules/clickwarp.lua"] = function()
-- Selected click-warp behaviour by FYP / we_sux / Sambrero, shared input ownership.
local g=require('imgui')
local settings=integration.service('combo_settings.lua')
local cfg,path=settings.load(integration,'clickwarp',{main={enabled=false}})
local packets=integration.service('sync_packets.lua').new(_G)
local selecting,target,point,marker=false,nil,nil,nil
local function removeMarker()if marker then removeUser3dMarker(marker);marker=nil end end
local function cancel()
    selecting=false;target=nil;point=nil;removeMarker();integration.refreshInput()
end
local function start()
    if selecting then cancel();return end
    if not cfg.main.enabled or not integration.access:require(1,integration.message)then return end
    local player=integration.observation()
    if not player then integration.message('ClickWarp: сначала начните слежку за игроком.');return end
    target={id=player.id,nickname=player.nickname};selecting=true;integration.refreshInput()
end
integration.keys:register('clickwarp','ClickWarp — выбрать точку в слежке',{key=4,second=0})
integration.keys:register('clickwarp_apply','ClickWarp — переместить игрока',{key=1,second=0})
integration.begin=start
integration.ownsMarkerInput=function()return integration.observation()~=nil end
integration.onDisconnect=cancel
integration.stop=cancel
integration.onAccessChanged=cancel
integration.reconcilePointer=function(windowVisible)
    local observed=selecting and integration.observation()
    if selecting and (windowVisible or not observed or observed.id~=target.id or observed.nickname~=target.nickname) then
        selecting=false;target=nil;point=nil;removeMarker()
    end
end
integration.hudActive=function()return selecting,selecting,false end
integration.update=function()
    local toggle=integration.keys:pressed('clickwarp')
    local apply=integration.keys:pressed('clickwarp_apply')
    local input=not integration.windowOpen() and isGameWindowForeground() and not isPauseMenuActive() and not sampIsChatInputActive() and not sampIsDialogActive()
    if selecting and (not input or not cfg.main.enabled or sampGetGamestate()~=3 or not integration.access:can(1))then cancel();return end
    if toggle and input and integration.observation()~=nil and sampGetGamestate()==3 and (selecting or not sampIsCursorActive())then start() end
    if not selecting then return end
    if isKeyDown(27)then cancel();return end
    local observed=integration.observation()
    if not observed or observed.id~=target.id or observed.nickname~=target.nickname
        or not sampIsPlayerConnected(target.id) or sampGetPlayerNickname(target.id)~=target.nickname then cancel();return end
    local sx,sy=getCursorPos();local sw,sh=getScreenResolution()
    point=nil;removeMarker()
    if sx<0 or sy<0 or sx>=sw or sy>=sh then return end
    local x,y,z=convertScreenCoordsToWorld3D(sx,sy,700)
    local cx,cy,cz=getActiveCameraCoordinates()
    local hit,p=processLineOfSight(cx,cy,cz,x,y,z,true,true,false,true,false,false,false)
    if not hit or not p or p.entity==0 then return end
    local n=p.normal;x=p.pos[1]-n[1]*0.1;y=p.pos[2]-n[2]*0.1;z=p.pos[3]-n[3]*0.1
    local ground,q=processLineOfSight(x,y,z+(n[3]>=0.5 and 1 or 300),x,y,z-0.3,true,true,false,true,false,false,false)
    if not ground or not q then return end
    point={q.pos[1],q.pos[2],q.pos[3]+1.2}
    marker=createUser3dMarker(point[1],point[2],point[3]+0.1,4)
    if apply then
        -- One snapshot; player sync is not suppressed during normal server spectating.
        if packets.onfoot(point[1],point[2],point[3]) then sampSendChat('/gethere '..target.id..' 1')end
        cancel()
    end
end
integration.drawSettings=function()
    if settings.toggle(g,'ClickWarp — перенос игрока мышью в слежке',cfg.main,'enabled')then
        if not cfg.main.enabled then cancel()end;integration.storage:saveIni(cfg,path)
    end
    integration.keys:draw(g,'clickwarp');integration.keys:draw(g,'clickwarp_apply')
    if g.Button('Выбрать точку##clickwarp')then start()end
    g.TextWrapped('В слежке включите выбор точки назначенной клавишей. Маркер показывает место переноса; подтверждение — ЛКМ по умолчанию. Esc отменяет. Колёсико включает выбор точки; повторное нажатие отменяет. ЛКМ переносит игрока и убирает метку.')
end

    end
    sources["modules/correction.lua"] = function()
-- CorrectionWords by Royan Millans, using Yandex Speller; no background check while disabled.
local g=require('imgui');local u8=require('encoding').UTF8;local events=require('lib.samp.events')
local settings=integration.service('combo_settings.lua')
integration.keys:register('correction_apply','Коррекция: применить подсказку',{key=113})
local cfg,path=settings.load(integration,'correction',{main={enabled=false,mode=2,hint=true,auto_upper_and_point=true}})
local generation,serial=0,0;local pending,undo=nil,nil;local sending=false;local hintShown=false
local function save()integration.storage:saveIni(cfg,path)end
integration.onDisconnect=function()generation=generation+1;serial=serial+1;pending=nil;undo=nil;hintShown=false end
integration.stop=integration.onDisconnect
local channels={b=true,n=true,a=true,ad=true,s=true,w=true,r=true,f=true,me=true,["do"]=true,todo=true}
local function split(raw)
    if raw:sub(1,1)~='/'then return '',raw end
    local cmd,rest=raw:match('^/(%w+)%s+(.+)$');if not cmd then return end
    if channels[cmd:lower()]then return '/'..cmd..' ',rest end
    if cmd:lower()=='ans'then local id,text=rest:match('^(%d+)%s+(.+)$');if id then return '/ans '..id..' ',text end end
end
local function prepare(text)
    if not cfg.main.auto_upper_and_point then return text end
    local first=text:byte(1);if not first then return text end
    local upper=first>=224 and first<=255 and string.char(first-32)or first==184 and string.char(168)or text:sub(1,1):upper()
    text=upper..text:sub(2);if not text:find('[.!?:]$')then text=text..'.'end;return text
end
local function replaceWords(text,words)
    local suggestions={};local done={}
    for _,entry in ipairs(words)do
        if type(entry)=='table' and type(entry.word)=='string' and type(entry.s)=='table'and type(entry.s[1])=='string'then
            local wrong,right=u8:decode(entry.word),u8:decode(entry.s[1])
            if wrong~=''and not done[wrong]then
                text=text:gsub(wrong:gsub('([^%w])','%%%1'),function()return right end)
                suggestions[#suggestions+1]=right;done[wrong]=true
            end
        end
    end
    return text,table.concat(suggestions,', ')
end
local function request(text,done,latestOnly)
    local token=generation;serial=serial+1;local ticket=serial
    local url='https://speller.yandex.net/services/spellservice.json/checkText?text='..tostring(u8(text)):gsub('([^%w%-_%.~])',function(c)return string.format('%%%02X',c:byte())end)
    local ok,lanes=pcall(require,'lanes')
    if not ok then integration.message('Коррекция: библиотека lanes недоступна.');return false end
    local setup,worker=pcall(function()
        if type(lanes.configure)=='function'then lanes=lanes.configure()end
        -- Source is compiled in the worker, without copying the module environment.
        return lanes.gen('*',{package={path=package.path,cpath=package.cpath}},[=[
            local address=...
            local requests=require('requests')
            local r=requests.get(address,{timeout=8})
            return r.status_code,r.text
        ]=])(url)
    end)
    if not setup then integration.message('Коррекция: не удалось запустить проверку.');return false end
    lua_thread.create(function()
        local deadline=os.clock()+10
        while worker.status~='done'and worker.status~='error'and os.clock()<deadline do
            if token~=generation or not cfg.main.enabled then pcall(function()worker:cancel()end);return end
            wait(50)
        end
        if token~=generation or latestOnly and ticket~=serial or not cfg.main.enabled then return end
        if worker.status~='done'or worker[1]~=200 then integration.message('Коррекция: ошибка сервиса. Текст сохранён в поле чата.');return end
        local valid,data=pcall(decodeJson,worker[2]);if not valid or type(data)~='table'then integration.message('Коррекция: некорректный ответ сервиса.');return end
        done(replaceWords(text,data))
    end)
    return true
end
local function send(text)
    if #text>144 or text:find('[%z\1-\31]')then integration.message('Исправленный текст слишком длинный или содержит управляющие символы.');return end
    sending=true;sampSendChat(text);sending=false
end
local function check(raw,input,display)
    local prefix,text=split(raw);if not text or text==''then return end
    local original=raw;text=prepare(text)
    local mode=cfg.main.mode
    local started=request(text,function(corrected,suggestions)
        if input then
            if sampIsChatInputActive()and sampGetChatInputText()==original then undo=original;sampSetChatInputText(prefix..corrected)end
        elseif display then integration.message(tostring(u8(prefix..corrected)))
        elseif mode==1 then send(prefix..corrected)
        elseif suggestions~=''then pending={text=suggestions,prefix=prefix,mode=mode};integration.message('Найдены ошибки: '..tostring(u8(suggestions))..'. '..integration.keys:name('correction_apply')..' — '..(mode==3 and 'копировать.'or 'отправить исправление.'))end
    end,input or (mode~=1 and not display))
    if started and mode==1 and not input and not display then sampSetChatInputText(original);return false end
end
function events.onSendChat(text)
    if cfg.main.enabled and not sending and not integration.commandOwner()then return check(text)end
end
function events.onSendCommand(text)
    if cfg.main.enabled and not sending and not integration.commandOwner()then return check(text)end
end
integration.update=function()
    if integration.keys:captureActive() or integration.windowOpen() or not cfg.main.enabled or sampGetGamestate()~=3 then return end
    if not isGameWindowForeground()or isPauseMenuActive()or sampIsDialogActive()then return end
    if sampIsChatInputActive()then
        if isKeyDown(17)and isKeyJustPressed(88)then check(sampGetChatInputText(),true)end
        if isKeyDown(17)and isKeyJustPressed(90)and undo then serial=serial+1;sampSetChatInputText(undo);undo=nil end
    elseif integration.keys:pressed('correction_apply')and pending then
        if pending.mode==3 then setClipboardText(pending.text)else send(pending.prefix..'Кхе.. '..pending.text..'.')end;pending=nil
    end
end
integration.start=function()
    sampRegisterChatCommand('checkw',function(text)if cfg.main.enabled then check(text,false,true)end end)
end
integration.drawSettings=function()
    local enabled=g.ImBool(cfg.main.enabled)
    if g.Checkbox('Коррекция текста',enabled)then cfg.main.enabled=enabled.v;integration.onDisconnect();save()end
    if not cfg.main.enabled then return end
    g.TextWrapped('Проверка текста через Яндекс Спеллер. Ctrl+X — исправить ввод, Ctrl+Z — вернуть, Применение подсказки — по назначенной клавише. Команды авторизации и параметры игровых действий не проверяются.')
    integration.keys:draw(g,'correction_apply')
    local mode=g.ImInt(math.max(0,math.min(2,cfg.main.mode-1)));g.PushItemWidth(310)
    if g.Combo('Режим коррекции',mode,'Исправить до отправки\0Подсказка после отправки\0Копировать исправления\0\0')then cfg.main.mode=mode.v+1;integration.onDisconnect();save()end
    g.PopItemWidth()
    if settings.toggle(g,'Заглавная буква и точка',cfg.main,'auto_upper_and_point')then save()end
end

    end
    sources["modules/environment.lua"] = function()
-- Local weather/time from setWeather&Time; no version-specific memory patch.
local imgui, sampev = require 'imgui', require 'samp.events'
local storage = integration.storage
local CONFIG = storage:path('settings', 'environment.ini', {getWorkingDirectory() .. '/config/CasualAT_environment.ini'})
local cfg = storage:loadIni({environment={time_enabled=false,weather_enabled=false,hour=12,weather=0}}, CONFIG) or {}
cfg.environment=type(cfg.environment)=='table' and cfg.environment or {}
local settings = cfg.environment
local function bounded(value, maximum, fallback)
    value=tonumber(value)
    if not value or value~=value or value<0 or value>maximum then return fallback end
    return math.floor(value)
end
settings.hour=bounded(settings.hour,23,12)
settings.weather=bounded(settings.weather,45,0)
settings.time_enabled=settings.time_enabled==true
settings.weather_enabled=settings.weather_enabled==true
local serverHour,serverMinute,serverWeather,timeApplied,weatherApplied
local function save() storage:saveIni(cfg,CONFIG) end
local function connected() return isSampAvailable() and sampGetGamestate()==3 end
local function restoreTime()
    if timeApplied and serverHour then setTimeOfDay(serverHour,serverMinute or 0) end
    timeApplied=false
end
local function restoreWeather()
    if weatherApplied then
        if serverWeather then forceWeatherNow(serverWeather)
        elseif type(releaseWeather)=='function' then releaseWeather() end
    end
    weatherApplied=false
end
local function apply()
    if not connected() then return end
    if settings.time_enabled then
        if not timeApplied and type(getTimeOfDay)=='function' then
            serverHour,serverMinute=getTimeOfDay()
        end
        setTimeOfDay(settings.hour,0); timeApplied=true
    elseif timeApplied then restoreTime() end
    if settings.weather_enabled then
        if not weatherApplied then forceWeatherNow(settings.weather) end
        weatherApplied=true
    elseif weatherApplied then restoreWeather() end
end

function sampev.onInitGame(playerId,hostName,world,vehicleModels,vehicleFriendlyFire)
    if type(world)~='table' then return end
    serverHour,serverMinute,serverWeather=world.worldTime,0,world.worldWeather
    timeApplied,weatherApplied=settings.time_enabled,settings.weather_enabled
    if not timeApplied and not weatherApplied then return end
    local patched={}; for key,value in pairs(world) do patched[key]=value end
    if timeApplied then patched.worldTime=settings.hour end
    if weatherApplied then patched.worldWeather=settings.weather end
    return {playerId,hostName,patched,vehicleModels,vehicleFriendlyFire}
end
function sampev.onSetPlayerTime(hour,minute)
    serverHour,serverMinute=hour,minute
    if settings.time_enabled then return {settings.hour,0} end
end
function sampev.onSetWorldTime(hour)
    serverHour,serverMinute=hour,0
    if settings.time_enabled then return {settings.hour} end
end
function sampev.onSetWeather(weather)
    serverWeather=weather
    if settings.weather_enabled then return {settings.weather} end
end
local function command(kind,arg)
    arg=tostring(arg or ''):match('^%s*(.-)%s*$'):lower()
    local enabled=kind=='time' and 'time_enabled' or 'weather_enabled'
    local key=kind=='time' and 'hour' or 'weather'
    local maximum=kind=='time' and 23 or 45
    if arg=='' or arg=='off' then
        settings[enabled]=false
        if kind=='time' then restoreTime() else restoreWeather() end
    elseif arg:match('^%d+$') and tonumber(arg)<=maximum then
        settings[key],settings[enabled]=tonumber(arg),true
        if kind=='weather' then weatherApplied=false end
        apply()
    else
        integration.message((kind=='time' and '/st' or '/sw')..' 0–'..maximum..'. Без аргумента или с off — вернуть серверное значение.')
        return
    end
    save()
end
function integration.start()
    while true do
        apply()
        wait(settings.time_enabled and connected() and 0 or 250)
    end
end
integration.drawSettings=function()
    imgui.Text('Локальное время и погода')
    imgui.TextWrapped('Выберите время и погоду для своей игры. Чтобы изменить погоду на сервере, откройте «Инструменты» → «Погода».')
    imgui.Spacing()
    local time=imgui.ImBool(settings.time_enabled)
    if imgui.Checkbox('Зафиксировать время суток',time) then settings.time_enabled=time.v; apply(); save() end
    local hour=imgui.ImInt(settings.hour)
    imgui.PushItemWidth(150)
    if imgui.InputInt('Час суток: 0–23',hour) then settings.hour=bounded(hour.v,23,settings.hour); apply(); save() end
    imgui.PopItemWidth(); imgui.Spacing()
    local weather=imgui.ImBool(settings.weather_enabled)
    if imgui.Checkbox('Зафиксировать погоду',weather) then settings.weather_enabled=weather.v; apply(); save() end
    local id=imgui.ImInt(settings.weather)
    imgui.PushItemWidth(150)
    if imgui.InputInt('ID погоды: 0–45',id) then settings.weather=bounded(id.v,45,settings.weather); weatherApplied=false; apply(); save() end
    imgui.PopItemWidth(); imgui.Spacing()
    imgui.TextWrapped('Снимите галочку, чтобы вернуть серверное значение. Изменения сохраняются автоматически.')
end
integration.draw=integration.drawSettings
integration.onDisconnect=function()
    restoreTime(); restoreWeather()
    serverHour,serverMinute,serverWeather=nil,nil,nil
end
function integration.stop() restoreTime(); restoreWeather() end

integration.setLocalValue=command

    end
    sources["modules/familia.lua"] = function()
-- CasualAT module. Author: Casual Alvarez. Original source: integration/sources.
require 'lib.moonloader'
local events = require 'lib.samp.events'
local encoding = require 'encoding'
encoding.default = 'CP1251'
local u8 = encoding.UTF8

-- Source is UTF-8; SA-MP strings are CP1251.
local TIMEOUT, GAP = 8, 1.2
local queue, pending = {}, nil
local nextRequest = 0
local watching, target, header = false, nil, nil
local family, internal = nil, false
local enabled, generation = integration.featureAllowed(), 0
local accessRevision = integration.access:revision()
local replyPath=integration.storage:path('settings','family-replies.ini')
local replyExists=integration.storage:exists(replyPath)
local replies=integration.storage:loadIni({main={enabled=false,delay=2,cooldown=15,color=1724645631,return_delay=15}},replyPath)
if not replyExists then
    local old=integration.storage:loadIni({main={}},integration.storage:path('settings','autoreply.ini'))
    replies.main.enabled=old.main.family_answers==true
    replies.main.delay=tonumber(old.main.reply_delay) or 2
    replies.main.cooldown=tonumber(old.main.message_cooldown) or 15
    replies.main.return_delay=old.main.afk_protect==false and 0 or tonumber(old.main.return_delay) or 15
    replies.main.color=tonumber(old.main.strict_color) or 1724645631
    integration.storage:saveIni(replies,replyPath)
end
local keywordParser=integration.service('family_question.lua')
local keywordPath=integration.storage:path('settings','family-keywords.ini')
local keywordConfig=integration.storage:loadIni({main={count=-1},words={}},keywordPath)
local keywords,keywordBuffers={},{}
if tonumber(keywordConfig.main.count)==-1 then
    for i,word in ipairs(keywordParser.defaults)do keywords[i]=word end
else
    for i=1,math.min(100,math.max(0,tonumber(keywordConfig.main.count)or 0))do
        keywords[i]=tostring(keywordConfig.words['word'..i]or '')
    end
end
local replyGeneration,replyRecent,replyAway,replyReturned=0,{},false,-100000
local function replyReady()
    local time=getGameTimer()/1000
    if not isGameWindowForeground() or isPauseMenuActive() or isGamePaused() then replyAway=true;return false end
    if replyAway then replyAway=false;replyReturned=time end
    return time-replyReturned>=replies.main.return_delay
end

local function now() return getGameTimer() / 1000 end
local function trim(s) return (s or ''):match('^%s*(.-)%s*$') end
local function clean(s) return trim((s or ''):gsub('{%x+}', '')) end
-- Server statistics may uppercase account names; SA-MP nicknames are ASCII.
-- Keep the original spelling for commands and player-ID ownership checks.
local function sameAccountName(a, b)
    if not a or not b then return false end
    a, b = clean(a), clean(b)
    return a ~= '' and b ~= '' and a:lower() == b:lower()
end
local function say(s) sampAddChatMessage(u8:decode('{F4C542}[X-Tools]{FFFFFF} ' .. s), -1) end
local function syncAccess()
    local revision = integration.access:revision()
    if revision ~= accessRevision then
        accessRevision = revision
        generation = generation + 1
        queue, family = {}, nil
        if pending then pending.cancelled = true end
    end
end
local function send(s)
    internal = true
    sampSendChat(u8:decode(s))
    internal = false
end
local function nickname(id)
    if id and id >= 0 and id <= 1003 and sampIsPlayerConnected(id) then
        return tostring(u8(sampGetPlayerNickname(id)))
    end
end
local function enqueue(job)
    syncAccess()
    if not integration.access:require(1, say) then return end
    if #queue >= 10 then say('Очередь запросов заполнена. Команду можно повторить после её освобождения.'); return end
    job.accessRevision = accessRevision
    queue[#queue + 1] = job
    return true
end
local function observe(id)
    watching = true
    if target == id then return end
    target, family = id, nil
    if not enabled or not integration.access:can(1) then return end
    -- Drop obsolete overlay requests, preserve all punishments.
    for i = #queue, 1, -1 do
        if queue[i].kind == 'view' then table.remove(queue, i) end
    end
    local name = nickname(id)
    if name then enqueue({kind = 'view', id = id, name = name}) end
end
local function punish(kind, raw)
    if not enabled then say('Работа с семьями выключена. Включение: Настройки → Семьи или /familia.'); return end
    if not integration.access:require(1, say) then return end
    local args = trim(tostring(u8(raw)))
    local id, amount, reason
    if kind == 'warn' then id, reason = args:match('^(%d+)%s+(.+)$')
    else id, amount, reason = args:match('^(%d+)%s+(%d+)%s+(.+)$') end
    id = tonumber(id)
    if not id or not reason or trim(reason) == '' or (kind ~= 'warn' and tonumber(amount) < 1) then
        say(kind == 'warn' and 'Использование: /fw ID причина' or
            (kind == 'jail' and 'Использование: /fj ID минуты причина' or 'Использование: /fb ID дни причина'))
        return
    end
    local name = nickname(id)
    if not name then say('Игрок с указанным ID не в сети.'); return end
    enqueue({kind = kind, id = id, name = name, amount = amount, reason = trim(reason)})
end
local function answerFamily(recipient, subject, guard, delay)
    if not enabled or not integration.featureAllowed() then return false end
    recipient=tonumber(recipient)
    subject=integration.service('family_question.lua').target(subject)
    if not subject then return false end
    local recipientName=nickname(recipient)
    if not recipientName then return false end
    local id=subject:match('^%d+$') and tonumber(subject) or nil
    local name=id and nickname(id) or subject
    if id and not name then return false end
    return enqueue({kind='answer',id=id,name=name,recipient=recipient,recipientName=recipientName,guard=guard,notBefore=now()+math.max(0,tonumber(delay) or 0)})==true
end
local function validAnswer(job)
    return (not job.id or nickname(job.id)==job.name)
        and nickname(job.recipient)==job.recipientName and (not job.guard or job.guard())
end
local function fama(raw)
    local recipient,subject=trim(tostring(u8(raw))):match('^(%d+)%s+(.+)$')
    if not recipient or not answerFamily(recipient,subject) then
        say('Использование: /fama ID_получателя ID_игрока или Ник_Игрока. Получатель и игрок по ID должны быть в сети.')
    end
end
integration.answerFamily=answerFamily
local function finish(job, value)
    syncAccess()
    if job.cancelled or job.accessRevision ~= accessRevision then return end
    if not integration.access:require(1, say) then return end
    if job.kind == 'answer' then
        if not validAnswer(job) then
            say('Ответ отменён: игрок или получатель вышел либо сменил ник.'); return
        end
        local displayFamily = trim(value:gsub('[%[%]]', ''))
        local noFamily = {['Нет'] = true, ['нет'] = true, ['НЕТ'] = true,
            ['-'] = true, ['—'] = true, ['Не состоит'] = true, ['не состоит'] = true,
            ['Не состоит в семье'] = true, ['не состоит в семье'] = true,
            ['Отсутствует'] = true, ['отсутствует'] = true}
        local message = '/ans ' .. job.recipient .. ' Игрок ' .. job.name:gsub('_', ' ') ..
            (noFamily[displayFamily] and ' не состоит в семье.' or ' состоит в семье ' .. displayFamily .. '.')
        if #u8:decode(message) > 144 then say('Ответ отменён: сообщение превышает ограничение чата (144 байта).'); return end
        send(message)
        return
    end
    if not enabled then return end
    if job.kind == 'view' then
        if watching and target == job.id and nickname(job.id) == job.name then family = value end
        return
    end
    if nickname(job.id) ~= job.name then say('Наказание отменено: игрок вышел или ID занят другим игроком.'); return end
    local adminLevel = integration.adminLevel()
    if not adminLevel or adminLevel < 1 then say('Наказание отменено: уровень администратора не подтверждён.'); return end
    local requestOnly = adminLevel <= 2
    local reason = job.reason .. (requestOnly and ' (' .. value .. ')' or ' [' .. value .. ']')
    local command = '/' .. job.kind .. ' ' .. job.id .. ' ' .. (job.amount and job.amount .. ' ' or '') .. reason
    local displayName = job.name:gsub('_', ' ')
    local displayFamily = value:gsub('[%[%]]', '')
    local description = 'Член семьи ' .. displayFamily .. ' ' .. displayName
    if job.kind == 'jail' then description = description .. ' отправлен в тюрьму'
    elseif job.kind == 'ban' then description = description .. ' заблокирован'
    else description = description .. ' получил предупреждение' end
    local message = '/msg 300 ' .. description .. '. Причина: ' .. job.reason
    if requestOnly then
        command = '/a ' .. command
        message = job.kind == 'jail' and '/a /msg 0 ' .. description .. '. Причина: ' .. job.reason or nil
    end
    -- SA-MP command payload must fit without silently truncating the family.
    if #u8:decode(command) > 144 or (message and #u8:decode(message) > 144) then
        say('Наказание отменено: команда или уведомление превышает 144 байта. Нужна более короткая причина.'); return
    end
    local issuedGeneration = generation
    send(command)
    wait(650)
    syncAccess()
    if message and enabled and generation == issuedGeneration and integration.access:can(1) then send(message) end
end

local function toggle()
    enabled = not enabled
    generation = generation + 1
    family = nil
    for i = #queue, 1, -1 do
        if queue[i].kind ~= 'answer' then table.remove(queue, i) end
    end
    -- Drain an already sent /offst, but never execute its cancelled punishment.
    if pending and pending.kind ~= 'answer' then pending.cancelled = true end
    if enabled and watching and target then
        local id = target
        target = nil
        observe(id)
    end
    say(enabled and 'Работа с семьями включена.' or 'Работа с семьями выключена.')
end

function events.onShowDialog(id, style, title, b1, b2, text)
    syncAccess()
    if not pending or pending.result or id ~= 0 or style ~= 0 then return end
    if clean(tostring(u8(title))) ~= 'Оффлайн статистика игрока' then return end
    local name, found
    for line in tostring(u8(text)):gmatch('[^\r\n]+') do
        local key, value = clean(line):match('^([^:]+):%s*(.*)$')
        if key == 'Имя' then name = trim(value) end
        if key == 'Семья' then found = trim(value) end
    end
    if not sameAccountName(name, pending.name) then return end
    pending.result = {family = found ~= '' and found or nil}
    -- Close only our matched response, from the main coroutine.
    return false
end
function events.onTogglePlayerSpectating(state)
    watching = state == true or state == 1
    if not watching then
        target, family, header = nil, nil, nil
        for i = #queue, 1, -1 do if queue[i].kind == 'view' then table.remove(queue, i) end end
    end
end
function events.onSpectatePlayer(id) observe(id) end
function events.onSpectateVehicle()
    if header and now() - header.time < 3 then observe(header.id)
    else watching, target, family = true, nil, nil end
end
function events.onServerMessage(color, text)
    syncAccess()
    local line = clean(tostring(u8(text)))
    if replies.main.enabled and enabled and integration.access:can(1) and color==replies.main.color and replyReady() then
        local recipient,question=integration.service('report_reader.lua').parse(tostring(u8(text)))
        local subject=question and keywordParser.parse(question,keywords)
        local found,selfID=sampGetPlayerIdByCharHandle(PLAYER_PED)
        local key=recipient and subject and (recipient..'|'..subject:lower())
        if key and (not found or recipient~=selfID) and (not replyRecent[key] or now()-replyRecent[key]>=replies.main.cooldown) then
            local token=replyGeneration
            local guard=function()return token==replyGeneration and replies.main.enabled and enabled and replyReady() end
            if answerFamily(recipient,subject,guard,replies.main.delay) then replyRecent[key]=now() end
        end
    end

    local name, id = line:match('^%[SP%]%s+([^%[%]]+)%[(%d+)%]%s*|')
    id = tonumber(id)
    if id and sameAccountName(nickname(id), name) then
        header = {id = id, time = now()}
        observe(id)
    end
end
function events.onInitGame()
    enabled = integration.featureAllowed()
    accessRevision = integration.access:revision()
    generation = generation + 1
    queue, pending, target, family, header = {}, nil, nil, nil, nil
    watching, nextRequest = false, 0
    replyGeneration=replyGeneration+1;replyRecent={};replyAway=true
end
events.onConnectionLost = events.onInitGame
events.onConnectionClosed = events.onInitGame
function events.onSendCommand(command)
    if internal then return end
    if pending and command:lower():match('^/offst%s') then
        say('Статистика уже запрошена. Следующий запрос доступен после получения ответа.'); return false
    end
end
function events.onPlayerQuit(id)
    if target == id then target, family = nil, nil end
    if header and header.id == id then header = nil end
end
local function drawFamily()
    if not enabled or not watching or not family then return end
    -- Native GTA SA font 3 (Pricedown), with black outline, centered at the top.
    local label = u8:decode(family):gsub('~', '')
    useRenderCommands(true)
    setGxtEntry('FAMHUD', label)
    setTextProportional(true)
    setTextJustify(false)
    setTextWrapx(640.0)
    setTextFont(3)
    setTextScale(0.7, 1.5)
    setTextColour(244, 197, 66, 255)
    setTextEdge(2, 0, 0, 0, 255)
    setTextCentre(true)
    displayText(320.0, 25.0, 'FAMHUD')
end
function integration.start()
    repeat wait(100) until isSampAvailable()
    sampRegisterChatCommand('fama', fama)
    sampRegisterChatCommand('fj', function(a) punish('jail', a) end)
    sampRegisterChatCommand('fw', function(a) punish('warn', a) end)
    sampRegisterChatCommand('fb', function(a) punish('ban', a) end)
    lua_thread.create(function()
        while true do wait(0); if isSampAvailable() then drawFamily() end end
    end)
    while true do
        wait(0)
        syncAccess()
        replyReady()
        for k,t in pairs(replyRecent) do if now()-t>3600 then replyRecent[k]=nil end end
        if not isSampAvailable() then
            enabled = integration.featureAllowed()
            generation = generation + 1
            queue, pending, target, family, header = {}, nil, nil, nil, nil
            watching, nextRequest = false, 0
        elseif pending then
            if pending.result then
                local job = pending
                pending = nil
                sampSendDialogResponse(0, 0, 0, '')
                nextRequest = now() + GAP
                if not job.cancelled and enabled then
                    if job.result.family then finish(job, job.result.family)
                    else say('Запрос отменён: в статистике ' .. job.name .. ' нет сведений о семье.') end
                end
            elseif now() - pending.started > TIMEOUT then
                if not pending.cancelled then say('Запрос отменён: статистика ' .. pending.name .. ' не получена за 8 секунд.') end
                pending, nextRequest = nil, now() + GAP
            end
        elseif #queue > 0 and now() >= nextRequest and now()>=(queue[1].notBefore or 0) and not sampIsDialogActive() and not integration.queryBusy('offst') then
            local job = table.remove(queue, 1)
            if job.accessRevision == accessRevision and integration.access:can(1)
                and enabled and (job.kind=='answer' and validAnswer(job) or job.kind~='answer' and nickname(job.id)==job.name) then
                pending = job
                job.started = now()
                send('/offst ' .. job.name)
            elseif job.kind ~= 'view' then say('Запрос отменён: игрок вышел, сменил ник или функция выключена.') end
        end
    end
end

integration.onDisconnect = events.onInitGame
integration.queryPending = function(kind) return kind=='offst' and pending~=nil end
integration.draw = function()
    local imgui = require('imgui')
    local columns = integration.layout.begin('families_summary', 680)
    integration.layout.heading('В наблюдении')
    local name = target and nickname(target)
    imgui.TextWrapped(name and (name .. ' [' .. target .. ']') or 'Игрок не выбран')
    imgui.TextWrapped(family and ('Семья: ' .. family) or
        (pending and 'Получаем сведения о семье…' or 'Семья появится при наблюдении за игроком.'))
    if #queue > 0 then imgui.Text('Запросов в очереди: ' .. #queue) end
    integration.layout.next(columns)
    integration.layout.heading('Семейные команды')
    imgui.TextWrapped('/fj — тюрьма · /fw — предупреждение · /fb — бан')
    imgui.TextWrapped('/fama — сообщить игроку название семьи')
    imgui.TextWrapped('Семья добавляется к причине автоматически.')
    if imgui.Button('Синтаксис и примеры##familia_help') then integration.openHelp('families') end
    integration.layout.finish(columns)
end

integration.drawSettings = function()
    local imgui = require('imgui')
    imgui.TextWrapped('Общий переключатель включает название семьи в наблюдении и семейные команды. Параметры контроля аптечек — ниже.')
    local opts=integration.service('combo_settings.lua')
    local changed=opts.toggle(imgui,'Отвечать на вопросы о семье',replies.main,'enabled')
    imgui.TextWrapped('Репорты: 57 фама; Ombre_Leather в какой фаме?; Ombre Leather какая фама? Ник — 1–3 части. Проверка /offst, ответ автору /ans.')
    imgui.PushItemWidth(130)
    changed=opts.integer(imgui,'Задержка ответа, сек.',replies.main,'delay',2,0,300) or changed
    changed=opts.integer(imgui,'Интервал повтора, сек.',replies.main,'cooldown',15,1,3600) or changed
    changed=opts.integer(imgui,'Задержка после AFK, сек.',replies.main,'return_delay',15,0,600) or changed
    imgui.PopItemWidth()
    imgui.Separator()
    imgui.Text('Ключевые слова и фразы')
    imgui.TextWrapped('Вопрос: ID или ник, затем одна из фраз ниже. Например: 57 фама. Регистр не важен. Пустой список отключает распознавание вопросов.')
    local keywordsChanged=false
    for i,word in ipairs(keywords)do
        keywordBuffers[i]=keywordBuffers[i]or imgui.ImBuffer(word,256)
        imgui.PushItemWidth(math.max(80,imgui.GetContentRegionAvailWidth()-110))
        if imgui.InputText('##family_keyword_'..i,keywordBuffers[i])then keywords[i]=keywordBuffers[i].v;keywordsChanged=true end
        imgui.PopItemWidth();imgui.SameLine()
        if imgui.Button('Удалить##family_keyword_delete_'..i)then
            table.remove(keywords,i);keywordBuffers={};keywordsChanged=true;break
        end
    end
    if #keywords<100 and imgui.Button('Добавить фразу##family_keyword_add')then
        keywords[#keywords+1]='';keywordsChanged=true
    end
    if keywordsChanged then
        local data={main={count=#keywords},words={}}
        for i,word in ipairs(keywords)do data.words['word'..i]=word end
        integration.storage:saveIni(data,keywordPath)
        replyGeneration=replyGeneration+1;replyRecent={}
    end
    if changed then replyGeneration=replyGeneration+1;integration.storage:saveIni(replies,replyPath) end
end

integration.setEnabled=function(value) if enabled~=value then toggle() end end

    end
    sources["modules/fisheye.lua"] = function()
-- Adapted from FishEyeEffect by Receiver; no separate command or render loop.
local applied=false
local function restore()
    if applied then cameraSetLerpFov(70.0,70.0,1000,1);applied=false end
end
integration.update=function()
    local p=integration.preferences.data.main
    if not p.fishEye or sampGetGamestate()~=3 or not doesCharExist(PLAYER_PED) then restore();return end
    -- Keep the source's normal sniper aiming view.
    if isCurrentCharWeapon(PLAYER_PED,34) and isKeyDown(2) then restore();return end
    cameraSetLerpFov(p.fishEyeAngle,p.fishEyeAngle,1000,1)
    applied=true
end
integration.onDisconnect=restore
integration.stop=restore
integration.drawSettings=function()
    local g=require('imgui')
    local p=integration.preferences.data.main
    local enabled=g.ImBool(p.fishEye)
    if g.Checkbox('Рыбий глаз',enabled) then p.fishEye=enabled.v;integration.preferences:save();if not p.fishEye then restore() end end
    g.SameLine();g.PushItemWidth(85)
    local angle=g.ImInt(p.fishEyeAngle)
    if g.InputInt('##fish_eye_angle',angle,0,0) then p.fishEyeAngle=angle.v;integration.preferences:save() end
    g.PopItemWidth();g.SameLine();g.Text('°')
end

    end
    sources["modules/fogdist.lua"] = function()
-- FogDist by LUCHARE: reversible patches, applied only while enabled.
local g=require('imgui')
local memory=require('memory')
local cfg,path=integration.service('combo_settings.lua').load(integration,'fogdist',{main={enabled=false,distance=1200}})
local original=nil
local function restore()
    if not original then return end
    for address,value in pairs(original.bytes)do if memory.getuint8(address)==0xEB then memory.setuint8(address,value,true)end end
    memory.setfloat(0xB7C4F0,original.distance,false);original=nil
end
integration.stop=restore;integration.onDisconnect=restore
integration.update=function()
    if not cfg.main.enabled or sampGetGamestate()~=3 then restore();return end
    if not original then
        local bytes={};for _,address in ipairs({0x5609FF,0x561344})do
            local value=memory.getuint8(address)
            if value~=0xEB and (value<0x70 or value>0x7F)then
                cfg.main.enabled=false;integration.message('Дальность прорисовки: версия кода игры не поддерживается.');return
            end
            bytes[address]=value
        end
        original={bytes=bytes,distance=memory.getfloat(0xB7C4F0)}
        for address in pairs(bytes)do memory.setuint8(address,0xEB,true)end
    end
    memory.setfloat(0xB7C4F0,math.max(0,math.min(3600,tonumber(cfg.main.distance)or 1200)),false)
end
integration.drawSettings=function()
    local enabled=g.ImBool(cfg.main.enabled)
    if g.Checkbox('Дальность прорисовки',enabled)then cfg.main.enabled=enabled.v;if not enabled.v then restore()end;integration.storage:saveIni(cfg,path)end
    g.SameLine();g.PushItemWidth(100);local distance=g.ImInt(cfg.main.distance)
    if g.InputInt('##fog_distance',distance,0,0)then cfg.main.distance=math.max(0,math.min(3600,distance.v));integration.storage:saveIni(cfg,path)end
    g.PopItemWidth();g.SameLine();g.Text('м')
end

    end
    sources["modules/gang.lua"] = function()
-- CasualAT module. Author: Casual Alvarez. Original source: integration/sources.
require "lib.moonloader"
require "lib.sampfuncs"

local encoding = require "encoding"
local bit = require "bit"
local imgui = require "imgui"
local storage = integration.storage
local CONFIG = storage:path('settings', 'gangs.ini')
local preferences = storage:loadIni({features={enabled=false}}, CONFIG)

encoding.default = "CP1251"
local u8 = encoding.UTF8

local PREFIX = "{F4C542}[X-Tools]{FFFFFF} "

local GANG_BY_COLOR = {
    [-3407617] = "BALLAS",
    [-16738048] = "GROVE",
    [-13056] = "VAGOS",
    [-10066177] = "RIFA",
    [-16724737] = "AZTEC"
}

local function utf8_to_cp1251(text)
    return u8:decode(tostring(text or ""))
end

local function trim(text)
    return tostring(text or ""):match("^%s*(.-)%s*$")
end

local function msg(text, color)
    sampAddChatMessage(utf8_to_cp1251(PREFIX .. text), color or -1)
end

local function feature_enabled()
    if preferences.features.enabled then return true end
    msg('Команды /gw и /gb выключены. Включите их: Настройки → Банды.', 0xAAAAAA)
    return false
end

local function process_command(command_utf8)
    if not integration.access:require(1, msg) then return false end
    local command_cp1251 = utf8_to_cp1251(command_utf8)
    local ok = pcall(sampProcessChatInput, command_cp1251)
    if not ok then
        sampSendChat(command_cp1251)
    end
    return true
end

local function get_player_gang(player_id)
    if not sampIsPlayerConnected(player_id) then
        return nil, "Игрок с указанным ID не в сети."
    end

    local ok, color = pcall(sampGetPlayerColor, player_id)
    if not ok or not color then
        return nil, "Не удалось определить банду по цвету ника."
    end

    return GANG_BY_COLOR[bit.tobit(color)]
end

local function build_warn_command(player_id)
    local gang, err = get_player_gang(player_id)
    if err then
        return nil, err
    end

    if gang then
        return string.format("/warn %d Нарушение правил /capture [%s]", player_id, gang)
    end

    return string.format("/warn %d Нарушение правил /capture", player_id)
end

local function build_ban_command(player_id, days)
    local gang, err = get_player_gang(player_id)
    if err then
        return nil, err
    end

    if gang then
        return string.format("/ban %d %d Использование читов [%s]", player_id, days, gang)
    end

    return string.format("/ban %d %d Использование читов", player_id, days)
end

local function handle_gw_command(params)
    if not feature_enabled() then return end
    local player_id = tonumber(trim(params):match("^(%d+)$"))
    if not player_id then
        msg("Предупреждение за нарушение правил капта: /gw ID", 0xAAAAAA)
        return
    end

    local command, err = build_warn_command(player_id)
    if not command then
        msg(err, 0xFF6666)
        return
    end

    if process_command(command) then msg("Команда отправлена: " .. command, 0x99FF99) end
end

local function handle_gb_command(params)
    if not feature_enabled() then return end
    local player_id, days = trim(params):match("^(%d+)%s+(%d+)$")
    player_id = tonumber(player_id)
    days = tonumber(days)

    if not player_id or not days or days < 1 then
        msg("Блокировка за использование читов: /gb ID дни (не менее 1 дня).", 0xAAAAAA)
        return
    end

    local command, err = build_ban_command(player_id, days)
    if not command then
        msg(err, 0xFF6666)
        return
    end

    if process_command(command) then msg("Команда отправлена: " .. command, 0x99FF99) end
end

integration.drawSettings = function()
    local value = imgui.ImBool(preferences.features.enabled)
    if imgui.Checkbox('Включить работу с бандами##gang_enabled', value) then
        preferences.features.enabled = value.v
        assert(storage:saveIni(preferences, CONFIG))
    end
    imgui.TextWrapped('Разрешить команды /gw и /gb для наказаний на каптах. Изменение сохраняется автоматически.')
    imgui.Spacing()
    imgui.TextWrapped('/gw ID — предупреждение за нарушение правил капта.')
    imgui.TextWrapped('/gb ID дни — блокировка за использование читов.')
    imgui.TextWrapped('Если банда определена по цвету ника, её название добавляется к причине наказания.')
end

integration.status = function()
    return {enabled=preferences.features.enabled}
end

function integration.start()
    repeat
        wait(100)
    until isSampAvailable()

    sampRegisterChatCommand("gw", handle_gw_command)
    sampRegisterChatCommand("gb", handle_gb_command)


    while true do
        wait(0)
    end
end

    end
    sources["modules/glass_scoreboard.lua"] = function()
-- Glass Scoreboard by chapo: shared-context port, replaces the old ADM-Tab renderer.
local g=require('imgui');local u8=require('encoding').UTF8;local bit=require('bit')
local path=integration.storage:path('settings','glass-scoreboard.ini')
local legacy=integration.storage:loadIni({main={enabled=false}},integration.storage:path('settings','adm-tab.ini'))
local cfg=integration.storage:loadIni({main={enabled=legacy.main.enabled,hold=true,scroll=true,pos=2}},path)
local visible,alpha,pressedAt=false,0,nil
local searchFocused=false
local players,selected={},nil
local search=g.ImBuffer('',128);local lastRefresh=-10000;local targetScroll=nil
local function save()integration.storage:saveIni(cfg,path)end
local function allowed()return sampGetGamestate()==3 and isGameWindowForeground()and not isPauseMenuActive()and not sampIsChatInputActive()and not sampIsDialogActive()end
local function refresh()
    players={};local ok,me=sampGetPlayerIdByCharHandle(PLAYER_PED)
    for id=0,1003 do
        if (ok and id==me) or sampIsPlayerConnected(id)then players[#players+1]={id=id,name=tostring(u8(sampGetPlayerNickname(id))),score=sampGetPlayerScore(id),ping=sampGetPlayerPing(id),color=sampGetPlayerColor(id),self=ok and id==me}end
    end
    table.sort(players,function(a,b)if a.self~=b.self then return a.self end;return a.id<b.id end)
    lastRefresh=getGameTimer()
end
local function open(value)
    visible=value and cfg.main.enabled
    if visible then integration.closeWindow();refresh();sampToggleScoreboard(false)end
    integration.refreshInput()
end
integration.onDisconnect=function()visible=false;alpha=0;searchFocused=false;pressedAt=nil;players={};selected=nil;targetScroll=nil end
integration.stop=integration.onDisconnect
integration.onWindowMessage=function(msg,key,lp)
    if not cfg.main.enabled or not allowed()then return end
    if key==27 and visible and (msg==0x100 or msg==0x101)then consumeWindowMessage(true,false);if msg==0x101 then open(false)end;return end
    if key==9 and not integration.keys:captureActive() and (msg==0x100 or msg==0x101)then
        consumeWindowMessage(true,false)
        if msg==0x100 and bit.band(tonumber(lp)or 0,0x40000000)==0 then pressedAt=getGameTimer();open(not visible)
        elseif msg==0x101 then if cfg.main.hold and pressedAt and getGameTimer()-pressedAt>=700 then open(false)end;pressedAt=nil end
    end
end
integration.update=function()
    if not allowed()then if visible then open(false)end;return end
    if visible then sampToggleScoreboard(false);if getGameTimer()-lastRefresh>1000 then refresh()end end
end
integration.hudActive=function()return cfg.main.enabled and allowed()and not integration.windowOpen() and (visible or alpha>0.001),visible,searchFocused end
local lastFrame=nil
integration.drawHud=function()
    if not integration.hudActive()then return end
    local time=getGameTimer();local dt=lastFrame and math.min(0.1,(time-lastFrame)/1000)or 0.016;lastFrame=time
    alpha=math.max(0,math.min(1,alpha+(visible and 1 or -1)*dt/0.25))
    local sw,sh=getScreenResolution();local scale=math.max(0.8,math.min(1.15,sh/900))
    local width=math.min(600,sh*0.60,sw-32);local x=cfg.main.pos==1 and 20 or cfg.main.pos==3 and sw-width-20 or (sw-width)/2
    local rowHeight=46*scale;local font=integration.fontFace(sh>=900 and 18 or 14,false)
    local function color(rgb,a)return bit.bor(bit.band(rgb,0xFFFFFF),bit.lshift(math.floor(255*alpha*(a or 1)),24))end
    g.SetNextWindowPos(g.ImVec2(x,0),g.Cond.Always);g.SetNextWindowSize(g.ImVec2(width,sh),g.Cond.Always)
    g.PushStyleVar(g.StyleVar.Alpha,alpha);g.PushStyleVar(g.StyleVar.WindowRounding,0)
    g.PushStyleColor(g.Col.WindowBg,g.ImVec4(0.04,0.05,0.06,0.32))
    g.PushStyleColor(g.Col.ChildWindowBg,g.ImVec4(0,0,0,0))
    g.PushStyleColor(g.Col.FrameBg,g.ImVec4(0,0,0,0))
    local flags=g.WindowFlags.NoTitleBar+g.WindowFlags.NoResize+g.WindowFlags.NoMove+g.WindowFlags.NoCollapse+g.WindowFlags.NoSavedSettings
    if not visible then flags=flags+g.WindowFlags.NoInputs end
    g.Begin('TAB Жидкое стекло###xt_glass_scoreboard',g.ImBool(true),flags)
    if font then g.PushFont(font)end
    local draw=g.GetWindowDrawList();local origin=g.GetCursorScreenPos();local w=width-28
    draw:PushClipRect(g.ImVec2(0,0),g.ImVec2(sw,sh),false)
    draw:AddRectFilledMultiColor(g.ImVec2(x-90*scale,0),g.ImVec2(x,sh),0,color(0x000000,0.32),color(0x000000,0.32),0)
    draw:AddRectFilledMultiColor(g.ImVec2(x+width,0),g.ImVec2(x+width+90*scale,sh),color(0x000000,0.32),0,0,color(0x000000,0.32))
    draw:PopClipRect()
    local online=#players..' в сети';local onlineSize=g.CalcTextSize(online)
    draw:AddText(origin,color(0xCCCCCC),os.date('%H:%M:%S'))
    draw:AddText(g.ImVec2(origin.x+w-onlineSize.x,origin.y),color(0xCCCCCC),online)
    g.Dummy(g.ImVec2(w,24*scale))
    local server=tostring(u8(sampGetCurrentServerName()));local serverSize=g.CalcTextSize(server);local p=g.GetCursorScreenPos()
    draw:AddText(g.ImVec2(p.x+math.max(0,(w-serverSize.x)/2),p.y),color(0xFFFFFF),server)
    g.Dummy(g.ImVec2(w,38*scale))
    p=g.GetCursorScreenPos()
    local nameX=52*scale;local scoreX=w*0.67;local pingX=w-12*scale
    draw:AddText(g.ImVec2(p.x+12*scale,p.y),color(0xDDDDDD),'ID')
    draw:AddText(g.ImVec2(p.x+nameX,p.y),color(0xDDDDDD),'ИМЯ')
    draw:AddText(g.ImVec2(p.x+scoreX-25*scale,p.y),color(0xDDDDDD),'УРОВЕНЬ')
    local pingHeader=g.CalcTextSize('ЗАДЕРЖКА')
    draw:AddText(g.ImVec2(p.x+pingX-pingHeader.x,p.y),color(0xDDDDDD),'ЗАДЕРЖКА')
    g.Dummy(g.ImVec2(w,24*scale))
    local searchPos=g.GetCursorScreenPos()
    g.PushItemWidth(w)
    if g.InputText('##glass_search',search)then targetScroll=0 end
    searchFocused=g.IsItemActive()==true
    if search.v=='' and not searchFocused then local q=searchPos;draw:AddText(g.ImVec2(q.x+4,q.y+3),color(0xDDDDDD),'Найти игрока')end
    g.PopItemWidth();g.Separator()
    if not integration.windowOpen()then g.CaptureKeyboardFromApp(searchFocused)end
    g.BeginChild('##glass_players',g.ImVec2(w,math.max(80,sh-142*scale)),false,cfg.main.scroll and g.WindowFlags.NoScrollWithMouse or 0)
    if cfg.main.scroll then
        local wheel=tonumber(g.GetIO().MouseWheel)or 0
        if targetScroll==nil then targetScroll=g.GetScrollY()end
        if g.IsWindowHovered()and wheel~=0 then targetScroll=math.max(0,math.min(g.GetScrollMaxY(),targetScroll-wheel*rowHeight*2))end
        g.SetScrollY(g.GetScrollY()+(targetScroll-g.GetScrollY())*math.min(1,dt*14))
    end
    local query=search.v:lower()
    for _,row in ipairs(players)do
        if query==''or row.name:lower():find(query,1,true)or tostring(row.id)==query then
            local pos=g.GetCursorScreenPos();local rw=w-12;local d=g.GetWindowDrawList()
            g.InvisibleButton('##glass_player_'..row.id,g.ImVec2(rw,rowHeight))
            local hover=g.IsItemHovered();local current=(row.self or sampIsPlayerConnected(row.id))and tostring(u8(sampGetPlayerNickname(row.id)))==row.name
            if current and hover and g.IsMouseDoubleClicked(0)then sampSendClickPlayer(row.id,0);open(false)
            elseif current and g.IsItemClicked(0)then if selected==row.id then selected=nil else selected=row.id end end
            d:AddRectFilled(pos,g.ImVec2(pos.x+rw,pos.y+rowHeight-4),color(0x999999,hover and 0.35 or 0.13),4)
            if selected==row.id then d:AddRect(pos,g.ImVec2(pos.x+rw,pos.y+rowHeight-4),color(0xFFFFFF,0.5),4,15,1)end
            local textY=pos.y+(rowHeight-g.GetFontSize())/2-2
            d:AddText(g.ImVec2(pos.x+12*scale,textY),color(0xFFFFFF),tostring(row.id))
            local dot=bit.bor(bit.lshift(bit.band(row.color,255),16),bit.band(row.color,0xFF00),bit.band(bit.rshift(row.color,16),255))
            d:AddCircleFilled(g.ImVec2(pos.x+nameX-9*scale,textY+g.GetFontSize()/2),3*scale,color(dot))
            d:AddText(g.ImVec2(pos.x+nameX,textY),color(current and 0xFFFFFF or 0x999999),row.name)
            d:AddText(g.ImVec2(pos.x+scoreX,textY),color(0xFFFFFF),tostring(row.score))
            local ping=tostring(row.ping);local size=g.CalcTextSize(ping)
            d:AddText(g.ImVec2(pos.x+pingX-12-size.x,textY),color(0xFFFFFF),ping)
            if g.BeginPopupContextItem('##glass_actions_'..row.id)then
                g.TextWrapped(row.name..' ['..row.id..']')
                if g.Button('Скопировать ник##glass_'..row.id)then setClipboardText(u8:decode(row.name));g.CloseCurrentPopup()end
                if g.Button('Закрыть##glass_popup_'..row.id)then g.CloseCurrentPopup()end
                g.EndPopup()
            end
        end
    end
    g.EndChild()
    if font then g.PopFont()end
    g.End();g.PopStyleColor(3);g.PopStyleVar(2)
end
integration.drawSettings=function()
    local enabled=g.ImBool(cfg.main.enabled)
    if g.Checkbox('TAB Жидкое стекло',enabled)then cfg.main.enabled=enabled.v;save();if not enabled.v then integration.onDisconnect()end end
    local helper=integration.service('combo_settings.lua')
    if helper.toggle(g,'Плавная прокрутка##glass',cfg.main,'scroll')then targetScroll=nil;save()end
    if helper.toggle(g,'Закрывать при отпускании TAB после удержания##glass',cfg.main,'hold')then save()end
    local pos=g.ImInt(math.max(0,math.min(2,cfg.main.pos-1)));g.PushItemWidth(220)
    if g.Combo('Положение##glass',pos,'Слева\0По центру\0Справа\0\0')then cfg.main.pos=pos.v+1;save()end
    g.PopItemWidth()
end

    end
    sources["modules/hospital.lua"] = function()
-- CasualAT module. Author: Casual Alvarez. Original source: integration/sources.
require 'lib.moonloader'

local encoding = require 'encoding'

encoding.default = 'CP1251'
u8 = encoding.UTF8

local TELEPORT_DELAY_MS = 1000
local MAX_PLAYER_ID = 999
local BRAND_HEX = 'FF6666'
local BRAND_PREFIX = string.format('{%s}[X-Tools]{FFFFFF}: ', BRAND_HEX)
local LOAD_PREFIX = BRAND_PREFIX

local queue_token = 0

local function cp1251_to_utf8(str)
    return tostring(u8(str or ''))
end

local function utf8_to_cp1251(str)
    return u8:decode(tostring(str or ''))
end

local function chat(text, color)
    if isSampAvailable() then
        sampAddChatMessage(utf8_to_cp1251(text), color or 0xFFFFFF)
    end
end

local function brand_chat(text)
    chat(BRAND_PREFIX .. text, 0xFFFFFF)
end

local function load_chat(text)
    chat(LOAD_PREFIX .. text, 0xFFFFFF)
end

local function parse_ids(raw_args)
    local ids = {}
    local invalid = {}

    for token in tostring(raw_args or ''):gmatch('%S+') do
        local id = tonumber(token)

        if id ~= nil and id >= 0 and id <= MAX_PLAYER_ID and id % 1 == 0 then
            ids[#ids + 1] = id
        else
            invalid[#invalid + 1] = token
        end
    end

    return ids, invalid
end

local function cancel_queue(show_message)
    queue_token = queue_token + 1

    if show_message then
        brand_chat('Очередь телепортации остановлена.')
    end
end

local function run_queue(ids)
    if not integration.access:require(1, brand_chat) then return end
    queue_token = queue_token + 1
    local my_token = queue_token
    local accessRevision = integration.access:revision()
    local names = {}
    for _, id in ipairs(ids) do
        if sampIsPlayerConnected(id) then names[id] = sampGetPlayerNickname(id) end
    end

    lua_thread.create(function()
        for index, id in ipairs(ids) do
            if my_token ~= queue_token or accessRevision ~= integration.access:revision() or not integration.access:can(1) then
                return
            end

            if names[id] and sampIsPlayerConnected(id) and sampGetPlayerNickname(id) == names[id] then
                sampSendChat(utf8_to_cp1251(string.format('/gethere %d', id)))
                brand_chat(string.format('Команда /gethere %d отправлена (%d из %d).', id, index, #ids))
            else
                brand_chat(string.format('ID %d пропущен: игрок вышел или этот ID занят другим игроком.', id))
            end

            if index < #ids then
                wait(TELEPORT_DELAY_MS)
            end
        end

        if my_token == queue_token then
            brand_chat(string.format('Очередь завершена. Проверено ID: %d.', #ids))
        end
    end)
end

local function handle_clearhospital_command(raw_args)
    local args = tostring(raw_args or ''):match('^%s*(.-)%s*$') or ''

    if args == '' then
        brand_chat('Телепортация к себе: /clearhospital ID [ID...]')
        brand_chat('Остановить очередь: /clearhospital stop')
        return
    end

    if args:lower() == 'stop' then
        cancel_queue(true)
        return
    end

    local ids, invalid = parse_ids(args)

    if #ids == 0 then
        brand_chat('Нужен хотя бы один целый ID от 0 до 999.')
        return
    end

    if #invalid > 0 then
        brand_chat(string.format('Некорректные ID пропущены: %s', table.concat(invalid, ', ')))
    end

    if not integration.access:require(1, brand_chat) then return end

    if #ids == 1 then
        cancel_queue(false)
        if not sampIsPlayerConnected(ids[1]) then brand_chat('Игрок не в сети.'); return end
        sampSendChat(utf8_to_cp1251(string.format('/gethere %d', ids[1])))
        brand_chat(string.format('Команда /gethere %d отправлена.', ids[1]))
        return
    end

    cancel_queue(false)
    brand_chat(string.format('Очередь телепортации запущена. Игроков: %d; интервал: %d сек.', #ids, TELEPORT_DELAY_MS / 1000))
    run_queue(ids)
end

function integration.start()
    repeat
        wait(100)
    until isSampAvailable()

    sampRegisterChatCommand('clearhospital', handle_clearhospital_command)

end

integration.onDisconnect = function() cancel_queue(false) end

    end
    sources["modules/invisible.lua"] = function()
-- Levels 1-2: Bart4 spectator-sync invisibility. Level 3+: server /inv.
local events=require('lib.samp.events')
local packets=integration.service('sync_packets.lua').new(_G)
local active,startupDone,spectating=false,false,false
local nextPacket=0
integration.keys:register('invisible','Невидимость — /inv (1–2: Bart4)',{key=0,second=0})
local function localMode()
    local level=integration.access:level();return level==1 or level==2
end
local function localRunning()
    return active and localMode() and not spectating and sampGetGamestate()==3
        and sampIsLocalPlayerSpawned() and not isCharInAnyCar(PLAYER_PED)
end
local function toggleLocal()
    active=not active;nextPacket=0
    if not active and not spectating and sampIsLocalPlayerSpawned() and not isCharInAnyCar(PLAYER_PED) then packets.onfoot() end
end
function events.onSendCommand(command)
    if tostring(command):lower():match('^%s*/inv%s*$') then
        if localMode() then toggleLocal();return false end
        if integration.access:can(3) then active=not active end
    end
end
function events.onSendPlayerSync()if localRunning()then return false end end
function events.onTogglePlayerSpectating(value)spectating=value==true;nextPacket=0 end
local function reset() active=false;startupDone=false;spectating=false;nextPacket=0 end
events.onConnectionClosed=reset
events.onConnectionLost=reset
events.onConnectionRequestAccepted=reset
integration.onDisconnect=reset
integration.stop=function()
    local restore=active and localMode() and not spectating
    if active and not localMode() and integration.access:can(3) and sampGetGamestate()==3 then sampSendChat('/inv')end
    reset()
    if restore and sampGetGamestate()==3 and sampIsLocalPlayerSpawned() and not isCharInAnyCar(PLAYER_PED)then packets.onfoot()end
end
integration.isActive=function()return active end
local function activate()if localMode()then toggleLocal()else sampSendChat('/inv')end end
integration.update=function()
    if not startupDone and sampGetGamestate()==3 and sampIsLocalPlayerSpawned() and integration.access:can(1) then
        startupDone=true
        if integration.preferences.data.main.invisibleOnStart and not active then activate() end
    end
    local pressed=integration.keys:pressed('invisible')
    if pressed and integration.access:can(1) and sampGetGamestate()==3 and isGameWindowForeground() and not isPauseMenuActive()
        and not sampIsChatInputActive() and not sampIsDialogActive() and not sampIsCursorActive() then
        activate()
    end
    if localRunning() and getGameTimer()>=nextPacket then
        packets.spectator(getCharCoordinates(PLAYER_PED));nextPacket=getGameTimer()+50
    end
end

    end
    sources["modules/joinquit.lua"] = function()
-- CasualAT module. Author: Casual Alvarez. Original source: integration/sources.
require "lib.moonloader"
local sampev = require "lib.samp.events"
local encoding = require "encoding"
local imgui = require "imgui"
local bit = require "bit"

encoding.default = "CP1251"
local u8 = encoding.UTF8

local storage = integration.storage
local CONFIG_DIR = storage:directory('settings')
local CONFIG_PATH = storage:path('settings', 'events.lua', {getWorkingDirectory() .. '/config/joinandquit_settings.lua'})

local settings_window_state = imgui.ImBool(false)

local confirmed_players = {}
local pending_joins = {}
local visible_players = {}
local last_stream_time = {}
local event_log = {}

local hud_font = nil
local last_update_time = 0

local update_interval_ms = 500
local min_score = 1
