local settings = {
    ui = {
        visible = true,
        show_hud_log = true,
        duplicate_to_chat = true,
        show_timestamp = true,

        log_x = 30,
        log_y = 300,
        log_max_lines = 10,
        log_alpha = 1.00,
        font_size = 9
    },
    global = {
        connects_enabled = true,
        disconnects_enabled = true
    },
    connects = {},
    disconnects = {}
}

local function msg(text, color)
    sampAddChatMessage(u8:decode(text), color or -1)
end

local function ensureConfigDir()
    if not doesDirectoryExist(CONFIG_DIR) then
        createDirectory(CONFIG_DIR)
    end
end

local function serializeValue(v, indent)
    indent = indent or 0
    local pad = string.rep("    ", indent)
    local nextPad = string.rep("    ", indent + 1)

    if type(v) == "table" then
        local out = "{\n"
        for k, val in pairs(v) do
            local key
            if type(k) == "string" and k:match("^[_%a][_%w]*$") then
                key = k
            else
                key = "[" .. string.format("%q", tostring(k)) .. "]"
            end
            out = out .. nextPad .. key .. " = " .. serializeValue(val, indent + 1) .. ",\n"
        end
        out = out .. pad .. "}"
        return out
    elseif type(v) == "string" then
        return string.format("%q", v)
    elseif type(v) == "number" or type(v) == "boolean" then
        return tostring(v)
    end

    return "nil"
end

local function makeDefaultSettings()
    local s = {
        ui = {
            visible = true,
            show_hud_log = true,
            duplicate_to_chat = true,
            show_timestamp = true,

            log_x = 30,
            log_y = 300,
            log_max_lines = 10,
            log_alpha = 1.00,
            font_size = 9
        },
        global = {
            connects_enabled = true,
            disconnects_enabled = true
        },
        connects = {},
        disconnects = {}
    }

    for _, faction in ipairs(faction_list) do
        s.connects[faction.key] = true
        s.disconnects[faction.key] = true
    end

    return s
end

local function saveSettings()
    ensureConfigDir()

    local f = io.open(CONFIG_PATH, "w")
    if not f then
        msg("{B4A2FF}[X-Tools]{FFFFFF} Не удалось сохранить настройки входов и выходов. Проверьте доступ к config/CasualTool/settings.")
        return
    end

    f:write("return ")
    f:write(serializeValue(settings))
    assert(f:close())
end

local function loadSettings()
    ensureConfigDir()

    local data = storage:loadTable(CONFIG_PATH)
    if data then
        settings = data
    else
        settings = makeDefaultSettings()
        saveSettings()
    end

    settings.ui = settings.ui or {}
    settings.global = settings.global or {}
    settings.connects = settings.connects or {}
    settings.disconnects = settings.disconnects or {}

    if settings.ui.visible == nil then settings.ui.visible = true end
    if settings.ui.show_hud_log == nil then settings.ui.show_hud_log = true end
    if settings.ui.duplicate_to_chat == nil then settings.ui.duplicate_to_chat = true end
    if settings.ui.show_timestamp == nil then settings.ui.show_timestamp = true end
    if settings.ui.log_x == nil then settings.ui.log_x = 30 end
    if settings.ui.log_y == nil then settings.ui.log_y = 300 end
    if settings.ui.log_max_lines == nil then settings.ui.log_max_lines = 10 end
    if settings.ui.log_alpha == nil then settings.ui.log_alpha = 1.00 end
    if settings.ui.font_size == nil then settings.ui.font_size = 9 end

    if settings.global.connects_enabled == nil then settings.global.connects_enabled = true end
    if settings.global.disconnects_enabled == nil then settings.global.disconnects_enabled = true end

    for _, faction in ipairs(faction_list) do
        if settings.connects[faction.key] == nil then
            settings.connects[faction.key] = true
        end
        if settings.disconnects[faction.key] == nil then
            settings.disconnects[faction.key] = true
        end
    end

    settings_window_state.v = settings.ui.visible
end

local function recreateHudFont()
    if hud_font and renderReleaseFont then
        pcall(renderReleaseFont, hud_font)
    end
    hud_font = renderCreateFont("Arial", settings.ui.font_size, 5)
end

local function colorToChatHex(color)
    local rgb = color % 0x1000000
    return string.format("%06X", rgb)
end

local function getQuitReasonText(reason)
    if reason == 0 then
        return "timeout/crash", "FFAA00"
    elseif reason == 1 then
        return "left", "AAAAAA"
    elseif reason == 2 then
        return "kick/ban", "FF4444"
    end
    return "reason:" .. tostring(reason), "FFFFFF"
end

local function isPlayerConfirmed(playerId)
    if not sampIsPlayerConnected(playerId) then
        return false
    end

    local ok_name, name = pcall(sampGetPlayerNickname, playerId)
    if not ok_name or not name or name == "" then
        return false
    end

    local ok_score, score = pcall(sampGetPlayerScore, playerId)
    if not ok_score or score == nil then
        return false
    end

    return score >= min_score
end

local function isRecentlyVisible(playerId)
    if visible_players[playerId] then
        return true
    end

    local t = last_stream_time[playerId]
    if t and (os.clock() - t <= vision_memory_seconds) then
        return true
    end

    return false
end

local function getFactionInfo(playerId)
    local ok, color = pcall(sampGetPlayerColor, playerId)
    if not ok or not color then
        return "unknown", "UNKNWN", "FFFFFF"
    end

    color=integration.originalPlayerColor(playerId,color)
    if integration.isMaskColor(color) then return 'mask','MASK',colorToChatHex(integration.maskColor()) end
    local faction = faction_by_color[color]
    if faction then
        return faction.key, faction.name, colorToChatHex(color)
    end

    return "unknown", "UNKNWN", "FFFFFF"
end

local function shouldTrack(mode, factionKey)
    if mode == "connects" then
        return settings.global.connects_enabled and settings.connects[factionKey] == true
    elseif mode == "disconnects" then
        return settings.global.disconnects_enabled and settings.disconnects[factionKey] == true
    end
    return true
end

local function setAll(mode, value)
    if mode == "connects" then
        for _, faction in ipairs(faction_list) do
            settings.connects[faction.key] = value
        end
    elseif mode == "disconnects" then
        for _, faction in ipairs(faction_list) do
            settings.disconnects[faction.key] = value
        end
    end
    saveSettings()
end

local function boolRef(value)
    return imgui.ImBool(value)
end

local function intRef(value)
    return imgui.ImInt(value)
end

local function floatRef(value)
    return imgui.ImFloat(value)
end

local function addEventLog(entry)
    table.insert(event_log, entry)

    while #event_log > max_log_hard_limit do
        table.remove(event_log, 1)
    end

    if settings.ui.duplicate_to_chat and entry.chat then
        msg(entry.chat)
    end
end

local function markExistingPlayersAsKnown()
    for playerId = 0, 1003 do
        if isPlayerConfirmed(playerId) then
            confirmed_players[playerId] = true
            pending_joins[playerId] = nil
        end
    end
end

local function refreshConfirmedPlayers()
    for playerId = 0, 1003 do
        if isPlayerConfirmed(playerId) then
            confirmed_players[playerId] = true
        end
    end
end

local function cleanupDisconnectedPlayers()
    for playerId, _ in pairs(confirmed_players) do
        if not sampIsPlayerConnected(playerId) then
            confirmed_players[playerId] = nil
        end
    end
end

local function processPendingJoins()
    local now = os.clock()

    for playerId, joinTime in pairs(pending_joins) do
        if not sampIsPlayerConnected(playerId) then
            pending_joins[playerId] = nil

        elseif isPlayerConfirmed(playerId) then
            local was_confirmed = confirmed_players[playerId] == true

            if tracking_enabled and not was_confirmed then
                local name = "Unknown"
                pcall(function()
                    name = sampGetPlayerNickname(playerId)
                end)

                local faction_key, faction_name, faction_hex = getFactionInfo(playerId)

                if shouldTrack("connects", faction_key) then
                    local chat_text = string.format(
                        "{%s}%s{%s}[%d] {FFFFFF}from {%s}%s{FFFFFF} just {228B22}connected",
                        faction_hex,
                        name,
                        faction_hex,
                        playerId,
                        faction_hex,
                        faction_name
                    )

                    addEventLog({
                        kind = "connect",
                        time = os.date("%H:%M:%S"),
                        chat = chat_text,
                        name = name,
                        playerId = playerId,
                        faction = faction_name,
                        faction_color = faction_hex
                    })
                end
            end

            confirmed_players[playerId] = true
            pending_joins[playerId] = nil

        elseif now - joinTime > join_timeout_seconds then
            pending_joins[playerId] = nil
        end
    end
end

local function hexToArgb(hex, alpha)
    hex = tostring(hex or "FFFFFF"):gsub("#", "")
    local rgb = tonumber(hex, 16) or 0xFFFFFF
    alpha = alpha or 255
    return bit.bor(bit.lshift(alpha, 24), rgb)
end

local function getTextWidth(text)
    if renderGetFontDrawTextLength then
        return renderGetFontDrawTextLength(hud_font, text)
    end
    return #tostring(text) * (settings.ui.font_size * 0.60)
end

local function drawHudChunk(text, x, y, color, shadow_color)
    text = u8:decode(text)
    renderFontDrawText(hud_font, text, x + 1, y + 1, shadow_color)
    renderFontDrawText(hud_font, text, x, y, color)
    return getTextWidth(text)
end

local movingLog=false
local function drawHudLog()
    if not settings.ui.show_hud_log and not movingLog then
        return
    end

    if not hud_font then
        return
    end

    local start_index = math.max(1, #event_log - settings.ui.log_max_lines + 1)
    local base_x = settings.ui.log_x
    if movingLog then renderFontDrawText(hud_font, "Enter - save", base_x, settings.ui.log_y, -1)end
    local y = settings.ui.log_y
    local line_h = settings.ui.font_size + 5

    local alpha = math.floor(math.max(0.0, math.min(1.0, settings.ui.log_alpha)) * 255)
    local white = hexToArgb("FFFFFF", alpha)
    local green = hexToArgb("22CC22", alpha)
    local red = hexToArgb("FF4444", alpha)
    local shadow = hexToArgb("000000", math.floor(alpha * 0.70))

    for i = start_index, #event_log do
        local entry = event_log[i]
        local x = base_x

        if settings.ui.show_timestamp then
            x = x + drawHudChunk("[" .. (entry.time or "--:--:--") .. "] ", x, y, white, shadow)
        end

        local faction_color = hexToArgb(entry.faction_color or "FFFFFF", alpha)
        x = x + drawHudChunk(entry.name or "Unknown", x, y, faction_color, shadow)
        x = x + drawHudChunk("[" .. tostring(entry.playerId or -1) .. "] ", x, y, faction_color, shadow)

        x = x + drawHudChunk(entry.faction or "UNKNWN", x, y, faction_color, shadow)
        x = x + drawHudChunk(" ", x, y, white, shadow)

        if entry.kind == "connect" then
            x = x + drawHudChunk("connected", x, y, green, shadow)
        elseif entry.kind == "disconnect" then
            x = x + drawHudChunk("discon ", x, y, red, shadow)

            local reason_color = hexToArgb(entry.reason_color or "FFFFFF", alpha)
            x = x + drawHudChunk(entry.reason or "unknown", x, y, reason_color, shadow)
            x = x + drawHudChunk(" ", x, y, white, shadow)

            local stream_color = hexToArgb(entry.stream_color or "FFFFFF", alpha)
            x = x + drawHudChunk(entry.stream or "off stream", x, y, stream_color, shadow)
        else
            x = x + drawHudChunk("event", x, y, white, shadow)
        end

        y = y + line_h
    end
end

function integration.start()
    while not isSampAvailable() do
        wait(100)
    end

    loadSettings()
    recreateHudFont()
    imgui.Process = settings_window_state.v

    wait(1000)
    startup_time = os.clock()
    last_update_time = os.clock()


    while true do
        imgui.Process = settings_window_state.v

        local now = os.clock()

        if not tracking_enabled then
            markExistingPlayersAsKnown()

            if now - startup_time >= startup_grace_seconds then
                tracking_enabled = true
                pending_joins = {}
            end
        else
            if (now - last_update_time) * 1000 >= update_interval_ms then
                processPendingJoins()
                refreshConfirmedPlayers()
                cleanupDisconnectedPlayers()
                last_update_time = now
            end
        end

        drawHudLog()
        wait(0)
    end
end

function sampev.onPlayerJoin(playerId, color, isNpc)
    if isNpc then
        return
    end

    if not tracking_enabled then
        return
    end

    if confirmed_players[playerId] then
        return
    end

    pending_joins[playerId] = os.clock()
end

function sampev.onPlayerQuit(playerId, reason)
    if confirmed_players[playerId] then
        local name = "Unknown"
        pcall(function()
            name = sampGetPlayerNickname(playerId)
        end)

        local stream_text, stream_hex
        if isRecentlyVisible(playerId) then
            stream_text = "in stream"
            stream_hex = "FF0000"
        else
            stream_text = "off stream"
            stream_hex = "228B22"
        end

        local faction_key, faction_name, faction_hex = getFactionInfo(playerId)
        local reason_text, reason_hex = getQuitReasonText(reason)

        if shouldTrack("disconnects", faction_key) then
            local chat_text = string.format(
                "{%s}%s{%s}[%d] {FFFFFF}from {%s}%s{FFFFFF} just {FF0000}discon{FFFFFF} by {%s}%s{FFFFFF} | %s",
                faction_hex,
                name,
                faction_hex,
                playerId,
                faction_hex,
                faction_name,
                reason_hex,
                reason_text,
                stream_text
            )

            addEventLog({
                kind = "disconnect",
                time = os.date("%H:%M:%S"),
                chat = chat_text,
                name = name,
                playerId = playerId,
                faction = faction_name,
                faction_color = faction_hex,
                reason = reason_text,
                reason_color = reason_hex,
                stream = stream_text,
                stream_color = stream_hex
            })
        end
    end

    confirmed_players[playerId] = nil
    pending_joins[playerId] = nil
    visible_players[playerId] = nil
    last_stream_time[playerId] = nil
end

function sampev.onPlayerStreamIn(playerId)
    visible_players[playerId] = true
    last_stream_time[playerId] = os.clock()
end

function sampev.onPlayerStreamOut(playerId)
    visible_players[playerId] = nil
    last_stream_time[playerId] = os.clock()
end

local settings_page = 1
local journal_page = 1

integration.drawSettings = function()
    local sw, sh = getScreenResolution()
    local titles = {'События', 'Фракции', 'Журнал на экране'}
    local width = imgui.GetContentRegionAvailWidth()
    local per_row = width >= 620 and 3 or (width >= 410 and 2 or 1)
    local tab_width = math.min(210, (width - (per_row - 1) * 8) / per_row)
    for index, title in ipairs(titles) do
        if (index - 1) % per_row ~= 0 then imgui.SameLine() end
        local active = settings_page == index
        if active then imgui.PushStyleColor(imgui.Col.Button, integration.color(integration.palette.selection)) end
        if imgui.Button(title .. '##joinquit_settings_' .. index, imgui.ImVec2(tab_width, 34)) then
            settings_page = index
            imgui.SetScrollY(0)
        end
        if active then imgui.PopStyleColor(1) end
    end
    imgui.Spacing()
    imgui.Separator()
    imgui.Spacing()
    if settings_page == 1 then
    local event_columns=integration.layout.begin('joinquit_event_preferences',680)
    integration.layout.heading('Какие события отслеживать')
    do
        local v = boolRef(settings.global.connects_enabled)
        if imgui.Checkbox("Показывать входы игроков", v) then
            settings.global.connects_enabled = v.v
            saveSettings()
        end
    end

    do
        local v = boolRef(settings.global.disconnects_enabled)
        if imgui.Checkbox("Показывать выходы игроков", v) then
            settings.global.disconnects_enabled = v.v
            saveSettings()
        end
    end

    do
        local v = boolRef(settings.ui.duplicate_to_chat)
        if imgui.Checkbox("Дублировать события в чат", v) then
            settings.ui.duplicate_to_chat = v.v
            saveSettings()
        end
    end

    integration.layout.next(event_columns)
    integration.layout.heading('Журнал на экране')
    do
        local v = boolRef(settings.ui.show_hud_log)
        if imgui.Checkbox("Показывать журнал на экране", v) then
            settings.ui.show_hud_log = v.v
            saveSettings()
        end
    end

    do
        local v = boolRef(settings.ui.show_timestamp)
        if imgui.Checkbox("Показывать время события", v) then
            settings.ui.show_timestamp = v.v
            saveSettings()
        end
    end
    integration.layout.finish(event_columns)
    imgui.Spacing()
    imgui.TextWrapped('Фракции выбираются на соседней вкладке. Изменения применяются к новым событиям.')
    elseif settings_page == 3 then
    imgui.Separator()
    local columns = integration.layout.begin('event_log_appearance', 740)
    integration.layout.heading('Расположение журнала')
    if imgui.Button('Переместить журнал##joinquit')then
        movingLog=true
        integration.beginPlacement(function()movingLog=false;saveSettings()end,function()
            local x,y=getCursorPos();local sw,sh=getScreenResolution()
            settings.ui.log_x=math.max(0,math.min(x,sw-100));settings.ui.log_y=math.max(0,math.min(y,sh-40))
        end)
    end

    do
        local v = intRef(settings.ui.log_x)
        if imgui.SliderInt("X##logx", v, 0, sw) then
            settings.ui.log_x = v.v
            saveSettings()
        end
    end

    do
        local v = intRef(settings.ui.log_y)
        if imgui.SliderInt("Y##logy", v, 0, sh) then
            settings.ui.log_y = v.v
            saveSettings()
        end
    end

    integration.layout.next(columns)
    integration.layout.heading('Внешний вид')
    do
        local v = intRef(settings.ui.log_max_lines)
        if imgui.SliderInt("Количество строк##loglines", v, 3, 20) then
            settings.ui.log_max_lines = v.v
            saveSettings()
        end
    end

    do
        local v = intRef(settings.ui.font_size)
        if imgui.SliderInt("Размер шрифта##fontsize", v, 7, 16) then
            settings.ui.font_size = v.v
            recreateHudFont()
            saveSettings()
        end
    end

    do
        local v = floatRef(settings.ui.log_alpha)
        if imgui.SliderFloat("Непрозрачность##logalpha", v, 0.20, 1.00) then
            settings.ui.log_alpha = v.v
            saveSettings()
        end
    end

    integration.layout.finish(columns)
    imgui.Spacing()
    if imgui.Button("Очистить журнал") then
        event_log = {}
    end
    if imgui.GetContentRegionAvailWidth() >= 360 then imgui.SameLine() end
    if imgui.Button("Сбросить позицию") then
        settings.ui.log_x = 30
        settings.ui.log_y = 300
        saveSettings()
    end

    elseif settings_page == 2 then
        imgui.TextWrapped('Входы и выходы для каждой фракции настраиваются независимо.')
        imgui.Spacing()
        if imgui.Button('Включить все##joinquit_factions', imgui.ImVec2(150, 34)) then
            setAll('connects', true); setAll('disconnects', true)
        end
        if imgui.GetContentRegionAvailWidth() >= 340 then imgui.SameLine() end
        if imgui.Button('Выключить все##joinquit_factions', imgui.ImVec2(160, 34)) then
            setAll('connects', false); setAll('disconnects', false)
        end
        imgui.Spacing()
        local width = imgui.GetContentRegionAvail().x
        imgui.Columns(3, 'joinquit_faction_matrix', false)
        imgui.SetColumnWidth(0, width * 0.44)
        imgui.SetColumnWidth(1, width * 0.28)
        imgui.TextDisabled('Фракция'); imgui.NextColumn()
        imgui.TextDisabled('Входы'); imgui.NextColumn()
        imgui.TextDisabled('Выходы'); imgui.NextColumn()
        imgui.Separator()
        imgui.AlignTextToFramePadding()
        imgui.TextDisabled('Выбрать все')
        imgui.NextColumn()
        for _, kind in ipairs({'connects', 'disconnects'}) do
            local all = true
            for _, faction in ipairs(faction_list) do
                if not settings[kind][faction.key] then all = false; break end
            end
            local v = boolRef(all)
            if imgui.Checkbox('##all_' .. kind, v) then setAll(kind, v.v) end
            imgui.NextColumn()
        end
        imgui.Separator()
        -- One matrix in the workspace flow: the mouse wheel always scrolls the page.
        for _, faction in ipairs(faction_list) do
            imgui.AlignTextToFramePadding()
            imgui.TextWrapped(faction.name)
            imgui.NextColumn()
            for _, kind in ipairs({'connects', 'disconnects'}) do
                local v = boolRef(settings[kind][faction.key])
                if imgui.Checkbox('##' .. kind .. '_' .. faction.key, v) then
                    settings[kind][faction.key] = v.v
                    saveSettings()
                end
                imgui.NextColumn()
            end
        end
        imgui.Columns(1)
    end

    imgui.Separator()
    imgui.TextDisabled('Изменения сохраняются автоматически.')


end
integration.onDisconnect = function()
    confirmed_players, pending_joins, visible_players, last_stream_time = {}, {}, {}, {}
    tracking_enabled = false
    startup_time = os.clock()
end

-- Journal shares the main workspace; filters live in common settings.
local journal_filter = 'all'
local journal_search = imgui.ImBuffer('', 128)
integration.draw = function()
    local joins, quits = 0, 0
    for _, e in ipairs(event_log) do
        if e.kind == 'connect' then joins = joins + 1 else quits = quits + 1 end
    end
    local green = imgui.ImVec4(0.48, 0.85, 0.67, 1)
    local red = imgui.ImVec4(0.96, 0.56, 0.62, 1)
    integration.layout.heading('Лента событий')
    imgui.TextDisabled('Последние 200 событий · новые сверху')
    imgui.Spacing()
    imgui.TextColored(green, 'ВХОДЫ  ' .. joins)
    imgui.SameLine();imgui.TextDisabled('   /   ')
    imgui.SameLine();imgui.TextColored(red, 'ВЫХОДЫ  ' .. quits)
    imgui.Spacing()
    for i, item in ipairs({{'all','Все'}, {'connect','Входы'}, {'disconnect','Выходы'}}) do
        if i > 1 then imgui.SameLine() end
        local active = journal_filter == item[1]
        if active then imgui.PushStyleColor(imgui.Col.Button, integration.color(integration.palette.selection)) end
        if imgui.Button(item[2] .. '##journal_filter', imgui.ImVec2(85, 30)) then journal_filter=item[1];journal_page=1 end
        if active then imgui.PopStyleColor() end
    end
    imgui.Spacing()
    imgui.TextDisabled('Найти по нику, ID или фракции')
    imgui.PushItemWidth(math.max(100, imgui.GetContentRegionAvailWidth()))
    if imgui.InputText('##journal_search', journal_search) then journal_page=1 end
    imgui.PopItemWidth()
    imgui.Spacing()
    local rows = {}
    local query = journal_search.v:lower()
    for i=#event_log,1,-1 do
        local e=event_log[i]
        local text=string.format('%s %s %s', e.name or '', tostring(e.playerId or -1), e.faction or '')
        if (journal_filter=='all' or journal_filter==e.kind) and (query=='' or text:lower():find(query,1,true)) then rows[#rows+1]=e end
    end
    imgui.TextDisabled('Найдено: ' .. #rows)
    if imgui.Button('Очистить журнал', imgui.ImVec2(170, 30)) then event_log={};rows={};journal_page=1 end
    imgui.Spacing()
    if #rows==0 then
        imgui.Separator();imgui.Spacing()
        imgui.TextWrapped(#event_log==0 and 'Здесь появятся входы и выходы игроков.' or 'Нет событий по выбранному фильтру.')
        imgui.TextDisabled(#event_log==0 and 'Отслеживание и фракции выбираются в настройках сверху.' or 'Измените поиск или выберите «Все».')
        return
    end
    local page_size=12
    local pages=math.max(1,math.ceil(#rows/page_size))
    journal_page=math.max(1,math.min(journal_page,pages))
    if pages>1 then
        if imgui.Button('Новее##joinquit',imgui.ImVec2(90,30)) then journal_page=math.max(1,journal_page-1) end
        imgui.SameLine();imgui.Text(' '..journal_page..' / '..pages..' ');imgui.SameLine()
        if imgui.Button('Раньше##joinquit',imgui.ImVec2(90,30)) then journal_page=math.min(pages,journal_page+1) end
    end
    local first=(journal_page-1)*page_size+1
    for i=first,math.min(#rows,first+page_size-1) do
        local e=rows[i]
        local entered=e.kind=='connect'
        imgui.PushID('journal_card_'..i)
        imgui.Spacing();imgui.Separator();imgui.Spacing()
        imgui.TextColored(entered and green or red, entered and '+  ВОШЁЛ' or '-  ВЫШЕЛ')
        imgui.SameLine();imgui.TextDisabled('   '..(e.time or ''))
        imgui.TextWrapped(string.format('%s  [%s]',e.name or '',tostring(e.playerId or -1)))
        imgui.TextDisabled(e.faction or '')
        if not entered then imgui.TextWrapped('Причина: '..(e.reason or 'не указана')) end
        imgui.PopID()
    end
end

    end
    sources["modules/killids.lua"] = function()
-- CasualAT module. Author: Casual Alvarez. Original source: integration/sources.
local samp = require 'samp.events'
local ffi = require 'ffi'

ffi.cdef[[
struct AdminToolsKillEntry
{
	char					szKiller[25];
	char					szVictim[25];
	uint32_t				clKillerColor; // D3DCOLOR
	uint32_t				clVictimColor; // D3DCOLOR
	uint8_t					byteType;
} __attribute__ ((packed));

struct AdminToolsKillInfo
{
	int						iEnabled;
	struct AdminToolsKillEntry		killEntry[5];
	int 					iLongestNickLength;
  	int 					iOffsetX;
  	int 					iOffsetY;
	void			    	*pD3DFont; // ID3DXFont
	void		    		*pWeaponFont1; // ID3DXFont
	void		   	    	*pWeaponFont2; // ID3DXFont
	void					*pSprite;
	void					*pD3DDevice;
	int 					iAuxFontInited;
    void 		    		*pAuxFont1; // ID3DXFont
    void 			    	*pAuxFont2; // ID3DXFont
} __attribute__ ((packed));
]]

local pending = {}
local generation = 0
local function formatted(name, id)
    local suffix = '[' .. id .. ']'
    return name:sub(1, math.max(0, 24 - #suffix)) .. suffix
end

function samp.onPlayerDeathNotification(killerId, killedId, reason)
    local hasId, myId = sampGetPlayerIdByCharHandle(PLAYER_PED)
    local function name(id)
        if sampIsPlayerConnected(id) or (hasId and id == myId) then return sampGetPlayerNickname(id) end
    end
    pending[#pending + 1] = {killer=name(killerId), victim=name(killedId), killerId=killerId, victimId=killedId, reason=reason}
    if #pending > 1 then return end
    local token = generation
    lua_thread.create(function()
        wait(0)
        if token ~= generation or not integration.featureAllowed() then return end
        local batch = pending
        pending = {}
        if not isSampAvailable() or sampGetGamestate() ~= 3 then return end
        local ptr = sampGetKillInfoPtr()
        if ptr == nil or ptr == 0 then return end
        local kill = ffi.cast('struct AdminToolsKillInfo*', ptr)
        -- Several notifications can arrive before one frame. Match each final
        -- row before editing; never reuse a pointer captured before the wait.
        for i = math.max(1, #batch - 4), #batch do
            local item = batch[i]
            local row = kill.killEntry[4 - (#batch - i)]
            if row.byteType == item.reason then
                if integration.preferences.data.main.killidsKiller and item.killer and ffi.string(row.szKiller) == item.killer:sub(1,24) then
                    row.szKiller = ffi.new('char[25]', formatted(item.killer, item.killerId))
                end
                if integration.preferences.data.main.killidsVictim and item.victim and ffi.string(row.szVictim) == item.victim:sub(1,24) then
                    row.szVictim = ffi.new('char[25]', formatted(item.victim, item.victimId))
                end
            end
        end
    end)
end
integration.onDisconnect = function()
    generation = generation + 1
    pending = {}
end

    end
    sources["modules/lego.lua"] = function()
-- Integrated LegoSearch by Shimizu. Shared X-Tools UI; no mimgui dependency.
local g=require('imgui')
local events=require('lib.samp.events')
local u8=require('encoding').UTF8
local ID,MAX_PAGES=688,30
local state={mode='idle',pages={},locations={},generation=0,ready=false}
local ownsDialogs=false
local search,author=g.ImBuffer(256),g.ImBuffer(128)
local minimum,maximum=g.ImInt(0),g.ImInt(0)
local statusFilter,sortMode=g.ImInt(0),g.ImInt(0)
local function clean(s) return tostring(s or ''):gsub('{%x%x%x%x%x%x}','') end
local function lines(s)
    local out={};for line in (s:gsub('\r','')..'\n'):gmatch('(.-)\n') do if line~='' then out[#out+1]=line end end;return out
end
local function lower(s)
    s=s:lower():gsub('Ё','ё')
    return (s:gsub('[\208\209][\128-\191]',function(c)
        local a,b=c:byte(1,2)
        if a==208 and b>=144 and b<=159 then return string.char(208,b+32) end
        if a==208 and b>=160 and b<=175 then return string.char(209,b-32) end
        return c
    end))
end
local function parse(text,style)
    local rows={};local list=lines(text)
    for i=style==5 and 2 or 1,#list do
        local cols={};for value in (list[i]..'\t'):gmatch('(.-)\t') do cols[#cols+1]=clean(value) end
        rows[#rows+1]={index=#rows,name=cols[1] or '',author=cols[2] or '',objects=cols[3] or '',status=cols[4] or ''}
    end
    return rows
end
local function enabled() return integration.preferences.data.main.legoReplace==true end
local function reset()
    ownsDialogs=false
    state={mode='idle',pages={},locations={},generation=state.generation+1,ready=false}
end
local function stop(message)
    state.generation=state.generation+1;state.mode='idle';state.status=message;state.pending=nil;state.deadline=nil
end
local function request(command)
    ownsDialogs=true
    state.deadline=getGameTimer()+5000
    sampSendChat(command or '/lego')
end
local function later(fn)
    local token=state.generation
    lua_thread.create(function()
        wait(420)
        if token==state.generation and enabled() and sampGetGamestate()==3 and integration.access:can(1) then fn() end
    end)
end
local function nextPage()
    later(function() state.deadline=getGameTimer()+5000;sampSendDialogResponse(ID,0,0,'') end)
end
local function rebuild()
    state.locations={}
    for page=1,MAX_PAGES do
        for _,row in ipairs(state.pages[page] or {}) do
            if row.index>1 or page==1 then row.page=page;state.locations[#state.locations+1]=row end
        end
    end
end
local function open(refresh)
    if not integration.access:require(1,integration.message) then return end
    integration.open('lego')
    if state.ready and not refresh then return end
    if state.mode~='idle' and not refresh then return end
    reset();state.mode='collect';state.page=1;state.status='Загрузка локаций…';request()
end
function events.onSendCommand(command)
    if not enabled() or integration.commandOwner()=='lego' then return end
    if command:lower():match('^/lego%s*$') then open(false);return false end
    if command:lower():match('^/legorefresh%s*$') then open(true);return false end
    -- Named /lego commands pass through unchanged and cancel owned navigation.
    if command:lower():match('^/lego%s+') then ownsDialogs=false;stop('Открыта обычная команда /lego с параметром.') end
end
-- Local chat handlers also work when another script consumes outgoing commands.
sampRegisterChatCommand('lego',function(argument)
    argument=tostring(argument or ''):match('^%s*(.-)%s*$')
    if not enabled() or argument~='' then
        ownsDialogs=false;stop('Открыта обычная команда /lego.');sampSendChat('/lego'..(argument~='' and ' '..argument or ''));return
    end
    open(false)
end)
sampRegisterChatCommand('legorefresh',function()
    if enabled()then open(true)else sampSendChat('/lego')end
end)
local function select(location)
    state.generation=state.generation+1;state.pending=location;state.page=1;state.mode='select';state.status='Открытие локации…';request()
end
function events.onShowDialog(id,style,title,b1,b2,body)
    if not enabled() then return end
    title,b1,b2,body=clean(u8(title)),clean(u8(b1)),clean(u8(b2)),u8(body)
    local listDialog=id==ID and (style==5 or style==4) and title:lower():find('lego',1,true)
    local actionDialog=clean(body):find('Загрузить или убрать локацию',1,true)
        and clean(body):find('Удалить локацию',1,true) and b1:find('Выбрать',1,true)
    -- Requests may finish after timeout, closing the overlay, or an action reply.
    -- Retain ownership until a named passthrough command or session reset.
    if ownsDialogs and listDialog and state.mode~='collect' and state.mode~='select' then
        if state.mode~='idle' then stop('Сервер вернул список. Нажмите «Обновить».') end
        return false
    end
    if ownsDialogs and actionDialog and state.mode~='action_wait' then return false end
    if state.mode=='idle' then return end
    if state.mode=='action_wait' then
        if clean(body):find('Загрузить или убрать локацию',1,true) and clean(body):find('Удалить локацию',1,true) and b1:find('Выбрать',1,true) then
            state.action={id=id,rows=lines(clean(body)),back=b2};state.mode='action';state.deadline=nil
            return false
        end
        stop('Сервер открыл другой диалог.');return
    end
    if state.mode~='collect' and state.mode~='select' then return end
    if id~=ID or (style~=5 and style~=4) or not title:lower():find('lego',1,true) then
        stop('Загрузка прервана другим диалогом.');return
    end
    state.deadline=nil
    local rows=parse(body,style)
    local nextNumber=tonumber(lower(b2):match('стр%.?%s*(%d+)'))
    if state.mode=='select' then
        local target=state.pending
        if state.page==target.page then
            local row=rows[target.index+1]
            if not row or row.name~=target.name or row.author~=target.author then
                state.ready=false;stop('Список изменился. Нажмите «Обновить».');return false
            end
            state.mode='action_wait'
            later(function() state.deadline=getGameTimer()+5000;sampSendDialogResponse(ID,1,target.index,'') end)
        elseif not nextNumber or nextNumber<=state.page or state.page>=MAX_PAGES then
            state.ready=false;stop('Нужная страница больше недоступна. Обновите список.')
        else state.page=nextNumber;nextPage() end
        return false
    end
    state.pages[state.page]=rows;rebuild()
    if nextNumber==1 or not nextNumber then
        state.ready=true;stop('Загружено локаций: '..#state.locations)
    elseif nextNumber<=state.page or nextNumber>MAX_PAGES then
        stop('Показана часть списка: достигнут предел страниц.');state.ready=true
    else state.page=nextNumber;nextPage() end
    return false
end
integration.update=function()
    if not enabled() and (state.mode~='idle' or state.ready) then reset() end
    if state.deadline and getGameTimer()>=state.deadline then
        rebuild();stop('Сервер не ответил. Доступны уже полученные строки; повторите обновление.')
    end
end
integration.onDisconnect=reset
integration.onWindowClosed=function() stop('Загрузка остановлена.') end
local function active(row) return lower(row.status):find('вкл',1,true)~=nil end
integration.draw=function()
    if not enabled() then g.TextWrapped('Включите «Заменять /lego автоматически» в игровых функциях.');return end
    if g.Button('Обновить##lego_refresh') then open(true) end
    g.SameLine();if g.Button('Остановить##lego_stop') then stop('Загрузка остановлена.') end
    g.TextWrapped(state.status or 'LEGO — поиск локаций')
    if state.mode=='action' then
        g.Separator();g.TextWrapped(state.pending and state.pending.name or 'Управление локацией')
        for i,row in ipairs(state.action.rows) do
            if g.Button(row..'##lego_action_'..i,g.ImVec2(-1,32)) then
                sampSendDialogResponse(state.action.id,1,i-1,'')
                state.ready=false;stop('Действие отправлено. Обновите список для проверки результата.');return
            end
        end
        if g.Button('Назад##lego_back') then
            sampSendDialogResponse(state.action.id,0,0,'');stop('Выберите локацию.');return
        end
        return
    end
    g.PushItemWidth(math.min(320,g.GetContentRegionAvail().x-16))
    g.InputText('Поиск по названию или автору',search)
    if g.CollapsingHeader('Фильтры##lego_filters') then
        g.InputText('Автор',author)
        g.InputInt('Минимум объектов',minimum);g.InputInt('Максимум (0 — любой)',maximum)
        minimum.v=math.max(0,minimum.v);maximum.v=math.max(0,maximum.v)
        g.Combo('Состояние',statusFilter,'Все\0Включены\0Выключены\0\0')
        g.Combo('Сортировать',sortMode,'По страницам\0По названию\0По числу объектов\0\0')
    end
    g.PopItemWidth()
    if g.CollapsingHeader('Команды LEGO##lego_commands') then
        g.TextWrapped('/lego [название] — открыть локацию; /legorefresh — перечитать список; /newobj — новый объект; /dellast — удалить последний; /delall — удалить объекты; /objedit — редактировать; /repeat — повторить действие.')
    end
    local filtered={};local query=lower(search.v);local creator=lower(author.v)
    for _,row in ipairs(state.locations) do
        local count=tonumber(row.objects:match('%d+')) or 0
        if row.index<2 or ((query=='' or lower(row.name..' '..row.author):find(query,1,true))
            and (creator=='' or lower(row.author):find(creator,1,true)) and count>=minimum.v
            and (maximum.v<=0 or count<=maximum.v) and (statusFilter.v==0 or active(row)==(statusFilter.v==1))) then filtered[#filtered+1]=row end
    end
    if sortMode.v==1 then table.sort(filtered,function(a,b)return lower(a.name)<lower(b.name)end)
    elseif sortMode.v==2 then table.sort(filtered,function(a,b)return (tonumber(a.objects) or 0)>(tonumber(b.objects) or 0)end) end
    g.Text('Найдено: '..#filtered..' / '..#state.locations)
    g.BeginChild('##lego_results',g.ImVec2(0,0),true)
    for _,row in ipairs(filtered) do
        local label=row.name..' | '..row.author..' | '..row.objects..' | '..row.status
        if g.Selectable(label..'##lego_'..row.page..'_'..row.index,false) and state.mode=='idle' then select(row) end
    end
    g.EndChild()
end

    end
    sources["modules/lookup.lua"] = function()
-- CasualTool account lookup: original parsers/storage with a single embedded ImGui view.
local imgui = require("admintools.ui")
local encoding = require("encoding")
local sampev = require("lib.samp.events")
local ffi = require("ffi")
local has_dkjson, dkjson = pcall(require, "dkjson")
local has_cjson, cjson = pcall(require, "cjson")
local has_luasql, luasql = pcall(require, "luasql.sqlite3")

if not has_cjson then
    has_cjson, cjson = pcall(require, "cjson.safe")
end

encoding.default = "CP1251"
u8 = encoding.UTF8

function cp1251_to_utf8(str)
    return tostring(u8(str or ""))
end

function utf8_to_cp1251(str)
    return u8:decode(tostring(str or ""))
end

local SCRIPT_TAG = "[X-Tools]"
