function get_online_player_id_for_account(account_label)
    local normalized = normalize_identity(account_label)
    if normalized == "" then
        return nil
    end

    local local_found, local_player_id = sampGetPlayerIdByCharHandle(PLAYER_PED)
    if local_found and local_player_id ~= nil then
        local local_nickname = strip_color_tags(cp1251_to_utf8(sampGetPlayerNickname(local_player_id) or ""))
        if normalize_identity(local_nickname) == normalized then
            return local_player_id
        end
    end

    for player_id = 0, 1003 do
        if (not local_player_id or player_id ~= local_player_id) and sampIsPlayerConnected(player_id) then
            local nickname = strip_color_tags(cp1251_to_utf8(sampGetPlayerNickname(player_id) or ""))
            if normalize_identity(nickname) == normalized then
                return player_id
            end
        end
    end

    return nil
end


local function pump_query_queue()
    local now = os.clock()

    if active_query and now - active_query.sent_at >= (tonumber(active_query.timeout) or QUERY_TIMEOUT) then
        local expired_kind = active_query.kind
        local expired_value = trim(active_query.value or "")
        local expired_role = get_active_query_role()
        if expired_kind == "offst" and expired_role == "offst_batch" and expired_value ~= "" then
            set_account_offst_lookup(expired_value, {
                message = "Нет ответа /offst",
            })
        end
        push_error(("Нет ответа на %s"):format(format_command(active_query.kind, active_query.value)))
        active_query = nil
        internal_command_guard = nil
        last_query_action_at = now
        force_next_query_immediately = false
    end

    if active_query ~= nil then
        return
    end

    if now < (tonumber(flood_cooldown_until or 0) or 0) then
        return
    end

    if #pending_queries == 0 then
        if retry_missing_batch_checks() then
            return
        end
        return
    end

    if not force_next_query_immediately and now - last_query_action_at < QUERY_DELAY then
        return
    end

    if pending_queries[1] and integration.queryBusy and integration.queryBusy(pending_queries[1].kind) then
        return
    end
    local next_query = table.remove(pending_queries, 1)
    if next_query then
        force_next_query_immediately = false
        send_query_now(next_query.kind, next_query.value, next_query.meta)
    end
end

local function register_commands()
    local function register(name, callback)
        sampRegisterChatCommand(name, function(params)
            integration.open('lookup')
            callback(params)
        end)
    end
    register("cadm", function() end)

    register("cget", function(params)
        start_lookup("get", cp1251_to_utf8(params or ""))
    end)

    register("creg", function(params)
        local target = cp1251_to_utf8(params or "")
        local clean_target = trim(strip_color_tags(target))
        if clean_target == "" then
            chat("Использование: /creg <ID игрока>", 0xE0C36A)
            return
        end

        local player_id = tonumber(clean_target)
        if player_id == nil then
            chat("/creg работает только по числовому ID игрока.", 0xE0C36A)
            return
        end

        player_id = math.floor(player_id)
        if not sampIsPlayerConnected(player_id) then
            chat(("Игрок с ID %d сейчас не в игре."):format(player_id), 0xE57373)
            return
        end

        local nickname = strip_color_tags(cp1251_to_utf8(sampGetPlayerNickname(player_id) or ""))
        if nickname == "" then
            chat(("Не удалось получить ник игрока с ID %d."):format(player_id), 0xE57373)
            return
        end

        request_registration_lookup(nickname)
    end)

    register("offcreg", function(params)
        local target = trim(strip_color_tags(cp1251_to_utf8(params or "")))
        if target == "" then
            chat("Использование: /offcreg <ник или номер аккаунта>", 0xE0C36A)
            return
        end

        request_registration_lookup(target)
    end)

    register("coffreg", function(params)
        local target = trim(strip_color_tags(cp1251_to_utf8(params or "")))
        if target == "" then
            chat("Использование: /coffreg <ник или номер аккаунта>", 0xE0C36A)
            return
        end

        request_registration_lookup(target)
    end)

    register("namestore", function(params)
        request_nick_history(cp1251_to_utf8(params or ""))
    end)

    register("cip", function(params)
        local target = trim(strip_color_tags(cp1251_to_utf8(params or "")))
        if target == "" then
            chat("Использование: /cip <IP-адрес>", 0xE0C36A)
            return
        end
        if not is_ip(target) then
            chat("Введите корректный IPv4-адрес: /cip <IP-адрес>.", 0xE57373)
            return
        end

        request_ip_preview(target)
    end)

    register("clip", function(params)
        local target = trim(strip_color_tags(cp1251_to_utf8(params or "")))
        if target == "" then
            chat("Использование: /clip <IP-адрес>", 0xE0C36A)
            return
        end
        if not is_ip(target) then
            chat("Введите корректный IPv4-адрес: /clip <IP-адрес>.", 0xE57373)
            return
        end

        request_lip_preview(target)
    end)

    register("cas", function(params)
        local target = cp1251_to_utf8(params or "")
        local clean_target = trim(strip_color_tags(target))
        if clean_target == "" then
            chat("Использование: /cas <ID игрока>", 0xE0C36A)
            return
        end
        local player_id = tonumber(clean_target)
        if player_id == nil then
            chat("/cas принимает ID игрока. Для ника или номера аккаунта используйте /cget.", 0xE0C36A)
            return
        end
        player_id = math.floor(player_id)
        if not sampIsPlayerConnected(player_id) then
            chat(("Игрок с ID %d сейчас не в игре."):format(player_id), 0xE57373)
            return
        end

        local nickname = strip_color_tags(cp1251_to_utf8(sampGetPlayerNickname(player_id) or ""))
        if nickname == "" then
            chat(("Не удалось получить ник игрока с ID %d."):format(player_id), 0xE57373)
            return
        end

        start_lookup("get", nickname)
    end)
end


function sampev.onSendCommand(command)
    local owner = integration.commandOwner and integration.commandOwner()
    if owner and owner ~= 'lookup' then return end
    local raw = strip_color_tags(cp1251_to_utf8(command or ""))
    if raw == "" then
        return
    end

    local normalized = raw:lower()
    if internal_command_guard and normalized == internal_command_guard then
        internal_command_guard = nil
        return
    end

    local kind, value = raw:match("^/?([^%s]+)%s*(.*)$")
    kind = kind and kind:lower() or ""
    value = strip_color_tags(value)

    if not SUPPORTED_COMMANDS[kind] then
        return
    end

    stop_all_checks("Проверка остановлена ручной командой")

    return
end

function sampev.onServerMessage(color, text)
    syncAccess()
    if message_reports_flood(text or "") and (active_query ~= nil or #pending_queries > 0 or command_context ~= nil or main_window_state[0] or main_window_minimized) then
        if handle_flood_message(text or "") then
            return false
        end
        flood_cooldown_until = math.max(tonumber(flood_cooldown_until or 0) or 0, os.clock() + 5.0)
        last_query_action_at = flood_cooldown_until
        force_next_query_immediately = false
        set_server_notice(strip_color_tags(cp1251_to_utf8(text or "")), "muted", 6.0)
        return false
    end
    if handle_flood_message(text or "") then
        return false
    end
    if handle_empty_result_message(text or "") then
        return false
    end
end

function sampev.onShowDialog(dialog_id, style, title, button1, button2, text)
    syncAccess()
    if not integration.access:can(3) then return end
    local dialog = {
        id = tonumber(dialog_id) or 0,
        style = tonumber(style) or 0,
        title = strip_color_tags(cp1251_to_utf8(title or "")),
        button1 = cp1251_to_utf8(button1 or ""),
        button2 = cp1251_to_utf8(button2 or ""),
        text = cp1251_to_utf8(text or ""),
    }

    if looks_like_history_dialog(dialog.title) and history_preview and history_preview.loading then
        return handle_history_dialog(dialog)
    end

    local kind = detect_dialog_kind(dialog)
    if not kind then
        return
    end

    if kind == "get" or kind == "admget" or kind == "account" then
        parse_account_dialog(kind, dialog)
        return false
    end

    if kind == "iplog" then
        parse_iplog_dialog(dialog)
        return false
    end

    if kind == "ip" or kind == "lip" then
        upsert_ip_section(kind, dialog)
        return false
    end

    if kind == "log" then
        parse_log_dialog(dialog)
        return false
    end

    if kind == "baninfo" then
        parse_baninfo_dialog(dialog)
        return false
    end

    if kind == "offst" then
        parse_offst_dialog(dialog)
        return false
    end

    if kind == "ip_related" then
        upsert_ip_section("ip", dialog)
        return false
    end
end

function integration.start()
    repeat
        wait(200)
    until isSampAvailable()

    load_config()
    ensure_storage_artifacts()
    register_commands()

    while true do
        wait(0)
        if integration.update then integration.update() end
        pump_query_queue()
    end
end

-- All controls are drawn inside CasualTool. Only the host owns windows/scrolling.
View = {page = 'profile', pages = {}, selected = nil, preview = 'ip',
    filter = imgui.new.char[96](), target = nil, confirmBan = nil}

function View.selectPage(page)
    View.page, View.selected, View.selectedId, View.confirmBan = page, nil, nil, nil
    set_buffer_text(View.filter, '')
end

function View.beginLookup()
    View.selectPage('profile')
    View.pages, View.target = {}, nil
    for _, state in ipairs({ip_preview_window_state, lip_preview_window_state, ipwhois_preview_window_state,
        ip_accounts_window_state, account_preview_window_state, registration_preview_window_state, history_window_state}) do
        state[0] = false
    end
    integration.open('lookup')
end

function View.button(label, action, same)
    local width = imgui.CalcTextSize(label:match('^(.-)##') or label).x + 30
    if not same then
        View.rowMax = imgui.GetContentRegionAvail().x
        View.rowWidth = width
    elseif (View.rowWidth or 0) + width + 10 <= (View.rowMax or 0) then
        imgui.SameLine(); View.rowWidth = View.rowWidth + width + 10
    else
        View.rowWidth = width
    end
    if imgui.Button(label) then action() end
end

function View.append(rows, title, values)
    if not values or #values == 0 then return end
    rows[#rows + 1] = {text = title, tone = 'accent', heading = true}
    for _, row in ipairs(values) do rows[#rows + 1] = row end
end

function View.profileRows(current)
    local rows = {}
    if current then
        View.append(rows, 'Аккаунт', current.profile_rows)
        View.append(rows, 'Примечания', current.note_rows)
        View.append(rows, 'Статистика аккаунта', current.offst_rows)
        View.append(rows, 'Блокировки', current.ban_rows)
        View.append(rows, 'Сравнение IP', current.geo_compare_rows)
        View.append(rows, 'Сохранённые связи аккаунтов', current.geo_saved_rows)
        View.append(rows, 'Ошибки запроса', current.errors)
    end
    return rows
end

function View.currentRows()
    if View.page == 'profile' then return View.profileRows(session) end
    if View.page == 'history' then return history_preview and history_preview.rows or {} end
    if View.page == 'auth' then return session and session.auth_rows or {} end
    if View.page == 'punish' then return session and session.punish_rows or {} end
    local rows = {}
    if View.page == 'ips' and session then
        for _, kind in ipairs({'ip', 'lip'}) do
            for _, section in ipairs(collect_session_sections_by_kind(session, kind)) do
                rows[#rows + 1] = {text = section.title or kind, ip = section.ip, tone = 'accent'}
                for _, row in ipairs(section.rows or {}) do rows[#rows + 1] = row end
            end
        end
    elseif View.page == 'details' then
        if View.preview == 'account' then return View.profileRows(account_preview)
        elseif View.preview == 'registration' then return View.profileRows(registration_preview)
        elseif View.preview == 'accounts' then
            for _, nick in ipairs(get_ip_account_labels(View.target or '')) do
                rows[#rows + 1] = {text = nick, account = nick}
            end
        else
            local preview = session and session[View.preview .. '_preview']
            if preview then
                rows[#rows + 1] = {text = preview.title or preview.ip, ip = preview.ip, tone = 'accent'}
                for _, row in ipairs(preview.rows or {}) do rows[#rows + 1] = row end
            end
        end
    elseif View.page == 'raw' and session then
        for _, dialog in ipairs(session.raw_dialogs or {}) do
            rows[#rows + 1] = {text = (dialog.kind or '') .. ': ' .. (dialog.title or ''), heading = true, tone = 'accent'}
            for _, line in ipairs(split_lines(dialog.text)) do rows[#rows + 1] = {text = line} end
        end
    end
    return rows
end

function View.openPreview(kind, target)
    View.selectPage('details')
    View.preview, View.target = kind, target
    if kind == 'ip' then request_ip_preview(target)
    elseif kind == 'lip' then request_lip_preview(target)
    elseif kind == 'ipwhois' then request_ipwhois_preview(target, false)
    elseif kind == 'account' then request_account_preview(target)
    elseif kind == 'registration' then request_registration_lookup(target) end
end

function View.actions(row)
    if not row or row.heading then return end
    imgui.Separator()
    imgui.TextWrapped(tostring(row.text or ''))
    View.button('Копировать строку##lookup_copy_row', function() copy_to_clipboard(row.text) end)
    local ip = trim(row.ip or extract_ip_from_text(row.text))
    if ip ~= '' then
        View.button('/ip##lookup_ip', function() View.openPreview('ip', ip) end, true)
        View.button('/lip##lookup_lip', function() View.openPreview('lip', ip) end, true)
        View.button('Геоданные##lookup_geo', function() View.openPreview('ipwhois', ip) end, true)
        View.button('Связанные аккаунты##lookup_links', function() View.openPreview('accounts', ip) end, true)
        if not row.account and not row.nick then return end
    end
    local account = trim(row.account or row.nick or extract_account_target_from_text(row.text))
    if account == '' then return end
    imgui.TextDisabled(account .. format_account_offst_brief(account))
    View.button('Открыть профиль##lookup_account', function() View.openPreview('account', account) end)
    View.button('Проверить аккаунт##lookup_collect', function() start_lookup('get', account); View.selectPage('profile') end, true)
    View.button('Проверить блокировки##lookup_ban', function() request_baninfo_for_accounts({account}, 'Выбранный аккаунт', true) end, true)
    View.button('Запросить статистику##lookup_offst', function() request_offst_for_accounts({account}, 'Выбранный аккаунт', true) end, true)
    local online = get_online_player_id_for_account(account)
    if online then imgui.TextColored(THEME.good, 'В игре: ID ' .. online) end
    View.button('/sban · 30 дней##lookup_sban', function() View.confirmBan = account end)
    if View.confirmBan == account then
        imgui.TextWrapped('Заблокировать ' .. account .. ' на 30 дней с причиной «До выяснений.»?')
        View.button('Заблокировать на 30 дней##lookup_confirm_sban', function() send_sban_for_account(account); View.confirmBan = nil end)
        View.button('Отменить##lookup_cancel_sban', function() View.confirmBan = nil end, true)
    end
end

function View.rows(rows)
    imgui.Text('Фильтр результатов')
    imgui.PushItemWidth(math.min(360, imgui.GetContentRegionAvail().x - 20))
    if imgui.InputText('##lookup_filter', View.filter, ffi.sizeof(View.filter)) then
        View.pages[View.page], View.selected = 1, nil
    end
    imgui.PopItemWidth()
    local query, filtered = lower_text(get_buffer_text(View.filter)), {}
    for _, row in ipairs(rows) do
        if query == '' or lower_text(row.text):find(query, 1, true) then filtered[#filtered + 1] = row end
    end
    local total = math.max(1, math.ceil(#filtered / 12))
    local page = math.min(total, math.max(1, View.pages[View.page] or 1))
    View.pages[View.page] = page
    View.button('<##lookup_prev', function() View.pages[View.page] = math.max(1, page - 1); View.selected = nil end)
    imgui.SameLine(); imgui.Text(('Страница %d / %d · строк: %d'):format(page, total, #filtered))
    View.button('>##lookup_next', function() View.pages[View.page] = math.min(total, page + 1); View.selected = nil end, true)
    imgui.Separator()
    if #filtered == 0 then imgui.TextDisabled('Нет результатов. Выполните проверку или измените фильтр.') end
    for index = (page - 1) * 12 + 1, math.min(page * 12, #filtered) do
        local row = filtered[index]
        View.readableRow('lookup_row_' .. index, row)
    end
end

-- A dossier is a structured page, not a paginated dump of unrelated rows.
-- Cards remain in the host's scroll flow; their text is never truncated.
function View.heading(title, count)
    imgui.Spacing()
    imgui.PushStyleColor(imgui.Col.Text,THEME.accent)
    imgui.TextWrapped(title .. (count and (' · ' .. count) or ''))
    imgui.PopStyleColor()
    imgui.Separator()
end

function View.readableRow(id, row)
    local text = tostring(row.text or '')
    if text == '' then return end
    local selectionKey = id .. '\0' .. text
    imgui.PushID(id)
    imgui.PushStyleColor(imgui.Col.Text, row_text_color(row.tone or 'normal'))
    imgui.TextWrapped(text)
    imgui.PopStyleColor()
    if not row.heading then
        if imgui.IsItemClicked(0) then View.selected, View.selectedId = row, selectionKey; View.confirmBan = nil end
        if imgui.IsItemHovered() then imgui.SetTooltip('Нажмите: копирование и действия с аккаунтом или IP') end
        if View.selected and View.selectedId == selectionKey then
            View.selected = row
            View.actions(row)
        end
    end
    imgui.PopID()
end

function View.cardRows(id, title, rows, empty, maximum, destination)
    rows = rows or {}
    View.heading(title, #rows)
    if #rows == 0 then imgui.TextWrapped(empty); return end
    for index = 1, math.min(#rows, maximum or #rows) do
        View.readableRow(id .. '_' .. index, rows[index])
    end
    if maximum and #rows > maximum then
        View.button(('Все записи (%d)##lookup_all_%s'):format(#rows, id), function() View.selectPage(destination) end)
    end
end

function View.commandCard(current, kind)
    local sections = collect_session_sections_by_kind(current, kind)
    View.heading(kind == 'ip' and 'Аккаунты по /ip' or 'Аккаунты по /lip', #sections)
    if #sections == 0 then imgui.TextWrapped('Ответ ' .. '/' .. kind .. ' пока не получен.'); return end
    for sectionIndex, section in ipairs(sections) do
        View.readableRow(kind .. '_section_' .. sectionIndex,
            {text = section.title or section.ip or kind, ip = section.ip, tone = 'accent'})
        local rows = section.rows or {}
        for index = 1, #rows do
            View.readableRow(kind .. '_' .. sectionIndex .. '_' .. index, rows[index])
        end

    end
end

function View.dossier(current, complete)
    if not current then
        imgui.TextWrapped('Введите игрока и нажмите «Проверить». Здесь появится подробное досье, которое будет дополняться по мере получения ответов сервера.')
        return
    end
    local name = trim(current.nick or '')
    if name == '' then name = current.target or 'Аккаунт' end
    imgui.TextColored(THEME.accent, name)
    local meta = {}
    if trim(current.account or '') ~= '' then meta[#meta + 1] = 'Аккаунт № ' .. current.account end
    if trim(current.level or '') ~= '' then meta[#meta + 1] = 'Уровень игрока: ' .. current.level end
    meta[#meta + 1] = 'Обновлено: ' .. format_time(current.updated_at)
    imgui.TextWrapped(table.concat(meta, '   ·   '))
    local columns = integration.layout.begin('lookup_dossier', 780)
    View.cardRows('dossier_profile', 'Профиль аккаунта', current.profile_rows, 'Ожидание ответа /get…')
    if #current.note_rows > 0 then View.cardRows('dossier_notes', 'Примечания', current.note_rows, '') end
    View.cardRows('dossier_stats', 'OFFST /offst', current.offst_rows, 'Статистика ещё не получена.')
    View.cardRows('dossier_bans', 'BANINFO /baninfo', current.ban_rows, 'Сведения о блокировках ещё не получены.')
    if #current.errors > 0 then View.cardRows('dossier_errors', 'Ошибки и таймауты', current.errors, '') end
    integration.layout.next(columns)
    View.cardRows('dossier_geo', 'Регистрационные данные: регистрация и последний вход', current.geo_compare_rows, 'Ожидание IP из профиля…')
    if is_ip(current.reg_ip or '') or is_ip(current.last_ip or '') then
        View.button('Повторить загрузку геоданных##lookup_retry_geo', function()
            local seen = {}
            for _, ip in ipairs({current.reg_ip or '', current.last_ip or ''}) do
                if is_ip(ip) and not seen[ip] then lookup_ipwhois(ip, true); seen[ip] = true end
            end
            geo_changed = true
        end)
    end
    local accounts,seen={},{}
    for _,ip in ipairs({current.reg_ip or '',current.last_ip or ''}) do
        for _,account in ipairs(get_ip_account_labels(ip)) do
            local key=normalize_identity(account)..'@'..ip
            if not seen[key] then
                accounts[#accounts+1]={text=account..' — '..ip,account=account,ip=ip}
                seen[key]=true
            end
        end
    end
    View.cardRows('dossier_saved','История совпадений по IP',accounts,'Этот IP ещё не встречался в сохранённой истории.')
    imgui.TextWrapped('Ник — IP: сохраняются подтверждённые ответы предыдущих проверок. Совпадение IP не доказывает общего владельца.')
    if complete then
        View.commandCard(current, 'ip')
        View.commandCard(current, 'lip')
        View.cardRows('dossier_auth', 'Авторизации', current.auth_rows,
            integration.access:can(5) and 'История входов ещё не получена.' or 'История входов доступна с 5-го уровня администратора.')
        View.cardRows('dossier_punish', 'Наказания', current.punish_rows, 'История наказаний ещё не получена.')
    end
    integration.layout.finish(columns)
end

function integration.draw()
    if not config then imgui.TextDisabled('Ожидание подключения к серверу…'); return end
    local width = imgui.GetContentRegionAvailWidth()
    local check_width = imgui.CalcTextSize('Проверить').x + 30
    local busy = active_query ~= nil or #pending_queries > 0
    local stop_width = busy and (imgui.CalcTextSize('Остановить').x + 30) or 0
    local inline_stop = busy and width >= check_width + stop_width + 176
    local input_width = math.max(80, width - check_width - 12 - (inline_stop and (stop_width + 8) or 0))
    imgui.TextWrapped('Ник или № аккаунта')
    imgui.PushItemWidth(input_width)
    imgui.InputText('##lookup_target', query_input, ffi.sizeof(query_input))
    imgui.PopItemWidth()
    imgui.SameLine()
    if imgui.Button('Проверить##lookup_start', imgui.ImVec2(check_width, 32)) then
        start_lookup('get', get_buffer_text(query_input)); View.selectPage('profile')
    end
    if busy then
        if inline_stop then imgui.SameLine() end
        if imgui.Button('Остановить##lookup_stop', imgui.ImVec2(stop_width, 32)) then stop_all_checks('Проверка остановлена') end
    end
    imgui.TextWrapped(('Уровень %s · В очереди: %d · %s'):format(get_admin_level_text(), #pending_queries, session and session.status or 'Ожидание запроса'))
    if server_notice.expires > os.clock() then imgui.TextWrapped(server_notice.text) end
    if clipboard_notice.expires > os.clock() then imgui.TextColored(THEME.good, 'Скопировано в буфер обмена') end
    local tabs = {{'profile','Профиль'},{'ips','IP и аккаунты'},{'auth','Авторизации'},
        {'punish','Наказания'},{'history','История ников'},{'details','Подробнее'},{'raw','Ответы сервера'}}
    local current, titles = 0, {}
    for index, tab in ipairs(tabs) do
        if tab[1] == View.page then current = index - 1 end
        titles[#titles + 1] = tab[2]
    end
    local selected = imgui.ImInt(current)
    imgui.PushItemWidth(-1)
    if imgui.Combo('##lookup_page', selected, table.concat(titles, '\0') .. '\0\0') then
        local tab = tabs[selected.v + 1]
        if tab then View.selectPage(tab[1]); imgui.SetScrollY(0) end
    end
    imgui.PopItemWidth()
    if imgui.CollapsingHeader('Действия##lookup_actions') then
        View.button('Обновить##lookup_refresh', function()
            start_lookup('get', session and (session.source_query or session.target) or get_buffer_text(query_input)); View.selectPage('profile')
        end)
        View.button('Очистить результаты##lookup_reset', function() stop_all_checks(); session = nil; account_preview = nil; registration_preview = nil; View.selected = nil end, true)
        View.button('Как проверить игрока##lookup_help', function() integration.openHelp('lookup') end, true)
        View.button('Свернуть##lookup_compact_minimize', function() main_window_minimized=true end, true)
        if View.page == 'profile' then
            View.button('Копировать досье##lookup_copy', function() copy_to_clipboard(compose_full_dossier_dump(session)) end)
            View.button('Сохранить в TXT##lookup_export', function()
                local path, err = export_session_dossier(session)
                if path then set_server_notice('Сохранено: ' .. path, 'good', 8) else set_server_notice(err or 'Нет данных', 'alert', 5) end
            end, true)
            View.button('Отправить сводку в /a##lookup_share', function() send_admin_chat_summary(session) end, true)
        end
    end
    if View.page == 'profile' then
        -- The dossier follows the compact toolbar immediately.
    elseif View.page == 'ips' then
        local rows = View.currentRows()
        local targets = collect_row_account_targets(rows)
        View.button('Запросить статистику всех##lookup_batch_offst', function() request_offst_for_accounts(targets, 'Связанные аккаунты', false) end)
        View.button('Проверить блокировки всех##lookup_batch_ban', function() request_baninfo_for_accounts(targets, 'Связанные аккаунты', false) end, true)
        local state = summarize_account_ban_checks(targets)
        imgui.TextDisabled(('Аккаунтов: %d · проверено: %d · блокировок: %d'):format(#targets, state.checked, state.banned))
    elseif View.page == 'history' then
        View.button('Запросить историю ников##lookup_history', function()
            request_nick_history(session and (session.nick ~= '' and session.nick or session.target) or get_buffer_text(query_input))
        end)
        if history_preview then imgui.TextDisabled(history_preview.status or '') end
    elseif View.page == 'details' then
        imgui.TextDisabled('Выберите строку с аккаунтом или IP, чтобы открыть данные и доступные действия.')
        if View.preview == 'ipwhois' and View.target then
            View.button('Обновить геоданные##lookup_geo_refresh', function() request_ipwhois_preview(View.target, true) end)
        end
    end
    if View.page == 'profile' then View.dossier(session, true)
    elseif View.page == 'details' and (View.preview == 'account' or View.preview == 'registration') then
        View.dossier(View.preview == 'account' and account_preview or registration_preview, false)
    else View.rows(View.currentRows()) end
end

-- Keep the complete single-flow dossier for small windows and larger UI scales.
-- The original multi-pane view below remains available when its columns fit.
local render_compact_dossier = integration.draw

function integration.drawSettings()
    if not config then imgui.TextDisabled('Ожидание подключения к серверу…'); return end
    if imgui.Checkbox('Собирать связанные данные при проверке игрока##lookup_auto', auto_collect_state) then
        save_config()
        if not auto_collect_state[0] then stop_all_checks('Автосбор выключен') end
    end
    imgui.TextWrapped('После получения профиля X-Tools запрашивает IP, связанные аккаунты, статистику и наказания. С 5-го уровня также доступны /admget и история входов /iplog. Отключение отменяет текущую очередь запросов.')
    imgui.TextWrapped('Досье сохраняется в TXT по кнопке «Сохранить в TXT». Файлы находятся в moonloader/config/CasualTool/data/dossiers.')
    imgui.TextWrapped('Геоданные загружаются с ipwho.is и сохраняются для повторного просмотра. Местоположение по IP приблизительное и само по себе не подтверждает связь аккаунтов.')
    View.button('Справка по проверке игрока##lookup_settings_help', function() integration.openHelp('lookup') end)
end

function integration.update()
    syncAccess()
    for ip, state in pairs(pending_geo) do
        if state.completed then state.finish(true)
        elseif os.clock() - state.started > 12 then state.finish(false, 'ipwho.is не ответил за 12 секунд') end
    end
    if geo_changed then
        geo_changed = false
        for _, current in pairs({session = session, account = account_preview, registration = registration_preview}) do
            build_geo_compare_rows(current)
            if current.ipwhois_preview then
                local preview = current.ipwhois_preview
                preview.info = ipwho_cache[preview.ip]
                preview.rows = build_ipwhois_rows(preview.ip, preview.info)
            end
        end
    end
    if history_preview and history_preview.loading and os.clock() - (history_preview.started_at or 0) > 20 then
        history_preview.loading = false; history_preview.status = 'История: время ожидания истекло'
    end
end

function integration.onDisconnect(reason)
    accessRevision = integration.access:revision()
    lookup_generation = lookup_generation + 1
    stop_all_checks(reason or 'Соединение прервано')
    history_collect, history_preview = nil, nil
    session, account_preview, registration_preview = nil, nil, nil
    for ip, state in pairs(pending_geo) do os.remove(state.path); ipwho_cache[ip] = nil end
    pending_geo = {}
    View.selected, View.confirmBan = nil, nil
end

function integration.stop()
    integration.onDisconnect()
    if sql_conn then pcall(function() sql_conn:close() end); sql_conn = nil end
    if sql_env then pcall(function() sql_env:close() end); sql_env = nil end
end

function integration.lookupState()
    return {page = View.page, target = session and session.target, queued = #pending_queries,
        active = active_query and active_query.kind, autoCollect = auto_collect_state[0],
        profileRows = session and #session.profile_rows or 0, historyRows = history_preview and #history_preview.rows or 0}
end

-- Share ownership with modules that use the same native server response.
function integration.queryPending(kind)
    return kind == 'offst' and active_query ~= nil and active_query.kind == kind
end


