get_probe_button_state = function(ip)
    local info = get_cached_ipwhois(ip)
    if info and info.success ~= false then
        local label = trim(info.country or "")
        if label == "" then
            label = trim(info.country_code or "")
        end
        if label == "" then
            label = trim(info.region or "")
        end
        if label == "" then
            label = trim(info.city or "")
        end
        if label ~= "" then
            return shorten_text(label, 14), "good", ("Открыть пробив по IP (%s)"):format(label)
        end
    end
    if info and info.success == false then
        return "Ошибка", "alert", trim(info.message or "ipwho.is недоступен")
    end
    return "Пробив", "muted", "Открыть расширенную информацию по IP через ipwho.is"
end

function draw_right_counter(text, tone)
    local label = trim(text)
    if label == "" then
        return
    end

    imgui.SameLine()
    local size = imgui.CalcTextSize(label)
    local available = imgui.GetContentRegionAvail()
    if available.x > size.x then
        imgui.SetCursorPosX(imgui.GetCursorPosX() + available.x - size.x)
    end
    imgui.TextColored(row_text_color(tone or "muted"), label)
end

function calc_chip_width(label)
    local text = trim(label)
    if text == "" then
        return 0
    end

    local style = imgui.GetStyle()
    local size = imgui.CalcTextSize(text)
    return size.x + style.FramePadding.x * 2 + 10
end

function push_actions_to_right(labels, min_gap)
    local total_width = 0
    local count = 0

    for _, label in ipairs(labels or {}) do
        local width = calc_chip_width(label)
        if width > 0 then
            total_width = total_width + width
            count = count + 1
        end
    end

    if count == 0 then
        return
    end

    total_width = total_width + math.max(0, count - 1) * 6

    imgui.SameLine()
    local available = imgui.GetContentRegionAvail()
    local shift = available.x - total_width
    if shift < (min_gap or 18) then
        shift = min_gap or 18
    end
    imgui.SetCursorPosX(imgui.GetCursorPosX() + shift)
end

function draw_section_header(title, hint)
    imgui.TextColored(THEME.gold, title)
    if hint and hint ~= "" then
        imgui.SameLine()
        imgui.TextDisabled(hint)
    end
    imgui.Separator()
end

draw_rows = function(id_prefix, rows, empty_text)
    local is_profile_like = id_prefix == "profile" or id_prefix == "account_preview_profile_rows"
    local is_wrapped_block = is_profile_like
        or id_prefix == "offst_rows"
        or id_prefix == "baninfo_rows"
        or id_prefix == "account_preview_baninfo_rows"
    if not rows or #rows == 0 then
        imgui.TextDisabled(empty_text or "Нет данных")
        return
    end

    for index, row in ipairs(rows) do
        local row_id = ("%s_%d"):format(id_prefix, index)
        local text = trim(row and row.text or "")
        local ip = trim(row and row.ip or "")
        local account_target = ""
        if ip == "" then
            ip = extract_ip_from_text(text)
        end
        if ip == "" then
            account_target = extract_account_target_from_text(text)
        end

        if ip ~= "" then
            local wrap_actions = is_profile_like and should_wrap_profile_ip_actions(text, ip)
            draw_clickable_text_row(row_id, text, row and row.tone or "normal", ip)
            if wrap_actions then
                imgui.Indent(16)
                draw_ip_actions_inline(row_id, ip, { inline = false })
                imgui.Unindent(16)
            else
                draw_ip_actions_inline(row_id, ip, { inline = true })
            end
        elseif account_target ~= "" then
            local online_id = get_online_player_id_for_account(account_target)
            local display_text = online_id and ("%s (ID: %d)"):format(account_target, online_id) or text
            display_text = display_text .. format_account_offst_brief(account_target)
            local ban_entry = get_account_ban_lookup(account_target)
            local row_tone = online_id and "good" or (row and row.tone or "normal")
            if ban_entry and ban_entry.is_banned then
                row_tone = "alert"
            end
            draw_clickable_text_row(row_id, display_text, row_tone, account_target)
            draw_account_actions_inline(row_id, account_target)
        else
            if is_wrapped_block then
                draw_wrapped_copyable_row(row_id, text, row and row.tone or "normal", true)
            else
                draw_copyable_row(row_id, text, row and row.tone or "normal")
            end
        end
    end
end

render_auth_entries = function(entries)
    if not entries or #entries == 0 then
        imgui.TextDisabled("Нет авторизаций")
        return
    end

    for index, entry in ipairs(entries) do
        local has_structured = trim(entry.date or "") ~= "" or trim(entry.time or "") ~= "" or trim(entry.ip or "") ~= ""
        if has_structured then
            if trim(entry.date or "") ~= "" then
                draw_copy_chip(("auth_date_%d"):format(index), entry.date, entry.date, "accent", "Скопировать дату")
            end
            if trim(entry.time or "") ~= "" then
                if trim(entry.date or "") ~= "" then
                    imgui.SameLine()
                end
                draw_copy_chip(("auth_time_%d"):format(index), entry.time, entry.time, "normal", "Скопировать время")
            end
            if trim(entry.ip or "") ~= "" then
                if trim(entry.date or "") ~= "" or trim(entry.time or "") ~= "" then
                    imgui.SameLine()
                end
                draw_copy_chip(("auth_ip_%d"):format(index), entry.ip, entry.ip, "accent", "Скопировать IP")
                imgui.SameLine()
                if draw_action_chip(("auth_ip_preview_%d"):format(index), "IP", "accent", "Быстро открыть /ip по этому IP") then
                    request_ip_preview(entry.ip)
                end
                imgui.SameLine()
                if draw_action_chip(("auth_lip_%d"):format(index), "LIP", "accent", "Быстро открыть /lip по этому IP") then
                    request_lip_preview(entry.ip)
                end
                imgui.SameLine()
                draw_probe_action_inline(("auth_%d"):format(index), entry.ip)
            end
            if trim(entry.full_text or "") ~= "" then
                if trim(entry.date or "") ~= "" or trim(entry.time or "") ~= "" or trim(entry.ip or "") ~= "" then
                    imgui.SameLine()
                end
                draw_copy_chip(("auth_full_%d"):format(index), "всё", entry.full_text, "muted", "Скопировать всю строку")
            end
            if tonumber(entry.ip_hits or 0) and tonumber(entry.ip_hits or 0) > 0 then
                draw_right_counter(("входов: %d"):format(tonumber(entry.ip_hits or 0)), tonumber(entry.ip_hits or 0) > 1 and "accent" or "muted")
            end
        else
            draw_copyable_row(("auth_raw_%d"):format(index), entry.raw_text or entry.full_text or "-", "normal")
        end
    end
end

render_top_bar = function()
    if imgui.Button('Остановить##lookup_stop') then stop_all_checks('Проверка остановлена') end
    imgui.SameLine()
    if imgui.Button('Повторить загрузку геоданных##lookup_retry_geo') and session then
