        imgui.EndTooltip()
    end
    imgui.PopStyleColor(3)
    imgui.SetCursorPosY(math.max(after_title_y, corner_button_y + corner_button_height + 2))

    local top_row_width = imgui.GetContentRegionAvail().x
    local probe_button_width = 82
    local input_width = math.max(220, math.floor(top_row_width * 0.32))
    if input_width > top_row_width - probe_button_width - 12 then
        input_width = math.max(180, top_row_width - probe_button_width - 12)
    end

    imgui.PushItemWidth(input_width)
    imgui.InputTextWithHint("##lookup_target", "Ник или номер аккаунта", query_input, ffi.sizeof(query_input))
    imgui.PopItemWidth()

    imgui.SameLine()
    push_primary_button_colors()
    if imgui.Button("Пробив", imgui.ImVec2(probe_button_width, 24)) then
        start_lookup("get", get_buffer_text(query_input))
    end
    imgui.PopStyleColor(3)

    if server_notice.expires > os.clock() and trim(server_notice.text) ~= "" then
        imgui.SameLine()
        imgui.TextColored(row_text_color(server_notice.tone), shorten_text(server_notice.text, 78))
    end

    push_secondary_button_colors()
    if imgui.Button("Обновить", imgui.ImVec2(92, 24)) then
        if session then
            build_full_collection_queue(session)
        else
            chat("Сначала получи /get на нужный аккаунт.", 0xE0C36A)
        end
    end
    imgui.PopStyleColor(3)

    imgui.SameLine()
    push_secondary_button_colors()
    if imgui.Button("Копировать", imgui.ImVec2(100, 24)) then
        copy_to_clipboard(compose_session_dump(session), "Полная сводка аккаунта")
    end
    imgui.PopStyleColor(3)

    imgui.SameLine()
    push_secondary_button_colors()
    if imgui.Button("Отправить в чат", imgui.ImVec2(126, 24)) then
        send_admin_chat_summary(session)
    end
    imgui.PopStyleColor(3)

    imgui.SameLine()
    push_secondary_button_colors()
    if imgui.Button("Экспорт", imgui.ImVec2(82, 24)) then
        local file_path, err = export_session_dossier(session)
        if file_path then
            chat(("Данные аккаунта сохранены: %s"):format(file_path), 0x9CCC65)
        else
            chat(err or "Не удалось сохранить данные аккаунта.", 0xE57373)
        end
    end
    imgui.PopStyleColor(3)

    imgui.SameLine()
    push_secondary_button_colors()
    if imgui.Button("История ников", imgui.ImVec2(118, 24)) then
        local target = ""
        if session then
            local requested_target = trim(session.target or "")
            local nick_target = trim(session.nick or "")
            local account_target = trim(session.account or "")
            if requested_target:match("^%d+$") then
                target = requested_target
            elseif nick_target ~= "" then
                target = nick_target
            elseif account_target ~= "" then
                target = account_target
            else
                target = requested_target
            end
        end
        request_nick_history(target)
    end
    imgui.PopStyleColor(3)

    imgui.SameLine()
    push_secondary_button_colors()
    if imgui.Button("Сброс", imgui.ImVec2(70, 24)) then
        session = nil
        account_preview = nil
        registration_preview = nil
        command_context = nil
        set_buffer_text(query_input, "")
        ip_preview_window_state[0] = false
        lip_preview_window_state[0] = false
        ipwhois_preview_window_state[0] = false
        ip_accounts_window_state[0] = false
        account_preview_window_state[0] = false
        registration_preview_window_state[0] = false
        ip_accounts_preview = nil
        clear_server_notice()
        clear_pending_queries()
    end
    imgui.PopStyleColor(3)

    if imgui.Checkbox(get_auto_collect_label(), auto_collect_state) then
        save_config()
    end

    if session then
        local status_text = session.status ~= "" and session.status or "Ожидание"
        imgui.TextColored(THEME.text, ("Статус: %s"):format(status_text))

        local queue_text = active_query and ("В работе: " .. format_command(active_query.kind, active_query.value))
            or (#pending_queries > 0 and ("В очереди: " .. tostring(#pending_queries)))
            or "Очередь пуста"
        imgui.SameLine()
        imgui.TextColored(THEME.muted, " | " .. queue_text)
    else
        if integration.access:level()~=nil and not integration.access:can(1) then
            imgui.TextColored(THEME.alert, "Скрипт доступен только для 3+ уровня администрации.")
        else
            imgui.TextDisabled("Введи ник/аккаунт, нажми Пробив или используй /cget, /cas ID.")
        end
    end

    if clipboard_notice.expires > os.clock() then
        imgui.TextColored(THEME.good, ("Скопировано: %s"):format(shorten_text(clipboard_notice.text, 64)))
    end
end

function render_offst_summary_card(current, width, height)
    if imgui.BeginChild("offst_summary_card", imgui.ImVec2(width, height), true) then
        draw_section_header("OFFST", "/offst")
        if current then
            if current.offst_rows and #current.offst_rows > 0 then
                draw_rows("offst_rows", current.offst_rows, "Нет данных /offst")
            else
                imgui.TextDisabled("Жду /offst.")
            end
        else
            imgui.TextDisabled("Жду /offst.")
        end
    end
    imgui.EndChild()
end

function estimate_summary_card_height(current, max_height)
    local limit = tonumber(max_height) or 0
    if limit <= 0 then
        return 320
    end

    local rows = 0
    if current then
        rows = rows + #(current.profile_rows or {})
        rows = rows + #(current.offst_rows or {})
        rows = rows + #(current.note_rows or {})
        rows = rows + #(current.errors or {})
        if #(current.note_rows or {}) > 0 then
            rows = rows + 1
        end
        if #(current.errors or {}) > 0 then
            rows = rows + 2
        end
    end

    local estimated = 130 + rows * 20
    if estimated < 250 then
        estimated = 250
    end

    local max_compact = math.min(limit, 560)
    if estimated > max_compact then
        estimated = max_compact
    end

    return estimated
end

function clamp_number(value, min_value, max_value)
    local number = tonumber(value) or 0
    local min_number = tonumber(min_value) or number
    local max_number = tonumber(max_value) or number
    if min_number > max_number then
        min_number, max_number = max_number, min_number
    end
    if number < min_number then
        return min_number
    end
    if number > max_number then
        return max_number
    end
    return number
end

function count_list_rows(rows)
    return rows and #rows or 0
end

function estimate_rows_text_width(rows, limit)
    local width = 0
    local count = 0
    for _, row in ipairs(rows or {}) do
        local text = trim(row and row.text or "")
        if text ~= "" then
            width = math.max(width, imgui.CalcTextSize(text).x)
            count = count + 1
            if limit and count >= limit then
                break
            end
        end
    end
    return width
end

function estimate_ordered_section_stats(sections)
    local row_count = 0
    local section_count = 0
    for _, section in ipairs(collect_ordered_sections(sections) or {}) do
        section_count = section_count + 1
        row_count = row_count + 1 + #(section.rows or {})
    end
    return row_count, section_count
end

function estimate_card_height_by_rows(row_count, section_count, min_height, max_height, base_height, row_height, section_height)
    local rows = math.max(0, tonumber(row_count) or 0)
    local sections = math.max(0, tonumber(section_count) or 0)
    local height = (tonumber(base_height) or 56) + rows * (tonumber(row_height) or 20) + sections * (tonumber(section_height) or 12)
    return clamp_number(math.floor(height), tonumber(min_height) or 120, tonumber(max_height) or height)
end

function estimate_offst_card_width(current, content_width)
    local total_width = math.max(0, tonumber(content_width) or 0)
    local min_width = 210
    local max_width = clamp_number(math.floor(total_width * 0.40), 240, 360)
    local width = min_width

    for index, row in ipairs((current and current.offst_rows) or {}) do
        local text = trim(row and row.text or "")
        if text ~= "" then
            width = math.max(width, math.floor(imgui.CalcTextSize(text).x) + 34)
        end
        if index >= 16 then
            break
        end
    end

    if count_list_rows(current and current.offst_rows or nil) > 10 then
        width = width + 12
    end

    return clamp_number(width, min_width, max_width)
end

function calc_summary_split_widths(current, content_width)
    local total_width = math.max(0, tonumber(content_width) or 0)
    local gap = 8
    local min_left = 320
    local min_right = 210
    if total_width <= min_left + min_right + gap then
        local right_width = clamp_number(math.floor((total_width - gap) * 0.34), 150, math.max(150, total_width - gap - 180))
        local left_width = math.max(0, total_width - right_width - gap)
        return left_width, right_width
    end
    local right_width = estimate_offst_card_width(current, total_width)
    if total_width - right_width - gap < min_left then
        right_width = math.max(min_right, total_width - min_left - gap)
    end
    right_width = math.max(0, right_width)
    local left_width = math.max(min_left, total_width - right_width - gap)
    if left_width + right_width + gap > total_width then
        left_width = math.max(260, total_width - right_width - gap)
    end
    return left_width, right_width
end

function distribute_vertical_heights(total_height, gap, specs)
    local count = #specs
    if count == 0 then
        return {}
    end

    local usable = math.max(0, math.floor((tonumber(total_height) or 0) - (tonumber(gap) or 0) * math.max(0, count - 1)))
    local heights = {}
    local min_sum = 0
    local extra_sum = 0
    local grow_index = count

    for index, spec in ipairs(specs) do
        local min_height = math.max(0, math.floor(tonumber(spec.min) or 0))
        local preferred = math.max(min_height, math.floor(tonumber(spec.preferred) or min_height))
        heights[index] = min_height
        min_sum = min_sum + min_height
        extra_sum = extra_sum + math.max(0, preferred - min_height)
        if spec.grow then
            grow_index = index
        end
    end

    if usable <= min_sum and min_sum > 0 then
        local used = 0
        local scale = usable / min_sum
        for index, spec in ipairs(specs) do
            heights[index] = math.max(0, math.floor((tonumber(spec.min) or 0) * scale))
            used = used + heights[index]
        end
        heights[grow_index] = math.max(0, heights[grow_index] + usable - used)
        return heights
    end

    local remaining = math.max(0, usable - min_sum)
    if extra_sum > 0 then
        local ratio = math.min(1, remaining / extra_sum)
        local used = min_sum
        for index, spec in ipairs(specs) do
            local min_height = math.max(0, math.floor(tonumber(spec.min) or 0))
            local preferred = math.max(min_height, math.floor(tonumber(spec.preferred) or min_height))
            local extra = math.max(0, math.floor((preferred - min_height) * ratio))
            heights[index] = min_height + extra
            used = used + extra
        end
        heights[grow_index] = heights[grow_index] + math.max(0, usable - used)
        return heights
    end

    heights[grow_index] = heights[grow_index] + remaining
    return heights
end

function estimate_main_column_widths(current, total_width)
    local gap = 8
    local full_width = math.max(0, tonumber(total_width) or 0)
    local min_left = 380
    local min_right = 360
    if full_width <= min_left + min_right + gap then
        local left_width = clamp_number(math.floor((full_width - gap) * 0.48), 260, math.max(260, full_width - gap - 220))
        local right_width = math.max(0, full_width - left_width - gap)
        return left_width, right_width
    end
    local max_left = math.max(min_left, math.floor(full_width * 0.62))
    local offst_width = estimate_offst_card_width(current, math.max(420, math.floor(full_width * 0.5)))
    local profile_width = math.max(
        estimate_rows_text_width(current and current.profile_rows or nil, 16),
        estimate_rows_text_width(current and current.note_rows or nil, 8),
        estimate_rows_text_width(current and current.errors or nil, 6),
        320
    )
    local preferred_left = profile_width + offst_width + gap + 44
    local left_width = clamp_number(preferred_left, min_left, max_left)
    if full_width - left_width - gap < min_right then
        left_width = math.max(min_left, full_width - min_right - gap)
    end
    local right_width = math.max(min_right, full_width - left_width - gap)
    return left_width, right_width
end

function estimate_bottom_split_width(current, total_width)
    local full_width = math.max(0, tonumber(total_width) or 0)
    local gap = 8
    local auth_count = 0
    local log_count = 0
    if current then
        auth_count = math.max(count_list_rows(current.auth_entries), count_list_rows(current.auth_rows))
        log_count = count_list_rows(current.punish_rows)
    end
    local total_count = math.max(1, auth_count + log_count)
    local auth_ratio = clamp_number(0.44 + (auth_count / total_count) * 0.20, 0.44, 0.66)
    if full_width <= 0 then
        return 0
    end
    if full_width <= 540 then
        return clamp_number(math.floor((full_width - gap) * 0.5), 180, math.max(180, full_width - gap - 180))
    end
    local auth_width = math.floor((full_width - gap) * auth_ratio)
    auth_width = clamp_number(auth_width, 320, math.max(320, full_width - gap - 260))
    return auth_width
end

function render_summary_card(current, width, height)
    if imgui.BeginChild("summary_card", imgui.ImVec2(width, height), true) then
        draw_section_header("Профиль", "")

        if current then
            imgui.TextColored(THEME.gold, current.nick ~= "" and current.nick or "Неизвестный аккаунт")
            if current.account ~= "" then
                imgui.SameLine()
                imgui.TextDisabled("№ " .. current.account)
            end

            local meta_bits = {}
            if current.level ~= "" then
                table.insert(meta_bits, "Уровень: " .. current.level)
            end
            table.insert(meta_bits, "Обновлено: " .. format_time(current.updated_at))
            imgui.TextColored(THEME.muted, table.concat(meta_bits, "  |  "))
            imgui.Separator()

            local content = imgui.GetContentRegionAvail()
            local gap = 8
            local left_width, right_width = calc_summary_split_widths(current, content.x)

            if imgui.BeginChild("summary_profile_left", imgui.ImVec2(left_width, 0), false) then
                draw_rows("profile", current.profile_rows, "Нет данных профиля")
                if #current.note_rows > 0 then
                    imgui.Spacing()
                    draw_rows("notes", current.note_rows, "")
                end

                if #current.errors > 0 then
                    draw_section_header("Ошибки / таймауты", "")
                    draw_rows("errors", current.errors, "")
                end
            end
            imgui.EndChild()

            imgui.SameLine(0, gap)
            if imgui.BeginChild("summary_profile_right", imgui.ImVec2(right_width, 0), false) then
                if should_show_baninfo_summary(current) then
                    local right_available = imgui.GetContentRegionAvail()
                    local split_heights = distribute_vertical_heights(right_available.y, gap, {
                        {
                            min = 170,
                            preferred = math.max(200, math.floor(right_available.y * 0.66)),
                            grow = true,
                        },
                        {
                            min = 110,
                            preferred = math.max(118, math.floor(right_available.y * 0.34)),
                        },
                    })
                    render_offst_summary_card(current, 0, split_heights[1] or 0)
                    imgui.Dummy(imgui.ImVec2(0, gap))
                    render_baninfo_summary_card(current, 0, split_heights[2] or 0, "baninfo_rows")
                else
                    render_offst_summary_card(current, 0, 0)
                end
            end
            imgui.EndChild()
        else
            imgui.TextDisabled(integration.access:can(5) and "Жду /get и доп. данные." or "Жду /get.")
        end
    end
    imgui.EndChild()
end

function render_geo_compare_card(current, width, height)
    if imgui.BeginChild("geo_compare_card", imgui.ImVec2(width, height), true) then
        draw_section_header("Регистрационные данные", "")
        if current and (#current.geo_compare_rows > 0 or #(current.geo_saved_rows or {}) > 0) then
            local saved_rows = current.geo_saved_rows or {}
            local saved_count = tonumber(current.geo_saved_accounts_count or 0) or 0
            local saved_button_label = ("Аккаунтов с IP в базе (%d)"):format(saved_count)
            if #saved_rows > 0 then
                local content = imgui.GetContentRegionAvail()
                local gap = 8

                if content.x >= 720 then
                    local right_width = clamp_number(math.floor(content.x * 0.34), 230, math.max(230, content.x - gap - 260))
                    local left_width = math.max(0, content.x - right_width - gap)

                    if imgui.BeginChild("geo_compare_left", imgui.ImVec2(left_width, 0), false) then
                        draw_rows("geo_compare", current.geo_compare_rows, "Нет данных")
                    end
                    imgui.EndChild()

                    imgui.SameLine(0, gap)
                    if imgui.BeginChild("geo_compare_right", imgui.ImVec2(right_width, 0), true) then
                        draw_section_header("В базе по IP", "")
                        push_secondary_button_colors()
                        if imgui.Button(saved_button_label, imgui.ImVec2(-1, 24)) then
                            current.geo_saved_open = not current.geo_saved_open
                        end
                        imgui.PopStyleColor(3)
                        if current.geo_saved_open then
                            imgui.Separator()
                            draw_rows("geo_compare_saved", saved_rows, "Нет совпадений в базе")
                        else
                            imgui.TextDisabled("Нажми кнопку, чтобы показать список аккаунтов.")
                        end
                    end
                    imgui.EndChild()
                else
                    draw_rows("geo_compare", current.geo_compare_rows, "Нет данных")
                    imgui.Separator()
                    draw_section_header("В базе по IP", "")
                    push_secondary_button_colors()
                    if imgui.Button(saved_button_label, imgui.ImVec2(-1, 24)) then
                        current.geo_saved_open = not current.geo_saved_open
                    end
                    imgui.PopStyleColor(3)
                    if current.geo_saved_open then
                        draw_rows("geo_compare_saved", saved_rows, "Нет совпадений в базе")
                    else
                        imgui.TextDisabled("Нажми кнопку, чтобы показать список аккаунтов.")
                    end
                end
            else
                draw_rows("geo_compare", current.geo_compare_rows, "Нет данных")
            end
        else
            imgui.TextDisabled("Жду IP из профиля аккаунта.")
        end
    end
    imgui.EndChild()
end

function should_show_baninfo_summary(current)
    if not current or not is_command_allowed_for_admin("baninfo") then
        return false
    end

    return #(current.ban_rows or {}) > 0
        or trim(current.source_query or "") ~= ""
        or trim(current.nick or "") ~= ""
        or trim(current.account or "") ~= ""
end

function render_baninfo_summary_card(current, width, height, row_prefix)
    local child_id = "baninfo_summary_card_" .. tostring(row_prefix or "main")
    if imgui.BeginChild(child_id, imgui.ImVec2(width, height), true) then
        draw_section_header("BANINFO", "/baninfo")
        if current then
            if current.ban_rows and #current.ban_rows > 0 then
                draw_rows(row_prefix or "baninfo_rows", current.ban_rows, "Нет данных /baninfo")
            else
                imgui.TextDisabled("Жду /baninfo.")
            end
        else
            imgui.TextDisabled("Жду /baninfo.")
        end
    end
    imgui.EndChild()
end

render_command_sections_card = function(id, title, hint, sections, width, height, empty_text)
    if imgui.BeginChild(id, imgui.ImVec2(width, height), true) then
        draw_section_header(title, hint)

        local card_targets = collect_section_account_targets(sections)
        if #card_targets > 0 then
            local has_controls = false

            if is_command_allowed_for_admin("offst") then
                push_secondary_button_colors()
                if imgui.Button(("Проверить лвл/фракцию##%s"):format(id), imgui.ImVec2(186, 22)) then
                    request_offst_for_accounts(card_targets, title, true)
                end
                imgui.PopStyleColor(3)
                has_controls = true
            end

            if is_command_allowed_for_admin("baninfo") then
                if has_controls then
                    imgui.SameLine()
                end
                push_secondary_button_colors()
                if imgui.Button(("Проверить на баны##%s"):format(id), imgui.ImVec2(154, 22)) then
                    request_baninfo_for_accounts(card_targets, title, true)
                end
                imgui.PopStyleColor(3)
                has_controls = true
            end

            if has_controls then
                local offst_summary = summarize_account_offst_checks(card_targets)
                local ban_summary = summarize_account_ban_checks(card_targets)

                if is_command_allowed_for_admin("offst") then
                    if offst_summary.pending > 0 then
                        imgui.TextColored(THEME.muted, ("Лвл/фракция: проверяется %d/%d"):format(offst_summary.pending, offst_summary.total))
                    elseif offst_summary.checked > 0 then
                        imgui.TextColored(THEME.muted, ("Лвл/фракция: %d/%d"):format(offst_summary.checked, offst_summary.total))
                    elseif not is_command_allowed_for_admin("baninfo") then
                        imgui.TextColored(THEME.muted, ("Аккаунтов: %d"):format(#card_targets))
                    end
                end

                if is_command_allowed_for_admin("baninfo") then
                    if is_command_allowed_for_admin("offst") then
                        imgui.SameLine()
                        imgui.TextColored(THEME.muted, " | ")
                        imgui.SameLine()
                    end
                    if ban_summary.pending > 0 then
                        imgui.TextColored(THEME.muted, ("Баны: проверяется %d/%d"):format(ban_summary.pending, ban_summary.total))
                    elseif ban_summary.checked > 0 then
                        imgui.TextColored(ban_summary.banned > 0 and THEME.alert or THEME.muted, ("Баны: %d/%d | Найдено: %d"):format(ban_summary.checked, ban_summary.total, ban_summary.banned))
                    else
                        imgui.TextColored(THEME.muted, ("Аккаунтов: %d"):format(ban_summary.total))
                    end
                end

                imgui.Spacing()
            end
        end

        local printed = 0
        local ordered_sections = collect_ordered_sections(sections)
        for _, section in ipairs(ordered_sections) do
            if printed > 0 then
                imgui.Separator()
            end

            imgui.TextColored(THEME.accent, section.title or title)
            if trim(section.ip or "") ~= "" then
                local probe_label = get_probe_button_state(section.ip)
                push_actions_to_right({ "IP", "LIP", probe_label, "Окно" }, 28)
                if draw_action_chip(("%s_section_ip_%d"):format(id, printed + 1), "IP", "accent", "Быстро открыть /ip по этому IP") then
                    request_ip_preview(section.ip)
                end
                imgui.SameLine()
                if draw_action_chip(("%s_section_lip_%d"):format(id, printed + 1), "LIP", "accent", "Быстро открыть /lip по этому IP") then
                    request_lip_preview(section.ip)
                end
                imgui.SameLine()
                draw_probe_action_inline(("%s_section_%d"):format(id, printed + 1), section.ip)
                imgui.SameLine()
                if draw_action_chip(("%s_section_window_%d"):format(id, printed + 1), "Окно", "muted", "Открыть список аккаунтов в отдельном окне") then
                    open_section_preview(section)
                end
            end

            draw_rows(
                id .. "_" .. tostring(trim(section.slot_key or "") ~= "" and section.slot_key or section.ip or printed),
                section.rows,
                "Нет данных"
            )
            printed = printed + 1
        end

        if printed == 0 then
            imgui.TextDisabled(empty_text)
        end
    end
    imgui.EndChild()
end

