    imgui.EndChild()
end

render_lip_preview_window = function()
    if not lip_preview_window_state[0] then
        return
    end

    local preview = session and session.lip_preview or nil
    imgui.SetNextWindowSize(imgui.ImVec2(390, 260), imgui.Cond.FirstUseEver)
    imgui.Begin("X-Tools — Связанные аккаунты###CasualTool — Связанные аккаунты", lip_preview_window_state, imgui.WindowFlags.NoCollapse)

    if preview then
        render_preview_header(preview)
        local preview_targets = collect_row_account_targets(preview.rows or {})
        local can_check_offst = #preview_targets > 0 and is_command_allowed_for_admin("offst")
        local can_check_bans = #preview_targets > 0 and is_command_allowed_for_admin("baninfo")

        push_secondary_button_colors()
        if imgui.Button("Копия сводки", imgui.ImVec2(110, 22)) then
            copy_to_clipboard(compose_rows_dump(preview.rows or {}), "Сводка LIP")
        end
        imgui.PopStyleColor(3)

        imgui.SameLine()
        push_secondary_button_colors()
        if imgui.Button("Обновить /lip", imgui.ImVec2(112, 22)) then
            request_lip_preview(preview.ip or "")
        end
        imgui.PopStyleColor(3)

        if can_check_offst or can_check_bans then
            imgui.Spacing()
        end

        if can_check_offst then
            push_secondary_button_colors()
            if imgui.Button("Проверить /offst", imgui.ImVec2(126, 22)) then
                request_offst_for_accounts(preview_targets, "LIP Preview", true)
            end
            imgui.PopStyleColor(3)
        end

        if can_check_bans then
            if can_check_offst then
                imgui.SameLine()
            end
            push_secondary_button_colors()
            if imgui.Button("Проверить на баны", imgui.ImVec2(154, 22)) then
                request_baninfo_for_accounts(preview_targets, "LIP Preview", true)
            end
            imgui.PopStyleColor(3)
        end

        if #preview_targets > 0 then
            local offst_summary = summarize_account_offst_checks(preview_targets)
            local ban_summary = summarize_account_ban_checks(preview_targets)
            local has_summary = false

            if can_check_offst then
                if offst_summary.pending > 0 then
                    imgui.TextColored(THEME.muted, ("OFFST: проверяется %d/%d"):format(offst_summary.pending, offst_summary.total))
                    has_summary = true
                elseif offst_summary.checked > 0 then
                    imgui.TextColored(THEME.muted, ("OFFST: проверено %d/%d"):format(offst_summary.checked, offst_summary.total))
                    has_summary = true
                end
            end

            if can_check_bans then
                if has_summary then
                    imgui.SameLine()
                    imgui.TextColored(THEME.muted, " | ")
                    imgui.SameLine()
                end
                if ban_summary.pending > 0 then
                    imgui.TextColored(THEME.muted, ("Баны: проверяются %d/%d"):format(ban_summary.pending, ban_summary.total))
                elseif ban_summary.checked > 0 then
                    imgui.TextColored(THEME.muted, ("Баны: %d/%d | Найдено: %d"):format(ban_summary.checked, ban_summary.total, ban_summary.banned))
                elseif not has_summary then
                    imgui.TextColored(THEME.muted, ("Аккаунтов: %d"):format(#preview_targets))
                end
            elseif not has_summary then
                imgui.TextColored(THEME.muted, ("Аккаунтов: %d"):format(#preview_targets))
            end
        end

        imgui.Spacing()
        draw_rows("lip_preview", preview.rows or {}, "Нет данных по preview")
    else
        imgui.TextDisabled("Нажми LIP у нужного IP в блоке авторизаций.")
    end

    imgui.End()
end

function draw_clickable_text_row(id, text, tone, copy_value)
    local value = trim(text)
    if value == "" then
        value = "-"
    end

    local clipboard_value = trim(copy_value or value)
    if clipboard_value == "" then
        clipboard_value = value
    end

    imgui.PushIDStr(tostring(id))
    imgui.TextColored(row_text_color(tone or "normal"), value)
    if imgui.IsItemClicked() then
        copy_to_clipboard(clipboard_value)
    end
    if imgui.IsItemHovered() then
        imgui.BeginTooltip()
        imgui.Text("ЛКМ - скопировать строку")
        imgui.EndTooltip()
    end
    imgui.PopID()
end

