    if preview and trim(preview.ip or "") ~= "" then
        imgui.SameLine()
        draw_copy_chip("preview_ip_copy", preview.ip, preview.ip, "accent", "Скопировать IP")
        imgui.SameLine()
        if draw_action_chip(("preview_ip_action_%s"):format(trim(preview.kind or "ip")), "IP", "accent", "Быстро открыть /ip по этому IP") then
            request_ip_preview(preview.ip)
        end
        imgui.SameLine()
        if draw_action_chip(("preview_lip_action_%s"):format(trim(preview.kind or "lip")), "LIP", "accent", "Быстро открыть /lip по этому IP") then
            request_lip_preview(preview.ip)
        end
        imgui.SameLine()
        draw_probe_action_inline(("preview_%s"):format(trim(preview.kind or "ip")), preview.ip)
    end
    if preview.updated_at then
        imgui.TextColored(THEME.muted, "Обновлено: " .. format_time(preview.updated_at))
    end
    imgui.Separator()
end

render_ip_preview_window = function()
    if not ip_preview_window_state[0] then
        return
    end

    local preview = session and session.ip_preview or nil
    imgui.SetNextWindowSize(imgui.ImVec2(390, 260), imgui.Cond.FirstUseEver)
    imgui.Begin("X-Tools — IP###CasualTool — IP", ip_preview_window_state, imgui.WindowFlags.NoCollapse)

    if preview then
        render_preview_header(preview)
        local preview_targets = collect_row_account_targets(preview.rows or {})
        local can_check_offst = #preview_targets > 0 and is_command_allowed_for_admin("offst")
        local can_check_bans = #preview_targets > 0 and is_command_allowed_for_admin("baninfo")

        push_secondary_button_colors()
        if imgui.Button("Копия сводки", imgui.ImVec2(110, 22)) then
            copy_to_clipboard(compose_rows_dump(preview.rows or {}), "Сводка IPWHO.IS")
        end
        imgui.PopStyleColor(3)

        imgui.SameLine()
        push_secondary_button_colors()
        if imgui.Button("Обновить /ip", imgui.ImVec2(112, 22)) then
            request_ip_preview(preview.ip or "")
        end
        imgui.PopStyleColor(3)

        if can_check_offst or can_check_bans then
            imgui.Spacing()
        end

        if can_check_offst then
            push_secondary_button_colors()
            if imgui.Button("Проверить /offst", imgui.ImVec2(126, 22)) then
                request_offst_for_accounts(preview_targets, "IP Preview", true)
            end
            imgui.PopStyleColor(3)
        end

        if can_check_bans then
            if can_check_offst then
                imgui.SameLine()
            end
            push_secondary_button_colors()
            if imgui.Button("Проверить на баны", imgui.ImVec2(154, 22)) then
                request_baninfo_for_accounts(preview_targets, "IP Preview", true)
            end
            imgui.PopStyleColor(3)
        end

        if #preview_targets > 0 then
            local offst_summary = summarize_account_offst_checks(preview_targets)
            local ban_summary = summarize_account_ban_checks(preview_targets)
            local has_summary = false

            if can_check_offst then
                if offst_summary.pending > 0 then
                    imgui.TextColored(THEME.muted, ("OFFST: проверяется %d/%d"):format(offst_summary.pending, offst_summary.total))
                    has_summary = true
                elseif offst_summary.checked > 0 then
                    imgui.TextColored(THEME.muted, ("OFFST: проверено %d/%d"):format(offst_summary.checked, offst_summary.total))
                    has_summary = true
                end
            end

            if can_check_bans then
                if has_summary then
                    imgui.SameLine()
                    imgui.TextColored(THEME.muted, " | ")
                    imgui.SameLine()
                end
                if ban_summary.pending > 0 then
                    imgui.TextColored(THEME.muted, ("Баны: проверяются %d/%d"):format(ban_summary.pending, ban_summary.total))
                elseif ban_summary.checked > 0 then
                    imgui.TextColored(THEME.muted, ("Баны: %d/%d | Найдено: %d"):format(ban_summary.checked, ban_summary.total, ban_summary.banned))
                elseif not has_summary then
                    imgui.TextColored(THEME.muted, ("Аккаунтов: %d"):format(#preview_targets))
                end
            elseif not has_summary then
                imgui.TextColored(THEME.muted, ("Аккаунтов: %d"):format(#preview_targets))
            end
        end

        imgui.Spacing()
        draw_rows("ip_preview", preview.rows or {}, "Нет данных по preview")
    else
        imgui.TextDisabled("Нажми IP у нужного адреса в интерфейсе.")
    end

    imgui.End()
end

function draw_probe_action_inline(id, ip)
    local clean_ip = trim(ip)
    if clean_ip == "" then
        return
    end

    local probe_label, probe_tone, probe_tooltip = get_probe_button_state(clean_ip)
    if draw_action_chip(("%s_probe_action"):format(id), probe_label, probe_tone, probe_tooltip) then
        request_ipwhois_preview(clean_ip, false)
    end
end

function calc_ip_action_total_width(ip)
    local clean_ip = trim(ip)
    if clean_ip == "" then
        return 0
    end

    local probe_label = get_probe_button_state(clean_ip)
    local labels = { "IP", "LIP", probe_label }
    local total_width = 0
    local count = 0

    for _, label in ipairs(labels) do
        local width = calc_chip_width(label)
        if width > 0 then
            total_width = total_width + width
            count = count + 1
        end
    end

    if count > 1 then
        total_width = total_width + (count - 1) * 6
    end

    return total_width
end

should_wrap_profile_ip_actions = function(text, ip)
    local available_width = math.max(0, imgui.GetContentRegionAvail().x)
    if available_width <= 0 then
        return false
    end

    local row_text = trim(text)
    if row_text == "" then
        row_text = "-"
    end

    local text_width = imgui.CalcTextSize(row_text).x
    local actions_width = calc_ip_action_total_width(ip)
    return text_width + actions_width + 14 > available_width
end

draw_account_actions_inline = function(id, target)
    local clean_target = strip_color_tags(target)
    if clean_target == "" then
        return
    end

    push_actions_to_right({ "Профиль", "Lookup", "SBAN" }, 26)
    if draw_action_chip(("%s_profile_action"):format(id), "Профиль", "accent", "Открыть отдельное окно профиля по этому аккаунту") then
        request_account_preview(clean_target)
    end
    imgui.SameLine()
    if draw_action_chip(("%s_lookup_action"):format(id), "Lookup", "good", "Заменить текущий аккаунт и пробить его полностью") then
        lookup_account_in_main(clean_target)
    end
    imgui.SameLine()
    if draw_action_chip(("%s_sban_action"):format(id), "SBAN", "alert", "Отправить /sban на 30 дней с причиной 'До выяснений.'") then
        send_sban_for_account(clean_target)
    end
end

function render_ip_account_links_info(ip, id_prefix, inline)
    local clean_ip = trim(ip)
    if not is_ip(clean_ip) then
        return
    end

    local accounts = get_ip_account_labels(clean_ip)
    if #accounts == 0 then
        imgui.TextDisabled("Этот IP еще не встречался в локальной базе аккаунтов.")
        return
    end

    imgui.TextColored(THEME.muted, ("Этот IP встречался у %d людей"):format(#accounts))
    imgui.SameLine()
    if draw_action_chip(("%s_accounts_btn"):format(id_prefix), "Люди", "accent", "Показать список аккаунтов по этому IP") then
        open_ip_accounts_preview(clean_ip)
    end
end

function render_ip_accounts_window()
    if not ip_accounts_window_state[0] then
        return
    end

    local preview = ip_accounts_preview
    imgui.SetNextWindowSize(imgui.ImVec2(360, 320), imgui.Cond.FirstUseEver)
    imgui.Begin("X-Tools — Аккаунты по IP###CasualTool — Аккаунты по IP", ip_accounts_window_state, imgui.WindowFlags.NoCollapse)

    if preview and is_ip(preview.ip or "") then
        imgui.TextColored(THEME.gold, "Аккаунты по IP")
        imgui.SameLine()
        draw_copy_chip("ip_accounts_ip_copy", preview.ip, preview.ip, "accent", "Скопировать IP")
        imgui.TextColored(THEME.muted, ("IP: %s"):format(preview.ip))
        local online_count = 0
        for _, account_label in ipairs(preview.accounts or {}) do
            if get_online_player_id_for_account(account_label) ~= nil then
                online_count = online_count + 1
            end
        end
        imgui.TextColored(THEME.muted, ("Найдено людей: %d"):format(#(preview.accounts or {})))
        if online_count > 0 then
            imgui.TextColored(THEME.good, ("Онлайн: %d"):format(online_count))
        end
        imgui.Separator()
        if preview.accounts and #preview.accounts > 0 then
            for index, account_label in ipairs(preview.accounts) do
                local row_id = ("ip_accounts_%d"):format(index)
                local online_id = get_online_player_id_for_account(account_label)
                local display_label = online_id and ("%s (ID: %d)"):format(account_label, online_id) or account_label
                local ban_entry = get_account_ban_lookup(account_label)
                local row_tone = online_id and "good" or "normal"
                if ban_entry and ban_entry.is_banned then
                    row_tone = "alert"
                end
                draw_clickable_text_row(row_id, display_label, row_tone)
                draw_account_actions_inline(row_id, account_label)
            end
        else
            imgui.TextDisabled("Нет связанных аккаунтов")
        end
    else
        imgui.TextDisabled("Нет данных по IP.")
    end

    imgui.End()
end

function render_history_window()
