        imgui.TextColored(THEME.gold, preview.title or "История ников")
        if preview.updated_at then
            imgui.TextColored(THEME.muted, "Обновлено: " .. format_time(preview.updated_at))
        end

        if preview.loading then
            imgui.TextColored(THEME.accent, preview.status or "Собираю страницы истории ...")
        else
            imgui.TextColored(THEME.muted, preview.status or ("Собрано записей: " .. tostring(#(preview.rows or {}))))
        end
        imgui.Separator()

        push_secondary_button_colors()
        if imgui.Button("Копировать", imgui.ImVec2(100, 22)) then
            copy_to_clipboard(compose_rows_dump(preview.rows or {}), "История ников")
        end
        imgui.PopStyleColor(3)

        if trim(preview.target or "") ~= "" then
            imgui.SameLine()
            push_secondary_button_colors()
            if imgui.Button("Обновить /namestore", imgui.ImVec2(148, 22)) then
                request_nick_history(preview.target)
            end
            imgui.PopStyleColor(3)
        end

        imgui.Spacing()
        if preview.rows and #preview.rows > 0 then
            local content = imgui.GetContentRegionAvail()
            local total_width = math.max(220, content.x)
            local date_width = clamp_number(math.floor(total_width * 0.33), 132, 170)
            local nick_width = math.max(140, total_width - date_width - 12)
            local row_start_x = imgui.GetCursorPosX()

            imgui.TextColored(THEME.muted, "Дата")
            imgui.SameLine(row_start_x + date_width + 12)
            imgui.TextColored(THEME.muted, "Ник")
            imgui.Separator()

            for index, row in ipairs(preview.rows) do
                local date_text = trim(row.date or "")
                local nick_text = trim(row.nick or "")
                local tone = row and row.tone or "normal"

                if date_text ~= "" and nick_text ~= "" then
                    local line_x = imgui.GetCursorPosX()
                    imgui.BeginGroup()
                    imgui.PushTextWrapPos(line_x + date_width)
                    draw_clickable_text_row(("history_date_%d"):format(index), date_text, tone)
                    imgui.PopTextWrapPos()
                    imgui.EndGroup()
                    imgui.SameLine(line_x + date_width + 12)
                    imgui.BeginGroup()
                    imgui.PushTextWrapPos(line_x + date_width + 12 + nick_width)
                    draw_clickable_text_row(("history_nick_%d"):format(index), nick_text, tone)
                    imgui.PopTextWrapPos()
                    imgui.EndGroup()
                else
                    draw_clickable_text_row(("history_row_%d"):format(index), row.text or "-", tone)
                end
            end
        else
            imgui.TextDisabled(preview.loading and "Собираю страницы..." or "Нет истории ников")
        end
    else
        imgui.TextDisabled("Нет данных по истории ников.")
    end

    imgui.End()
end

