end

integration.ownsKeys = function() return menu_active end

integration.drawSettings = function()
    local active = imgui.ImBool(enabled)
    if imgui.Checkbox('Заменять серверное меню наблюдения', active) then
        enabled = active.v
        settings.features.enabled = enabled
