end

integration.keys:register('observation_up','Наблюдение: Вверх',{key=38},nil,function() return integration.ownsKeys and integration.ownsKeys() end)

integration.keys:register('observation_down','Наблюдение: Вниз',{key=40},nil,function() return integration.ownsKeys and integration.ownsKeys() end)

