    sources["modules/movement.lua"] = function()
-- Lua ports of AntiBH (AIR), MatrixJump and BackF; see integration/CLEO_PORTS.md.
local events=require('lib.samp.events')
local bit=require('bit')
local steps=integration.service('stunt_steps.lua')
local generation,busy,owned=0,false,nil
integration.keys:register('matrix_jump','Акробатический прыжок',{key=32,shift=true,second=0})
integration.keys:register('back_flip','Сальто назад',{key=32,second=67})
local function clean()
    if owned and doesCharExist(owned.ped) and getCharPointer(owned.ped)==owned.pointer then
        setCharRotation(owned.ped,0,0,owned.heading)
        if not owned.proof then
            local address=owned.pointer+0x42
            writeMemory(address,1,bit.band(readMemory(address,1,false),0xEF),false)
        end
    end
    owned=nil;busy=false
end
local function cancel() generation=generation+1;clean() end
local function available()
    return sampGetGamestate()==3 and doesCharExist(PLAYER_PED) and not isCharDead(PLAYER_PED)
        and not isCharInAnyCar(PLAYER_PED) and not isPauseMenuActive() and isGameWindowForeground()
        and not sampIsChatInputActive() and not sampIsDialogActive() and not sampIsCursorActive()
end
local function run(kind)
    busy=true;local token=generation;local ped=PLAYER_PED;local pointer=getCharPointer(ped)
    local heading=getCharHeading(ped)
    local flags=readMemory(pointer+0x42,1,false)
    owned={ped=ped,pointer=pointer,heading=heading,proof=bit.band(flags,0x10)~=0}
    -- CPhysical collision-proof bit only; keep the other protection flags intact.
    writeMemory(pointer+0x42,1,bit.bor(flags,0x10),false)
    setCharRotation(ped,0,0,heading)
    local x,y=getCharVelocity(ped)
    if kind=='matrix' then x,y=x*1.3*1.3,y*1.3*1.3 end
    setCharVelocity(ped,x,y,10)
    taskPlayAnimNonInterruptable(ped,kind=='matrix' and 'FALL_FALL' or 'FALL_SKYDIVE','PED',3,false,false,false,false,kind=='matrix' and 440 or 410)
    lua_thread.create(function()
        for _,step in ipairs(steps[kind]) do
            if step[1]>0 then wait(step[1]) end
            if token~=generation then return end
            if not integration.preferences.data.main[kind=='matrix' and 'matrixJump' or 'backFlip'] or not available() or PLAYER_PED~=ped or getCharPointer(ped)~=pointer then clean();return end
            setCharRotation(ped,step[2],0,heading)
        end
        if token==generation then
            clean()
            if kind=='backflip' then busy=true;wait(600);if token==generation then busy=false end end
        end
    end)
end
function events.onSendPlayerSync(data)
    if integration.preferences.data.main.antiBH and tonumber(data.keysData)==40 then data.keysData=32 end
end
integration.update=function()
    local prefs=integration.preferences.data.main
    local matrixPressed=integration.keys:pressed('matrix_jump')
    local backPressed=integration.keys:pressed('back_flip')
    if busy or integration.flightActive() or (not prefs.matrixJump and not prefs.backFlip) or not available() then return end
    if isCharPlayingAnim(PLAYER_PED,'CLIMB_JUMP') then return end
    if prefs.matrixJump and matrixPressed then run('matrix')
    elseif prefs.backFlip and backPressed then run('backflip') end
end
integration.onDisconnect=cancel
integration.stop=cancel
integration.drawSettings=function()
    local g=require('imgui')
    for _,item in ipairs({{'antiBH','Баннихоп (AntiBH)'},{'matrixJump','Акробатический прыжок'},{'backFlip','Сальто назад'}}) do
        local value=g.ImBool(integration.preferences.data.main[item[1]])
        if g.Checkbox(item[2],value) then integration.preferences.data.main[item[1]]=value.v;integration.preferences:save();cancel() end
        if item[1]=='matrixJump' then
            g.TextWrapped('Усиленный прыжок с вращением: скорость вперёд ×1,69 и подброс вверх. Ранее Matrix Jump.')
            integration.keys:draw(g,'matrix_jump')
        elseif item[1]=='backFlip' then
            g.TextWrapped('Подброс вверх с сальто назад. Ранее BackF.')
            integration.keys:draw(g,'back_flip')
        end
    end
    g.TextWrapped('Без назначенной клавиши трюк не запускается.')
end

-- Assigned keys replace the source combinations; an unassigned binding keeps them.

    end
    sources["modules/observer_extras.lua"] = function()
-- Selected sp_plus features (Sambrero) and DeathMatch Informer, on shared X-Tools HUD.
local g=require('imgui')
local events=require('lib.samp.events')
local bit=require('bit')
local u8=require('encoding').UTF8
local settings=integration.service('combo_settings.lua')
local path=integration.storage:path('settings','observer-extras.ini')
local cfg=integration.storage:loadIni({
    keys={enabled=false,x=30,y=200,mode=0},
    gaze={enabled=false,x=30,y=400,length=5,width=2},
    chat={enabled=false,x=400,y=180,lines=13,font=14},
    warnings={enabled=false,x=500,y=350,lines=8,debug=false,rapid=true,obstacles=true,medkit=true,deagle=0.3,m4=0.01},
    dm={enabled=false,x=700,y=220,lines=13,font=14}
},path)
local samples,aims,chat,warnings,shots,rapid,medkits={},{},{},{},{},{},{}
local lastTarget=nil
local offsets={chat=0,dm=0,warnings=0}
local function now()return getGameTimer()/1000 end
local function save()integration.storage:saveIni(cfg,path)end
if not cfg.chat.nativeVersion then cfg.chat.nativeVersion=1;if cfg.chat.font==14 then cfg.chat.font=8 end;save()end
local farChat=integration.service('far_chat.lua').new(_G,cfg.chat,save)
local hud=integration.service('hud_panels.lua').new(g,_G,save)
local labels={keys='Клавиши наблюдаемого игрока',gaze='Куда смотрит игрок',chat='Дальний чат',warnings='Варнинги',dm='Информер попаданий'}
for _,id in ipairs({'keys','gaze','chat','warnings','dm'}) do
    integration.keys:register('observer_'..id,labels[id]..': включить / выключить',{key=id=='chat' and 116 or 0,second=0})
end
local function usable()return sampGetGamestate()==3 and not isPauseMenuActive() and isGameWindowForeground()end
local function player(id)
    if not id or not sampIsPlayerConnected(id) then return end
    return tostring(u8(sampGetPlayerNickname(id)))
end
local function streamed(id)
    if not player(id) then return false end
    local localFound,localID=sampGetPlayerIdByCharHandle(PLAYER_PED)
    if localFound and id==localID then return true end
    local found,ped=sampGetCharHandleBySampPlayerId(id)
    return found and ped and doesCharExist(ped)
end
local function push(list,row,limit)
    list[#list+1]=row
    while #list>limit do table.remove(list,1) end
end
local function signed(v) v=tonumber(v) or 0;return v>32767 and v-65536 or v end
local function sample(id,data,vehicle)
    if not cfg.keys.enabled or not streamed(id) then return end
    local observation=integration.observation();if not observation or observation.id~=id then return end
    samples[id]={nick=player(id),time=now(),x=signed(data.leftRightKeys),y=signed(data.upDownKeys),bits=tonumber(data.keysData) or 0,vehicle=vehicle}
end
local function warn(id,text)
    if not player(id) then return end
    local line=player(id)..'['..id..']: '..text
    push(warnings,os.date('%H:%M:%S')..' '..line,100)
    sampAddChatMessage('{FF6060}[Warning] {FFFFFF}'..u8:decode(line),-1)
end
function events.onPlayerSync(id,data)
    sample(id,data,false)
    local item=medkits[id]
    if cfg.warnings.enabled and cfg.warnings.medkit and item then
        if item.nick~=player(id) or now()>item.expires then medkits[id]=nil
        elseif tonumber(data.animationId)==1157 then item.started=true
        elseif item.started then warn(id,'возможный сбив анимации аптечки');medkits[id]=nil
        elseif now()>item.check then warn(id,'не появилась анимация аптечки');medkits[id]=nil end
    end
end
function events.onVehicleSync(id,vehicle,data) medkits[id]=nil;sample(id,data,true) end
function events.onAimSync(id,data)
    if not cfg.gaze.enabled or not streamed(id) then return end
    local ob=integration.observation();if not ob or ob.id~=id then return end
    local v=data.camFront;if not v then return end
    local x,y,z=tonumber(v.x),tonumber(v.y),tonumber(v.z)
    if not x or not y or not z or x~=x or y~=y or z~=z then return end
    local length=math.sqrt(x*x+y*y+z*z)
    if length<0.001 or length>100 then return end
    aims[id]={nick=player(id),time=now(),x=x/length,y=y/length,z=z/length}
end
function events.onApplyPlayerAnimation(id,lib,name,delta)
    if cfg.warnings.enabled and cfg.warnings.medkit and name=='gum_eat' and streamed(id) then
        medkits[id]={nick=player(id),expires=now()+math.min(10,math.max(1,tonumber(delta) or 4)),check=now()+1.9}
    end
end
function events.onPlayerChatBubble(id,color,distance,duration,text)
    if not streamed(id) then return end
    text=tostring(u8(text)):gsub('{%x%x%x%x%x%x}','')
    if cfg.warnings.enabled and cfg.warnings.medkit and color==-1721303041 and text:match('%+%d+%s+Hp') then
        medkits[id]={nick=player(id),expires=now()+4,check=now()+1.9}
    end
    if not cfg.chat.enabled then return end
    for _,pattern in ipairs({'На паузе %d+:%d+','На паузе %d+ сек.','%d+ hp','%+%d+%s+Hp','На паузе более часа'}) do if text:match(pattern) then return end end
    push(chat,os.date('%H:%M:%S')..' '..player(id)..'['..id..']: '..text,500)
    farChat:add(id,color,text)
end
local weapons={[22]='Glock',[23]='Silenced',[24]='Deagle',[25]='Shotgun',[26]='Sawn-off',[27]='SPAS-12',[28]='Uzi',[29]='MP5',[30]='AK-47',[31]='M4',[32]='TEC-9',[33]='Rifle',[34]='Sniper',[38]='Minigun'}
local function bullet(id,data,own)
    if not (cfg.warnings.enabled or cfg.dm.enabled) or not usable() or not streamed(id) then return end
    local name=player(id);local weapon=tonumber(data.weaponId) or -1;local target=tonumber(data.targetId)
    local hit=tonumber(data.targetType)==1 and player(target)
    if cfg.dm.enabled and hit then
        push(shots,os.date('%H:%M:%S')..' '..name..'['..id..'] > '..(weapons[weapon] or tostring(weapon))..' > '..hit..'['..target..']',50)
    end
    if not cfg.warnings.enabled or own and not cfg.warnings.debug then return end
    if cfg.warnings.rapid and (weapon==24 or weapon==31) then
        local key=id..':'..weapon;local t=now();local row=rapid[key]
        if not row or row.nick~=name then row={nick=name,count=0,last=t,warning=t};rapid[key]=row
        else
            if t-row.warning>7 then row.count=0 end
            local threshold=weapon==24 and cfg.warnings.deagle or cfg.warnings.m4
            if t-row.last<threshold then row.count=row.count+1;row.warning=t end
            if row.count>=3 then warn(id,string.format('слишком быстро стреляет с %s {FF6060}%.2fs. / {60E890}%.2fs.',weapons[weapon],t-row.last,threshold));row.count=0 end
            row.last=t
        end
    end
    if cfg.warnings.obstacles and hit and data.origin and data.target then
        local o,t=data.origin,data.target
        local values={o.x,o.y,o.z,t.x,t.y,t.z};local valid=true;for i=1,6 do local n=values[i];if type(n)~='number' or n~=n or math.abs(n)>100000 then valid=false end end
        if valid and not isLineOfSightClear(o.x,o.y,o.z,t.x,t.y,t.z,true,false,false,false,true) then warn(id,'возможное попадание через препятствие в '..hit) end
    end
end
function events.onBulletSync(id,data)bullet(id,data)end
function events.onSendBulletSync(data)local ok,id=sampGetPlayerIdByCharHandle(PLAYER_PED);if ok then bullet(id,data,true)end end
function events.onPlayerQuit(id)samples[id]=nil;aims[id]=nil;medkits[id]=nil;for key in pairs(rapid)do if key:match('^(%d+):')==tostring(id)then rapid[key]=nil end end end
local function change(id,value)
    cfg[id].enabled=value
    if id=='chat' and not value then farChat:stop()end
    if not value and hud.edit==id then hud:reset() end
    if id=='keys' then samples={} elseif id=='gaze' then aims={} elseif id=='warnings' then rapid={};medkits={} end
    save();integration.refreshInput()
end
integration.update=function()
    local ob=integration.observation();local identity=ob and (ob.id..':'..ob.nickname)
    if identity~=lastTarget then samples={};aims={};lastTarget=identity end
    local allow=usable() and not sampIsChatInputActive() and not sampIsDialogActive() and not sampIsCursorActive()
    for _,id in ipairs({'keys','gaze','chat','warnings','dm'}) do
        local toggle=integration.keys:pressed('observer_'..id)
        if allow and toggle then change(id,not cfg[id].enabled) end
    end
end
integration.onDisconnect=function()samples={};aims={};chat={};warnings={};shots={};rapid={};medkits={};hud:reset();farChat:clear();farChat:stop();lastTarget=nil end
integration.stop=integration.onDisconnect
integration.hudActive=function()
    if not usable() then return false,false end
    local ob=integration.observation()
    local visible=cfg.dm.enabled or (ob and cfg.keys.enabled) or hud.edit~=nil or farChat.moving
    return visible==true,farChat.moving or hud.edit~=nil or visible and (sampIsChatInputActive() or sampIsDialogActive()) or false
end
local function listPanel(id,title,list)
    local p=cfg[id]
    hud:window(id,title,p,math.min(660,tonumber(p.width) or 600),80+math.min(50,p.lines)*22,function()
        local face=integration.fontFace(p.font or 14,false);if face then g.PushFont(face)end
        if #list==0 then g.TextWrapped('Пока нет событий.') end
        local offset=math.max(0,math.min(offsets[id] or 0,math.max(0,#list-p.lines)))
        if sampIsChatInputActive() or sampIsDialogActive() or hud.edit==id then
            if g.Button('< Раньше##history_'..id) then offset=math.min(math.max(0,#list-p.lines),offset+p.lines)end
            g.SameLine();if g.Button('Позже >##history_'..id) then offset=math.max(0,offset-p.lines)end
        end
        offsets[id]=offset
        for i=math.max(1,#list-offset-p.lines+1),#list-offset do g.TextWrapped(list[i]) end
        if face then g.PopFont()end
    end)
end
integration.drawHud=function()
    if not integration.hudActive() then return end
    local ob=integration.observation()
    if cfg.keys.enabled and (ob or hud.edit=='keys') then
        hud.noTitle=true
        hud:window('keys','Клавиши игрока',cfg.keys,396,(cfg.keys.mode==2 or ob and cfg.keys.mode==0 and ob.mobile)and 150 or 88,function()
            local row=ob and samples[ob.id]
            if not row or now()-row.time>2 then g.Text('Ожидание данных игрока.');return end
            local mobile=cfg.keys.mode==2 or cfg.keys.mode==0 and ob.mobile
            if mobile then
                local p=g.GetCursorScreenPos();local draw=g.GetWindowDrawList();local center=g.ImVec2(p.x+55,p.y+55)
                draw:AddCircle(center,44,0xFFB5A0FF,32,2)
                draw:AddCircleFilled(g.ImVec2(center.x+math.max(-1,math.min(1,row.x/128))*32,center.y+math.max(-1,math.min(1,row.y/128))*32),12,0xFFB5A0FF)
                g.Dummy(g.ImVec2(115,112));g.Text('Мобильный джойстик')
            else
                integration.service('key_overlay.lua').draw(g,row,0xFFFFA0B5)
            end
        end)
        hud.noTitle=false
    end
    if cfg.dm.enabled then listPanel('dm','Информер попаданий',shots)end
end
integration.onD3DPresent=function()
    if usable() then farChat:draw()end
    if not cfg.gaze.enabled or not usable() then return end
    local ob=integration.observation();local a=ob and aims[ob.id]
    if not a or now()-a.time>2 or a.nick~=tostring(u8(ob.nickname)) then return end
    local found,ped=sampGetCharHandleBySampPlayerId(ob.id);if not found then return end
    local x,y,z=getCharCoordinates(ped);z=z+0.7
    local ex,ey,ez=x+a.x*cfg.gaze.length,y+a.y*cfg.gaze.length,z+a.z*cfg.gaze.length
    if isPointOnScreen(x,y,z,1) and isPointOnScreen(ex,ey,ez,1) then
        local sx,sy=convert3DCoordsToScreen(x,y,z);local tx,ty=convert3DCoordsToScreen(ex,ey,ez)
        renderDrawLine(sx,sy,tx,ty,cfg.gaze.width,0xFFB5A0FF)
    end
end
local expanded={}
local function controls(id)
    if settings.toggle(g,labels[id],cfg[id],'enabled') then change(id,cfg[id].enabled) end
    g.SameLine()
    if g.Button('Настройки##observer_settings_'..id)then expanded[id]=not expanded[id]end
    if not expanded[id]then return false end
    g.Spacing()
    integration.keys:draw(g,'observer_'..id)
    if id~='warnings' and id~='gaze'then
    if g.Button('Переместить##observer_'..id) then change(id,true);if id=='chat'then farChat.moving=true else hud:move(id)end;integration.beginPlacement(function()hud:reset();farChat.moving=false;save()end) end
    g.SameLine();if g.Button('Сброс позиции##observer_'..id) then cfg[id].x=30;cfg[id].y=180;save()end
    end
    return true
end
integration.drawSettings=function()
    for _,id in ipairs({'keys','gaze','chat'})do
        g.Separator();if controls(id)then
        local p=cfg[id];local dirty=false;g.PushItemWidth(140)
        if id=='keys' then
            local mode=g.ImInt(p.mode);if g.Combo('Отображение##keys_mode',mode,'Авто\0Клавиатура\0Джойстик\0\0')then p.mode=mode.v;dirty=true end
        elseif id=='gaze' then
            dirty=settings.integer(g,'Длина линии, м',p,'length',5,1,30) or dirty
            dirty=settings.integer(g,'Толщина линии',p,'width',2,1,8) or dirty
        else
            dirty=settings.integer(g,'Строк на экране##'..id,p,'lines',13,1,50) or dirty
            dirty=settings.integer(g,'Размер шрифта##'..id,p,'font',id=='chat'and 8 or 14,6,22) or dirty
            if g.Button('Очистить##observer_'..id)then if id=='dm'then shots={}else chat={};farChat:clear()end end
            if id=='dm' then
                if g.CollapsingHeader('История попаданий (до 50)') then for _,line in ipairs(shots)do g.TextWrapped(line)end end
                g.TextWrapped('Показывает попадания по BulletSync, а не подтверждённый урон сервера. История: последние 50 попаданий.')end
            if id=='chat' then g.TextWrapped('Сообщения и шёпот из полученных чат-пузырей игроков в стриме. Для перемещения откройте чат/диалог, нажмите ПКМ на панели, затем ЛКМ в новом месте. История: до 500 сообщений.')end
        end
        g.PopItemWidth();if dirty then save()end
        end
    end
end
integration.drawHitHistory=function()
    g.Separator();g.Text('История попаданий · BulletSync');if controls('dm')then
    g.PushItemWidth(140)
    local dirty=settings.integer(g,'Строк HUD##dm',cfg.dm,'lines',13,1,50)
    dirty=settings.integer(g,'Шрифт HUD##dm',cfg.dm,'font',14,10,22)or dirty
    g.PopItemWidth();if dirty then save()end
    if g.Button('Очистить историю попаданий')then shots={}end
    end
    g.TextWrapped('Последние 50 попаданий по входящим и собственным BulletSync. Пакет попадания не подтверждает фактический урон.')
    for _,line in ipairs(shots)do g.TextWrapped(line)end
end
integration.draw=function()
    local showSettings=controls('warnings');g.TextWrapped('Возможные нарушения, не доказательство. Автоматические наказания не выполняются.')
    if showSettings then
    g.TextWrapped('Уведомления выводятся в игровой чат, как в sp_plus. Три коротких интервала вызывают варнинг; через 7 секунд без нарушения счётчик сбрасывается.')
    local p=cfg.warnings;local dirty=settings.toggle(g,'Отладка: проверять собственные выстрелы',p,'debug')
    for _,v in ipairs({{'Слишком быстрая стрельба','rapid'},{'Попадания через препятствия','obstacles'},{'Сбив или отсутствие анимации аптечки','medkit'}})do dirty=settings.toggle(g,v[1],p,v[2])or dirty end
    g.PushItemWidth(140)
    for _,v in ipairs({{'Deagle: минимальный интервал, сек.','deagle',0.01,1.5},{'M4: минимальный интервал, сек.','m4',0.001,0.5}})do
        local n=g.ImFloat(p[v[2]]);if g.InputFloat(v[1],n,0,0)then p[v[2]]=math.max(v[3],math.min(v[4],n.v));dirty=true end
    end
    g.PopItemWidth()
    if dirty then save()end
    if g.Button('Очистить варнинги')then warnings={}end
    end
    for i=math.max(1,#warnings-30),#warnings do g.TextWrapped(warnings[i])end
end


    end
    sources["modules/online.lua"] = function()
-- Clear Online functions integrated into CasualTool; no independent updater/window.
local imgui,events=require 'imgui',require 'samp.events'
local encoding=require 'encoding'
local stats=integration.service('online_stats.lua')
local storage=integration.storage
local configPath=storage:path('settings','online.ini')
local legacy={}
for _,name in ipairs({'config.ini','goals_config.ini','historical_data.txt','week_data.txt','monthly_data.txt','stats_data.txt','counted_days.txt','reset_flag.txt','monthly_reset_flag.txt'}) do
    legacy[name]=storage:path('data','online_legacy/'..name,{integration.root..'/ClearOnline/'..name})
end
local config=storage:loadIni({main={enabled=true,auto=false,interval=60,notifications=true,report=false},
    goals={daily=120,weekly=840,monthly=3600}},configPath)
local settings,goals=config.main,config.goals
if not storage:exists(configPath) then
    local old=storage:read(legacy['goals_config.ini']) or ''
    for _,key in ipairs({'daily','weekly','monthly'}) do goals[key]=tonumber(old:match(key..'_goal=(%d+)')) or goals[key] end
    if old:match('notifications=false') then settings.notifications=false end
    local preferences=storage:read(legacy['config.ini']) or ''
    settings.interval=tonumber(preferences:match('auto_check_interval=(%d+)')) or settings.interval
    settings.report=preferences:match('display_mode=chat')~=nil
    -- Automatic server queries remain opt-in after migration.
    storage:saveIni(config,configPath)
end
local function bound(value,minimum,maximum,fallback)
    value=tonumber(value)
    if not value or value~=value then return fallback end
    return math.floor(math.max(minimum,math.min(maximum,value)))
end
settings.interval=bound(settings.interval,60,3600,60)
for _,key in ipairs({'enabled','auto','notifications','report'}) do settings[key]=settings[key]==true end
for key,limit in pairs({daily=1440,weekly=10080,monthly=44640}) do goals[key]=bound(goals[key],1,limit,120) end
local ledger,path,identity,pending,lastRequest,lastSnapshot,status
local historyPage=1
local function saveConfig() storage:saveIni(config,configPath) end
local function duration(minutes)
    minutes=math.floor(minutes or 0)
    return string.format('%d ч %02d мин',math.floor(minutes/60),minutes%60)
end
local function account()
    if not isSampAvailable() or sampGetGamestate()~=3 or not integration.access:can(1) then return end
    local found,id=sampGetPlayerIdByCharHandle(PLAYER_PED)
    if not found then return end
    local nickname=sampGetPlayerNickname(id)
    local server,port=sampGetCurrentServerAddress()
    if not nickname then return end
    -- Byte encoding avoids unsafe filenames and preserves distinct identities.
    local raw=server..':'..tostring(port)..'/'..nickname
    return (raw:gsub('.',function(char) return string.format('%02x',char:byte()) end)),nickname
end
local function sync()
    local current=account()
    if current~=identity then
        identity=current;pending=nil;lastRequest=nil;lastSnapshot=nil;historyPage=1
        ledger,path=nil,nil
        if current then
            path=storage:path('data','online/'..current..'.ini')
            ledger=storage:loadIni({days={},notified={},meta={}},path)
            for key,value in pairs(ledger.days) do
                if not stats.timestamp(key) or not tonumber(value) or tonumber(value)<0 or tonumber(value)>1440 then ledger.days[key]=nil end
            end
        end
    end
    return ledger~=nil
end
local function request()
    if not settings.enabled then status='Включите учёт в настройках модуля.';return end
    if not sync() then status='Ожидание подтверждённых прав администратора.';return end
    if pending or lastRequest and os.clock()-lastRequest<10 then return end
    if sampIsDialogActive() or integration.queryBusy('time') then status='Дождитесь закрытия текущего диалога.';return end
    lastRequest=os.clock();pending={started=lastRequest,identity=identity,revision=integration.access:revision()}
    sampSendChat('/c 60');status='Ожидание ответа службы времени…'
end
local function accept(snapshot)
    ledger.days[snapshot.date]=snapshot.today
    if snapshot.yesterday then ledger.days[stats.shift(snapshot.date,-1)]=snapshot.yesterday end
    ledger.meta.lastDate=snapshot.date
    lastSnapshot=snapshot
    local summary=stats.summary(ledger.days,snapshot.date)
    for _,item in ipairs({{'daily',snapshot.date,'день'},{'weekly',stats.week(snapshot.date),'неделю'},{'monthly',snapshot.date:sub(1,7),'месяц'}}) do
        local key=item[1]..'_'..item[2]
        if settings.notifications and summary[item[1]]>=goals[item[1]] and not ledger.notified[key] then
            ledger.notified[key]=true;integration.message('Цель онлайна за '..item[3]..' выполнена: '..duration(summary[item[1]])..'.')
        end
    end
    local saved=storage:saveIni(ledger,path)
    status=saved and 'Обновлено по данным сервера: '..snapshot.date or 'Ошибка сохранения. Проверьте раздел «Система».'
    if settings.report then integration.message('Чистый онлайн: сегодня '..duration(summary.daily)..', неделя '..duration(summary.weekly)..', месяц '..duration(summary.monthly)..'.') end
end
function events.onShowDialog(id,style,title,button1,button2,text)
    if not settings.enabled or not sync() then return end
    local decoded=tostring(encoding.UTF8(text or ''))
    local snapshot,reason=stats.parse(decoded)
    if not snapshot then if reason then status=reason;pending=nil end;return end
    local owned=pending and os.clock()-pending.started<=30 and pending.identity==identity and pending.revision==integration.access:revision()
    pending=nil;accept(snapshot)
    -- Observe manually requested dialogs without swallowing or replacing them.
    if owned then return false end
end
function integration.update()
    if not sync() then return end
    if pending and os.clock()-pending.started>30 then pending=nil;status='Служба времени не ответила за 30 секунд.' end
    if settings.enabled and settings.auto and (not lastRequest or os.clock()-lastRequest>=settings.interval) then request() end
end
function integration.onDisconnect()
    identity,ledger,path,pending,lastSnapshot,lastRequest=nil,nil,nil,nil,nil,nil
end
function integration.queryPending(kind) return kind=='time' and pending~=nil end
function events.onSendCommand(command)
    if tostring(command):match('^/c%s+60%s*$') and integration.commandOwner()~='online' then pending=nil end
end
function integration.start()
end
function integration.draw()
    if imgui.Button('Обновить онлайн##online_refresh') then request() end
    if status then imgui.TextWrapped(status) end
    if not sync() or not ledger.meta.lastDate then
        imgui.TextWrapped('Запросите /c 60 или нажмите «Обновить онлайн». Время без AFK появится после ответа сервера.');return
    end
    local date=ledger.meta.lastDate
    local summary=stats.summary(ledger.days,date)
    imgui.TextWrapped('Последний серверный день: '..date..'. Суммы включают только сохранённые дни; пропущенные дни не восстанавливаются автоматически.')
    local columns=integration.layout.begin('online_summary',760)
    integration.layout.heading('Чистый онлайн и цели')
    for _,item in ipairs({{'daily','День'},{'weekly','Неделя'},{'monthly','Месяц'}}) do
        local value=summary[item[1]]
        imgui.Text(item[2]..': '..duration(value)..' / '..duration(goals[item[1]]))
        imgui.ProgressBar(math.min(1,value/goals[item[1]]),imgui.ImVec2(-1,16),string.format('%.0f%%',value/goals[item[1]]*100))
    end
    if lastSnapshot then imgui.Text('Всего сегодня: '..duration(lastSnapshot.total));imgui.Text('AFK: '..duration(lastSnapshot.afk)) end
    integration.layout.next(columns)
    integration.layout.heading('Рекорды и средние значения')
    for _,item in ipairs({{'dayBest','Лучший день'},{'weekBest','Лучшая неделя'},{'monthBest','Лучший месяц'}}) do
        imgui.TextWrapped(item[2]..': '..duration(summary[item[1]])..' · '..(summary[item[1]..'Date'] or '—'))
    end
    imgui.Text('В среднем за записанный день: '..duration(summary.average))
    imgui.Text('В среднем за записанную неделю: '..duration(summary.weekAverage))
    integration.layout.finish(columns)
    if imgui.CollapsingHeader('Динамика за последние 7 дней##online_trend') then
        for offset=-6,0 do
            local key=stats.shift(date,offset)
            local value=ledger.days[key]
            imgui.Text(key..': '..(value and duration(value) or 'нет записи'))
            imgui.ProgressBar(math.min(1,(tonumber(value) or 0)/goals.daily),imgui.ImVec2(-1,12),'')
        end
    end
    integration.layout.heading('История по дням')
    local dates={};for key in pairs(ledger.days) do dates[#dates+1]=key end;table.sort(dates,function(a,b)return a>b end)
    local pages=math.max(1,math.ceil(#dates/10));historyPage=math.min(historyPage,pages)
    for index=(historyPage-1)*10+1,math.min(#dates,historyPage*10) do
        local key=dates[index];imgui.Text(key..'    '..duration(ledger.days[key]))
    end
    if historyPage>1 and imgui.Button('Назад##online_history') then historyPage=historyPage-1 end
    if historyPage<pages and imgui.Button('Далее##online_history') then historyPage=historyPage+1 end
    imgui.TextDisabled(string.format('Страница %d / %d',historyPage,pages))
end
function integration.drawSettings()
    for _,item in ipairs({{'enabled','Учитывать чистый онлайн'},{'auto','Автоматически запрашивать /c 60'},
        {'notifications','Уведомлять о достижении целей'},{'report','Показывать сводку в моём чате'}}) do
        local value=imgui.ImBool(settings[item[1]])
        if imgui.Checkbox(item[2],value) then settings[item[1]]=value.v;pending=nil;saveConfig() end
    end
    local interval=imgui.ImInt(settings.interval)
    if imgui.InputInt('Интервал проверки, сек.',interval) then settings.interval=bound(interval.v,60,3600,60);saveConfig() end
    integration.layout.heading('Цели в минутах')
    for _,item in ipairs({{'daily','День',1440},{'weekly','Неделя',10080},{'monthly','Месяц',44640}}) do
        local value=imgui.ImInt(goals[item[1]])
        if imgui.InputInt(item[2]..'##online_goal',value) then goals[item[1]]=bound(value.v,1,item[3],120);saveConfig() end
    end
    imgui.TextWrapped('Неделя начинается в понедельник. Периоды определяются датой из ответа сервера. История разделена по серверу и нику; прежние дни сохраняются при смене недели и месяца.')
    local oldHistory=storage:read(legacy['historical_data.txt'])
    if oldHistory then
        imgui.TextWrapped('Прежние файлы ClearOnline скопированы в data/online_legacy. У них нет привязки к аккаунту. Импортируйте историю только в нужном аккаунте; существующие дни не заменяются.')
        if imgui.Button('Импортировать старую историю в текущий аккаунт##online_import') and sync() then
            local section,count=nil,0
            for line in oldHistory:gmatch('[^\r\n]+') do
                if line:match('^# Daily data') then section='daily'
                elseif line:match('^#') then section=nil
                elseif section=='daily' then
                    local date,minutes=line:match('^(%d%d%d%d%-%d%d%-%d%d):%s*(%d+)')
                    minutes=tonumber(minutes)
                    if date and stats.timestamp(date) and minutes and minutes<=1440 and ledger.days[date]==nil then
                        ledger.days[date]=minutes;count=count+1
                    end
                end
            end
            if not ledger.meta.lastDate then
                for date in pairs(ledger.days) do if not ledger.meta.lastDate or date>ledger.meta.lastDate then ledger.meta.lastDate=date end end
            end
            storage:saveIni(ledger,path);integration.message('Импортировано дней: '..count..'. Старые сводные файлы сохранены в архиве данных.')
        end
    end
end

    end
    sources["modules/queue.lua"] = function()
-- File-backed, explicitly started command queue. All UI belongs to CasualTool.
local imgui, sampev, u8 = require 'imgui', require 'samp.events', require('encoding').UTF8
local root=integration.root or getWorkingDirectory()
local storage=integration.storage
local primary=storage:path('data', 'command_queue.txt', {root..'/command_queue.txt', root..'/offban_commands.txt'})
local RESPONSE_TIMEOUT=22000
local settingsPath=storage:path('settings','queue.ini')
local settings=storage:loadIni({main={interval=30}},settingsPath)
settings.main.interval=math.max(1,math.min(300,tonumber(settings.main.interval) or 30))
local editor,editorSnapshot
local state={running=false,generation=0,page=1,index=0,total=0,done=0,status='Очередь не запущена.'}
local function message(text) state.status=text; integration.message(text) end
local function read(path)
    local file=io.open(path,'rb'); if not file then return end
    local text=file:read('*a'); file:close(); return text
end
local function write(path,text)
    local file,err=io.open(path,'wb'); if not file then return nil,err end
    local ok,reason=file:write(text); local closed,closeError=file:close()
    if not ok or not closed then return nil,reason or closeError end
    return true
end
local function utf8(text)
    local i=1
    while i<=#text do
        local a,b,c,d=text:byte(i,i+3)
        local function cont(x) return x and x>=128 and x<=191 end
        if a<128 then i=i+1
        elseif a>=194 and a<=223 and cont(b) then i=i+2
        elseif a>=224 and a<=239 and cont(b) and cont(c) and (a~=224 or b>=160) and (a~=237 or b<=159) then i=i+3
        elseif a>=240 and a<=244 and cont(b) and cont(c) and cont(d) and (a~=240 or b>=144) and (a~=244 or b<=143) then i=i+4
        else return false end
    end
    return true
end
local function loadQueue()
    local path=primary
    local raw=read(path)
    if not raw then return nil,'Файл не найден. Создайте шаблон и добавьте свои команды.' end
    if #raw>2*1024*1024 then return nil,'Файл очереди превышает 2 МБ.' end
    local bom=raw:sub(1,3)=='\239\187\191'
    local body=bom and raw:sub(4) or raw
    local isUtf8=utf8(body)
    if bom and not isUtf8 then return nil,'Повреждена кодировка UTF-8 в файле очереди.' end
    local data={path=path,raw=raw,bom=bom,utf8=isUtf8,newline=body:find('\r\n',1,true) and '\r\n' or '\n',lines={},items={},invalid=0,completed=0}
    for line in (body:gsub('\r\n','\n')..'\n'):gmatch('(.-)\n') do
        data.lines[#data.lines+1]=line
        local trimmed=line:match('^%s*(.-)%s*$')
        if trimmed~='' and not trimmed:match('^#') and not trimmed:match('^//') then
            if trimmed:match('%s%[[^%[%]]*%]$') then data.completed=data.completed+1
            else
                local ok,cp=pcall(function() return isUtf8 and u8:decode(trimmed) or trimmed end)
                local valid=ok and cp and cp:match('^/[%w_]+') and not cp:find('[%z\1-\31]') and #cp<=144
                local labelOk,label=pcall(function() return isUtf8 and trimmed or u8(trimmed) end)
                if not labelOk then valid=false; label='Некорректная кодировка строки' end
                data.items[#data.items+1]={line=#data.lines,command=valid and cp or nil,label=label,original=line}
                if not valid then data.invalid=data.invalid+1 end
            end
        end
    end
    return data
end
local function reload()
    if state.running then message('Сначала остановите очередь.'); return end
    local data,err=loadQueue(); state.data=data; state.page=1; state.done=0
    state.status=data and ('Ожидают отправки: '..#data.items..'. Уже отмечены: '..data.completed..'. Ошибок: '..data.invalid..'.') or err
    return data
end
local function mark(data,item,result)
    -- A stale UI snapshot must never overwrite a user's edits in their editor.
    if read(data.path)~=data.raw then return nil,'Файл изменён извне; очередь остановлена. Проверьте последнюю попытку перед повторным запуском.' end
    result=result:gsub('[\r\n%[%]]',' ')
    local suffix=data.utf8 and result or u8:decode(result)
    local previous=data.lines[item.line]
    data.lines[item.line]=item.original..' ['..suffix..']'
    local raw=(data.bom and '\239\187\191' or '')..table.concat(data.lines,data.newline)
    -- Keep the pre-write file recoverable if disk writing fails partway through.
    local backup,backupError=write(data.path..'.casualat.bak',data.raw)
    if not backup then data.lines[item.line]=previous; return nil,'Не сохранена резервная копия: '..tostring(backupError) end
    local ok,err=write(data.path,raw)
    if not ok then data.lines[item.line]=previous; return nil,'Не сохранён статус; очередь остановлена: '..tostring(err) end
    data.raw=raw
    return true
end
local function alive(generation)
    return state.running and generation==state.generation and isSampAvailable() and sampGetGamestate()==3
        and state.accessRevision==integration.access:revision() and integration.access:can(1)
end
local function delay(ms,generation)
    local deadline=getGameTimer()+ms
    repeat
        if not alive(generation) then return false end
        wait(math.min(200,math.max(0,deadline-getGameTimer())))
    until getGameTimer()>=deadline
    return alive(generation)
end
local function stop(reason)
    integration.cancelPending()
    state.running=false; state.generation=state.generation+1; state.waiting=nil; state.query=nil
    state.status=reason or 'Очередь остановлена. Уже начатые попытки не повторяются.'
end
local function start()
    if state.running then message('Очередь уже работает.'); return end
    if not isSampAvailable() or sampGetGamestate()~=3 then message('Дождитесь подключения к серверу.'); return end
    if not integration.access:require(1, message) then return end
    local data,err=loadQueue()
    if not data then message(err); return end
    state.data=data
    if data.invalid>0 then message('Исправьте строки с ошибками: '..data.invalid..'. Нужны команды с / длиной до 144 байт.'); return end
    if #data.items==0 then message('В файле нет команд без отметки результата.'); return end
    state.running=true; state.generation=state.generation+1
    state.accessRevision=integration.access:revision()
    state.total=#data.items; state.done=0; state.index=0
    local generation=state.generation
    lua_thread.create(function()
        for index,item in ipairs(data.items) do
            if not alive(generation) then break end
            local kind=item.command:match('^/(%S+)'):lower()
            while alive(generation) and integration.queryBusy(kind) do
                state.status='Ожидание завершения другого запроса /'..kind..'…'
                wait(100)
            end
            if not alive(generation) then break end
            state.index=index; state.response=nil
            -- Persist BEFORE invoking: a crash/disconnect cannot silently retry a punishment.
            local marked,why=mark(data,item,'X-Tools: попытка начата; результат не подтверждён')
            if not marked then stop(why); integration.message(why); return end
            state.query=kind
            item.result='Ожидание подтверждения';state.waiting=item.command:match('^/%S+%s+(%S+)');state.command=item.label
            local targetId=tonumber(state.waiting)
            state.expectedTarget=targetId and sampIsPlayerConnected(targetId) and sampGetPlayerNickname(targetId) or state.waiting
            local sent,sendError=pcall(sampSendChat,item.command)
            state.done=index
            if not sent then
                state.waiting=nil
                mark(data,item,'X-Tools: ошибка отправки; результат не подтверждён')
                stop('Ошибка отправки: '..tostring(sendError)); return
            end
            state.status='Попытка '..index..' из '..#data.items..'. Ожидание ответа…'
            local deadline=getGameTimer()+RESPONSE_TIMEOUT
            while alive(generation) and not state.response and getGameTimer()<deadline do
                state.response=integration.guardResult(item.label);wait(200)
            end
            state.waiting=nil; state.query=nil
            if not alive(generation) then break end
            local note=state.response and ('Результат: '..state.response) or 'X-Tools: запрос передан; ответ не подтверждён'
            item.result=state.response and ('Ответ: '..state.response) or 'Нет подтверждения сервера'
            local saved,reason=mark(data,item,note)
            if not saved then stop(reason); integration.message(reason); return end
            if index<#data.items then
                state.status='Отправлено попыток: '..index..'. Пауза '..settings.main.interval..' сек.'
                if not delay(settings.main.interval*1000,generation) then break end
            end
        end
        if generation==state.generation then
            stop('Очередь завершена. Попыток: '..state.done..'. Результаты проверьте в файле и на сервере.')
        end
    end)
end
function sampev.onServerMessage(_,text)
    if not state.waiting or state.response then return end
    local ok,decoded=pcall(function() return u8(text or '') end)
    if not ok then return end
    local clean=tostring(decoded):gsub('{%x%x%x%x%x%x}','')
    local found,id=sampGetPlayerIdByCharHandle(PLAYER_PED)
    local actor=found and sampGetPlayerNickname(id)
    if integration.service('queue_confirmation.lua').match(state.command,clean,state.expectedTarget,actor)then state.response=clean end
end
local function status() integration.message(state.status) end
local function template()
    if read(primary)~=nil then message('Файл очереди уже существует.'); return end
    local ok,err=write(primary,'\239\187\191# X-Tools: по одной команде с / на строку.\r\n# Комментарии начинаются с # или //.\r\n# Строки с итоговой отметкой [результат] повторно не отправляются.\r\n# Добавьте свои команды ниже. Запуск — кнопкой в меню.\r\n')
    if not ok then message('Не удалось создать файл: '..tostring(err)); return end
    reload()
end
integration.startQueue=start
integration.stopQueue=stop
integration.reloadQueue=reload
function integration.start() end
integration.draw=function()
    local wide=imgui.GetContentRegionAvailWidth()>=680
    imgui.BeginChild('##queue_summary',imgui.ImVec2(0,state.running and 132 or 108),true)
    imgui.Text(state.running and 'ВЫДАЧА НАКАЗАНИЙ' or 'ОЧЕРЕДЬ НАКАЗАНИЙ')
    imgui.TextWrapped(state.status)
    local count=state.data and #state.data.items or 0
    imgui.TextDisabled('В очереди: '..count..'     Обработано: '..state.done..'     Ошибок: '..(state.data and state.data.invalid or 0))
    if state.running and state.total>0 then imgui.ProgressBar(state.done/state.total,imgui.ImVec2(-1,18),state.done..' / '..state.total)end
    imgui.EndChild()
    imgui.Spacing()
    imgui.Text('Управление очередью')
    local interval=imgui.ImInt(settings.main.interval)
    imgui.TextWrapped('Пауза между командами, сек. (1–300)')
    imgui.PushItemWidth(math.min(180,imgui.GetContentRegionAvailWidth()))
    if imgui.InputInt('##queue_interval',interval,0,0) then settings.main.interval=math.max(1,math.min(300,interval.v));storage:saveIni(settings,settingsPath) end
    imgui.PopItemWidth()
    if state.running then
        if imgui.Button('Остановить##queue_stop') then stop() end
    elseif editor then
        -- Editor replaces the journal. Its own scroll area never contains action buttons.
        if imgui.Button('Сохранить файл##queue_save') then
            if (read(primary) or '')~=editorSnapshot then message('Файл изменён извне. Сохранение отменено; перечитайте файл.')
            else
                local ok,err=storage:write(primary,editor.v)
                if ok then editor=nil;reload() else message('Ошибка записи: '..tostring(err)) end
            end
        end
        if wide then imgui.SameLine() end
        if imgui.Button('Закрыть редактор##queue_close_editor') then editor=nil end
    else
        if imgui.Button('Прочитать файл##queue_read') then reload() end
        if wide then imgui.SameLine() end
        if imgui.Button('Редактировать в игре##queue_editor') then
            editorSnapshot=read(primary) or ''
            local text=editorSnapshot:gsub('^\239\187\191','')
            if not utf8(text) then text=u8(text) end
            if #text>262140 then message('Для большого файла используйте внешний редактор.')
            else editor=imgui.ImBuffer(262144);editor.v=text end
        end
        if not editor and state.data and #state.data.items>0 and state.data.invalid==0 then
            if wide then imgui.SameLine() end
            if imgui.Button('Запустить очередь##queue_start') then start() end
        end
        if not state.data then
            if imgui.Button('Создать пустой шаблон##queue_template') then template() end
        end
    end
    if imgui.CollapsingHeader('Файл и отметки##queue_details') then
        imgui.TextWrapped(state.data and state.data.path or primary)
        imgui.TextWrapped('Отмеченные строки пропускаются. Отметка — попытка отправки, результат сверяйте с сервером. /offban проверяется через /baninfo.')
        if imgui.Button('Как подготовить файл##queue_help') then integration.openHelp('queue') end
    end
    imgui.Separator()
    if editor then
        imgui.TextDisabled('По одной команде на строку')
        local available=imgui.GetContentRegionAvail()
        imgui.InputTextMultiline('##queue_text',editor,imgui.ImVec2(math.max(1,available.x-1),math.max(80,available.y-8)))
        return
    end
    local data=state.data
    if data and #data.items>0 then
        local pages=math.max(1,math.ceil(#data.items/8))
        state.page=math.max(1,math.min(pages,state.page))
        imgui.Text('Страница '..state.page..' / '..pages)
        if imgui.Button('Назад##queue_prev') then state.page=math.max(1,state.page-1); imgui.SetScrollY(0) end
        imgui.SameLine()
        if imgui.Button('Далее##queue_next') then state.page=math.min(pages,state.page+1); imgui.SetScrollY(0) end
        for i=(state.page-1)*8+1,math.min(state.page*8,#data.items) do
            local item=data.items[i]
            imgui.BeginChild('##queue_item_'..i,imgui.ImVec2(0,110),true)
            imgui.TextWrapped((item.command and '' or 'Ошибка · ')..'Строка '..item.line..': '..item.label)
            imgui.TextWrapped(item.result or (i<=state.done and 'Попытка начата · результат в файле' or 'Ожидает отправки'))
            imgui.EndChild()
            imgui.Spacing()
        end
    elseif data then imgui.TextWrapped('Нет новых команд. Добавьте строки в редакторе или перечитайте изменённый файл.')
    else
        imgui.Spacing();imgui.Text('Подготовьте список наказаний')
        imgui.TextWrapped('1. Откройте файл или создайте шаблон.\n2. В редакторе добавьте по одной команде на строку.\n3. Проверьте список и нажмите «Запустить очередь».')
        imgui.Spacing();imgui.TextDisabled('Примеры формата')
        imgui.Text('/offban Nick_Name 3 Причина')
        imgui.Text('/mute 57 10 Причина')
        imgui.TextWrapped('Подтверждение учитывает администратора, игрока и вид наказания. Если сервер не подтвердил выдачу, строка остаётся с отдельной отметкой — повторной отправки не будет.')
    end
end
integration.onDisconnect=function() stop('Соединение потеряно. Автоматическое продолжение отключено.') end
integration.queryPending=function(kind) return kind=='offst' and state.query==kind and state.running end
function integration.stop() stop('X-Tools остановлен.') end

    end
    sources["modules/reminders.lua"] = function()
local g=require('imgui')
local u8=require('encoding').UTF8
local settings=integration.service('combo_settings.lua')
local defaults=integration.service('reminder_templates.lua')
local templates={};for i,v in ipairs(defaults)do templates[i]=v end
local builtinCount=#templates
local cfg,path=settings.load(integration,'reminders',{main={selected=1,delay=3,target='0',customCount=0}})
for i=1,settings.limit(cfg.main.customCount,0,0,100)do
    local pack=cfg['pack'..(builtinCount+i)] or {}
    templates[#templates+1]={name=tostring(pack.name or ('Мой набор '..i)),lines={}}
end
local function deleted(i)return cfg['pack'..i]and cfg['pack'..i].deleted==true end
local creating=false
local newName=g.ImBuffer('',128)
if cfg.main.expandRange~=nil then cfg.main.expandRange=nil;integration.storage:saveIni(cfg,path)end
local targetInput=g.ImBuffer(tostring(cfg.main.target),32)
local lines={}
local draft,index,queue,nextAt,status=nil,nil,nil,0,'Выберите набор и проверьте текст перед отправкой.'
local function select(i)
    index=i;cfg.main.selected=i
    if not templates[i]or deleted(i)then index=nil;cfg.main.selected=0;draft=nil;lines={};return end
    draft=g.ImBuffer(cfg['pack'..i] and cfg['pack'..i].text or table.concat(templates[i].lines,'\n'),16384)
    lines={};for line in (draft.v..'\n'):gmatch('(.-)\n')do lines[#lines+1]=g.ImBuffer(line:gsub('\r',''),16384)end
end
local function selectAvailable(preferred)
    if templates[preferred]and not deleted(preferred)then select(preferred);return end
    for i=1,#templates do if not deleted(i)then select(i);return end end
    select(0)
end
selectAvailable(tonumber(cfg.main.selected)or 1)
local function saveLines()
    local text={};for _,buffer in ipairs(lines)do text[#text+1]=buffer.v end
    draft.v=table.concat(text,'\n')
    cfg['pack'..index]=cfg['pack'..index]or {};cfg['pack'..index].text=draft.v
    integration.storage:saveIni(cfg,path)
end
local function stop()queue=nil;status='Отправка остановлена.'end
integration.onDisconnect=stop
integration.stop=stop
integration.onAccessChanged=stop
integration.update=function()
    if not queue then return end
    if not integration.access:can(4) or sampGetGamestate()~=3 then stop();return end
    if getGameTimer()<nextAt then return end
    sampSendChat(queue[1]);table.remove(queue,1)
    nextAt=getGameTimer()+math.max(3,tonumber(cfg.main.delay)or 3)*1000
    if #queue==0 then queue=nil;status='Набор отправлен.'else status='Осталось строк: '..#queue end
end
integration.draw=function()
    g.TextWrapped('Напоминание игрокам через /msg. Доступно с 4-го уровня администратора.')
    local width=g.GetContentRegionAvail().x
    local wide=width>=620
    local left=wide and math.min(260,width*0.3)or width
    local right=wide and width-left-20 or width
    if wide then g.Columns(2,'##reminders_layout',false);g.SetColumnWidth(0,left)end
    g.Text('МОИ НАБОРЫ')
    g.BeginChild('##reminders_packs',g.ImVec2(left-16,wide and 340 or 140),true)
    for i,pack in ipairs(templates)do if not deleted(i)then
        if g.Selectable(pack.name..'##reminder_pack_'..i,index==i,0,g.ImVec2(0,30))then stop();select(i);integration.storage:saveIni(cfg,path)end
        g.TextDisabled(i<=builtinCount and 'Готовый набор' or 'Свой набор');g.Separator()
    end end
    g.EndChild()
    g.PushItemWidth(math.max(100,left-16))
    if g.Button('Создать новый набор##reminders_new')then creating=true;newName.v='' end
    if creating then
        g.InputText('Название набора##reminders_name',newName)
        if g.Button('Создать##reminders_create')then
            local name=newName.v:match('^%s*(.-)%s*$')
            local slot=#templates+1;for i=builtinCount+1,#templates do if deleted(i)then slot=i;break end end
            if name=='' or name:find('[%z\1-\31]')then status='Введите название набора.'
            elseif slot>builtinCount+100 then status='Можно создать до 100 своих наборов.'
            else
                stop();templates[slot]={name=name,lines={}}
                cfg.main.customCount=#templates-builtinCount
                cfg['pack'..slot]={name=name,text=''}
                select(slot);integration.storage:saveIni(cfg,path)
                creating=false;status='Набор создан. Введите текст ниже — он сохраняется автоматически.'
            end
        end
        g.SameLine();if g.Button('Отмена##reminders_create')then creating=false end
    end
    g.PopItemWidth()
    if wide then g.NextColumn()else g.Separator()end
    if not index then g.TextWrapped('Наборов нет. Создайте новый набор слева.');g.TextWrapped(status);if wide then g.Columns(1)end;return end
    g.TextWrapped(templates[index].name)
    g.TextDisabled('ПАРАМЕТРЫ ОТПРАВКИ')
    g.PushItemWidth(math.max(100,math.min(180,right-180)))
    if g.InputText('Режим / радиус',targetInput)then cfg.main.target=targetInput.v;integration.storage:saveIni(cfg,path)end
    local delay=g.ImInt(cfg.main.delay)
    if g.InputInt('Интервал, сек.',delay,0,0)then cfg.main.delay=math.max(3,math.min(60,delay.v));integration.storage:saveIni(cfg,path)end
    g.PopItemWidth()
    g.TextWrapped('0 — всем; 1 — важное всем; 20–300 — радиус видимости.')
    g.Separator();g.Text('СООБЩЕНИЯ');g.SameLine();g.TextDisabled(tostring(#lines)..' / 50')
    local insert,remove
    g.BeginChild('##reminder_lines',g.ImVec2(right-8,280),false)
    for i,buffer in ipairs(lines)do
        g.TextDisabled(string.format('%02d',i));g.SameLine()
        local scale=integration.preferences.data.main.scale or 1
        local spacing=g.GetStyle().ItemSpacing.x
        g.PushItemWidth(math.max(1,(g.GetContentRegionAvailWidth()-2*spacing)/scale-60))
        if g.InputText('##reminder_line_'..i,buffer)then saveLines()end
        g.PopItemWidth();g.SameLine()
        if g.Button('+##reminder_insert_'..i,g.ImVec2(30,0))then insert=i+1 end
        g.SameLine();if g.Button('×##reminder_remove_'..i,g.ImVec2(30,0))then remove=i end
    end
    g.EndChild()
    if remove then table.remove(lines,remove);saveLines()end
    if insert and #lines<50 then table.insert(lines,insert,g.ImBuffer('',16384));saveLines()end
    if g.Button('+ Добавить сообщение##reminders')and #lines<50 then lines[#lines+1]=g.ImBuffer('',16384);saveLines()end
    if index<=builtinCount and g.Button('Вернуть исходный текст##reminders')then
        cfg['pack'..index]=nil;select(index);integration.storage:saveIni(cfg,path)
    end
    g.TextWrapped('Одна строка — одно сообщение. Тексты из исходника можно изменить перед отправкой.')
    if g.Button('Отправить набор##reminders') and not queue and integration.access:require(4,integration.message)then
        local pending={};local valid=true
        local target,err=integration.service('msg_targets.lua').parse(targetInput.v)
        if not target then status=err;if wide then g.Columns(1)end;return end
        local lineCount=0
        for line in (draft.v..'\n'):gmatch('(.-)\n')do
            line=line:gsub('\r',''):match('^%s*(.-)%s*$')
            if line~='' then
                lineCount=lineCount+1
                local encoded=u8:decode('/msg '..target..' '..line)
                if #encoded>144 or line:find('[%z\1-\31]')then valid=false;break end
                pending[#pending+1]=encoded
            end
        end
        if valid and #pending>0 and lineCount<=50 then queue=pending;nextAt=getGameTimer();status='В очереди сообщений: '..#pending
        else status='Проверьте строки: команда до 144 байт CP1251, не более 50 строк текста.'end
    end
    g.SameLine();if g.Button('Остановить##reminders')then stop()end
    if g.Button('Удалить набор##reminders_delete')then
        stop();cfg['pack'..index]={deleted=true};selectAvailable(index)
        integration.storage:saveIni(cfg,path);status='Набор удалён.'
    end
    g.TextWrapped(status)
    g.TextDisabled('Изменения сохраняются автоматически.')
    if wide then g.Columns(1)end
end

    end
    sources["modules/rephelp.lua"] = function()
-- RepHelp by XZ KTO; editable templates, isolated per-command dispatch.
local g=require('imgui');local u8=require('encoding').UTF8;local events=require('lib.samp.events')
local defaults=integration.service('rephelp_defaults.lua')
local path=integration.storage:path('settings','rephelp.ini')
local cfg=integration.storage:loadIni({main={enabled=false,count=#defaults}},path)
local selected=1;local drafts={};local editor;local status=''
local function row(i)if not cfg['row'..i]then local d=defaults[i]or {};cfg['row'..i]={command=d.command or '',text=d.text or '',enabled=true}end;return cfg['row'..i]end
local function choose(i)
    selected=i
    if not drafts[i]then
        local r=row(i);local lines={}
        for line in (r.text..'\n'):gmatch('(.-)\n')do lines[#lines+1]=g.ImBuffer(line:gsub('\r',''),2048)end
        drafts[i]={command=g.ImBuffer('/'..r.command,64),lines=lines,dirty=false}
    end
    editor=drafts[i];status=''
end
local function save()integration.storage:saveIni(cfg,path)end
if cfg.main.count>0 then choose(1)end
local generation=0
integration.onDisconnect=function()generation=generation+1 end;integration.stop=integration.onDisconnect
function events.onSendCommand(raw)
    if not cfg.main.enabled or integration.commandOwner() then return end
    local cmd,args=tostring(u8(raw)):match('^/([%w_]+)%s*(.-)%s*$');if not cmd then return end
    for i=1,math.min(100,tonumber(cfg.main.count)or #defaults)do
        local r=row(i)
        if r.enabled~=false and cmd:lower()==r.command:lower()then
            local id=args:match('^%d+$')and tonumber(args)
            if not id or id>1003 or not sampIsPlayerConnected(id)then integration.message('/'..cmd..' ID: укажите игрока онлайн.');return false end
            local nickname=sampGetPlayerNickname(id);local commands={}
            for line in (r.text..'\n'):gmatch('(.-)\n')do
                line=line:gsub('\r',''):gsub('{id}',tostring(id)):gsub('{time}',os.date('%H:%M:%S')):gsub('{date}',os.date('%d.%m.%Y'))
                if line~=''then
                    if line:sub(1,1)~='/'then line='/ans '..id..' '..line end
                    local encoded=u8:decode(line)
                    if #encoded>144 or encoded:find('[%z\1-\31]')or #commands>=20 then integration.message('Проверьте шаблон: до 20 строк и 144 байт в команде.');return false end
                    commands[#commands+1]=encoded
                end
            end
            local token=generation
            lua_thread.create(function()
                for n,v in ipairs(commands)do
                    if n>1 then wait(500)end
                    if token~=generation or not cfg.main.enabled or sampGetGamestate()~=3 or not sampIsPlayerConnected(id)or sampGetPlayerNickname(id)~=nickname then return end
                    sampSendChat(v)
                end
            end)
            return false
        end
    end
end
integration.draw=function()
    local enabled=g.ImBool(cfg.main.enabled)
    if g.Checkbox('Включить биндер',enabled)then cfg.main.enabled=enabled.v;generation=generation+1;save()end
    g.SameLine();g.TextDisabled('Команды и ответы в одном месте')
    local width=g.GetContentRegionAvail().x
    local wide=width>=620
    local left=wide and math.min(260,width*0.3)or width
    local right=wide and width-left-20 or width
    if wide then g.Columns(2,'##binder_layout',false);g.SetColumnWidth(0,left)end
    g.Text('МОИ КОМАНДЫ')
    if g.Button('+ Новая команда##rephelp',g.ImVec2(left-16,32))and cfg.main.count<100 then
        cfg.main.count=cfg.main.count+1;row(cfg.main.count).enabled=false;choose(cfg.main.count);save()
    end
    g.BeginChild('##binder_commands',g.ImVec2(left-16,wide and 390 or 150),true)
    for i=1,math.min(100,cfg.main.count)do
        local r=row(i);local title=r.command~=''and '/'..r.command or 'Новая команда'
        if drafts[i]and drafts[i].dirty then title=title..' *'end
        if g.Selectable(title..'##binder_item_'..i,selected==i,0,g.ImVec2(0,28))then choose(i)end
        g.TextDisabled(r.enabled~=false and 'Включена' or 'Выключена')
        g.Separator()
    end
    g.EndChild()
    if wide then g.NextColumn()else g.Separator()end
    if not editor then g.TextWrapped('Нет биндов. Нажмите «Новая команда», чтобы создать первый.');if wide then g.Columns(1)end;return end
    g.Text('РЕДАКТОР КОМАНДЫ')
    g.TextDisabled('Команда запуска')
    g.PushItemWidth(math.max(100,right-8))
    if g.InputText('##binder_trigger',editor.command)then editor.dirty=true end
    g.PopItemWidth()
    local trigger=editor.command.v:match('^%s*/?(.-)%s*$')
    g.TextWrapped('Например: /'..(trigger~=''and trigger or 'gg')..' 123 — выполнить строки ниже для игрока 123.')
    local active=g.ImBool(row(selected).enabled~=false)
    if g.Checkbox('Команда включена##rephelp',active)then row(selected).enabled=active.v;generation=generation+1;save()end
    g.Separator();g.Text('СТРОКИ ДЕЙСТВИЙ')
    local insert,remove
    g.BeginChild('##binder_lines',g.ImVec2(right-8,240),false)
    for i,buffer in ipairs(editor.lines)do
        g.TextDisabled(string.format('%02d',i));g.SameLine()
        local scale=integration.preferences.data.main.scale or 1
        local spacing=g.GetStyle().ItemSpacing.x
        g.PushItemWidth(math.max(1,(g.GetContentRegionAvailWidth()-2*spacing)/scale-60))
        if g.InputText('##binder_line_'..i,buffer)then editor.dirty=true end
        g.PopItemWidth();g.SameLine()
        if g.Button('+##binder_insert_'..i,g.ImVec2(30,0))then insert=i+1 end
        g.SameLine();if g.Button('×##binder_remove_'..i,g.ImVec2(30,0))then remove=i end
    end
    g.EndChild()
    if remove then table.remove(editor.lines,remove);editor.dirty=true end
    if insert and #editor.lines<20 then table.insert(editor.lines,insert,g.ImBuffer('',2048));editor.dirty=true end
    if g.Button('+ Добавить строку##binder')and #editor.lines<20 then editor.lines[#editor.lines+1]=g.ImBuffer('',2048);editor.dirty=true end
    g.TextWrapped('{id} — ID игрока · {time} — время · {date} — дата. Обычный текст отправляется через /ans; строка с / выполняется как команда.')
    if g.Button('Сохранить##rephelp',g.ImVec2(150,32))then
        local name=trigger:lower();local valid=name:match('^[a-z][a-z0-9_]*$')~=nil
        for i=1,cfg.main.count do if i~=selected and row(i).command==name then valid=false end end
        local lines={};for _,buffer in ipairs(editor.lines)do
            if buffer.v:find('[%z\1-\31]')then valid=false end
            lines[#lines+1]=buffer.v
        end
        if valid then row(selected).command=name;row(selected).text=table.concat(lines,'\n');generation=generation+1;save();editor.dirty=false;status='Изменения сохранены.'
        else status='Проверьте уникальность команды и строки: без переносов внутри одного поля.'end
    end
    g.SameLine();g.TextDisabled(editor.dirty and 'Есть несохранённые изменения' or status)
    if g.Button('Удалить бинд##rephelp',g.ImVec2(150,32))then
        generation=generation+1
        for i=selected,cfg.main.count-1 do cfg['row'..i]=cfg['row'..(i+1)];drafts[i]=drafts[i+1]end
        cfg['row'..cfg.main.count]=nil;drafts[cfg.main.count]=nil
        cfg.main.count=cfg.main.count-1
        if cfg.main.count>0 then choose(math.min(selected,cfg.main.count))else selected=0;editor=nil end
        save();status='Бинд удалён.'
    end
    if wide then g.Columns(1)end
end

    end
    sources["modules/road.lua"] = function()
-- CasualTool road placement, adapted from bart4RoadTP (source in integration/sources).
-- One explicit action; no background loop, second UI window or startup message.
local ffi = require 'ffi'
local SEARCH_RADIUS, HEIGHT_OFFSET = 10000, 0.2
local fallback_roads = {{x=-151, y=-373, z=1, radius=1000}}

local function tell(text)
    integration.message(text)
end

local function finite(value)
    return type(value)=='number' and value==value and value~=math.huge and value~=-math.huge
end

local function find_road(ped)
    local x,y,z = getCharCoordinates(ped)
    if not (finite(x) and finite(y) and finite(z)) then return end
    -- Opcode 04B9 returns node1 XYZ, node2 XYZ, angle (no boolean prefix).
    local rx,ry,rz = getClosestStraightRoad(x,y,z,0,SEARCH_RADIUS)
    if finite(rx) and finite(ry) and finite(rz) and (rx~=0 or ry~=0 or rz~=0) then
        return rx,ry,rz+HEIGHT_OFFSET
    end
    local nearest, distance
    for _, point in ipairs(fallback_roads) do
        local squared = (x-point.x)^2+(y-point.y)^2+(z-point.z)^2
        if squared<=point.radius^2 and (not distance or squared<distance) then
            nearest,distance = point,squared
        end
    end
    if nearest then return nearest.x,nearest.y,nearest.z+HEIGHT_OFFSET end
end

local function send_position(local_id,x,y,z)
    local stream
    local ok,err = pcall(function()
        local sf = require 'lib.sampfuncs'
        require 'samp.synchronization'
        -- Retain the owned array until its bytes have been copied into the stream.
        local data = ffi.new('struct PlayerSyncData[1]')
        local pointer = tonumber(ffi.cast('uintptr_t',data))
        sampStorePlayerOnfootData(local_id,pointer)
        data[0].position.x,data[0].position.y,data[0].position.z = x,y,z
        stream = raknetNewBitStream()
        assert(stream and stream~=0, 'Cannot allocate road sync bitstream')
        raknetBitStreamWriteInt8(stream,sf.PACKET_PLAYER_SYNC)
        raknetBitStreamWriteBuffer(stream,pointer,ffi.sizeof(data))
        local sent = raknetSendBitStreamEx(stream,sf.HIGH_PRIORITY,sf.UNRELIABLE_SEQUENCED,1)
        assert(sent~=false, 'Road sync send failed')
    end)
    if stream and stream~=0 then
        local freed,free_error = pcall(raknetDeleteBitStream,stream)
        if not freed then ok,err=false,free_error end
    end
    return ok,err
end

local followupGeneration=0
integration.onDisconnect=function() followupGeneration=followupGeneration+1 end
local function move_to_road(argument)
    if not integration.access:require(1, tell) then return end
    local text = tostring(argument or ''):match('^%s*(%d+)%s*$')
    local target_id = text and tonumber(text)
    if not target_id or target_id<0 or target_id>1003 then
        tell('Укажите ID игрока: /tr ID.')
        return
    end
    if not isSampAvailable() or sampGetGamestate()~=3 then
        tell('Для перемещения на дорогу подключитесь к серверу.')
        return
    end
    local found,local_id = sampGetPlayerIdByCharHandle(PLAYER_PED)
    if not found or not finite(local_id) then
        tell('Не удалось определить ваш ID. Дождитесь входа в игру и повторите перемещение.')
        return
    end
    if target_id==local_id then
        tell('Укажите ID другого игрока для перемещения на дорогу.')
        return
    end
    if not sampIsPlayerConnected(target_id) then
        tell('Этот игрок не подключён к серверу. Проверьте ID.')
        return
    end
    local streamed,ped = sampGetCharHandleBySampPlayerId(target_id)
    if not streamed or not ped or ped==0 then
        tell('Игрок вне зоны прорисовки. Приблизьтесь к нему или начните слежку.')
        return
    end
    if getActiveInterior()~=0 then
        tell('Перемещение на дорогу доступно только вне интерьеров.')
        return
    end
    local ok,x,y,z = pcall(find_road,ped)
    if not ok then
        tell('Не удалось найти координаты дороги. '..tostring(x))
        return
    end
    if not x then
        tell('Поблизости нет подходящей точки для перемещения на дорогу.')
        return
    end
    local sent,err = send_position(local_id,x,y,z)
    if not sent then
        tell('Не удалось отправить запрос перемещения на дорогу. '..tostring(err))
        return
    end
    -- Preserve source ordering: one position update, then the server command.
    sampSendChat('/gethere '..target_id..' 1')
    -- Aegis already queues its own slap and observation refresh.
    if integration.preferences.data.main.roadFollowup and integration.commandOwner()~='aegis' then
        followupGeneration=followupGeneration+1
        local generation=followupGeneration
        local nickname=sampGetPlayerNickname(target_id)
        local function valid()
            return generation==followupGeneration and integration.preferences.data.main.roadFollowup
                and integration.access:can(1) and sampGetGamestate()==3
                and sampIsPlayerConnected(target_id) and sampGetPlayerNickname(target_id)==nickname
        end
        lua_thread.create(function()
            wait(350)
            if not valid() then return end
            sampSendChat('/slap '..target_id)
            wait(350)
            if valid() then sampSendChat('/sp '..target_id) end
        end)
    end
end

sampRegisterChatCommand('tr',move_to_road)


    end
    sources["modules/speed_boost.lua"] = function()
-- sh.cs: original 04BA speed boost, rewritten without a CLEO thread.
local g=require('imgui')
local settings=integration.service('combo_settings.lua')
local cfg,path=settings.load(integration,'speed-boost',{main={enabled=false}})
local nextAt=0
integration.keys:register('speed_boost','Ускорение транспорта — удерживать',{key=87,shift=true,second=0})
integration.update=function()
    if not cfg.main.enabled or not integration.access:can(1) or sampGetGamestate()~=3 then return end
    if not isGameWindowForeground() or isPauseMenuActive() or sampIsChatInputActive() or sampIsDialogActive() or sampIsCursorActive() then return end
    if not integration.keys:down('speed_boost') or getGameTimer()<nextAt then return end
    if not doesCharExist(PLAYER_PED) or not isCharInAnyCar(PLAYER_PED)then return end
    local car=storeCarCharIsInNoSave(PLAYER_PED)
    if getDriverOfCar(car)~=PLAYER_PED then return end
    local speed=getCarSpeed(car)
    if type(speed)~='number' or speed~=speed then return end
    setCarForwardSpeed(car,speed<190 and speed*1.15+4 or 61)
    nextAt=getGameTimer()+50
end
integration.onDisconnect=function()nextAt=0 end
integration.drawSettings=function()
    if settings.toggle(g,'Ускорение транспорта',cfg.main,'enabled')then integration.storage:saveIni(cfg,path)end
    integration.keys:draw(g,'speed_boost')
    g.TextWrapped('Удерживайте назначенную комбинацию за рулём. По умолчанию Shift + W. Поведение ускорения перенесено из sh.cs.')
end

    end
    sources["modules/stopsbiv.lua"] = function()
-- CasualTool medkit-animation observer, adapted from StopSbiv.
-- A detection is a suspicion. Spectating and warning always require user input.
local imgui = require 'imgui'
local events = require 'lib.samp.events'
local encoding = require 'encoding'
local storage = integration.storage
local bit = require 'bit'
encoding.default='CP1251'
local u8=encoding.UTF8
local CONFIG = storage:path('settings', 'medkits.ini', {getWorkingDirectory() .. '/config/stop_sbiv/settings.ini'})
local defaults={enabled=false,notify_chat=true,spectate_hotkey=true,warn_hotkey=true}
local config=storage:loadIni({main={enabled=false,notify_chat=true,spectate_hotkey=true,warn_hotkey=true}},CONFIG) or {}
config.main=type(config.main)=='table' and config.main or {}
for key,value in pairs(defaults) do
    local stored=config.main[key]
    if stored==nil then config.main[key]=value
    else config.main[key]=stored==true or stored==1 or stored=='1' or stored=='true' end
end
local MEDKIT_ANIMATION,MEDKIT_COLOR=1157,-1721303041
local CHECK_DELAY,TRACK_TIMEOUT,FOLLOW_TIMEOUT=1.10,5,10
integration.keys:register('medkit_warn','Аптечки: предупреждение',{key=0x48},nil,function() return integration.featureAllowed() end)
integration.keys:register('medkit_follow','Аптечки: слежка',{key=0x51,second=0x45},nil,function() return integration.featureAllowed() end)
local gangs={[-3407617]='ballas',[-16738048]='grove',[-13056]='vagos',[-10066177]='rifa',
    [-16724737]='aztec',[-16747147]='rm',[-4521984]='yakuza',[-6737050]='lcn'}
local suspects,animations,history={},{},{}
local last_suspect,requested_follow,follow
local spec_latch,warn_latch=false,false
local last_time=0
local save_error=false
local function now() return getGameTimer()/1000 end
local function nickname(id)
    if type(id)~='number' or id<0 or id>1003 or not sampIsPlayerConnected(id) then return end
    return sampGetPlayerNickname(id)
end
local function valid(target)
    return target and target.nick and nickname(target.id)==target.nick
end
local function identity(id)
    local nick=nickname(id)
    if nick then return {id=id,nick=nick} end
end
local function label(target) return tostring(u8(target.nick))..' ['..target.id..']' end
local function notify(text)
    integration.message(text)
end
local function reset()
    suspects,animations,history={},{},{}
    last_suspect,requested_follow,follow=nil,nil
    spec_latch,warn_latch=false,false
end
local function save()
    save_error=not storage:saveIni(config,CONFIG)
end
local function available()
    return integration.featureAllowed() and isSampAvailable() and sampGetGamestate()==3
end
local function can_check(id)
    if not nickname(id) then return false end
    local ok,ped=sampGetCharHandleBySampPlayerId(id)
    return ok and ped and ped~=0 and doesCharExist(ped) and not isCharInAnyCar(ped) and not isCharDead(ped)
end
local function inputs_available()
    return available() and not integration.windowOpen() and not sampIsChatInputActive()
        and not sampIsDialogActive() and not isPauseMenuActive() and not sampIsScoreboardOpen()
        and not isSampfuncsConsoleActive() and not sampIsCursorActive()
end
local function arm_warn(target)
    follow={id=target.id,nick=target.nick,expires=now()+FOLLOW_TIMEOUT}
    if config.main.warn_hotkey and config.main.notify_chat then
        notify('Зафиксирован возможный сбив аптечки: '..label(follow)..'. '..integration.keys:name('medkit_warn')..' — отправить /warn после проверки. Доступно 10 секунд.')
    end
    warn_latch=integration.keys:down('medkit_warn')
end
local function start_follow(target)
    if not config.main.enabled or not available() or not valid(target) or not target.reason or target.left then return end
    requested_follow={id=target.id,nick=target.nick,expires=now()+FOLLOW_TIMEOUT}
    follow=nil
    sampSendChat('/sp '..target.id)
end
local function send_warn()
    if not config.main.enabled or not available() or not valid(follow) or follow.expires<now() then
        follow=nil; return
    end
    local id=follow.id
    if integration.preferences.data.main.medkitMode=='families' then
        follow=nil;integration.invoke('fw',tostring(id)..' '..u8:decode('Нарушение правил: сбив аптечки'));return
    end
    local suffix=gangs[bit.tobit(sampGetPlayerColor(id))]
    local command='/warn '..id..' Нарушение правил /capture'..(suffix and ('['..suffix..']') or '')
    follow=nil
    -- Clear before dispatch: this event can call our onSendCommand synchronously.
    sampSendChat(u8:decode(command))
end
local function flag(id,reason)
    local suspect=suspects[id]
    suspects[id]=nil
    if not valid(suspect) or not can_check(id) then return end
    local record={id=id,nick=suspect.nick,reason=reason,time=now()}
    table.insert(history,1,record)
    while #history>8 do table.remove(history) end
    last_suspect=record
    if config.main.notify_chat then
        notify('Проверка аптечек: '..label(record)..' — возможный сбив анимации ('..reason..').')
        if config.main.spectate_hotkey then notify(integration.keys:name('medkit_follow')..' — перейти к проверке этого игрока в слежке.') end
    end
end
function events.onPlayerChatBubble(id,color,distance,duration,message)
    if not config.main.enabled or not available() or bit.tobit(color)~=bit.tobit(MEDKIT_COLOR) then return end
    if not tostring(message or ''):lower():match('%+%d+%s*hp') or not can_check(id) then return end
    local existing=suspects[id]
    if existing and valid(existing) and now()-existing.created<TRACK_TIMEOUT then return end
    local suspect=identity(id)
    suspect.created=now()
    local started=animations[id]
    if started and started.nick==suspect.nick and now()-started.time<=0.5 then suspect.started=started.time end
    suspects[id]=suspect
end
function events.onApplyPlayerAnimation(id,library,name)
    if not config.main.enabled or not available() then return end
    if tostring(name or ''):lower()~='gum_eat' then return end
    local nick=nickname(id)
    if not nick then return end
    animations[id]={nick=nick,time=now()}
    local suspect=suspects[id]
    if valid(suspect) and not suspect.started then suspect.started=now() end
end
function events.onClearPlayerAnimation(id)
    local suspect=suspects[id]
    animations[id]=nil
    if not config.main.enabled or not available() or not suspect then return end
    if suspect.started and now()-suspect.started<TRACK_TIMEOUT then flag(id,'анимация прервана')
    else suspects[id]=nil end
end
function events.onPlayerSync(id,data)
    if not config.main.enabled or not available() then return end
    local suspect=suspects[id]
    if not suspect then return end
    if not valid(suspect) or not can_check(id) then suspects[id]=nil; return end
    local elapsed=now()-suspect.created
    if not suspect.started and elapsed>TRACK_TIMEOUT then suspects[id]=nil; return end
    if not data or type(data.animationId)~='number' then return end
    if data.animationId==MEDKIT_ANIMATION then
        suspect.started=suspect.started or now()
    elseif not suspect.started and elapsed>=CHECK_DELAY then
        flag(id,'анимация аптечки не появилась')
    elseif suspect.started then
        if now()-suspect.started<TRACK_TIMEOUT then flag(id,'анимация аптечки прервана')
        else suspects[id]=nil end
    end
    -- Nil preserves the original packet and leaves other CasualTool observers intact.
end
function events.onPlayerQuit(id)
    suspects[id],animations[id]=nil,nil
    if last_suspect and last_suspect.id==id then last_suspect=nil end
    if requested_follow and requested_follow.id==id then requested_follow=nil end
    if follow and follow.id==id then follow=nil end
    -- Keep a short record, but disable its actions even if this ID is reused.
    for _,record in ipairs(history) do if record.id==id then record.left=true end end
end
function events.onPlayerStreamOut(id) suspects[id],animations[id]=nil,nil end
function events.onSendCommand(command)
    if not config.main.enabled then return end
    local text=tostring(command or ''):lower()
    local id=text:match('^/sp%s+(%d+)%s*$')
    if id then
        -- Only a request originating from a detected incident may arm /warn.
        if not valid(requested_follow) or requested_follow.id~=tonumber(id)
            or requested_follow.expires<now() then requested_follow=nil end
        follow=nil
    elseif text:match('^/sp%s*$') then requested_follow,follow=nil,nil
    elseif text:match('^/warn%s+') then follow=nil end
end
function events.onSpectatePlayer(id)
    if not config.main.enabled then return end
    if valid(requested_follow) and requested_follow.id==id and requested_follow.expires>=now() then
        arm_warn(requested_follow)
    else follow=nil end
    requested_follow=nil
end
function events.onTogglePlayerSpectating(enabled)
    if not enabled then requested_follow,follow=nil,nil end
end
function events.onSpectateVehicle()
    -- A vehicle RPC does not identify its passenger; never retain another target.
    requested_follow,follow=nil,nil
end
local function step()
    local time=now()
    if time<last_time then reset() end
    last_time=time
    if not config.main.enabled or not available() then return end
    for id,suspect in pairs(suspects) do
        local deadline=(suspect.started or suspect.created)+TRACK_TIMEOUT
        if time>deadline or not valid(suspect) then suspects[id]=nil end
    end
    for id,animation in pairs(animations) do if time-animation.time>TRACK_TIMEOUT then animations[id]=nil end end
    if requested_follow and (time>requested_follow.expires or not valid(requested_follow)) then requested_follow=nil end
    if follow and (time>follow.expires or not valid(follow)) then follow=nil end
    local spec_down=integration.keys:down('medkit_follow')
    local warn_down=integration.keys:down('medkit_warn')
    if inputs_available() then
        if config.main.spectate_hotkey and spec_down and not spec_latch then start_follow(last_suspect) end
        if config.main.warn_hotkey and warn_down and not warn_latch then send_warn() end
    end
    -- Holding a key while closing chat/settings must not trigger a server command.
    spec_latch,warn_latch=spec_down,warn_down
end
local function checkbox(label_text,key)
    local value=imgui.ImBool(config.main[key])
    if imgui.Checkbox(label_text,value) then
        config.main[key]=value.v
        if key=='enabled' and not value.v then reset() end
        if key=='warn_hotkey' then warn_latch=integration.keys:down('medkit_warn') end
        if key=='spectate_hotkey' then spec_latch=integration.keys:down('medkit_follow') end
        save()
    end
end
integration.drawSettings=function()
    checkbox('Отслеживать сбив анимации аптечки##stopsbiv_enabled','enabled')
    imgui.TextWrapped('После сообщения +HP над игроком проверяет, появилась ли анимация аптечки и завершилась ли она. Подозрения попадают в журнал для проверки в слежке.')
    imgui.Separator()
    checkbox('Показывать подозрения в чате##stopsbiv_chat','notify_chat')
    checkbox('Горячая клавиша слежки##stopsbiv_spec','spectate_hotkey')
    checkbox('Горячая клавиша предупреждения##stopsbiv_warn','warn_hotkey')
    imgui.TextWrapped(integration.keys:name('medkit_warn')..' отправляет /warn после вашей проверки, только после обнаруженного сбива: 10 секунд после перехода в слежку через предложение контроля аптечек. В режиме банд добавляется тег банды; в режиме семей запрашивается название семьи.')
    integration.keys:draw(imgui,'medkit_follow');integration.keys:draw(imgui,'medkit_warn')
    if save_error then imgui.TextWrapped('Не удалось сохранить настройки проверки аптечек. Проверьте доступ к папке настроек MoonLoader.') end
end
integration.draw=function()
    imgui.Text('Проверка аптечек: '..(config.main.enabled and 'включена' or 'выключена'))
    if imgui.Button('Настройки проверки##stopsbiv_settings') then integration.openSettings('stopsbiv') end
    imgui.SameLine()
    if imgui.Button('Очистить журнал##stopsbiv_clear') then history={}; last_suspect=nil end
    if valid(follow) and follow.expires>=now() then
        imgui.Text('Слежка: '..label(follow))
        if imgui.Button('Выдать /warn после проверки##stopsbiv_warn_action') then send_warn() end
    end
    imgui.Separator()
    if #history==0 then imgui.TextWrapped('Журнал пуст. При включённой проверке здесь появятся последние 8 подозрений за текущее подключение.'); return end
    for i,record in ipairs(history) do
        imgui.Text(label(record))
        imgui.SameLine()
        if not record.left and valid(record) and config.main.enabled then
            if imgui.Button('Следить##stopsbiv_row_'..i) then start_follow(record) end
        else imgui.TextDisabled('Слежка недоступна') end
        imgui.TextWrapped(record.reason)
        imgui.Separator()
    end
end
integration.onDisconnect=reset
function integration.start()
    while true do wait(0); step() end
end

    end
    sources["modules/tempfamily.lua"] = function()
local g=require('imgui')
local events=require('lib.samp.events')
local u8=require('encoding').UTF8
local path=integration.storage:path('settings','temporary-family.ini')
local config=integration.storage:loadIni({main={last='',automatic=true},history={}},path)
local input=g.ImBuffer(config.main.last or '',128)
local generation,lastPayday=0,-100000
local loginDone,readyAt=false,nil
local paydayDue,paydayFamily,paydayToken=nil,nil,nil
local paydayResetSeen=false
local RESET_WINDOW=120000
local function normalize(value)
    value=tostring(value or ''):match('^%s*(.-)%s*$')
    if value=='' or value:find('[%z\1-\31]') or #u8:decode('/tempfamily '..value)>144 then return nil end
    return value
end
local function remember(value)
    value=normalize(value);if not value then return false end
    local history={};history['1']=value
    local n=1
    for i=1,30 do
        local old=config.history[tostring(i)] or config.history[i]
        if old and old~=value and n<30 then n=n+1;history[tostring(n)]=old end
    end
    config.history=history;config.main.last=value;input.v=value
    integration.storage:saveIni(config,path);return true
end
local function assign(value)
    if not integration.access:require(3,integration.message) or not normalize(value) then return end
    if remember(value) then sampSendChat(u8:decode('/tempfamily '..config.main.last)) end
end
function events.onSendCommand(command)
    local value=u8(command):match('^/tempfamily%s+(.+)$')
    if value and integration.access:can(3) then remember(value);loginDone=true end
end
function events.onServerMessage(color,text)
    local line=tostring(u8(text)):gsub('{%x+}',''):match('^%s*(.-)%s*$')
    local now=getGameTimer()
    if line:match('^Вы покинули временную семью') then
        -- Keep the payday context after the fallback assignment: reset may arrive later.
        if not paydayResetSeen and paydayToken==generation and now-lastPayday<=RESET_WINDOW
            and config.main.automatic~=false and config.main.last==paydayFamily
            and sampGetGamestate()==3 and integration.access:can(3)then
            paydayResetSeen=true;paydayDue=now+2000
        end
        return
    end
    if line~='БАНКОВСКИЙ ЧЕК' then return end
    if config.main.automatic==false or not normalize(config.main.last) or not integration.access:can(3) then return end
    if now-lastPayday<30000 then return end
    lastPayday=now;paydayResetSeen=false
    paydayDue=now+8000;paydayFamily=config.main.last;paydayToken=generation
end
integration.update=function()
    if paydayDue then
        if paydayToken~=generation or config.main.automatic==false or config.main.last~=paydayFamily
            or sampGetGamestate()~=3 or not integration.access:can(3)then paydayDue=nil
        elseif getGameTimer()>=paydayDue and sampIsLocalPlayerSpawned() and not sampIsDialogActive()then
            local family=paydayFamily;paydayDue=nil;loginDone=true;assign(family)
        end
        return
    end
    if loginDone then return end
    if config.main.automatic==false or not normalize(config.main.last) or not integration.access:can(3)
        or sampGetGamestate()~=3 or not sampIsLocalPlayerSpawned() or sampIsDialogActive()then readyAt=nil;return end
    readyAt=readyAt or getGameTimer()
    if getGameTimer()-readyAt<1500 then return end
    loginDone=true;assign(config.main.last)
end
integration.onAccessChanged=function() generation=generation+1;readyAt=nil end
integration.onDisconnect=function() paydayDue=nil;generation=generation+1;lastPayday=-100000;loginDone=false;readyAt=nil end
integration.draw=function()
    g.PushItemWidth(math.min(360,g.GetContentRegionAvail().x-16))
    g.InputText('Название семьи',input);g.PopItemWidth()
    if g.Button('Назначить##tempfamily') then assign(input.v) end
    local enabled=g.ImBool(config.main.automatic~=false)
    if g.Checkbox('Назначать последнюю семью при входе и каждый Payday',enabled) then
        config.main.automatic=enabled.v;generation=generation+1;integration.storage:saveIni(config,path)
    end
    g.TextWrapped('Последняя семья: '..(config.main.last~='' and config.main.last or 'не выбрана'))
    g.Separator();g.Text('История семей')
    for i=1,30 do
        local name=config.history[tostring(i)] or config.history[i]
        if name and g.Selectable(name..'##family_history_'..i,name==config.main.last) then remember(name) end
    end
end

    end
