-- /msg scope: 0 = standard broadcast, 1 = important broadcast, 20..300 = radius.
local M={}
function M.parse(text)
    text=tostring(text or ''):match('^%s*(.-)%s*$')
    local n=text:match('^%d+$') and tonumber(text)
    if not n or not (n==0 or n==1 or n>=20 and n<=300) then
