    sources["native_fonts.lua"] = function()
local Fonts={}
Fonts.__index=Fonts
local faces={'Segoe UI','Arial','Tahoma'}
function Fonts.new(api,preferences) return setmetatable({api=api,preferences=preferences,entries={}},Fonts) end
function Fonts:create(requested,size,flags,preserveFace)
    local face=preserveFace and requested or faces[self.preferences.data.main.font] or faces[1]
    local font=self.api.renderCreateFont(face,size,flags)
    if font then self.entries[font]={size=size,flags=flags,face=face,current=font,fixed=preserveFace} end
    return font
end
function Fonts:resolve(font)
    local entry=self.entries[font];if not entry then return font end
    local face=entry.fixed and entry.face or faces[self.preferences.data.main.font] or faces[1]
    if entry.face~=face then
        local replacement=self.api.renderCreateFont(face,entry.size,entry.flags)
        if replacement then
            if entry.current~=font then self.api.renderReleaseFont(entry.current) end
            entry.current,entry.face=replacement,face
        end
    end
    return entry.current
end
function Fonts:release(font)
    local entry=self.entries[font]
    if entry and entry.current~=font then self.api.renderReleaseFont(entry.current) end
    self.entries[font]=nil
    return self.api.renderReleaseFont(font)
end
function Fonts:draw(font,text,...)
    local u8=self.api.require('encoding').UTF8
    return self.api.renderFontDrawText(self:resolve(font),u8:decode(self.preferences:mask(tostring(u8(text or '')))),...)
end
function Fonts:width(font,text,...)
    local u8=self.api.require('encoding').UTF8
    return self.api.renderGetFontDrawTextLength(self:resolve(font),u8:decode(self.preferences:mask(tostring(u8(text or '')))),...)
end
function Fonts:height(font,...) return self.api.renderGetFontDrawHeight(self:resolve(font),...) end
return Fonts

    end
    sources["numeric_input.lua"] = function()
-- Keep active edit buffers alive, but publish each edit before the page can close.
local M={}
function M.install(g)
    local state={}
    for _,kind in ipairs({'InputInt','InputFloat'})do
        local original=g[kind]
        g[kind]=function(label,value,...)
            local id=kind..':'..tostring(g.GetID(label)or label)
            local entry=state[id]
            if not entry then
                entry={buffer=kind=='InputInt'and g.ImInt(value.v)or g.ImFloat(value.v)};state[id]=entry
            end
            local frame=g.GetFrameCount and g.GetFrameCount()
            -- A field absent for a frame no longer owns an editing session.
            -- Refresh before drawing, so reopening cannot flash its old draft.
            local reopened=frame and entry.frame and frame>entry.frame+1
            if not entry.active or reopened then entry.buffer.v=value.v end
            entry.frame=frame
            local changed=original(label,entry.buffer,...)
            local active=g.IsItemActive()==true
            entry.active=active
            entry.model=value.v
            if changed then
                value.v=entry.buffer.v;entry.model=value.v;return true
            end
            return false
        end
    end
end
return M

    end
    sources["offban_guard.lua"] = function()
-- Every outgoing /offban is preceded by a /baninfo response.
local Guard={}
Guard.__index=Guard
function Guard.new(rt) return setmetatable({rt=rt,queue={},results={}},Guard) end
function Guard:enqueue(owner,api,command)
    if self.releasing then return false end
    local verb=command:match('^(/%S+)')
    if not verb or verb:lower()~='/offban' then return false end
    local target,days,reason=command:match('^/%S+%s+(%S+)%s+(%d+)%s+(.+)$')
    if not target or #target>32 or tonumber(days)<1 or command:find('[%z\1-\31]') then
        self.results[command]='Неверный формат /offban: укажите ник, положительный срок и причину.'
        self.rt:message(self.results[command]);return true
    end
    self.results[command]=nil
    self.queue[#self.queue+1]={owner=owner,api=api,target=target,days=tonumber(days),reason=reason,
        revision=self.rt.access:revision(),original=command}
    return true
end
function Guard:reset() self.queue={};self.pending=nil;self.releasing=false end
function Guard:cancel(owner)
    for i=#self.queue,1,-1 do if self.queue[i].owner==owner then table.remove(self.queue,i) end end
    if self.pending and self.pending.owner==owner then self.pending=nil;self.cooldown=self.rt.api.os.clock()+11 end
end
function Guard:observe(name,...)
    local p=self.pending;if not p then return end
    local args={...};local u8=self.rt.api.require('encoding').UTF8
    if name=='onShowDialog' then
        local title=tostring(u8(args[3] or '')):gsub('{%x+}',''):match('^%s*(.-)%s*$')
        if args[2]~=0 or title:lower()~=p.target:lower() then return end
        local text=tostring(u8(args[6] or '')):gsub('{%x+}','')
        local days=text:match('дней до конца бана:%s*(%d+)') or text:match('Дней до конца бана:%s*(%d+)')
        if days then p.remaining=tonumber(days);p.dialogId=args[1];return false end
        if text:find('не забанен',1,true) or text:find('не находится в бан',1,true) then p.remaining=0;p.dialogId=args[1];return false end
    elseif name=='onServerMessage' and p.remaining==nil then
        local text=tostring(u8(args[2] or '')):gsub('{%x+}',''):match('^%s*(.-)%s*$')
        if text=='Игрок с таким ником (или номером аккаунта) не найден в банлисте'
            or text=='Игрок с таким ником (или номером аккаунта) не найден в банлисте.' then
            -- This response has no target. It may belong to a timed-out or
            -- manually issued request, so it cannot authorize a punishment.
            p.uncorrelatedReply=true
        end
    end
end
function Guard:update()
    local rt=self.rt;local p=self.pending
    if p then
        if p.revision~=rt.access:revision() or not rt.access:can(1) then self:reset();return end
        if p.remaining~=nil then
            self.pending=nil
            if p.dialogId and rt.api.sampSendDialogResponse then rt.api.sampSendDialogResponse(p.dialogId,0,0,'') end
            if p.remaining>=30 then
                self.results[p.original]='Уже назначено 30 дней или больше; повторная блокировка не отправлена.'
                rt:message(self.results[p.original]);return
            end
            local total=math.min(30,p.remaining+p.days)
            local command=string.format('/offban %s %d %s',p.target,total,p.reason)
            self.releasing=true
            rt:send(p.owner,p.api,self.rt.api.require('encoding').UTF8:decode(command))
            self.releasing=false
        elseif rt.api.os.clock()-p.started>10 then
            self.results[p.original]=p.uncorrelatedReply and 'Ответ /baninfo без ника нельзя связать с игроком; наказание не отправлено.' or 'Нет ответа /baninfo; наказание не отправлено. Повторите запрос.'
            rt:message(self.results[p.original]);self.pending=nil
        end
        return
    end
    if #self.queue==0 or rt.api.sampIsDialogActive() or (self.cooldown and rt.api.os.clock()<self.cooldown) then return end
    p=table.remove(self.queue,1)
    if p.revision~=rt.access:revision() or not rt.access:can(1) then return end
    p.started=rt.api.os.clock();self.pending=p
    rt:send(p.owner,'sampSendChat','/baninfo '..p.target)
end
return Guard

    end
    sources["online_stats.lua"] = function()
-- Calendar ledger: server snapshots replace a day, never accumulate twice.
local Stats={}
local months={'января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'}
function Stats.date(year,month,day)
    year,month,day=tonumber(year),tonumber(month),tonumber(day)
    if not year or not month or not day or year<2000 or year>2100 or month<1 or month>12 or day<1 or day>31 then return end
    local stamp=os.time{year=year,month=month,day=day,hour=12}
    local key=string.format('%04d-%02d-%02d',year,month,day)
    if stamp and os.date('%Y-%m-%d',stamp)==key then return key,stamp end
end
function Stats.timestamp(key)
    if type(key)~='string' then return end
    local year,month,day=key:match('^(%d%d%d%d)%-(%d%d)%-(%d%d)$')
    return select(2,Stats.date(year,month,day))
end
function Stats.shift(key,days)
    local stamp=Stats.timestamp(key)
    if not stamp then return end
    local date=os.date('*t',stamp);date.day=date.day+days
    return os.date('%Y-%m-%d',os.time(date))
end
function Stats.week(key)
    local stamp=Stats.timestamp(key)
    return stamp and Stats.shift(key,-((os.date('*t',stamp).wday+5)%7))
end
function Stats.parse(text)
    text=tostring(text or ''):gsub('{%x+}','')
    if not text:find('Вы позвонили в службу точного времени',1,true) then return end
    local day,name,year=text:match('(%d+)%s+([^%s%d]+)%s+(%d+)%s+г%.')
    local month
    for index,label in ipairs(months) do if name==label then month=index end end
    local date=Stats.date(year,month,day)
    if not date then return nil,'Не распознана дата сервера; статистика не изменена.' end
    local function duration(label)
        local hours,minutes=text:match(label..':%s*(%d+)%s*ч%s*(%d+)%s*мин')
        hours,minutes=tonumber(hours),tonumber(minutes)
        if hours and minutes and minutes<60 and hours*60+minutes<=1440 then return hours*60+minutes end
    end
    local total,afk=duration('Время в игре сегодня'),duration('AFK за сегодня')
    if not total or not afk or afk>total then return nil,'Не распознаны время и AFK за сегодня; статистика не изменена.' end
    local previous,previousAfk=duration('Время в игре вчера'),duration('AFK за вчера')
    return {date=date,today=total-afk,total=total,afk=afk,
        yesterday=previous and previousAfk and previousAfk<=previous and previous-previousAfk or nil}
end
function Stats.summary(days,date)
    local result={daily=tonumber(days[date]) or 0,weekly=0,monthly=0,dayBest=0,weekBest=0,monthBest=0,count=0,total=0}
    local weeks,months={},{}
    for key,value in pairs(days) do
        value=tonumber(value)
        if Stats.timestamp(key) and value and value>=0 and value<=1440 then
            local week,month=Stats.week(key),key:sub(1,7)
            weeks[week]=(weeks[week] or 0)+value;months[month]=(months[month] or 0)+value
            result.count=result.count+1;result.total=result.total+value
            if value>result.dayBest then result.dayBest,result.dayBestDate=value,key end
        end
    end
    result.weekly=weeks[Stats.week(date)] or 0;result.monthly=months[date:sub(1,7)] or 0
    local weekCount=0
    for key,value in pairs(weeks) do
        weekCount=weekCount+1
        if value>result.weekBest then result.weekBest,result.weekBestDate=value,key end
    end
    for key,value in pairs(months) do if value>result.monthBest then result.monthBest,result.monthBestDate=value,key end end
    result.average=result.total/math.max(1,result.count)
    result.weekAverage=result.total/math.max(1,weekCount)
    return result
end
return Stats

    end
    sources["preferences.lua"] = function()
local Preferences={}
Preferences.__index=Preferences
Preferences.colors={{'Фиолетовый',0xC080FF,0x322B4C},{'Голубой',0x40CEFF,0x203B50},
    {'Мятный',0x35F4B3,0x203E37},{'Розовый',0xFF70BD,0x4A2B3B},{'Янтарный',0xFFD04A,0x493D29},
    {'Красный',0xFF4F70,0x4B2530}}

local function finite(value,fallback)
    local number=tonumber(value)
    if not number or number~=number or number==math.huge or number==-math.huge then return fallback end
    return number
end

local function boolean(value,fallback)
    if value==true or value==1 or value=='true' then return true end
    if value==false or value==0 or value=='false' then return false end
    return fallback
end

function Preferences:validate()
    self.data=type(self.data)=='table' and self.data or {}
    self.data.main=type(self.data.main)=='table' and self.data.main or {}
    local p=self.data.main
    p.color=math.max(1,math.min(#Preferences.colors,math.floor(finite(p.color,1))))
    p.font=math.max(1,math.min(11,math.floor(finite(p.font,1))))
    p.fishEyeAngle=math.max(30,math.min(150,math.floor(finite(p.fishEyeAngle,101))))
    p.scale=1 -- Migrate old interface zoom to the single supported size.
    p.timezoneEnabled=boolean(p.timezoneEnabled,false)
    p.timezoneMskOffset=math.max(-15,math.min(11,math.floor(finite(p.timezoneMskOffset,0))))
    p.compactSidebar=boolean(p.compactSidebar,false)
    p.wallpaper=boolean(p.wallpaper,true)
    p.motion=boolean(p.motion,true)
    p.windowManual=boolean(p.windowManual,false)
    for _,name in ipairs({'windowWidth','windowHeight','windowX','windowY'}) do
        -- Zero means initial placement/size; the workspace clamps to the actual screen.
        p[name]=math.max(0,math.min(32768,math.floor(finite(p[name],0))))
    end
    for _,name in ipairs({'streamer','ghetto','families','roadFollowup','legoReplace','antiBH','matrixJump','backFlip','fishEye','spectateChatN','invisibleOnStart'}) do p[name]=boolean(p[name],false) end
    for _,name in ipairs({'killidsKiller','killidsVictim'}) do p[name]=boolean(p[name],true) end
    if p.medkitMode~='ghetto' and p.medkitMode~='families' then p.medkitMode='none' end
    return p
end

function Preferences.new(storage)
    local path=storage:path('settings','interface.ini')
    local defaults={main={color=1,font=1,scale=1,compactSidebar=false,wallpaper=true,motion=true,
        windowWidth=0,windowHeight=0,windowX=0,windowY=0,windowManual=false,
        streamer=false,ghetto=false,families=false,medkitMode='none',killidsKiller=true,killidsVictim=true}}
    local ok,data=pcall(storage.loadIni,storage,defaults,path)
    local recovery
    if not ok then
        local backupOk,backup=pcall(function()
            assert(storage:exists(path..'.bak'),'No backup')
            return storage:loadIni(defaults,path..'.bak')
        end)
        data=backupOk and backup or defaults
        recovery=backupOk and 'Настройки интерфейса восстановлены из резервной копии.'
            or 'Настройки интерфейса повреждены. Используется стандартное оформление.'
    end
    local self=setmetatable({storage=storage,path=path,data=data},Preferences)
    self:validate()
    if recovery then
        self.recoveryPending=true;self.recoveryNotice=recovery
        if not self:save() then self.recoveryNotice=recovery..' Сохранение недоступно; исходные файлы не перезаписаны.' end
    end
    return self
end
function Preferences:save()
    self:validate()
    if self.recoveryPending then
        local ok,saved=pcall(function()
            -- Preserve both original inputs before saveIni rotates .bak.
            for _,source in ipairs({self.path,self.path..'.bak'})do
                if self.storage:exists(source)then
                    local bytes=assert(self.storage:read(source),'Cannot preserve damaged settings')
                    local archive
                    for i=1,1000 do
                        local candidate=source..'.damaged.'..i
                        if not self.storage:exists(candidate)then archive=candidate;break end
                    end
                    assert(archive,'Too many recovery archives')
                    assert(self.storage:write(archive,bytes),'Cannot archive settings')
                end
            end
            return self.storage:saveIni(self.data,self.path)
        end)
        if not ok or not saved then return false end
        self.recoveryPending=false
        return true
    end
    return self.storage:saveIni(self.data,self.path)
end
function Preferences:mask(text)
    if not self.data.main.streamer or type(text)~='string' then return text end
    -- Presentation only: raw protocol messages and data stay available to parsers.
    return (text:gsub('%d+%.%d+%.%d+%.%d+', '[IP скрыт]'))
end
return Preferences

    end
    sources["queue_confirmation.lua"] = function()
-- Match a server punishment announcement, never a quoted chat line.
local M={}
local actions={ban={'забанил игрока','забанил оффлайн игрока'},offban={'забанил оффлайн игрока','забанил игрока'},
 jail={'посадил в тюрьму игрока','посадил в тюрьму','посадил игрока','посадил в КПЗ игрока'},
 mute={'поставил затычку игроку','выдал затычку игроку'},warn={'выдал предупреждение игроку'},kick={'кикнул игрока'}}
actions.offjail=actions.jail;actions.offmute=actions.mute;actions.offwarn=actions.warn
local function trim(s)return (s:match('^%s*(.-)%s*$'))end
function M.match(command,text,target,actor)
    local kind,_,args=command:match('^/(%S+)%s+(%S+)%s*(.*)$')
    if not kind or not target or not actor then return false end
    kind=kind:lower();local verbs=actions[kind];if not verbs then return false end
    text=trim(text:gsub('{%x%x%x%x%x%x}',''))
    local issuer,body=text:match('^%[A%]%s+([%w_]+)%[%d+%]%s+(.+)$')
    if not issuer then issuer,body=text:match('^Администратор%s+([%w_]+)%[%d+%]%s+(.+)$')end
    if not issuer then issuer,body=text:match('^Администратор%s+([%w_]+)%s+(.+)$')end
    if not issuer or issuer:lower()~=actor:lower()then return false end
    for _,verb in ipairs(verbs)do
        if body:sub(1,#verb+1)==verb..' 'then
            local tail=body:sub(#verb+2)
            local nick,rest=tail:match('^([%w_]+)(.*)$')
            if nick and nick:lower()==target:lower()then
                rest=rest:gsub('^%[%d+%]','')
                if rest~='' and not rest:match('^[%s%.,:]')then return false end
                local reason=args
                if kind~='kick' and kind~='warn' and kind~='offwarn' then
                    local amount;amount,reason=args:match('^(%d+)%s+(.+)$')
                    local actual=rest:match('на%s+(%d+)')
                    -- /offban adds the existing ban duration before sending.
                    if kind~='offban' and amount and actual and tonumber(amount)~=tonumber(actual)then return false end
                end
                local reported=rest:match('[Пп]ричина:%s*(.+)$')
                if reported and reason and trim(reported):gsub('[.]$','')~=trim(reason):gsub('[.]$','')then return false end
                return true
            end
        end
    end
    return false
end
return M

    end
