    sources["sha256.lua"] = function()
-- SHA-256 over byte strings. LuaJIT bit operations; no external hashing package.
local bit = require 'bit'
local band, bxor, bnot, rshift, ror = bit.band, bit.bxor, bit.bnot, bit.rshift, bit.ror
local constants = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
}
local function word(n)
    return string.char(band(rshift(n,24),255),band(rshift(n,16),255),band(rshift(n,8),255),band(n,255))
end
return function(bytes, yield)
    local length=#bytes
    bytes=bytes..'\128'..string.rep('\0',(55-length)%64)..word(math.floor(length/536870912))..word(length*8)
    local hash={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}
    local words={}
    for offset=1,#bytes,64 do
        if yield and offset % 65536 == 1 then yield(0) end
        for i=0,15 do
            local a,b,c,d=bytes:byte(offset+i*4,offset+i*4+3)
            words[i]=bit.tobit(((a*256+b)*256+c)*256+d)
        end
        for i=16,63 do
            local x,y=words[i-15],words[i-2]
            words[i]=bit.tobit(words[i-16]+bxor(ror(x,7),ror(x,18),rshift(x,3))+words[i-7]+bxor(ror(y,17),ror(y,19),rshift(y,10)))
        end
        local a,b,c,d,e,f,g,h=unpack(hash)
        for i=0,63 do
            local first=bit.tobit(h+bxor(ror(e,6),ror(e,11),ror(e,25))+bxor(band(e,f),band(bnot(e),g))+constants[i+1]+words[i])
            local second=bit.tobit(bxor(ror(a,2),ror(a,13),ror(a,22))+bxor(band(a,b),band(a,c),band(b,c)))
            h,g,f,e,d,c,b,a=g,f,e,bit.tobit(d+first),c,b,a,bit.tobit(first+second)
        end
        local final={a,b,c,d,e,f,g,h}
        for i=1,8 do hash[i]=bit.tobit(hash[i]+final[i]) end
    end
    local result={}
    for i=1,8 do result[i]=bit.tohex(hash[i]) end
    return table.concat(result)
end

    end
    sources["storage.lua"] = function()
-- One filesystem boundary for CasualTool. Legacy files are copied, never modified.
local Storage = {}
Storage.__index = Storage
local kinds = {settings=true, data=true, cache=true, logs=true}
local function normal(path)
    return tostring(path or ''):gsub('\\','/'):gsub('/+','/'):gsub('/$','')
end
local function relative(path)
    path = normal(path)
    assert(path ~= '' and not path:match('^/') and not path:find(':',1,true)
        and not path:find('%z'), 'Invalid CasualTool relative path')
    for part in path:gmatch('[^/]+') do
        assert(part ~= '.' and part ~= '..', 'Path traversal is not allowed')
    end
    return path
end
local function clone(value)
    if type(value) ~= 'table' then return value end
    local result = {}; for key,item in pairs(value) do result[key] = clone(item) end
    return result
end
local function sorted(value)
    local keys={}; for key in pairs(value) do keys[#keys+1]=key end
    table.sort(keys,function(a,b) return tostring(a)<tostring(b) end)
    return keys
end
local function quote(value)
    return '"'..value:gsub('[%z\1-\31\\"]',function(c)
        if c=='\\' or c=='"' then return '\\'..c end
        return string.format('\\%03d',c:byte())
    end)..'"'
end
local function unquote(value)
    assert(value:sub(1,1)=='"' and value:sub(-1)=='"', 'Expected quoted INI string')
    local result,index={},2
    while index<#value do
        local char=value:sub(index,index)
        if char=='\\' then
            local digits=value:sub(index+1):match('^(%d%d?%d?)')
            if digits then
                local number=tonumber(digits); assert(number<=255,'Invalid INI byte escape')
                result[#result+1]=string.char(number); index=index+1+#digits
            else
                local escape=value:sub(index+1,index+1)
                assert(escape=='\\' or escape=='"','Invalid INI escape')
                result[#result+1]=escape; index=index+2
            end
        else result[#result+1]=char; index=index+1 end
    end
    return table.concat(result)
end

function Storage.new(api, root)
    api = api or _G
    local self = setmetatable({api=api, io=api.io or io, os=api.os or os,
        root=normal(root)..'/config/CasualTool', errors={}, serial=0},Storage)
    local config=normal(root)..'/config'
    if api.doesDirectoryExist and not api.doesDirectoryExist(config) and api.createDirectory then
        local ok,err=pcall(api.createDirectory,config)
        if not ok or not api.doesDirectoryExist(config) then
            error('CasualTool storage: Cannot create config directory: '..tostring(err))
        end
    end
    self:ensure(self.root)
    for kind in pairs(kinds) do self:ensure(self.root..'/'..kind) end
    return self
end

function Storage:problem(message)
    message = 'CasualTool storage: '..tostring(message)
    self.errors[#self.errors+1] = message
    if #self.errors>100 then table.remove(self.errors,1) end
    if self.api.storageError then self.api.storageError(message)
    elseif self.api.print then self.api.print(message) end
    return nil,message
end

function Storage:owns(path)
    path=normal(path)
    local folded,root=path:lower(),self.root:lower()
    if folded~=root and folded:sub(1,#root+1)~=root..'/' then return false end
    for part in path:gmatch('[^/]+') do if part=='.' or part=='..' then return false end end
    return not path:find('%z')
end

function Storage:ensure(path)
    path=normal(path)
    assert(self:owns(path), 'Directory outside CasualTool storage: '..path)
    local parent=path:match('^(.*)/[^/]+$')
    if parent and self:owns(parent) then self:ensure(parent) end
    if self.api.doesDirectoryExist and self.api.doesDirectoryExist(path) then return path end
    if self.api.createDirectory then
        local ok,err=pcall(self.api.createDirectory,path)
        if not ok or (self.api.doesDirectoryExist and not self.api.doesDirectoryExist(path)) then
            error(select(2,self:problem('Cannot create directory '..path..': '..tostring(err))))
        end
    else
        local lfs=self:lfs()
        if lfs.attributes(path,'mode')~='directory' then
            local ok,err=lfs.mkdir(path)
            if not ok then error(select(2,self:problem('Cannot create directory '..path..': '..tostring(err)))) end
        end
    end
    return path
end

function Storage:lfs()
    if self._lfs then return self._lfs end
    local ok,lib=pcall(self.api.require or require,'lfs')
    if not ok then error(select(2,self:problem('Directory migration requires lfs: '..tostring(lib)))) end
    self._lfs=lib; return lib
end

function Storage:directory(kind, name)
    assert(kinds[kind], 'Unknown CasualTool storage kind')
    return self:ensure(self.root..'/'..kind..(name and '/'..relative(name) or ''))
end

function Storage:read(path)
    if self:owns(path) then self:recover(normal(path)) end
    local file,err=self.io.open(normal(path),'rb')
    if not file then return nil,err end
    local data,reason=file:read('*a')
    local closed,closeError=file:close()
    if not data or closed==nil or closed==false then return nil,reason or closeError or 'Cannot read file' end
    return data
end

function Storage:recover(path)
    if not self:exists(path) and self:exists(path..'.previous') then
        local ok,err=self.os.rename(path..'.previous',path)
        if not ok then error(select(2,self:problem('Cannot recover interrupted save '..path..': '..tostring(err)))) end
    end
end

function Storage:exists(path)
    if self.api.doesFileExist then return self.api.doesFileExist(normal(path)) end
    local file=self.io.open(normal(path),'rb'); if file then file:close(); return true end
    return false
end

function Storage:rawWrite(path, text)
    local file,err=self.io.open(path,'wb')
    if not file then return nil,err end
    local written,reason=file:write(text)
    local closed,closeError=file:close()
    if not written or not closed then return nil,reason or closeError or 'Cannot finish writing file' end
    local actual,readError=self:read(path)
    if actual~=text then return nil,readError or 'Written bytes failed verification' end
    return true
end

function Storage:write(path, text)
    path=normal(path)
    if not self:owns(path) then return self:problem('Write outside shared directory refused: '..path) end
    if type(text)~='string' then return self:problem('Expected bytes for '..path) end
    self:recover(path)
    self:ensure(path:match('^(.*)/[^/]+$'))
    self.serial=self.serial+1
    local temporary=path..'.tmp.'..self.serial
    local ok,err=self:rawWrite(temporary,text)
    if not ok then return self:problem('Cannot prepare '..path..': '..tostring(err)) end
    local existed=self:exists(path)
    local previous=path..'.previous'
    if existed then
        local old,readError=self:read(path)
        if old==nil then return self:problem('Cannot preserve '..path..': '..tostring(readError)) end
        ok,err=self:rawWrite(path..'.bak',old)
        if not ok then return self:problem('Cannot back up '..path..': '..tostring(err)) end
        if self:exists(previous) then
            ok,err=self.os.remove(previous)
            if not ok then return self:problem('Cannot remove previous transaction '..previous..': '..tostring(err)) end
        end
        ok,err=self.os.rename(path,previous)
        if not ok then return self:problem('Cannot replace '..path..': '..tostring(err)) end
    end
    ok,err=self.os.rename(temporary,path)
    if not ok then
        if existed then
            local restored,restoreError=self.os.rename(previous,path)
            if not restored then return self:problem('Commit and rollback failed for '..path..'; backup: '..path..'.bak; '..tostring(restoreError)) end
        end
        return self:problem('Cannot commit '..path..': '..tostring(err))
    end
    if self:read(path)~=text then
        self.os.remove(path)
        if existed then self.os.rename(previous,path) end
        return self:problem('Final verification failed for '..path..'; previous data retained in .bak')
    end
    if existed then self.os.remove(previous) end
    return true
end

function Storage:append(path, text)
    path=normal(path)
    if not self:owns(path) then return self:problem('Append outside shared directory refused: '..path) end
    self:ensure(path:match('^(.*)/[^/]+$'))
    local file,err=self.io.open(path,'ab')
    if not file then return self:problem('Cannot open log '..path..': '..tostring(err)) end
    local ok,reason=file:write(text)
    local closed,closeError=file:close()
    if not ok or not closed then return self:problem('Cannot append '..path..': '..tostring(reason or closeError)) end
    return true
end

function Storage:remove(path)
    path=normal(path)
    if not self:owns(path) or path:lower()==self.root:lower() then
        return self:problem('Removal outside shared files refused: '..path)
    end
    local ok,err=self.os.remove(path)
    if not ok and self:exists(path) then return self:problem('Cannot remove '..path..': '..tostring(err)) end
    return ok,err
end

function Storage:rename(source, destination)
    source,destination=normal(source),normal(destination)
    if not self:owns(source) or not self:owns(destination)
        or source:lower()==self.root:lower() or destination:lower()==self.root:lower() then
        return self:problem('Rename outside shared files refused')
    end
    self:ensure(destination:match('^(.*)/[^/]+$'))
    local ok,err=self.os.rename(source,destination)
    if not ok then return self:problem('Cannot rename '..source..': '..tostring(err)) end
    return true
end

function Storage:open(path, mode)
    path,mode=normal(path),mode or 'r'
    if not mode:find('[wa+]') then return self.io.open(path,mode) end
    if not self:owns(path) then return self:problem('Write outside shared directory refused: '..path) end
    if mode:find('+',1,true) then return self:problem('Read/write streams are unsupported: '..path) end
    local owner,parts,closed=self,{},false
    local writer={}
    function writer:write(...)
        if closed then return nil,'File is closed' end
        for i=1,select('#',...) do
            local value=select(i,...)
            if type(value)~='string' and type(value)~='number' then return nil,'Expected a string or number' end
            parts[#parts+1]=tostring(value)
        end
        return self
    end
    function writer:flush()
        if closed then return nil,'File is closed' end
        -- A transaction is committed only by close; retaining bytes prevents partial settings.
        return true
    end
    function writer:close()
        if closed then return nil,'File is closed' end
        closed=true
        if mode:find('a',1,true) then return owner:append(path,table.concat(parts)) end
        return owner:write(path,table.concat(parts))
    end
    return writer
end

function Storage:path(kind, name, legacy)
    assert(kinds[kind], 'Unknown CasualTool storage kind')
    local path=self.root..'/'..kind..'/'..relative(name)
    self:ensure(path:match('^(.*)/[^/]+$'))
    self:recover(path)
    if not legacy or #legacy==0 or self:exists(path..'.migration') then return path end
    if self:exists(path) then
        assert(self:write(path..'.migration','Existing CasualTool file retained.\n'))
        return path
    end
    for _,source in ipairs(legacy) do
        source=normal(source)
        if self:exists(source) then
            local bytes,err=self:read(source)
            if bytes==nil then error(select(2,self:problem('Cannot import '..source..': '..tostring(err)))) end
            assert(self:write(path..'.imported.bak',bytes))
            assert(self:write(path,bytes))
            assert(self:write(path..'.migration','Copied from '..source..'\n'))
            return path
        end
    end
    return path
end

function Storage:migrateTree(kind, name, legacyDirectory)
    local destination=self:directory(kind,name)
    legacyDirectory=normal(legacyDirectory)
    if self.api.doesDirectoryExist and not self.api.doesDirectoryExist(legacyDirectory) then return destination end
    local lfs=self:lfs()
    if lfs.attributes(legacyDirectory,'mode')~='directory' then return destination end
    local function visit(source, suffix)
        for entry in lfs.dir(source) do
            if entry~='.' and entry~='..' then
                local input,part=source..'/'..entry,suffix=='' and entry or suffix..'/'..entry
                local mode=lfs.symlinkattributes(input,'mode')
                if mode=='directory' then visit(input,part)
                elseif mode=='file' then self:path(kind,name..'/'..part,{input})
                elseif mode=='link' then self:problem('Skipped linked legacy path '..input) end
            end
        end
    end
    visit(legacyDirectory,'')
    return destination
end

-- The two inherited Lua configuration formats contain only literal tables. Parse those
-- literals without executing Lua, so even a malformed config cannot run code or hang.
function Storage:loadTable(path)
    local source,reason=self:read(path)
    if source==nil then
        if self:exists(path) then error(select(2,self:problem('Cannot load '..path..': '..tostring(reason)))) end
        return nil
    end
    local function parse()
        assert(#source<=4*1024*1024,'Table file exceeds 4 MB')
        source=source:gsub('^\239\187\191','')
        local index,nodes=1,0
        local function whitespace()
            while true do
                local _,finish=source:find('^%s+',index)
                if finish then index=finish+1 end
                if source:sub(index,index+1)~='--' then return end
                if source:sub(index+2,index+3)=='[[' then
                    local stop=source:find(']]',index+4,true)
                    assert(stop,'Unterminated comment'); index=stop+2
                else index=(source:find('\n',index+2,true) or #source)+1 end
            end
        end
        local function expect(symbol)
            whitespace(); assert(source:sub(index,index+#symbol-1)==symbol,'Expected '..symbol)
            index=index+#symbol
        end
        local function stringValue()
            local quoteChar=source:sub(index,index); index=index+1
            local parts={}
            while index<=#source do
                local char=source:sub(index,index); index=index+1
                if char==quoteChar then return table.concat(parts) end
                if char=='\\' then
                    local escaped=source:sub(index,index)
                    local digits=source:sub(index):match('^(%d%d?%d?)')
                    if digits then
                        local number=tonumber(digits); assert(number<=255,'Invalid string byte escape')
                        parts[#parts+1]=string.char(number); index=index+#digits
                    elseif escaped=='x' then
                        local hex=source:sub(index+1,index+2)
                        assert(hex:match('^%x%x$'),'Invalid hexadecimal escape')
                        parts[#parts+1]=string.char(tonumber(hex,16)); index=index+3
                    else
                        local escapes={a='\7',b='\8',f='\12',n='\n',r='\r',t='\t',v='\11',
                            ['\\']='\\',['"']='"',["'"]="'",['\n']='\n',['\r']='\n'}
                        assert(escapes[escaped],'Invalid string escape')
                        parts[#parts+1]=escapes[escaped]; index=index+1
                        if escaped=='\r' and source:sub(index,index)=='\n' then index=index+1 end
                    end
                else
                    assert(char~='\n' and char~='\r','Unescaped newline in string')
                    parts[#parts+1]=char
                end
            end
            error('Unterminated string')
        end
        local value
        value=function(depth)
            whitespace(); nodes=nodes+1
            assert(depth<=32 and nodes<=100000,'Table complexity limit exceeded')
            local char=source:sub(index,index)
            if char=='"' or char=="'" then return stringValue() end
            if char=='{' then
                index=index+1; local result,arrayIndex={},1
                while true do
                    whitespace()
                    if source:sub(index,index)=='}' then index=index+1; return result end
                    local key,item
                    if source:sub(index,index)=='[' then
                        index=index+1; key=value(depth+1)
                        assert(type(key)=='string' or type(key)=='number' or type(key)=='boolean','Invalid table key')
                        expect(']'); expect('='); item=value(depth+1)
                    else
                        local name=source:sub(index):match('^([%a_][%w_]*)%s*=')
                        if name then
                            index=index+#name; expect('='); key,item=name,value(depth+1)
                        else key,item=arrayIndex,value(depth+1); arrayIndex=arrayIndex+1 end
                    end
                    result[key]=item; whitespace()
                    local nextChar=source:sub(index,index)
                    if nextChar==',' or nextChar==';' then index=index+1
                    elseif nextChar~='}' then error('Expected table separator') end
                end
            end
            local word=source:sub(index):match('^([%a_][%w_]*)')
            if word then
                index=index+#word
                if word=='true' then return true elseif word=='false' then return false
                elseif word=='nil' then return nil end
                error('Only literal table values are allowed')
            end
            local token=source:sub(index):match('^([+-]?0[xX]%x+)')
                or source:sub(index):match('^([+-]?%d*%.?%d+[eE][+-]?%d+)')
                or source:sub(index):match('^([+-]?%d*%.?%d+)')
            assert(token,'Expected literal value')
            local number=tonumber(token)
            assert(number and number==number and math.abs(number)<math.huge,'Invalid number')
            index=index+#token; return number
        end
        whitespace()
        assert(source:sub(index):match('^return[%s{]'),'Expected return table')
        index=index+6
        local result=value(1); assert(type(result)=='table','Expected table')
        whitespace(); assert(index>#source,'Unexpected code after table')
        return result
    end
    local ok,result=pcall(parse)
    if not ok then error(select(2,self:problem('Invalid table settings in '..path..': '..tostring(result)))) end
    return result
end

-- INI scalar types are inferred from defaults. This preserves numeric-looking passwords,
-- quoted text and both UTF-8/CP1251 bytes instead of coercing every value to a number.
function Storage:loadIni(defaults, path)
    local result=clone(defaults or {})
    local text,err=self:read(path)
    if not text then
        if self:exists(path) then error(select(2,self:problem('Cannot load settings '..path..': '..tostring(err)))) end
        return result
    end
    text=text:gsub('^\239\187\191','')
    local quotedFormat=text:match('^; CasualTool INI v1\r?\n')~=nil
    local section
    for line in (text..'\n'):gmatch('(.-)\n') do
        line=line:gsub('\r$','')
        if line:match('^%s*[^;#%s]') then
            local heading=line:match('^%s*%[([^%]]+)%]%s*$')
            if heading then
                section=heading; result[section]=type(result[section])=='table' and result[section] or {}
            else
                local key,value=line:match('^%s*([^=]+)%s*=(.*)$')
                if not key or not section then error(select(2,self:problem('Invalid INI structure in '..path))) end
                key=key:match('^%s*(.-)%s*$')
                value=value:match('^%s*(.-)%s*$')
                local default=defaults and defaults[section] and defaults[section][key]
                if quotedFormat and value:sub(1,1)=='"' then
                    local ok,decoded=pcall(unquote,value)
                    if not ok then error(select(2,self:problem('Invalid quoted INI value in '..path))) end
                    value=decoded
                elseif type(default)=='number' then value=tonumber(value) or default
                elseif type(default)=='boolean' then
                    if value=='true' or value=='1' then value=true
                    elseif value=='false' or value=='0' then value=false else value=default end
                elseif default==nil then
                    if value=='true' then value=true elseif value=='false' then value=false
                    else value=tonumber(value) or value end
                end
                result[section][key]=value
            end
        end
    end
    return result
end

function Storage:saveIni(values, path)
    local lines={'; CasualTool INI v1'}
    for _,section in ipairs(sorted(values)) do
        if type(values[section])~='table' or tostring(section):find('[\r\n%[%]]') then
            return self:problem('Invalid INI section for '..path)
        end
        lines[#lines+1]='['..section..']'
        for _,key in ipairs(sorted(values[section])) do
            local value=values[section][key]
            if (type(value)~='string' and type(value)~='number' and type(value)~='boolean')
                or tostring(key):find('[\r\n=]') then
                return self:problem('Invalid INI value in '..path..' ['..section..'] '..tostring(key))
            end
            lines[#lines+1]=key..'='..(type(value)=='string' and quote(value) or tostring(value))
        end
        lines[#lines+1]=''
    end
    return self:write(path,table.concat(lines,'\n'))
end

return Storage

    end
