    sources["sync_packets.lua"] = function()
-- Bounded native buffers shared by the imported spectator and click-warp features.
local M={}
function M.new(a)
    local function buffer(fn)
        local p=a.allocateMemory(68)
        assert(p and p~=0,'Не удалось выделить пакет синхронизации')
        local ok,err=pcall(function()
            for offset=0,64,4 do a.setStructElement(p,offset,4,0,false) end
            fn(p)
        end)
        a.freeMemory(p)
        if not ok then error(err) end
    end
    local function valid(x)return type(x)=='number' and x==x and math.abs(x)<100000 end
    return {
        spectator=function(x,y,z)
            assert(valid(x) and valid(y) and valid(z),'Некорректная позиция')
            buffer(function(p)
                a.setStructElement(p,4,2,1024,false)
                a.setStructFloatElement(p,6,x,false);a.setStructFloatElement(p,10,y,false);a.setStructFloatElement(p,14,z,false)
                a.sampSendSpectatorData(p)
            end)
        end,
        onfoot=function(x,y,z)
            local found,id=a.sampGetPlayerIdByCharHandle(a.PLAYER_PED)
            if not found then return false end
            if x~=nil then assert(valid(x) and valid(y) and valid(z),'Некорректная позиция')end
            buffer(function(p)
                a.sampStorePlayerOnfootData(id,p)
                if x~=nil then
                    a.setStructFloatElement(p,6,x,false);a.setStructFloatElement(p,10,y,false);a.setStructFloatElement(p,14,z,false)
                end
                a.sampSendOnfootData(p)
            end)
            return true
        end
    }
end
return M

    end
    sources["theme.lua"] = function()
-- One compact theme for every window in the shared MoonImGui context.
local Theme = {}
Theme.palette = {
    bg = 0x10101B, sidebar = 0x211A35, surface = 0x191827, button = 0x242238, hover = 0x34304E,
    border = 0x514865, text = 0xF0EDF8, muted = 0xABA5BF,
    accent = 0xB49AFF, selection = 0x453766, green = 0x62D6AF,
    amber = 0xF2C47D, danger = 0xFF687D, track = 0x343746
}
Theme.sizes={sidebar=176,sidebarCompact=60,outerPadding=16,panelPadding=12,
    gap=8,columnGap=16,rowGap=4,controlMinHeight=32,iconHitSize=28,rounding=5,scrollBar=10}
local savedStyles=setmetatable({},{__mode='k'})
local function blend(base,accent,amount)
    local result=0
    for _,factor in ipairs({65536,256,1}) do
        local a=math.floor(base/factor)%256
        local b=math.floor(accent/factor)%256
        result=result+math.floor(a+(b-a)*amount+0.5)*factor
    end
    return result
end
function Theme.apply(accent)
    local p=Theme.palette
    p.accent=accent
    for name,spec in pairs({bg={0x08090D,0.06},sidebar={0x101117,0.16},
        surface={0x121319,0.09},button={0x171820,0.17},hover={0x20212A,0.34},
        selection={0x171820,0.40},border={0x32333C,0.38},track={0x20212A,0.17},
        text={0xF5F5F7,0.07},muted={0xAAAAB4,0.12}}) do
        p[name]=blend(spec[1],accent,spec[2])
    end
end
function Theme.color(imgui, hex)
    return imgui.ImVec4(math.floor(hex / 65536) % 256 / 255,
        math.floor(hex / 256) % 256 / 255, hex % 256 / 255, 1)
end
function Theme.push(imgui,scale)
    scale=tonumber(scale) or 1
    if scale~=1 and scale~=1.25 and scale~=1.5 then scale=1 end
    local p, count, vars = Theme.palette, 0, 0
    local colors = {WindowBg=p.bg, ChildWindowBg=p.surface, PopupBg=p.surface,
        Border=p.border, Text=p.text, TextDisabled=p.muted, FrameBg=p.button,
        FrameBgHovered=p.hover, FrameBgActive=p.selection, Button=p.button,
        ButtonHovered=p.hover, ButtonActive=p.selection, Header=p.selection,
        HeaderHovered=p.hover, HeaderActive=p.selection, CheckMark=p.accent,
        SliderGrab=p.accent, SliderGrabActive=p.accent, TitleBg=p.bg,
        TitleBgActive=p.surface, ScrollbarBg=p.bg, ScrollbarGrab=p.accent,
        ScrollbarGrabHovered=p.accent, ScrollbarGrabActive=p.accent,
        Separator=p.border, SeparatorHovered=p.accent, SeparatorActive=p.accent,
        ResizeGrip=p.border, ResizeGripHovered=p.accent, ResizeGripActive=p.accent,
        TextSelectedBg=p.selection, ComboBg=p.surface}
    for name, hex in pairs(colors) do
        if imgui.Col[name] then imgui.PushStyleColor(imgui.Col[name], Theme.color(imgui, hex)); count=count+1 end
    end
    -- 16px body + 8px padding above/below = 32px minimum field height.
    local values = {WindowPadding=imgui.ImVec2(12*scale,12*scale),
        FramePadding=imgui.ImVec2(8*scale,8*scale),
        ItemSpacing=imgui.ImVec2(8*scale,4*scale),ItemInnerSpacing=imgui.ImVec2(6*scale,4*scale),
        WindowRounding=5*scale,ChildWindowRounding=5*scale,FrameRounding=5*scale,
        IndentSpacing=16*scale,GrabMinSize=12*scale}
    for name, value in pairs(values) do
        if imgui.StyleVar[name] then imgui.PushStyleVar(imgui.StyleVar[name],value); vars=vars+1 end
    end
    -- MoonImGui 1.1.2 does not expose these fields in StyleVar. Restore them
    -- explicitly at pop rather than silently leaving the old unscaled values.
    local manual={}
    local style=imgui.GetStyle and imgui.GetStyle()
    if style then
        for name,value in pairs({ScrollbarSize=10*scale,ScrollbarRounding=5*scale,GrabRounding=5*scale}) do
            local ok,previous=pcall(function() return style[name] end)
            if ok and type(previous)=='number' then
                local changed=pcall(function() style[name]=value end)
                if changed then manual[#manual+1]={name,previous} end
            end
        end
    end
    local stack=savedStyles[imgui] or {};savedStyles[imgui]=stack
    stack[#stack+1]={style=style,values=manual}
    return count, vars
end
function Theme.pop(imgui, colors, vars)
    imgui.PopStyleVar(vars)
    imgui.PopStyleColor(colors)
    local stack=savedStyles[imgui]
    local previous=stack and table.remove(stack)
    if previous and previous.style then
        for _,field in ipairs(previous.values) do previous.style[field[1]]=field[2] end
    end
end
return Theme

    end
    sources["totp.lua"] = function()
-- RFC 6238 / RFC 4226: SHA-1, 30 seconds, six decimal digits.
local bit=require('bit')
local M={}
local function word(n) return string.char(bit.band(bit.rshift(n,24),255),bit.band(bit.rshift(n,16),255),bit.band(bit.rshift(n,8),255),bit.band(n,255)) end
local function sha1(message)
    local length=#message
    message=message..'\128'..string.rep('\0',(55-length)%64)..word(math.floor(length/536870912))..word(length*8)
    local h={0x67452301,0xEFCDAB89,0x98BADCFE,0x10325476,0xC3D2E1F0}
    for offset=1,#message,64 do
        local w={}
        for i=0,15 do local a,b,c,d=message:byte(offset+i*4,offset+i*4+3);w[i]=bit.tobit(a*16777216+b*65536+c*256+d) end
        for i=16,79 do w[i]=bit.rol(bit.bxor(w[i-3],w[i-8],w[i-14],w[i-16]),1) end
        local a,b,c,d,e=unpack(h)
        for i=0,79 do
            local f,k
            if i<20 then f=bit.bor(bit.band(b,c),bit.band(bit.bnot(b),d));k=0x5A827999
            elseif i<40 then f=bit.bxor(b,c,d);k=0x6ED9EBA1
            elseif i<60 then f=bit.bor(bit.band(b,c),bit.band(b,d),bit.band(c,d));k=0x8F1BBCDC
            else f=bit.bxor(b,c,d);k=0xCA62C1D6 end
            local nextA=bit.tobit(bit.rol(a,5)+f+e+k+w[i])
            e,d,c,b,a=d,c,bit.rol(b,30),a,nextA
        end
        h[1],h[2],h[3],h[4],h[5]=bit.tobit(h[1]+a),bit.tobit(h[2]+b),bit.tobit(h[3]+c),bit.tobit(h[4]+d),bit.tobit(h[5]+e)
    end
    return word(h[1])..word(h[2])..word(h[3])..word(h[4])..word(h[5])
end
function M.normalize(secret)
    local value=tostring(secret or ''):upper():gsub('%s',''):gsub('%-',''):gsub('=+$','')
    if #value<16 or #value>128 or value:find('[^A-Z2-7]') then return nil end
    return value
end
function M.decode(secret)
    secret=M.normalize(secret);if not secret then return nil end
    local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
    local out,buffer,bits={},0,0
    for i=1,#secret do
        buffer=buffer*32+(alphabet:find(secret:sub(i,i),1,true)-1);bits=bits+5
        if bits>=8 then bits=bits-8;out[#out+1]=string.char(math.floor(buffer/2^bits));buffer=buffer%2^bits end
    end
    return table.concat(out)
end
function M.code(secret,time,digits)
    local key=M.decode(secret);if not key then return nil end
    local counter=math.floor((tonumber(time) or os.time())/30)
    local msg=word(math.floor(counter/4294967296))..word(counter%4294967296)
    if #key>64 then key=sha1(key) end
    key=key..string.rep('\0',64-#key)
    local inner,outer={},{}
    for i=1,64 do inner[i]=string.char(bit.bxor(key:byte(i),0x36));outer[i]=string.char(bit.bxor(key:byte(i),0x5c)) end
    local hash=sha1(table.concat(outer)..sha1(table.concat(inner)..msg))
    local offset=bit.band(hash:byte(20),15)+1
    local a,b,c,d=hash:byte(offset,offset+3)
    local number=bit.band(a,127)*16777216+b*65536+c*256+d
    digits=digits or 6
    return string.format('%0'..digits..'d',number%10^digits)
end
return M

    end
