    sources["typography.lua"] = function()
-- One font atlas extension for the workspace and observation HUD.
-- Keep glyph ranges alive until ImGui finishes rebuilding the atlas.
local Typography = {}
Typography.__index = Typography
Typography.sizes = {12,13,14,16,18,20,22,24,28,32,36}

Typography.faces={
    {'Segoe UI','segoeui.ttf','seguisb.ttf'}, {'Arial','arial.ttf','arialbd.ttf'},
    {'Tahoma','tahoma.ttf','tahomabd.ttf'}, {'Verdana','verdana.ttf','verdanab.ttf'},
    {'Calibri','calibri.ttf','calibrib.ttf'}, {'Trebuchet MS','trebuc.ttf','trebucbd.ttf'},
    {'Consolas','consola.ttf','consolab.ttf'}, {'Georgia','georgia.ttf','georgiab.ttf'},
    {'Manrope','Manrope-Regular.ttf','Manrope-Bold.ttf',bundled=true},
    {'Exo 2','Exo2-Regular.ttf','Exo2-Bold.ttf',bundled=true},
    {'IBM Plex Sans','IBMPlexSans-Regular.ttf','IBMPlexSans-Bold.ttf',bundled=true}
}
function Typography:paths(preference)
    local face=Typography.faces[preference] or Typography.faces[1]
    local folder=face.bundled and (self.base..'/fonts') or
        (self.api.getFolderPath and self.api.getFolderPath(0x14))
    local separator=face.bundled and '/' or '\\'
    return folder and (folder..separator..face[2]),folder and (folder..separator..face[3])
end
function Typography:choices()
    if self.choiceLabels then return self.choiceLabels end
    local names={}
    for i,face in ipairs(Typography.faces) do
        local normal=self:paths(i)
        local available=normal and self.api.doesFileExist(normal)
        names[#names+1]=face[1]..(available and '' or ' (резервный)')
    end
    self.choiceLabels=table.concat(names,'\0')..'\0\0'
    return self.choiceLabels
end

function Typography.new(base,api)
    return setmetatable({base=base,api=api,regular={},bold={},cache={},scale=1},Typography)
end

-- Called from BeforeDrawFrame, while the atlas is unlocked. Never call from get().
-- Each bounded face/scale pair is added once; cached fonts share the same context.
function Typography:load(imgui)
    local preference=tonumber(self.preference) or 1
    if not Typography.faces[preference] then preference=1 end
    local scale=tonumber(self.scale) or 1
    if scale~=1 and scale~=1.25 and scale~=1.5 then scale=1 end
    local key=tostring(preference)..':'..tostring(scale)
    if self.loadedKey==key then self.failed,self.failedKey=nil,nil;return true end
    if self.failedEntries and self.failedEntries[key] then
        self.failed,self.failedKey=self.failedEntries[key].error,key
        return false
    end
    local cached=self.cache[key]
    if cached then
        self.regular,self.bold=cached.regular,cached.bold
        self.builder,self.ranges=cached.builder,cached.ranges
        self.loadedPreference,self.loadedScale=preference,scale
        self.loadedKey,self.loaded=key,true
        self.failed,self.failedKey=nil,nil
        return true
    end
    local io = imgui.GetIO()
    if not io or not io.Fonts or not io.Fonts.AddFontFromFileTTF then return false end
    local entry={regular={},bold={}}
    local ok,err = pcall(function()
        -- Keep the native builder/ranges with the cache entry for the atlas lifetime.
        entry.builder = imgui.ImFontAtlasGlyphRangesBuilder()
        entry.builder:AddRanges(io.Fonts:GetGlyphRangesCyrillic())
        entry.builder:AddText('‚„…†‡€‰‹‘’“”•–—™›№←↑→↓')
        entry.ranges = entry.builder:BuildRanges()
        local normal,bold=self:paths(preference)
        if not normal or not self.api.doesFileExist(normal) then normal=self.base..'/fonts/EagleSans.ttf' end
        if not bold or not self.api.doesFileExist(bold) then bold=normal end
        for _,size in ipairs(Typography.sizes) do
            entry.regular[size]=assert(io.Fonts:AddFontFromFileTTF(normal,size*scale,nil,entry.ranges))
            entry.bold[size]=assert(io.Fonts:AddFontFromFileTTF(bold,size*scale,nil,entry.ranges))
        end
        imgui.RebuildFonts()
    end)
    if not ok then
        -- Keep ranges alive even after a partial atlas addition and preserve working fonts.
        self.failedEntries=self.failedEntries or {}
        entry.error=tostring(err)
        self.failedEntries[key]=entry
        self.failed,self.failedKey=tostring(err),key
        return false
    end
    self.cache[key]=entry
    self.regular,self.bold=entry.regular,entry.bold
    self.builder,self.ranges=entry.builder,entry.ranges
    self.loadedPreference,self.loadedScale=preference,scale
    self.loadedKey,self.loaded=key,true
    self.failed,self.failedKey=nil,nil
    return true
end

function Typography:get(size,bold)
    return (bold and self.bold or self.regular)[size]
end

return Typography

    end
    sources["ui_compat.lua"] = function()
-- Adapt Aegis's FFI-backed inputs to the single installed MoonImGui renderer.
-- This module does not load mimgui or create a second rendering context.
return function(imgui, ffi)
    local api = setmetatable({}, {__index = imgui})
    api.new = {
        bool = function(value) return ffi.new('bool[1]', value or false) end,
        int = function(value) return ffi.new('int[1]', value or 0) end,
        char = setmetatable({}, {__index = function(_, size)
            return function() return ffi.new('char[?]', size) end
        end})
    }
    api.Checkbox = function(label, value)
        local ref = imgui.ImBool(value[0])
        local changed = imgui.Checkbox(label, ref)
        value[0] = ref.v
        return changed
    end
    api.InputInt = function(label, value, ...)
        local ref = imgui.ImInt(value[0])
        local changed = imgui.InputInt(label, ref, ...)
        value[0] = ref.v
        return changed
    end
    local buffers = setmetatable({}, {__mode = 'k'})
    api.InputText = function(label, value, capacity, flags)
        local ref = buffers[value]
        local text = ffi.string(value)
        if not ref then ref = imgui.ImBuffer(text, capacity); buffers[value] = ref
        elseif ref.v ~= text then ref.v = text end
        local changed = imgui.InputText(label, ref, flags or 0)
        if changed then
            local result = ref.v:sub(1, capacity - 1)
            ffi.fill(value, capacity, 0)
            ffi.copy(value, result, #result)
        end
        return changed
    end
    api.InputTextWithHint=function(label,hint,value,capacity,flags)
        local changed=api.InputText(label,value,capacity,flags)
        if imgui.IsItemHovered() then imgui.SetTooltip(hint) end
        return changed
    end
    api.Begin=function(title,value,flags)
        if type(value)=='cdata' then
            local ref=imgui.ImBool(value[0]);local result=imgui.Begin(title,ref,flags or 0);value[0]=ref.v;return result
        end
        return imgui.Begin(title,value,flags or 0)
    end
    api.PushIDStr=imgui.PushID
    return api
end

    end
    sources["ui_components.lua"] = function()
-- Measured text shared by the workspace and legacy module controls.
local UI={}
function UI.wrap(g,text,width)
    text=tostring(text or '');width=math.max(1,width or 1)
    local lines={}
    for paragraph in (text..'\n'):gmatch('(.-)\n') do
        local line=''
        for word in paragraph:gmatch('%S+') do
            if line~='' and g.CalcTextSize(line..' '..word).x>width then lines[#lines+1]=line;line='' end
            if g.CalcTextSize(word).x>width then
                for ch in word:gmatch('[%z\1-\127\194-\244][\128-\191]*') do
                    if line~='' and g.CalcTextSize(line..ch).x>width then lines[#lines+1]=line;line='' end
                    line=line..ch
                end
            else line=line=='' and word or line..' '..word end
        end
        lines[#lines+1]=line
    end
    return table.concat(lines,'\n'),#lines
end
function UI.checkbox(g,label,value,scale,width)
    local text,id=label:match('^(.-)(##.*)$')
    text=text or label;id=id or '##'..label
    local wrapped=UI.wrap(g,text,(width or g.GetContentRegionAvailWidth())-40*(scale or 1))
    scale=scale or 1
    local start=g.GetCursorScreenPos()
    local colors=g.GetStyle().Colors
    local track=g.GetColorU32(colors[g.Col.FrameBg])
    local accent=g.GetColorU32(colors[g.Col.CheckMark])
    local knob=g.GetColorU32(colors[g.Col.Text])
    for _,key in ipairs({g.Col.FrameBg,g.Col.FrameBgHovered,g.Col.FrameBgActive,g.Col.CheckMark}) do
        g.PushStyleColor(key,g.ImVec4(0,0,0,0))
    end
    -- Native checkbox keeps focus, keyboard activation, and the whole clickable label.
    local changed=g.Checkbox(wrapped==text and label or wrapped..'###'..label,value)
    g.PopStyleColor(4)
    local draw=g.GetWindowDrawList()
    local top=start.y+7*scale
    draw:AddRectFilled(g.ImVec2(start.x,top),g.ImVec2(start.x+32*scale,top+18*scale),value.v and accent or track,9*scale)
    draw:AddCircleFilled(g.ImVec2(start.x+(value.v and 23 or 9)*scale,top+9*scale),6*scale,knob,16)
    return changed
end
function UI.columns(width,minimum,gap,max)
    return math.max(1,math.min(max or 3,math.floor((width+gap)/(minimum+gap))))
end
return UI

    end
    sources["update_adapter.lua"] = function()
-- Updater I/O. Workers return bytes only; only the app commits a release.
local Adapter = {}
function Adapter.new(rt)
    local api,storage=rt.api,rt.storage
    local settingsPath=storage:path('settings','release.ini')
    local worker,closed
    local function read(path)
        local file=api.io.open(path,'rb')
        if not file then return nil end
        local bytes=file:read('*a'); file:close(); return bytes
    end
    local function write(path,bytes)
        local file,err=api.io.open(path,'wb')
        if not file then return nil,err end
        local ok,why=file:write(bytes)
        local done,closeError=file:close()
        if not ok or not done then return nil,why or closeError end
        return read(path)==bytes,'Written bytes failed verification'
    end
    local function ensure(path)
        if api.doesDirectoryExist(path) then return true end
        local parent=path:match('^(.*)[/\\][^/\\]+$')
        if parent then assert(ensure(parent)) end
        api.createDirectory(path)
        assert(api.doesDirectoryExist(path),'Cannot create resource directory: '..path)
        return true
    end
    return {
        message=function(text) rt:message(text) end,
        drawDependencies=function(g)
            if not rt.dependencies then
                local raw=read(rt.base..'/assets/dependencies.json')
                if not raw then g.TextWrapped('Каталог библиотек отсутствует. Установите полный архив X-Tools.');return end
                local catalog=api.decodeJson(raw)
                local sha=rt:service('sha256.lua')
                rt.dependencies=rt:service('dependencies.lua').new(api,catalog,function(bytes)return sha(bytes,api.wait)end,function(text)rt:message(text)end)
            end
            rt.dependencies:draw(g)
        end,
        read=read, write=write, ensure=ensure,
        remove=function(path) if read(path)==nil then return true end; return api.os.remove(path) end,
        rename=function(from,to) return api.os.rename(from,to) end,
        compile=function(bytes) return loadstring(bytes,'@CasualTool/update-validation') end,
        hash=rt:service('sha256.lua'),
        decode=function(text) return api.decodeJson(text) end,
        loadSettings=function() return storage:loadIni({release={automatic=false}},settingsPath).release end,
        saveSettings=function(values) return storage:saveIni({release=values},settingsPath) end,
        run=function(fn) api.lua_thread.create(function() api.wait(0); if not closed then fn() end end) end,
        yield=function() api.wait(0); assert(not closed,'CasualTool stopped') end,
        cancel=function()
            closed=true
            if worker then pcall(function() worker:cancel() end); worker=nil end
        end,
        reload=function(finished)
            api.lua_thread.create(function()
                api.wait(500)
                if closed then return end
                local ok,result=pcall(function()
                    assert(type(rt.host.reload)=='function','Перезапуск недоступен')
                    return rt.host:reload()
                end)
                if finished then finished(ok and result~=false,ok and 'Перезапуск отклонён' or result) end
            end)
            return 'pending'
        end,
        fetch=function(url,limit)
            assert(not closed,'CasualTool stopped')
            local effil=api.require('effil')
            local transport=string.dump(assert(rt:source('discord_transport.lua')))
            worker=effil.thread(function(code,address,caFile,maxBytes)
                local client=assert(loadstring(code,'@CasualTool/release-https'))()
                return client.get(address,caFile,maxBytes)
            end)(transport,url,rt.base..'/assets/cacert.pem',limit)
            local deadline=api.os.time()+90
            while not closed do
                local state=worker:status()
                if state=='completed' then
                    local ok,status,body,_,err=worker:get()
                    worker=nil
                    assert(ok and status==200,'HTTPS '..tostring(status)..': '..tostring(err or 'download failed'))
                    assert(type(body)=='string' and #body<=limit,'Invalid release response')
                    return body
                end
                if state=='failed' or state=='canceled' or state=='cancelled' or api.os.time()>deadline then
                    pcall(function() worker:cancel() end); worker=nil
                    error('Release download failed or timed out')
                end
                api.wait(50)
            end
            error('CasualTool stopped')
        end
    }
end
return Adapter

    end
    sources["updates.lua"] = function()
-- One release, one transaction. Configuration and user data are never targets.
local Updates = {}
Updates.__index = Updates
local MAX_CODE,MAX_ASSETS,MAX_MANIFEST=8*1024*1024,64*1024*1024,512*1024
local function integer(n,limit) return type(n)=='number' and n>=0 and n<=limit and n==math.floor(n) end
local function digest(s) return type(s)=='string' and #s==64 and s:match('^[0-9a-f]+$') end
local function version(s)
    if type(s)~='string' then return end
    local a,b,c=s:match('^(%d+)%.(%d+)%.(%d+)$')
    if a and #a<=6 and #b<=6 and #c<=6 then return {tonumber(a),tonumber(b),tonumber(c)} end
end
local function newer(candidate,current)
    local a,b=version(candidate),version(current)
    if not a or not b then return false end
    for i=1,3 do if a[i]~=b[i] then return a[i]>b[i] end end
    return false
end
local function safePath(path)
    if type(path)~='string' or #path>180 or not path:match('^[%w_/%.-]+$') then return false end
    if path:sub(1,1)=='/' or path:sub(-1)=='/' or path:find('//',1,true) then return false end
    for part in path:gmatch('[^/]+') do
        if part=='.' or part=='..' or part:sub(-1)=='.' then return false end
        local stem=part:match('^[^.]+')
        if not stem then return false end
        stem=stem:upper()
        if stem=='CON' or stem=='PRN' or stem=='AUX' or stem=='NUL' or stem:match('^COM[1-9]$') or stem:match('^LPT[1-9]$') then return false end
    end
    local extension=path:match('%.([%w]+)$')
    return extension=='png' or extension=='ttf' or extension=='pem' or extension=='json' or extension=='md' or extension=='txt'
end
local function endpoint(url)
    if type(url)~='string' or url:find('..',1,true) then return end
    return url:match('^(https://[%w%.%-]+/[%w%._/%-]*/)[%w_.%-]+%.json$') or
        url:match('^(https://[%w%.%-]+/)[%w_.%-]+%.json$')
end
local function descriptor(file,name,maxBytes)
    assert(type(file)=='table' and file.file==name and digest(file.sha256) and integer(file.bytes,maxBytes) and file.bytes>0,'Invalid release file descriptor')
end
function Updates.validate(manifest,hash)
    assert(type(manifest)=='table' and manifest.schema==1 and manifest.product=='CasualTool' and version(manifest.version),'Invalid CasualTool manifest')
    assert(manifest.packagePath==nil or manifest.packagePath=='versions/'..manifest.version..'/','Invalid release package path')
    descriptor(manifest.script,'X-TOOL.lua',MAX_CODE)
    descriptor(manifest.assets,'assets.pack',MAX_ASSETS)
    local assets=manifest.assets
    assert(digest(assets.id) and type(assets.files)=='table' and #assets.files>0 and #assets.files<=2048,'Invalid resources')
    local seen,offset,identity={},6,{}
    for _,file in ipairs(assets.files) do
        assert(type(file)=='table' and safePath(file.path) and not seen[file.path:lower()],'Invalid or duplicate resource path')
        seen[file.path:lower()]=true
        assert(digest(file.sha256) and integer(file.bytes,MAX_ASSETS) and file.offset==offset,'Invalid resource span')
        offset=offset+file.bytes
        identity[#identity+1]=file.path..'\0'..string.format('%.0f',file.bytes)..'\0'..file.sha256..'\n'
        assert(offset<=assets.bytes,'Resource exceeds pack')
    end
    assert(offset==assets.bytes,'Incomplete resource pack')
    assert(hash(table.concat(identity)..assets.sha256)==assets.id,'Resource identity mismatch')
    return manifest
end
function Updates.new(api,host,release)
    api,host,release=api or {},host or {},release or {}
    local source=release.updateUrl
    if source=='' then source=nil end
    local current=tostring(host.version or '')
    if current:match('^%s*$') then current='не указана' end
    local self=setmetatable({api=api,host=host,version=current,source=source,release=release,
        state=source and 'idle' or 'unconfigured',settings={automatic=false}},Updates)
    if rawget(api,'loadSettings') then self.settings=api.loadSettings() end
    self.backupAvailable=release.bundled and host.path and rawget(api,'read') and api.read(host.path..'.bak')~=nil or false
    return self
end
function Updates:status()
    local titles={unconfigured='Источник обновлений не настроен',idle='Можно проверить обновления',
        checking='Проверка обновлений…',available='Доступна новая версия',current='Установлена актуальная версия',
        installing='Подготовка обновления…',installed='Обновление установлено',error='Обновление не выполнено',
        reload_required='Требуется перезапуск',restored='Предыдущая версия восстановлена',stopped='X-Tools остановлен'}
    return {state=self.state,version=self.version,source=self.source,automatic=self.settings.automatic==true,
        canReload=self.awaitingReload and not self.reloadRunning and not self.stopped,
        canCheck=not self.awaitingReload and not self.busy and not self.stopped and endpoint(self.source)~=nil,
        canInstall=not self.stopped and not self.awaitingReload and self.state=='available' and not self.busy and self.release.bundled==true,
        title=titles[self.state] or self.state,detail=self.detail or (self.source and 'Настройки и журналы сохраняются при обновлении.' or
        'Адрес публикации пока оставлен пустым. Фоновых запросов и скачивания нет.'),
        candidate=self.pending and self.pending.version,
        instructions={'Для первой установки распакуйте полный архив X-Tools в moonloader.',
            'В выпуске один X-TOOL.lua; изображения и шрифты находятся в resource/CasualTool.',
            'При обновлении сохраняются настройки и журналы в config/CasualTool.',
            'Предыдущий Lua-файл сохраняется рядом как X-TOOL.lua.bak; прежние ресурсы сохраняются для отката.'}}
end
function Updates:retryReload()
    if self.stopped or not self.awaitingReload or self.reloadRunning then return false end
    self.reloadRunning=true
    local function finished(ok,err)
        self.reloadRunning=false
        if self.stopped then return end
        self.state='reload_required'
        self.detail='Файлы установлены. Если скрипт не перезапустился, нажмите «Повторить перезапуск».'
        if not ok then self.detail='Файлы установлены, но перезапуск не выполнен: '..tostring(err)..'. Нажмите «Повторить перезапуск».' end
    end
    local ok,result=pcall(function()
        assert(type(rawget(self.api,'reload'))=='function','Перезапуск недоступен')
        return self.api.reload(finished)
    end)
    if not ok then finished(false,result)
    elseif result~='pending' then
        self.reloadRunning=false
        if result==false then finished(false,'Перезапуск отклонён') end
    end
    return ok
end
function Updates:job(state,fn)
    if self.busy or self.stopped or self.awaitingReload then return false end
    self.busy,self.state,self.detail=true,state,nil
    local function run()
        if self.stopped then self.busy=false; return end
        local ok,err=xpcall(fn,function(e) return tostring(e) end)
        self.busy=false
        if not ok and not self.stopped then
            self.state,self.detail='error','Не удалось завершить обновление: '..err
            if rawget(self.api,'message') then self.api.message(self.detail) end
        end
    end
    local ok,err=pcall(self.api.run,run)
    if not ok then self.busy=false; self.state='error'; self.detail=tostring(err) end
    return ok
end
function Updates:check(manual)
    if not self.source then
        if manual~=false and rawget(self.api,'message') then self.api.message('X-Tools '..self.version..': источник обновлений не настроен. Адрес будет добавлен в общую службу.') end
        return self:status()
    end
    if not endpoint(self.source) then self.state='error'; self.detail='Нужен прямой HTTPS-адрес manifest.json.'; return self:status() end
    self:job('checking',function()
        self.pending=nil
        local text=self.api.fetch(self.source,MAX_MANIFEST)
        assert(#text<=MAX_MANIFEST,'Manifest is too large')
        local manifest=Updates.validate(self.api.decode(text),self.api.hash)
        assert(version(self.version),'Installed version is invalid')
        if newer(manifest.version,self.version) then
            self.pending=manifest; self.state='available'
            if manual==false and rawget(self.api,'message') then self.api.message('Доступен X-Tools '..manifest.version..'. Установка: Настройки → Система X-Tools.') end
        else self.state='current' end
    end)
    return self:status()
end
function Updates:start()
    if self.settings.automatic and endpoint(self.source) then self:check(false) end
end
function Updates:stop()
    self.stopped=true
    if rawget(self.api,'cancel') then self.api.cancel() end
    self.state='stopped'
end
function Updates:pause()
    assert(not self.stopped,'CasualTool stopped')
    if rawget(self.api,'yield') then self.api.yield() end
    assert(not self.stopped,'CasualTool stopped')
end
function Updates:verify(bytes,description)
    assert(type(bytes)=='string' and #bytes==description.bytes and self.api.hash(bytes)==description.sha256,'Release integrity check failed')
    return bytes
end
function Updates:write(path,bytes)
    assert(self.api.write(path,bytes),'Cannot write '..path)
    assert(self.api.read(path)==bytes,'Write verification failed: '..path)
end
function Updates:commit(bytes)
    local path=self.host.path
    assert(type(path)=='string' and path:match('[/\\][^/\\]+%.lua$'),'Invalid script path')
    local old=assert(self.api.read(path),'Installed script is missing')
    assert(self.api.compile(old),'Cannot back up invalid installed Lua')
    local nextPath,previous=path..'.update-new',path..'.previous'
    self.cleanupWarning=nil
    local stale=self.api.read(previous)
    if stale~=nil then
        -- A completed commit leaves the same old bytes in .bak and .previous.
        -- Unknown recovery files must never be discarded automatically.
        assert(stale==self.api.read(path..'.bak') and self.api.compile(stale),
            'An interrupted transaction exists; restore the .previous file first')
        assert(self.api.remove(previous) and self.api.read(previous)==nil,
            'Cannot remove completed transaction .previous; close programs locking it and retry')
    end
    self:write(nextPath,bytes)
    self:write(path..'.bak',old)
    self.backupAvailable=true
    self:pause()
    assert(self.api.rename(path,previous),'Cannot preserve installed script')
    -- No yields between removing the old filename and committing/restoring it.
    local ok,reason=pcall(function()
        assert(self.api.rename(nextPath,path),'Cannot install staged script')
        assert(self.api.read(path)==bytes,'Installed script verification failed')
    end)
    if not ok then
        local removed=self.api.read(path)==nil or self.api.remove(path)
        local restored=removed and self.api.rename(previous,path)
        restored=restored and self.api.read(path)==old
        assert(restored,'Commit and rollback failed. Restore '..path..'.bak manually')
        error(reason)
    end
    local cleaned=self.api.remove(previous)
    if not cleaned or self.api.read(previous)~=nil then
        self.cleanupWarning=' Не удалось удалить .previous; резервная копия сохранена. Очистка повторится при следующей установке или откате.'
    end
end
function Updates:install()
    if not self:status().canInstall then return false end
    local manifest=self.pending
    return self:job('installing',function()
        local base=assert(endpoint(self.source))..(manifest.packagePath or '')
        local code=self:verify(self.api.fetch(base..manifest.script.file,manifest.script.bytes),manifest.script)
        assert(code:sub(1,3)~='\27LJ' and self.api.compile(code),'Invalid release Lua')
        assert(code:find('-- CasualTool release: '..manifest.version..'\n',1,true)==1,'Release version mismatch')
        assert(code:find('-- CasualTool assets: '..manifest.assets.id..'\n',1,true),'Resource version mismatch')
        local root=assert(self.host.path:match('^(.*)[/\\]'))..'/resource/CasualTool/'..manifest.assets.id
        local complete=true
        for _,file in ipairs(manifest.assets.files) do
            local bytes=self.api.read(root..'/'..file.path)
            if not bytes or #bytes~=file.bytes or self.api.hash(bytes)~=file.sha256 then complete=false end
            self:pause()
        end
        if not complete then
            local pack=self:verify(self.api.fetch(base..manifest.assets.file,manifest.assets.bytes),manifest.assets)
            assert(pack:sub(1,6)=='CTAS1\n','Invalid resource pack')
            -- Verify every resource before writing the first resource file.
            for _,file in ipairs(manifest.assets.files) do
                self:verify(pack:sub(file.offset+1,file.offset+file.bytes),file); self:pause()
            end
            for _,file in ipairs(manifest.assets.files) do
                local path=root..'/'..file.path
                assert(self.api.ensure(path:match('^(.*)/[^/]+$')))
                self:write(path,pack:sub(file.offset+1,file.offset+file.bytes)); self:pause()
            end
        end
        self:commit(code)
        self.state,self.detail='installed','Установлена версия '..manifest.version..'. X-Tools перезагрузится; настройки сохранены.'
        self.detail=self.detail..(self.cleanupWarning or '')
        self.awaitingReload=true
        self:retryReload()
    end)
end
function Updates:rollback()
    if self.busy or self.stopped or not self.release.bundled then return false end
    return self:job('installing',function()
        local bytes=assert(self.api.read(self.host.path..'.bak'),'No previous release')
        assert(bytes:match('^%-%- CasualTool release: %d+%.%d+%.%d+\n') and self.api.compile(bytes),'Invalid backup')
        self:commit(bytes)
        self.state,self.detail='restored','Предыдущая версия восстановлена. X-Tools перезагрузится.'
        self.detail=self.detail..(self.cleanupWarning or '')
        self.awaitingReload=true
        self:retryReload()
    end)
end
function Updates:draw(g)
    if rawget(self.api,'drawDependencies') then self.api.drawDependencies(g) end
    local state=self:status()
    g.TextWrapped('Версия X-Tools: '..state.version)
    g.TextWrapped(state.title); g.TextWrapped(state.detail)
    if state.candidate then g.TextWrapped('Новая версия: '..state.candidate) end
    if self.source then g.TextWrapped('Источник: '..self.source) end
    if self.source and rawget(self.api,'saveSettings') then
        self.automaticBox=self.automaticBox or g.ImBool(self.settings.automatic==true)
        if g.Checkbox('Проверять обновления при запуске##release_auto',self.automaticBox) then
            local wanted=self.automaticBox.v
            if self.api.saveSettings({automatic=wanted}) then self.settings.automatic=wanted
            else self.automaticBox.v=self.settings.automatic==true end
        end
        g.TextWrapped('Фоновая проверка только сообщает о новой версии. Установка — по кнопке ниже.')
    end
    g.Spacing()
    if g.CollapsingHeader('Установка и восстановление##release_instructions') then
        for i,text in ipairs(state.instructions) do g.TextWrapped(i..'. '..text) end
    end
    if not self.busy and not self.awaitingReload and g.Button('Проверить обновления##casual_updates_status') then self:check(true) end
    if state.canReload and g.Button('Повторить перезапуск##release_retry_reload') then self:retryReload() end
    if state.canInstall and g.Button('Установить и перезагрузить##release_install') then self:install() end
    if self.backupAvailable and not self.busy and not self.awaitingReload and
        g.Button('Вернуть предыдущую версию##release_rollback') then self:rollback() end
end
return Updates

    end
    sources["workspace.lua"] = function()
-- CasualTool workspace. One root window; pages never own a second main window.
local Workspace = {}
local modules = {
    {'core','Основные инструменты','Управление, игровые функции и общие настройки','tools'},
    {'aegis','Автовыдача','Запросы наказаний и защищённые списки','shield'},
    {'adm','Чекер','Администраторы, лидеры и друзья','checker'},
    {'capture','Гетто','Капты, Discord, наказания и контроль аптечек','territory'},
    {'familia','Семьи','Семейные команды и контроль аптечек','family'},
    {'queue','Очередь из файла','Подготовка и отправка наказаний','filequeue'},
    {'bullet','Траектории выстрелов','Свои и чужие выстрелы','target'},
    {'autoreply','Автоответ','Автоматические ответы на обращения по правилам','reply'},
    {'rephelp','Биндер','Редактируемые команды и ответы игрокам','keyboard'},
    {'reminders','Напоминание игрокам в msg','Наборы сообщений для игроков','megaphone'},
    {'joinquit','Входы и выходы','Журнал событий игроков','entry'}
}
Workspace.modules=modules
local function moduleById(id)
    for _,item in ipairs(modules) do if item[1]==id then return item end end
end
local navigation={{'home','Главная','','home'}}
for _,item in ipairs(modules) do navigation[#navigation+1]=item end
Workspace.navigation=navigation
local pages = {
    {'home','Главная','Всё для вашей смены','home'},
    {'core','Инструменты','Телепортация, мероприятия и управление сервером','tools'},
    {'aegis','Наказания','Запросы, проверка и подтверждение','shield'},
    {'adm','Чекер','Администраторы, лидеры и друзья','checker'},
    {'lookup','Проверка игрока','Аккаунт, история ников, IP и блокировки','users','Проверка'},
    {'menu','Наблюдение','Панели игрока и действия в слежке','eye'},
    {'capture','Капты','Ход капта, составы и отчёты','territory'},
    {'familia','Семьи','Информация о семье и семейные наказания','family'},
    {'joinquit','Входы и выходы','Журнал событий игроков','entry'},
    {'statistics','Статистика','Результаты работы администратора','chart'},
    {'settings','Настройки','Все переключатели и параметры CasualTool','settings'},
    {'commands','Справка','Команды, подсказки и ответы на частые вопросы','help'}
}
local tools = {
    {'Телепортация','teleportation_window',3}, {'Мероприятия','event_window',4},
    {'Лидерство и семья','templeader_window',3}, {'Погода сервера','weather_window',4}
}
local helpSections={reminders='reminders',autoreply='autoreply',home='start',core='tools',aegis='punishments',adm='checker',lookup='lookup',
    menu='observation',capture='capture',familia='families',joinquit='events',statistics='start',settings='system',commands='start',modules='start',queue='queue',
    schedule='schedule',online='online',gang='punishments',bullet='observation',stopsbiv='observation',environment='tools',hospital='tools',road='tools',killids='observation'}
local function pageById(id)
    if id=='schedule' then return {'schedule','Расписание мероприятий','Ежедневные события по московскому времени','chart'} end
    local module=moduleById(id)
    if module then return {module[1],module[2],module[3],module[4]} end
    if id=='settings' then return {'settings','Система X-Tools','Общие права, хранение данных и обновления','settings'} end
    for _, p in ipairs(pages) do if p[1] == id then return p end end
    return pages[1]
end

-- A small drawing vocabulary keeps spacing, type and hit areas identical.
local function painter(rt)
    local g, p = rt.imgui, rt.theme.palette
    local origin, draw = g.GetWindowPos(), g.GetWindowDrawList()
    origin=g.ImVec2(origin.x-g.GetScrollX(),origin.y-g.GetScrollY())
    local ui = {}
    local function point(x,y) return g.ImVec2(origin.x+x,origin.y+y) end
    local function color(hex) return g.GetColorU32(rt.theme.color(g,hex)) end
    function ui.rect(x,y,w,h,c,r)
        draw:AddRectFilled(point(x,y),point(x+w,y+h),color(c),r or 8,-1)
    end
    function ui.line(x,y,x2,y2,c,width)
        draw:AddLine(point(x,y),point(x2,y2),color(c),width or 1)
    end
    function ui.font(size,bold)
        local f=rt.typography:get(size,bold)
        if f then g.PushFont(f) end
        return f
    end
    function ui.text(x,y,text,size,c,width,bold)
        local f=ui.font(size or 16,bold)
        text=rt.preferences:mask(tostring(text or ''))
        if width then text=rt:service('ui_components.lua').wrap(g,text,width) end
        local height=g.CalcTextSize(text).y
        g.SetCursorPos(g.ImVec2(x,y))
        g.TextColored(rt.theme.color(g,c or p.text),text)
        if f then g.PopFont() end
        return height
    end
    function ui.measure(text,size,width,bold)
        local f=ui.font(size or 16,bold)
        local value=rt:service('ui_components.lua').wrap(g,rt.preferences:mask(text),width)
        local height=g.CalcTextSize(value).y
        if f then g.PopFont() end
        return height
    end
    function ui.hit(id,x,y,w,h)
        g.SetCursorPos(g.ImVec2(x,y))
        local pressed=g.InvisibleButton(id,g.ImVec2(w,h))
        return pressed,g.IsItemHovered()
    end
    function ui.icon(kind,x,y,c)
        local scale=rt.preferences.data.main.scale or 1
        local function l(a,b,d,e) ui.line(x+a*scale,y+b*scale,x+d*scale,y+e*scale,c,1.6*scale) end
        local function circle(a,b,r)
            draw:AddCircle(point(x+a*scale,y+b*scale),r*scale,color(c),24,1.6*scale)
        end
        if kind=='checker' then
            circle(6,5,3);l(1,15,1,12);l(1,12,4,10);l(4,10,8,10)
            circle(12,12,4);l(15,15,18,18)
        elseif kind=='territory' then
            l(2,17,2,2);l(2,3,9,1);l(9,1,16,4);l(16,4,16,12)
            l(16,12,9,9);l(9,9,2,11);l(9,1,9,9)
        elseif kind=='family' then
            circle(9,4,2.5);circle(3,7,2);circle(15,7,2)
            l(5,17,5,12);l(5,12,7,10);l(7,10,11,10);l(11,10,13,12);l(13,12,13,17)
            l(1,16,1,12);l(1,12,3,11);l(17,16,17,12);l(17,12,15,11)
        elseif kind=='filequeue' then
            l(3,1,11,1);l(11,1,16,6);l(16,6,16,17);l(16,17,3,17);l(3,17,3,1)
            l(11,1,11,6);l(11,6,16,6);l(6,9,12,9);l(6,12,12,12);l(6,15,10,15)
        elseif kind=='target' then
            circle(9,9,6);circle(9,9,2)
            l(9,0,9,4);l(9,14,9,18);l(0,9,4,9);l(14,9,18,9)
        elseif kind=='reply' then
            l(2,2,16,2);l(16,2,16,13);l(16,13,8,13);l(8,13,3,17);l(3,17,3,13);l(3,13,2,13);l(2,13,2,2)
            l(6,7,12,7);l(6,7,9,4);l(6,7,9,10)
        elseif kind=='keyboard' then
            l(1,4,17,4);l(17,4,17,15);l(17,15,1,15);l(1,15,1,4)
            for row=0,1 do for col=0,3 do l(4+col*3,7+row*3,4.5+col*3,7+row*3)end end
            l(6,13,12,13)
        elseif kind=='megaphone' then
            l(2,7,6,7);l(6,7,13,3);l(13,3,13,15);l(13,15,6,11);l(6,11,2,11);l(2,11,2,7)
            l(5,11,6,17);l(6,17,9,17);l(9,17,8,12);l(16,6,18,5);l(16,9,18,9);l(16,12,18,13)
        elseif kind=='entry' then
            l(3,6,3,2);l(3,2,13,2);l(13,2,13,16);l(13,16,3,16);l(3,16,3,12)
            l(0,9,9,9);l(6,6,9,9);l(9,9,6,12);l(16,6,18,9);l(18,9,16,12)
        elseif kind=='home' then
            l(1,8,9,1); l(9,1,17,8); l(4,7,4,17); l(4,17,14,17); l(14,17,14,7); l(8,17,8,11)
        elseif kind=='chart' then
            l(2,17,17,17); l(4,13,4,9); l(9,13,9,3); l(14,13,14,6)
        elseif kind=='shield' then
            l(2,3,9,1); l(9,1,16,3); l(2,3,3,12); l(3,12,9,17); l(9,17,15,12); l(15,12,16,3); l(6,8,8,10); l(8,10,12,6)
        elseif kind=='eye' then
            l(1,9,5,4); l(5,4,13,4); l(13,4,17,9); l(17,9,13,14); l(13,14,5,14); l(5,14,1,9); l(9,7,9,11)
        elseif kind=='users' then
            l(6,2,11,2); l(11,2,11,7); l(11,7,6,7); l(6,7,6,2); l(2,17,2,12); l(2,12,15,12); l(15,12,15,17)
        elseif kind=='settings' then
            for i=0,2 do l(1,3+i*6,17,3+i*6) end
            l(5,1,5,5); l(12,7,12,11); l(7,13,7,17)
        elseif kind=='tools' then
            l(2,2,16,16); l(16,2,2,16); l(11,1,16,1); l(16,1,17,6)
        elseif kind=='help' then
            l(5,4,5,2); l(5,2,13,2); l(13,2,13,7); l(13,7,9,10); l(9,10,9,12); l(9,16,9,17)
        elseif kind=='power' then
            l(9,1,9,9);l(4,4,2,7);l(2,7,2,13);l(2,13,6,17);l(6,17,12,17);l(12,17,16,13);l(16,13,16,7);l(16,7,14,4)
        elseif kind=='save' then
            l(2,2,14,2);l(14,2,17,5);l(17,5,17,17);l(17,17,2,17);l(2,17,2,2)
            l(6,2,6,7);l(6,7,12,7);l(12,7,12,2);l(6,16,6,11);l(6,11,13,11);l(13,11,13,16)
        elseif kind=='motion' then
            l(3,9,15,9);l(9,3,9,15);l(5,5,13,13);l(13,5,5,13)
        else
            for i=0,2 do l(5,3+i*6,17,3+i*6); l(1,3+i*6,2,3+i*6) end
        end
    end
    function ui.chevron(x,y,c)
        ui.line(x,y,x+5,y+5,c,1.7); ui.line(x+5,y+5,x,y+10,c,1.7)
    end
    -- Compact vector adaptation of the Advance RolePlay mark: sharp at HUD
    -- scale, with no opaque favicon tile or extra texture to load.
    function ui.advanceMark(x,y)
        local function vertex(a,b) return point(x+a/8,y+b/8) end
        local function triangle(a,b,c,d,e,f)
            draw:AddTriangleFilled(vertex(a,b),vertex(c,d),vertex(e,f),color(p.text))
        end
        local function arc(first,last,radius)
            local previous
            for i=0,24 do
                local angle=math.rad(first+(last-first)*i/24)
                local current=vertex(104+math.cos(angle)*radius,99+math.sin(angle)*radius)
                if previous then draw:AddLine(previous,current,color(0xF3CB58),1.6) end
                previous=current
            end
        end
        arc(-103,-194,59); arc(124,48,52)
        triangle(123,13,113,64,27,147)
        triangle(113,64,89,101,27,147)
        triangle(123,13,147,125,113,64)
        triangle(147,125,121,129,113,64)
        triangle(67,107,166,79,160,101)
        triangle(67,107,160,101,27,147)
        triangle(134,76,148,62,155,70)
        triangle(134,76,155,70,145,82)
    end
    function ui.image(name,x,y,w,h,radius,tint)
        local art=rt.art:get(name)
        if not art then return end
        local cropW,cropH=1,1
        local target=w/h; local aspect=art.width/art.height
        if aspect>target then cropW=target/aspect else cropH=aspect/target end
        local u0,v0=(1-cropW)/2,(1-cropH)/2
        local function strip(left,top,right,bottom)
            draw:AddImage(art.texture,point(x+left,y+top),point(x+right,y+bottom),
                g.ImVec2(u0+left/w*cropW,v0+top/h*cropH),g.ImVec2(u0+right/w*cropW,v0+bottom/h*cropH),tint or 0xFFFFFFFF)
        end
        local r=math.min(radius or 0,h/2,w/2)
        if r==0 then strip(0,0,w,h); return true end
        strip(0,r,w,h-r)
        for i=0,r-1 do
            local inset=r-math.sqrt(r*r-(r-i-0.5)^2)
            strip(inset,i,w-inset,i+1); strip(inset,h-i-1,w-inset,h-i)
        end
        return true
    end
    function ui.ambient(x,y,w,h,time)
        -- A bounded, non-interactive orbit. No timers, threads or per-frame I/O.
        local tint=rt.theme.color(g,p.accent);tint.w=0.16
        local previous
        for i=0,32 do
            local angle=math.pi*(0.12+i/32*0.83)
            local current=point(x+w*(0.66+0.32*math.cos(angle)),y+h*(0.90-0.23*math.sin(angle)))
            if previous then draw:AddLine(previous,current,g.GetColorU32(tint),1) end
            previous=current
        end
        for i=1,5 do
            local angle=math.pi*(0.12+((time*0.012+i/5)%1)*0.83)
            local pos=point(x+w*(0.66+0.32*math.cos(angle)),y+h*(0.90-0.23*math.sin(angle)))
            tint.w=0.12;draw:AddCircleFilled(pos,5,g.GetColorU32(tint),12)
            tint.w=0.38;draw:AddCircleFilled(pos,1.4,g.GetColorU32(tint),8)
        end
    end
    function ui.avatar(x,y,r)
        rt.avatar:draw(draw,origin.x+x,origin.y+y,r,color(p.surface),color(p.accent))
    end
    function ui.action(id,x,y,w,title,caption,icon,fn)
        local clicked,hover=ui.hit(id,x,y,w,76)
        ui.rect(x,y,w,76,hover and p.hover or p.surface,12)
        ui.rect(x+16,y+20,36,36,p.selection,10)
        ui.icon(icon,x+25,y+29,p.accent)
        ui.text(x+68,y+16,title,18,p.text,w-98,true)
        ui.text(x+68,y+44,caption,14,p.muted,w-86)
        ui.chevron(x+w-25,y+28,p.accent)
        if clicked then fn() end
    end
    function ui.button(id,x,y,w,label,primary,fn)
        local scale=rt.preferences.data.main.scale or 1
        local h=math.max(32*scale,ui.measure(label,16,math.max(1,w-24*scale),true)+16*scale)
        local clicked,hover=ui.hit(id,x,y,w,h)
        ui.rect(x,y,w,h,primary and (hover and p.text or p.accent) or (hover and p.hover or p.button),5*scale)
        ui.text(x+12*scale,y+8*scale,label,16,primary and p.bg or p.text,w-24*scale,true)
        if clicked then fn() end
        return h
    end
    return ui
end

local function keyName(value)
    if type(value)~='string' then return '-' end
    return value:gsub('^VK_',''):gsub('LEFT','Left'):gsub('RIGHT','Right'):gsub('CONTROL','Ctrl'):gsub('MENU','Alt')
end

local function profile(rt)
    local api=rt.api
    local name,id='Игрок',nil
    if api.sampGetPlayerIdByCharHandle and api.PLAYER_PED then
        local ok,value=api.sampGetPlayerIdByCharHandle(api.PLAYER_PED)
        if ok then
            id=value
            if api.sampGetPlayerNickname then name=api.sampGetPlayerNickname(id) or name end
        end
    end
    local connected=api.isSampAvailable and api.isSampAvailable() and api.sampGetGamestate()==3
    return name,id,connected
end

local function dashboard(rt,ui,w,h)
    local p,g=rt.theme.palette,rt.imgui
    local scale=rt.preferences.data.main.scale or 1
    local gap,pad=16*scale,12*scale
    local wide=w>=656*scale
    local leftW=wide and math.floor((w-gap)*0.52) or w
    local rightW=wide and w-leftW-gap or w
    rt.homeSearch=rt.homeSearch or g.ImBuffer(128)
    local controls={}
    for _,item in ipairs(rt.homeControls or {}) do controls[#controls+1]=item end
    for _,item in ipairs({{'streamer','Режим стримера: скрывать IP'},
        {'ghetto','Функции гетто'},{'families','Семейные функции'}}) do
        local key,label=item[1],item[2]
        controls[#controls+1]={label=label,get=function() return rt.preferences.data.main[key] end,
            set=function(value) rt:setFeature(key,value) end}
    end
    local function match(label,query)
        local encoding=rt.api.require('encoding').UTF8
        local function lower(value)
            return tostring(encoding:decode(value)):lower():gsub('['..string.char(192)..'-'..string.char(223)..']',function(ch) return string.char(ch:byte()+32) end):gsub(string.char(168),string.char(184))
        end
        return lower(label):find(lower(query),1,true)~=nil
    end
    local query=tostring(rt.homeSearch.v or ''):match('^%s*(.-)%s*$')
    if query~=''then
        for _,binding in ipairs(rt.keys.order)do
            if match(binding.label,query)then controls[#controls+1]={label=binding.label..' · Горячие клавиши',open=function()rt:openSettings('keys')end}end
        end
        for _,entry in ipairs(rt:service('settings_index.lua'))do
            if match(entry.label..' '..entry.section,query)then
                local target=entry
                controls[#controls+1]={label=entry.label..' · '..entry.section,open=function()
                    rt:open(target.page);rt.moduleMode='settings'
                    if target.tab>0 then rt.coreSettingsTab=target.tab end
                    local tools={autostart=7,tempfamily=3,tpm=1,environment=6}
                    if tools[target.source]then rt.moduleMode='functions';rt.toolPage=tools[target.source]end
                    rt.restoreWorkspaceScroll=0
                end}
            end
        end
    end
    local rows={};local leftH=72*scale
    for _,item in ipairs(controls) do if match(item.label,tostring(rt.homeSearch.v or '')) then
        local rh=math.max(32*scale,ui.measure(item.label,16,leftW-2*pad-40*scale)+12*scale)
        rows[#rows+1]={item=item,height=rh};leftH=leftH+rh+4*scale
    end end
    if #rows==0 then leftH=leftH+48*scale end
    leftH=leftH+44*scale
    ui.rect(0,0,leftW,leftH,p.surface,5*scale)
    ui.text(pad,pad,'ПОЛЕЗНЫЕ ФУНКЦИИ',16,p.accent,leftW-2*pad,true)
    g.SetCursorPos(g.ImVec2(pad,40*scale));g.PushItemWidth(leftW-2*pad-64*scale)
    g.InputText('Поиск##home_search',rt.homeSearch);g.PopItemWidth()
    if g.IsItemHovered() then g.SetTooltip('Найти настройку по названию') end
    local y=76*scale
    for _,row in ipairs(rows) do
        local item=row.item;g.SetCursorPos(g.ImVec2(pad,y))
        if item.open then
            if g.Selectable(rt:service('ui_components.lua').wrap(g,item.label,leftW-2*pad-12*scale)..'##home_result_'..tostring(y),false,0,g.ImVec2(leftW-2*pad,row.height))then item.open()end
        else
            local value=g.ImBool(item.get())
            if rt:service('ui_components.lua').checkbox(g,item.label..'##home',value,scale,leftW-2*pad) then item.set(value.v) end
        end
        y=y+row.height+4*scale
    end
    if #rows==0 then ui.text(pad,y,'Настройки не найдены',16,p.muted,leftW-2*pad);y=y+48*scale end
    ui.button('home_settings',pad,leftH-44*scale,leftW-2*pad,'Все настройки',false,function() rt.page,rt.settingsPage='settings','core' end)
    local rx,ry=wide and leftW+gap or 0,wide and 0 or leftH+gap
    local name,id,connected=profile(rt);name=name:gsub('_',' ')
    local server=connected and (rt.api.sampGetCurrentServerName and rt.api.sampGetCurrentServerName() or 'Advance RolePlay') or 'Нет подключения'
    local nameH=ui.measure(name,18,rightW-116*scale,true)
    local serverH=ui.measure(server,14,rightW-116*scale)
    local profileH=math.max(108*scale,40*scale+nameH+serverH+22*scale)
    ui.rect(rx,ry,rightW,profileH,p.surface,5*scale)
    ui.avatar(rx+48*scale,ry+profileH/2,32*scale)
    local py=ry+pad
    py=py+ui.text(rx+94*scale,py,name,18,p.text,rightW-106*scale,true)+8*scale
    py=py+ui.text(rx+94*scale,py,server,14,p.muted,rightW-106*scale)+6*scale
    ui.text(rx+94*scale,py,id and ('ID '..id..' · Уровень '..tostring(rt.access:level() or '—')) or 'Ожидание входа',14,p.muted,rightW-106*scale)
    ry=ry+profileH+gap
    local schedule=rt:service('schedule.lua');local timestamp=rt.api.os.time()
    local upcoming=rt.schedule:nextEvents(timestamp,true)
    local eventsH=(#upcoming==0 and 120 or 76)*scale
    for i=1,math.min(2,#upcoming) do eventsH=eventsH+ui.measure(upcoming[i].name,16,rightW-2*pad,true)+40*scale end
    ui.rect(rx,ry,rightW,eventsH,p.surface,5*scale)
    ui.text(rx+pad,ry+pad,'БЛИЖАЙШИЕ СОБЫТИЯ · МСК',14,p.accent,rightW-2*pad,true)
    local ey=ry+38*scale
    for i=1,math.min(2,#upcoming) do
        local row=upcoming[i]
        ey=ey+ui.text(rx+pad,ey,row.name,16,p.text,rightW-2*pad,true)+4*scale
        ey=ey+ui.text(rx+pad,ey,row.time..' · '..schedule.countdown(row.seconds),14,p.muted,rightW-2*pad)+16*scale
    end
    if #upcoming==0 then ui.text(rx+pad,ey,'Нет включённых событий',14,p.muted,rightW-2*pad) end
    ui.button('home_schedule',rx+pad,ry+eventsH-44*scale,rightW-2*pad,'Расписание и редактор',false,function() rt:open('schedule') end)
    ry=ry+eventsH+gap
    local keyRows={};local keysH=88*scale
    for _,item in ipairs(rt.keys.order) do
        if #keyRows<4 and rt.keys.data[item.id].key>0 and (not item.active or item.active()) then
            local key=rt.keys:name(item.id)
            local rowH=math.max(32*scale,ui.measure(item.label,14,rightW-148*scale)+12*scale,ui.measure(key,14,100*scale)+12*scale)
            keyRows[#keyRows+1]={key=key,label=item.label,height=rowH};keysH=keysH+rowH+4*scale
        end
    end
    ui.rect(rx,ry,rightW,keysH,p.surface,5*scale)
    ui.text(rx+pad,ry+pad,'ГОРЯЧИЕ КЛАВИШИ',14,p.accent,rightW-2*pad,true)
    local ky=ry+38*scale
    for _,row in ipairs(keyRows) do
        ui.rect(rx+pad,ky,112*scale,row.height,p.button,3*scale)
        ui.text(rx+pad+6*scale,ky+6*scale,row.key,14,p.text,100*scale,true)
        ui.text(rx+136*scale,ky+6*scale,row.label,14,p.text,rightW-148*scale)
        ky=ky+row.height+4*scale
    end
    ui.button('home_keys',rx+pad,ry+keysH-44*scale,rightW-2*pad,'Все горячие клавиши',false,function() rt.page,rt.settingsPage='settings','keys' end)
    local bottom=(wide and leftH or math.max(leftH,ry+keysH))+gap
    local appearanceW=wide and leftW or w
    ui.text(0,bottom,'Оформление',14,p.muted,appearanceW)
    bottom=bottom+26*scale
    for i,color in ipairs(rt.preferences.colors) do
        local x=(i-1)*36*scale
        ui.rect(x,bottom,24*scale,24*scale,color[2],12*scale)
        if rt.preferences.data.main.color==i then
            ui.line(x,bottom+28*scale,x+24*scale,bottom+28*scale,p.text,2*scale)
        end
        local clicked,hover=ui.hit('accent_'..i,x,bottom,28*scale,32*scale)
        if hover then g.SetTooltip(color[1]) end
        if clicked then rt.preferences.data.main.color=i;rt.preferences:save() end
    end
    bottom=bottom+44*scale
    g.SetCursorPos(g.ImVec2(0,bottom));g.PushItemWidth(math.min(180*scale,w-90*scale))
    local font=g.ImInt(rt.preferences.data.main.font-1)
    if g.Combo('Шрифт',font,rt.typography:choices()) then
        rt.preferences.data.main.font=font.v+1;rt.preferences:save()
    end
    g.PopItemWidth();bottom=bottom+44*scale
    g.SetCursorPos(g.ImVec2(0,math.max(bottom,ry+keysH)));g.Dummy(g.ImVec2(1,1))
end

local function drawCore(rt,callback,panel,level)
    local g=rt.imgui
    rt:selectCorePanel(panel)
    if level and not rt.access:can(level) then
        g.TextWrapped(rt.access:level()==nil and 'Уровень администратора пока не подтверждён сервером.' or 'Доступно с '..level..' уровня администратора.')
        return
    end
    rt.embeddedCore=true
    g.PushItemWidth(math.max(160,math.min(360,g.GetContentRegionAvailWidth()-40)))
    local ok,err=xpcall(callback,debug.traceback)
    g.PopItemWidth()
    rt.embeddedCore=false
    if not ok then error(err) end
end

local function modulePage(rt,id,settingsPage)
    local m=rt.modules[id]
    local fn=m and m.bridge and m.bridge[settingsPage and 'drawSettings' or 'draw']
    if m and m.enabled and fn then rt:call(m,fn)
    else
        rt.imgui.TextWrapped('Этот раздел не загрузился. Проверьте состояние: /atmodules.')
        if rt.imgui.Button('Как устранить ошибку##module_help') then rt:openHelp('troubleshooting') end
    end
end

local function tabs(rt,items,value,suffix)
    local g,p=rt.imgui,rt.theme.palette
    local width=g.GetContentRegionAvailWidth()
    local used=0
    for i,item in ipairs(items) do
        local label=item[1]
        local scale=rt.preferences.data.main.scale or 1
        local size=math.min(width,g.CalcTextSize(label).x+24*scale)
        if i>1 and used+size+8<=width then g.SameLine(); used=used+8 else used=0 end
        local active=value==i
        if active then g.PushStyleColor(g.Col.Button,rt.theme.color(g,p.selection)); g.PushStyleColor(g.Col.Text,rt.theme.color(g,p.accent)) end
        if g.Button(label..suffix,g.ImVec2(size,32*scale)) then value=i; g.SetScrollY(0) end
        if active then g.PopStyleColor(2) end
        used=used+size
    end
    g.Spacing()
    return value
end

local function drawModule(rt,callback,spec)
    local g=rt.imgui
    local module=rt.modules[spec[1]]
    if spec[1]=='adm' and module and module.bridge then
        local entries={{'Настройки'},{'Админы'},{'Лидеры'},{'Друзья'}}
        local current=rt.moduleMode=='settings' and 1 or (module.bridge.directoryPage or 2)
        local choice=tabs(rt,entries,current,'##checker_top')
        rt.moduleMode=choice==1 and 'settings' or 'functions'
        if choice>1 then module.bridge.directoryPage=choice end
        module.bridge.externalNavigation=true;modulePage(rt,'adm',choice==1);module.bridge.externalNavigation=false
        return
    end
    if spec[1]=='capture' or spec[1]=='familia' then
        local key=spec[1]=='capture' and 'ghetto' or 'families'
        local enabled=g.ImBool(rt.preferences.data.main[key])
        if g.Checkbox('Включить '..(key=='ghetto' and 'функции гетто' or 'семейные функции'),enabled) then rt:setFeature(key,enabled.v) end
        if not enabled.v then g.TextDisabled('Включите раздел для доступа к его функциям.');return end
    end
    local hasSettings=spec[1]=='core' or spec[1]~='bullet' and module and module.bridge and module.bridge.drawSettings
    local mode=rt.moduleMode=='settings' and hasSettings and 2 or 1
    if hasSettings then mode=tabs(rt,{{'Функции'},{'Настройки'}},mode,'##module_mode') end
    rt.moduleMode=mode==2 and 'settings' or 'functions'
    if spec[1]=='core' then
        if mode==2 then
            rt.coreSettingsTab=tabs(rt,{{'Основные'},{'Клавиши'},{'Игровые функции'},{'Чат'}},rt.coreSettingsTab or 1,'##core_settings')
            _G.selected=rt.coreSettingsTab
            if rt.coreSettingsTab==2 then rt.keys:drawAll(g)
            else
                drawCore(rt,callback,'settings_window')
                g.Separator()
                if rt.coreSettingsTab==1 then
                    rt.clock:draw(g)
                    local roadFollowup=g.ImBool(rt.preferences.data.main.roadFollowup==true)
                    if g.Checkbox('После /tr: подбросить игрока и обновить слежку',roadFollowup) then rt.preferences.data.main.roadFollowup=roadFollowup.v;rt.preferences:save() end
                    local streamer=g.ImBool(rt.preferences.data.main.streamer)
                    if g.Checkbox('Режим стримера: скрывать IP',streamer) then rt.preferences.data.main.streamer=streamer.v;rt.preferences:save() end
                    if g.CollapsingHeader('Чистый онлайн') then modulePage(rt,'online',false);modulePage(rt,'online',true) end
                elseif rt.coreSettingsTab==3 then
                    local lego=g.ImBool(rt.preferences.data.main.legoReplace==true)
                    if g.Checkbox('Заменять /lego автоматически',lego) then rt.preferences.data.main.legoReplace=lego.v;rt.preferences:save() end
                    modulePage(rt,'movement',true);modulePage(rt,'airbreak',true);modulePage(rt,'broom',true);modulePage(rt,'mask_names',true)
                    modulePage(rt,'fisheye',true);modulePage(rt,'fogdist',true)
                    modulePage(rt,'observer_extras',true)
                    modulePage(rt,'speed_boost',true)
                    modulePage(rt,'clickwarp',true)
                    modulePage(rt,'adm_tab',true)
                    local capture=rt.modules.capture
                    if capture and capture.bridge.drawVisualSettings then rt:call(capture,capture.bridge.drawVisualSettings) end
                    modulePage(rt,'menu',true)
                elseif rt.coreSettingsTab==4 then
                    modulePage(rt,'correction',true)
                    local chatN=g.ImBool(rt.preferences.data.main.spectateChatN)
                    if g.Checkbox('Общение в слежке через /n',chatN) then rt.preferences.data.main.spectateChatN=chatN.v;rt.preferences:save() end
                    for _,item in ipairs({{'killidsKiller','ID убийцы в списке убийств'},{'killidsVictim','ID погибшего в списке убийств'}}) do
                        local ids=g.ImBool(rt.preferences.data.main[item[1]])
                        if g.Checkbox(item[2],ids) then rt:setFeature(item[1],ids.v) end
                    end
                end
            end
        else
            local choices={}
            for _,item in ipairs(tools) do choices[#choices+1]=item end
            choices[#choices+1]={'Статистика','statistic_window'}
            choices[#choices+1]={'Локальные время и погода','environment'}
            choices[#choices+1]={'Команды при старте','autostart'}
            choices[#choices+1]={'Варнинги','observer_extras'}
            rt.toolPage=tabs(rt,choices,rt.toolPage or 1,'##tool')
            local item=choices[rt.toolPage]
            if item[2]=='environment' then modulePage(rt,'environment',true)
            elseif item[2]=='observer_extras' then modulePage(rt,'observer_extras',false)
            elseif item[2]=='autostart' then modulePage(rt,'autostart',false)

            else
                if item[2]=='templeader_window' then g.Text('Временное лидерство');g.Separator()end
                drawCore(rt,callback,item[2],item[3])
                if item[2]=='templeader_window' then
                    g.Spacing();g.Separator();g.Text('Временная семья')
                    modulePage(rt,'tempfamily',false)
                end
                if item[2]=='teleportation_window' then modulePage(rt,'tpm',false) end
            end
        end
    elseif module and module.bridge and module.bridge[mode==2 and 'drawSettings' or 'draw'] then
        modulePage(rt,spec[1],mode==2)
        if spec[1]=='capture' or spec[1]=='familia' then
            if spec[1]=='capture' and mode==2 then g.Separator();modulePage(rt,'gang',true) end
            g.Separator()
            local key=spec[1]=='capture' and 'ghetto' or 'families'
            local checked=g.ImBool(rt.preferences.data.main.medkitMode==key)
            if g.Checkbox('Контроль аптечек: '..(key=='ghetto' and 'банды' or 'семьи'),checked) then
                rt.preferences.data.main.medkitMode=checked.v and key or 'none';rt.preferences:save()
                local m=rt.modules.stopsbiv;if m then rt:call(m,m.bridge.onDisconnect) end
            end
            if checked.v then modulePage(rt,'stopsbiv',mode==2) end
        end
    else
        g.TextWrapped(spec[3])
        g.TextDisabled('Этот модуль работает через команды или игровые события.')
    end
end

function Workspace.draw(rt,callback)
    local g,p=rt.imgui,rt.theme.palette
    rt.settingsPage=rt.settingsPage or 'core'
    if rt.page=='statistics' then rt.page,rt.toolPage,rt.moduleMode='core',5,'functions' end
    if rt.page=='settings' and rt.settingsPage~='system' then
        local coreSection={core=1,keys=2,utilities=3,chat=4,menu=3,online=1,environment=1}
        if rt.settingsPage=='gang' or rt.settingsPage=='stopsbiv' then rt.settingsPage=rt.preferences.data.main.medkitMode=='families' and 'familia' or 'capture' end
        if rt.settingsPage=='aegis' or rt.settingsPage=='adm' then rt:openSettings(rt.settingsPage);rt.settingsPage='system' end
        local target=coreSection[rt.settingsPage] and 'core' or rt.settingsPage
        if moduleById(target) then
            rt.page,rt.moduleMode=target,'settings'
            if coreSection[rt.settingsPage] then rt.coreSettingsTab=coreSection[rt.settingsPage] end
        end
    end
    local preferences=rt.preferences.data.main
    local scale=preferences.scale or 1
    local accent=rt.preferences.colors[preferences.color] or rt.preferences.colors[1]
    rt.theme.apply(accent[2])
    local colorCount,varCount=rt.theme.push(g,scale)
    local sw,sh=rt.api.getScreenResolution()
    -- All workspace pages share the home geometry; modules only draw content.
    local defaultHeight=720
    local width=math.min(preferences.windowWidth and preferences.windowWidth>0 and preferences.windowWidth or 1120*scale,sw-24)
    local height=math.min(preferences.windowManual and preferences.windowHeight and preferences.windowHeight>0 and preferences.windowHeight or defaultHeight*scale,sh-32)
    local x=preferences.windowWidth and preferences.windowWidth>0 and preferences.windowX or (sw-width)/2
    local y=preferences.windowHeight and preferences.windowHeight>0 and preferences.windowY or (sh-height)/2
    x=math.max(0,math.min(x or 0,sw-width));y=math.max(0,math.min(y or 0,sh-height))
    local changedScreen=rt.uiScreenW~=sw or rt.uiScreenH~=sh
    local resetGeometry=rt.uiResetGeometry==true
    local condition=(changedScreen or resetGeometry) and g.Cond.Always or g.Cond.FirstUseEver
    g.SetNextWindowSize(g.ImVec2(width,height),condition)
    g.SetNextWindowPos(g.ImVec2(x,y),condition)
    if g.SetNextWindowSizeConstraints then g.SetNextWindowSizeConstraints(g.ImVec2(math.min(sw-24,480*scale),math.min(sh-32,360*scale)),g.ImVec2(sw-24,sh-32)) end
    rt.uiScreenW,rt.uiScreenH=sw,sh
    local flags=g.WindowFlags.NoTitleBar+g.WindowFlags.NoScrollbar+g.WindowFlags.NoScrollWithMouse
    g.Begin('X-Tools###CasualTool##workspace-v4',_G.show_main_window,flags)
    local actual=g.GetWindowSize();width,height=actual.x,actual.y
    if not changedScreen and not resetGeometry and rt.uiActualWidth and
        (math.abs(width-rt.uiActualWidth)>1 or math.abs(height-rt.uiActualHeight)>1) then preferences.windowManual=true end
    rt.uiActualWidth,rt.uiActualHeight=width,height
    rt.uiResetGeometry=false
    local position=g.GetWindowPos()
    local geometry=string.format('%.0f:%.0f:%.0f:%.0f',width,height,position.x,position.y)
    local now=rt.api.os.clock()
    if rt.uiGeometry~=geometry then rt.uiGeometry=geometry;rt.uiGeometryChangedAt=now
    elseif rt.uiSavedGeometry~=geometry and now-(rt.uiGeometryChangedAt or now)>0.5 then
        preferences.windowWidth,preferences.windowHeight=width,height
        preferences.windowX,preferences.windowY=position.x,position.y
        rt.preferences:save();rt.uiSavedGeometry=geometry
    end
    g.SetWindowFontScale(1)
    if not rt.art then rt.art=rt:service('art.lua').new(g,rt.base,rt.api) end
    if not rt.avatar then rt.avatar=rt:service('avatar.lua').new(g,rt.base,_G) end
    local ui=painter(rt);local bodyFont=ui.font(16)
    local compact=preferences.compactSidebar or width<900*scale
    local side=(compact and 60 or 232)*scale
    local page=pageById(rt.page or 'home');rt.page=page[1]
    if preferences.wallpaper~=false then
        local tint=rt.theme.color(g,p.text);tint.w=0.70
        ui.image('xtools-background',side,0,width-side,height,0,g.GetColorU32(tint))
    end
    if preferences.motion~=false then ui.ambient(side,0,width-side,height,now) end
    ui.rect(0,0,side,height,p.sidebar,0);ui.line(side,0,side,height,p.border)
    local logoSize=(compact and 40 or 68)*scale
    if not ui.image('xtools-logo',10*scale,12*scale,logoSize,logoSize,0) then
        ui.rect(12*scale,16*scale,32*scale,32*scale,p.accent,5*scale)
        ui.text(19*scale,20*scale,'X',18,p.bg,28*scale,true)
    end
    if not compact then
        ui.text(86*scale,20*scale,'X-Tools',22,p.text,side-96*scale,true)
        ui.text(86*scale,48*scale,'Casual Alvarez',12,p.muted,side-96*scale)
        ui.text(86*scale,66*scale,'v'..tostring(rt.host.version or ''),12,p.muted,side-96*scale)
    end
    local quickActions={
        {'hide','power',rt.powered==false and 'Включить X-Tools' or 'Выключить X-Tools',function()rt:setPowered(rt.powered==false)end},
        {'save','save','Сохранить оформление',function()
            local saved=rt.preferences:save()
            rt.uiQuickNotice=saved and 'Оформление сохранено' or 'Ошибка сохранения'
            rt.uiQuickNoticeUntil=now+3
        end},
        {'motion','motion','Анимация фона',function() preferences.motion=preferences.motion==false;rt.preferences:save() end},
        {'help','help','Справка',function() rt:openHelp('start') end},
        {'system','settings','Система и обновления',function() rt:open('settings');rt.settingsPage='system' end}
    }
    local quickTop=(compact and 62 or 94)*scale
    for i,item in ipairs(quickActions) do
        local qx=(compact and 16 or 14+(i-1)*42)*scale
        local qy=quickTop+(compact and (i-1)*32*scale or 0)
        local clicked,over=ui.hit('quick_'..item[1],qx,qy,28*scale,28*scale)
        local active=item[1]=='motion' and preferences.motion~=false
        if over or active then ui.rect(qx,qy,28*scale,28*scale,over and p.hover or p.selection,4*scale) end
        ui.icon(item[2],qx+5*scale,qy+5*scale,active and p.accent or p.text)
        if over then g.SetTooltip(item[3]) end
        if clicked then item[4]() end
    end
    local navTop=(compact and 228 or 146)*scale
    if not compact and rt.uiQuickNotice and now<(rt.uiQuickNoticeUntil or 0) then
        ui.text(14*scale,128*scale,rt.uiQuickNotice,12,p.accent,side-28*scale)
    end
    g.SetCursorPos(g.ImVec2(0,navTop))
    g.BeginChild('workspace_navigation',g.ImVec2(side,math.max(40,height-navTop-60*scale)),false)
    local nav=painter(rt)
    local navWidth=math.min(side,g.GetContentRegionAvailWidth())
    local ny=0
    for _,item in ipairs(navigation) do
        local label=item[5] or item[2]
        local rowH=compact and 38*scale or math.max(38*scale,nav.measure(label,16,navWidth-56*scale,true)+16*scale)
        local active=rt.page==item[1] or rt.overlay==item[1] and rt.overlayVisible and rt.overlayVisible.v
        local clicked,hover=nav.hit('nav_'..item[1],6*scale,ny,navWidth-12*scale,rowH)
        if active or hover then nav.rect(6*scale,ny,navWidth-12*scale,rowH,active and p.selection or p.hover,4*scale) end
        if active then nav.rect(6*scale,ny+6*scale,3*scale,rowH-12*scale,p.accent,1) end
        nav.icon(item[4],(compact and 21 or 16)*scale,ny+10*scale,active and p.accent or p.muted)
        if not compact then nav.text(44*scale,ny+8*scale,label,16,active and p.text or p.muted,navWidth-56*scale,active)
        elseif hover then g.SetTooltip(item[2]) end
        if clicked then
            rt:open(item[1]);if item[1]=='settings' then rt.settingsPage='system' end
        end
        ny=ny+rowH+4*scale
    end
    g.SetCursorPos(g.ImVec2(0,ny));g.Dummy(g.ImVec2(1,1))
    g.EndChild()
    ui.button('sidebar_compact',8*scale,height-48*scale,side-16*scale,compact and '>' or '<  Свернуть',false,function()
        preferences.compactSidebar=not preferences.compactSidebar;rt.preferences:save()
    end)
    local bodyX=side+16*scale;local bodyW=width-bodyX-16*scale
    local titleH=ui.text(bodyX,16*scale,page[2],24,p.text,bodyW-78*scale,true)
    local headerH=math.max(60*scale,titleH+32*scale)
    if compact and rt.uiQuickNotice and now<(rt.uiQuickNoticeUntil or 0) then
        local noticeH=ui.text(bodyX,headerH-8*scale,rt.uiQuickNotice,12,p.accent,bodyW)
        headerH=headerH+noticeH+12*scale
    end
    local close,hover=ui.hit('workspace_close',width-40*scale,12*scale,28*scale,28*scale)
    if hover then ui.rect(width-40*scale,12*scale,28*scale,28*scale,p.hover,5*scale) end
    ui.line(width-32*scale,20*scale,width-20*scale,32*scale,p.muted,1.5*scale)
    ui.line(width-20*scale,20*scale,width-32*scale,32*scale,p.muted,1.5*scale)
    if close then
        _G.show_main_window.v=false
        if rt.keys.cancelCapture then rt.keys:cancelCapture() end
    end
    if page[1]~='commands' then
        local help,over=ui.hit('page_help',width-76*scale,12*scale,28*scale,28*scale)
        ui.icon('help',width-70*scale,18*scale,p.muted)
        if over then g.SetTooltip('Справка по разделу') end
        if help then rt:openHelp(helpSections[page[1]]) end
    end
    ui.line(bodyX,headerH-8*scale,width-16*scale,headerH-8*scale,p.border)
    rt:selectCorePanel(nil)
    local currentModule=moduleById(page[1])
    local bodyY=headerH
    g.SetCursorPos(g.ImVec2(bodyX,bodyY))
    g.PushStyleColor(g.Col.ChildWindowBg,g.ImVec4(0,0,0,0))
    local contentId='workspace_page_'..page[1]..'_'..tostring(rt.moduleMode or 'functions')..'_'..tostring(rt.settingsPage)
    local childFlags=page[1]=='commands' and (g.WindowFlags.NoScrollbar+g.WindowFlags.NoScrollWithMouse) or 0
    g.BeginChild(contentId,g.ImVec2(bodyW,height-bodyY-16*scale),false,childFlags)
    if rt.restoreWorkspaceScroll then g.SetScrollY(rt.restoreWorkspaceScroll);rt.restoreWorkspaceScroll=nil end
    rt.workspaceScroll=g.GetScrollY()
    g.PushItemWidth(math.min(300*scale,bodyW*0.48))
    rt.drawingWorkspace=true
    if rt.powered==false then
        g.TextWrapped('X-Tools выключен. Функции, HUD и автоматические команды остановлены.')
    elseif page[1]=='home' then dashboard(rt,painter(rt),math.max(1,bodyW-16*scale),height-bodyY-16*scale)
    elseif currentModule then drawModule(rt,callback,currentModule)
    elseif page[1]=='schedule' then rt:service('schedule_ui.lua').draw(rt)
    elseif page[1]=='settings' then
        g.TextColored(rt.theme.color(g,p.accent),'Оформление')
        local wallpaper=g.ImBool(preferences.wallpaper~=false)
        if g.Checkbox('Фоновое изображение',wallpaper) then preferences.wallpaper=wallpaper.v;rt.preferences:save() end
        local motion=g.ImBool(preferences.motion~=false)
        if g.Checkbox('Анимация фона',motion) then preferences.motion=motion.v;rt.preferences:save() end
        if g.Button('Подобрать размер окна') then preferences.windowManual=false;rt.uiResetGeometry=true;rt.preferences:save() end
        g.Separator();rt:drawSystemSettings()
    elseif page[1]=='commands' then rt:drawHelp() end
    rt.drawingWorkspace=false
    g.PopItemWidth();g.EndChild();g.PopStyleColor()
    if bodyFont then g.PopFont() end
    g.End();rt.theme.pop(g,colorCount,varCount)
end
return Workspace

    end
    return sources
end
