-- Load installed dependencies only. A missing library must never download
-- executable code from a former component author's repository.
function loadCredentialDependencies()
        Lockbox = require("lockbox")
        Lockbox.ALLOW_INSECURE = true -- Compatibility with saved local credentials and statistics.
        String = require("string")
        Array = require("lockbox.util.array")
        Stream = require("lockbox.util.stream")
        ECBMode = require("lockbox.cipher.mode.ecb")
        ZeroPadding = require("lockbox.padding.zero")
        AES128Cipher = require("lockbox.cipher.aes128")
        Queue = require("lockbox.util.queue")
        HMAC = require("lockbox.mac.hmac")
        require("lockbox.digest.sha2_256")
        require("aeslua")
end

function loadCoreDependencies()
    local loaded, err = pcall(function()
        loadCredentialDependencies()

        sampev = integrationRuntime:events("core")
        raknet = require("lib.samp.raknet")
        sampev.onSetPlayerHealth = sampOnSetPlayerHealth
        sampev.onTextDrawSetString = sampOnTextDrawSetString
        sampev.onPlayerDeathNotification = sampOnDeathMessage
        sampev.onChatMessage = sampOnChatMessage
        sampev.onServerMessage = sampOnServerMessage
        sampev.onSendCommand = sampOnSendCommand
        sampev.onShowDialog = sampOnShowDialog
        sampev.onInitMenu = sampevonInitMenu
        sampev.onShowMenu = sampevonShowMenu
        sampev.onHideMenu = sampevonHideMenu
        imgui = integrationRuntime:legacyImgui("core")
        imgui.OnDrawFrame = imguiOnDrawFrame
        apply_custom_style()
    end)
    if not loaded then
        print("[X-Tools dependencies] "..tostring(err))
        integrationRuntime:message("Не удалось загрузить обязательную библиотеку. Проверьте установку X-Tools; подробности — в moonloader.log.")
        return false
    end

    -- Forum and IP lookups need HTTP; the rest of the application can run
    -- while those optional installed libraries are unavailable.
    local networkLoaded, networkError = pcall(function()
        require("requests")
        lanes = require("lanes").configure()
    end)
    if not networkLoaded then
        lanes = nil
        print("[X-Tools HTTP dependencies] "..tostring(networkError))
        integrationRuntime:message("Веб-функции форума и проверки IP недоступны: не загружены requests или lanes. Подробности — в moonloader.log.")
    end
    return true
end

function main()
	integrationRuntime.fastConnect = integrationRuntime:service("fastconnect.lua").start(_G)
	while not isSampAvailable() do
		wait(100)
	end

	if not isSampLoaded() then
		return
	end

	local startupTimeoutSeconds = 15
	local startupStartedAt = os.time()

	while not isSampfuncsLoaded() do
		wait(1000)

		if os.time() > startupStartedAt + startupTimeoutSeconds then
			message(cp1251("{FF0000}Ошибка! Плагин \"SAMPFUNCS\" не найден."))
			print(cp1251("{FF0000}Ошибка! Плагин \"SAMPFUNCS\" не найден."))
			thisScript():unload()
		end
	end

	if not integrationRuntime:serverSupports('core') then
		message(cp1251("X-Tools работает только на Advance RolePlay Blue и Test, порт 7777."))
		thisScript():unload()
		return
	end

	local volumeSerialBuffer = ffi.new("unsigned long[1]", 0)

	ffi.C.GetVolumeInformationA(nil, nil, 0, volumeSerialBuffer, nil, nil, nil, 0)

	pass = checkLen(string.format("%X", volumeSerialBuffer[0]) .. string.char(55, 86, 50, 53, 104, 67, 56, 53))
	pass2 = string.format("%X", volumeSerialBuffer[0]) .. string.char(55, 86, 50, 53, 104, 67, 56, 53)
	pass_stats_ans = checkLen(string.format("%X", volumeSerialBuffer[0]) .. string.char(97, 110, 115, 53, 104, 67, 56, 53))
	pass_stats_mute = checkLen(string.format("%X", volumeSerialBuffer[0]) .. string.char(109, 117, 116, 101, 104, 67, 56, 53))
	pass_stats_kick = checkLen(string.format("%X", volumeSerialBuffer[0]) .. string.char(107, 105, 99, 107, 104, 67, 56, 53))
	pass_stats_skick = checkLen(string.format("%X", volumeSerialBuffer[0]) .. string.char(115, 107, 105, 99, 107, 67, 56, 53))
	pass_stats_jail = checkLen(string.format("%X", volumeSerialBuffer[0]) .. string.char(106, 97, 105, 108, 104, 67, 56, 53))
	pass_stats_warn = checkLen(string.format("%X", volumeSerialBuffer[0]) .. string.char(119, 97, 114, 110, 104, 67, 56, 53))
	pass_stats_ban = checkLen(string.format("%X", volumeSerialBuffer[0]) .. string.char(98, 97, 110, 53, 104, 67, 56, 53))
	pass_stats_seconds = checkLen(string.format("%X", volumeSerialBuffer[0]) .. string.char(115, 101, 99, 53, 104, 67, 56, 53))
	webpass = string.char(55, 86, 50, 53, 104, 67, 56, 53, 68, 54, 50, 110, 54, 57, 70, 98)

    -- Login is available before admin rights; gameplay remains gated below.
    integrationRuntime.loginDialog=function(id,style,title,body)
        if id~=1 or title~='Авторизация' or not integrationRuntime:serverSupports() then return end
        local config=iniConfig.load({auto_login={status=false,password='0'}},corePaths.config).auto_login
        if not config.status then return end
        if body:find('Неверный',1,true) then
            integrationRuntime:message('Не удалось выполнить автоматический вход. Введите пароль вручную.');return
        end
        local ready=pcall(loadCredentialDependencies)
        if not ready then
            integrationRuntime:message('Автовход недоступен: не загружены библиотеки шифрования. Введите пароль вручную.');return
        end
        local envelope=tostring(config.password or '')
        local cipher=envelope:sub(65)
        if #envelope<=64 then return end
        local valid,digest=pcall(getHmac,cipher)
        if not valid or envelope:sub(1,64)~=digest then return end
        local ok,password=pcall(aesDecrypt,pass,cipher)
        if not ok or type(password)~='string' then return end
        password=password:gsub('%z+$','')
        if password=='' or password:find('[%z\1-\31]') then return end
        sampSendDialogResponse(id,1,-1,password)
        return false
    end

    -- Do not apply gameplay patches before this session has confirmed admin rights.
    local accessNoticeShown=false
    while not integrationRuntime.access:can(1) do
        integrationRuntime.access:probeCurrentSession()
        if sampGetGamestate()==3 and not accessNoticeShown then
            integrationRuntime:message('Проверяются права администратора Advance RP.')
            accessNoticeShown=true
        elseif sampGetGamestate()~=3 then accessNoticeShown=false end
        nativeWait(100)
    end

	-- Removed an unversioned legacy patch to samp.dll (0x9D318).



