		if not string.match(currentServerAddress, string.char(49, 56, 53, 46, 49, 54, 57, 46, 49, 51, 52)) then
			message(cp1251("X-Tools предназначен для администраторов Advance-RP."))
			thisScript():unload()
		end

		while isPauseMenuActive() do
			wait(0)

			if cursorEnabled then
				show_Cursor(false)
			end

			local pauseFooterText = string.format("%s %s for ADV-RP by Casual Alvarez ", thisScript().name, thisScript().version)
			local pauseScreenWidth, pauseScreenHeight = getScreenResolution()
			local pauseFooterHeight = renderGetFontDrawHeight(font)
			local pauseFooterWidth = renderGetFontDrawTextLength(font, pauseFooterText)

			renderFontDrawText(font, pauseFooterText, pauseScreenWidth - pauseFooterWidth, pauseScreenHeight - pauseFooterHeight, 2431183080)

		end

		if os.clock() - activity_tick > 2 then
			if activity_tick2 == 0 then
				activity_tick2 = os.clock()
			elseif os.clock() - activity_tick2 > 4 then
				activity_tick = os.clock()
				activity_tick2 = 0
			end
		else
			activity_tick = os.clock()
		end

		if virtualKeys[reconnect_on_key2] ~= 0 then
			if integrationRuntime.keys:pressed('reconnect') and not sampIsChatInputActive() and not sampIsDialogActive() then
				local reconnectServerName = sampGetCurrentServerName()

				message(string.format(cp1251("Переподключение к серверу %s..."), reconnectServerName))

				local reconnectServerAddress, reconnectServerPort = sampGetCurrentServerAddress()

				sampConnectToServer(reconnectServerAddress, reconnectServerPort)
			end
		elseif integrationRuntime.keys:pressed('reconnect') and not sampIsChatInputActive() and not sampIsDialogActive() then
			local reconnectServerName = sampGetCurrentServerName()

			message(string.format(cp1251("Переподключение к серверу %s..."), reconnectServerName))

			local reconnectServerAddress, reconnectServerPort = sampGetCurrentServerAddress()

