					local cursorRayHit, cursorRayCollision = processLineOfSight(cursorRayOriginX, cursorRayOriginY, cursorRayOriginZ, cursorRayEndX, cursorRayEndY, cursorRayEndZ, true, true, false, true, false, false, false, false)

					if cursorRayHit and cursorRayCollision.entity ~= 0 then
