function sampOnDeathMessage(killerPlayerId, victimPlayerId, _)
	if sampIsPlayerConnected(killerPlayerId) and sampIsPlayerConnected(victimPlayerId) and capture_active then
		local victimNickname = sampGetPlayerNickname(victimPlayerId)
		local killerNickname = sampGetPlayerNickname(killerPlayerId)
		local victimAlreadyKilled = false

		for _, killedNickname in ipairs(killedOnCapture) do
			if string.lower(victimNickname) == string.lower(killedNickname) then
				victimAlreadyKilled = true

				message(string.format(cp1251("%s[%d] - был убит ранее (подозрение на RK)."), victimNickname, victimPlayerId))

				break
			elseif string.lower(killerNickname) == string.lower(killedNickname) then
				message(string.format(cp1251("%s[%d] - был убит ранее и совершил убийство (подозрение на RK)."), killerNickname, killerPlayerId))

				break
			end
		end

		if victimAlreadyKilled == false then
			table.insert(killedOnCapture, victimNickname)
		end

		if doesFileExist(corePaths.kills) then
			if gangs == nil then
				gangs = "-"
			end

			local captureKillLogLine = string.format(cp1251("[%s] %s\t| %s убил %s.\n"), integrationRuntime.clock:date("%d.%m.%Y %H:%M:%S"), gangs, killerNickname, victimNickname)
			local captureKillsFile = io.open(corePaths.kills, "a")

			captureKillsFile:write(captureKillLogLine)
			io.close(captureKillsFile)
		end

		local captureDeathsFile = io.open(corePaths.captureDeaths, "a")

		if captureDeathsFile then
			captureDeathsFile:write(string.format(cp1251("[%s] %s[%d] убил(а) %s[%d].\n"), integrationRuntime.clock:date("%H:%M:%S"), killerNickname, killerPlayerId, victimNickname, victimPlayerId))
			io.close(captureDeathsFile)
		end
	end
end

