function forum()
	if not check_forum_in_progress then
		check_forum_in_progress = true
		text = cp1251("Загрузка последних тем форума...")

		message(text)

		local forumSectionId
		local currentServerName = sampGetCurrentServerName()

		if string.match(currentServerName, "Green") then
			forumSectionId = 58
			currentServerName = "Green"
		elseif string.match(currentServerName, "Yellow") then
			forumSectionId = 102
			currentServerName = "Yellow"
		elseif string.match(currentServerName, "Orange") then
			forumSectionId = 159
			currentServerName = "Orange"
		elseif string.match(currentServerName, "Blue") then
			forumSectionId = 213
			currentServerName = "Blue"
		elseif string.match(currentServerName, "White") then
			forumSectionId = 260
			currentServerName = "White"
		elseif string.match(currentServerName, "Silver") then
			forumSectionId = 304
			currentServerName = "Silver"
		elseif string.match(currentServerName, "Purple") then
			forumSectionId = 391
			currentServerName = "Purple"
		elseif string.match(currentServerName, "Chocolate") then
			forumSectionId = 460

		else
			forumSectionId = 15

		end

		async_http_request("GET", string.format(cp1251("https://forum.advance-rp.ru/forums/Жалобы-на-администрацию.%d/index.rss"), forumSectionId), nil, function(forumResponse)
			forumTitle = {}
			forumCreator = {}
			forumComments = {}

			local rssBody = forumResponse.text
			local channelTitleOpenStart, channelTitleOpenEnd = string.find(rssBody, "<title>")

			if channelTitleOpenStart and channelTitleOpenEnd then
				local channelTitleCloseStart, channelTitleCloseEnd = string.find(rssBody, "</title>")

				rssBody = string.sub(rssBody, channelTitleCloseEnd, #rssBody)
			end

			repeat
				local topicTitleOpenStart, topicTitleOpenEnd = string.find(rssBody, "<title>")

				if topicTitleOpenStart and topicTitleOpenEnd then
					local topicTitleCloseStart, topicTitleCloseEnd = string.find(rssBody, "</title>")
					local topicTitle = string.sub(rssBody, topicTitleOpenEnd + 1, topicTitleCloseStart - 1)

					rssBody = string.sub(rssBody, topicTitleCloseEnd, #rssBody)

					table.insert(forumTitle, topicTitle)
				end

				local creatorOpenStart, creatorOpenEnd = string.find(rssBody, "<dc:creator>")

				if creatorOpenStart and creatorOpenEnd then
					local creatorCloseStart, creatorCloseEnd = string.find(rssBody, "</dc:creator>")
					local topicCreator = string.sub(rssBody, creatorOpenEnd + 1, creatorCloseStart - 1)

					rssBody = string.sub(rssBody, creatorCloseEnd, #rssBody)

					table.insert(forumCreator, topicCreator)
				end

				local commentsOpenStart, commentsOpenEnd = string.find(rssBody, "<slash:comments>")
				local commentsValueStart = commentsOpenEnd

				if commentsOpenStart and commentsValueStart then
					local commentsCloseStart, commentsCloseEnd = string.find(rssBody, "</slash:comments>")
					local topicCommentCount = string.sub(rssBody, commentsValueStart + 1, commentsCloseStart - 1)

					rssBody = string.sub(rssBody, commentsCloseEnd, #rssBody)

					table.insert(forumComments, topicCommentCount)
				end

				if not string.find(rssBody, "<slash:comments>") and not string.find(rssBody, "<dc:creator>") and not string.find(rssBody, "<title>") then
					break
				end
			until false

			check_forum_in_progress = false
			forum_window.v = not forum_window.v
		end, function(forumRequestError)
			print(forumRequestError)
			message(cp1251("Ошибка: ") .. forumRequestError)

			check_forum_in_progress = false
		end)
	end
end

function utf8toansi(utf8Text)
	local wideCharacterBuffer = ffi.new("wchar_t[?]", 1024)
	local ansiBuffer = ffi.new("char[?]", 1024)
	local usedDefaultCharacterBuffer = ffi.new("int[?]", 1)

	ffi.C.MultiByteToWideChar(65001, 0, utf8Text, #utf8Text, wideCharacterBuffer, 1024)
	ffi.C.WideCharToMultiByte(1251, 0, wideCharacterBuffer, -1, ansiBuffer, 1024, nil, usedDefaultCharacterBuffer)

	return ffi.string(ansiBuffer)
end

function getcar(vehicleIdInput)
	if string.match(vehicleIdInput, "%d") then
		local _, vehicleHandle = sampGetCarHandleBySampVehicleId(vehicleIdInput)

		if doesVehicleExist(vehicleHandle) then

			if getDriverOfCar(vehicleHandle) == -1 then
				local playerX, playerY, playerZ = getCharCoordinates(PLAYER_PED)

				sampSendEnterVehicle(vehicleIdInput, false)
				warpCharIntoCar(PLAYER_PED, vehicleHandle)
				restoreCameraJumpcut()
				setCarCoordinates(vehicleHandle, playerX, playerY, playerZ)
			else
