	setTextScale(0.33, 0.8)
	setTextDropshadow(0, 0, 0, 0, 0)
	setTextColour(255, 255, 255, 230)
	setTextEdge(1, 0, 0, 0, 100)
	setTextFont(1)
	displayText(labelX, labelY, vehicleNameLabel)
end

function createPointMarker(markerX, markerY, markerZ)
	pointMarker = createUser3dMarker(markerX, markerY, markerZ + 0.3, 4)
end

function removePointMarker()
	if pointMarker then
		removeUser3dMarker(pointMarker)

		pointMarker = nil
	end
end

function getCarFreeSeat(vehicleHandle)
	if doesCharExist(getDriverOfCar(vehicleHandle)) then
		local passengerSeatCount = getMaximumNumberOfPassengers(vehicleHandle)

		for passengerSeatIndex = 0, passengerSeatCount do
			if isCarPassengerSeatFree(vehicleHandle, passengerSeatIndex) then
				return passengerSeatIndex + 1
			end
		end

		return nil
	else
		return 0
	end
end

function jumpIntoCar(vehicleHandle)
	local availableSeat = getCarFreeSeat(vehicleHandle)

	if not availableSeat then
		return false
	end

	if availableSeat == 0 then
		warpCharIntoCar(PLAYER_PED, vehicleHandle)
	else
		warpCharIntoCarAsPassenger(PLAYER_PED, vehicleHandle, availableSeat - 1)
	end

	restoreCameraJumpcut()

	return true
end

function teleportPlayer(destinationX, destinationY, destinationZ)
	if isCharInAnyCar(PLAYER_PED) then
		setCharCoordinates(PLAYER_PED, destinationX, destinationY, destinationZ)
	end

	setCharCoordinatesDontResetAnim(PLAYER_PED, destinationX, destinationY, destinationZ)
end

function setCharCoordinatesDontResetAnim(characterHandle, destinationX, destinationY, destinationZ)
	if doesCharExist(characterHandle) then
		local characterAddress = getCharPointer(characterHandle)

		setEntityCoordinates(characterAddress, destinationX, destinationY, destinationZ)
	end
end

function setEntityCoordinates(entityAddress, destinationX, destinationY, destinationZ)
	if entityAddress ~= 0 then
		local entityMatrixAddress = readMemory(entityAddress + 20, 4, false)

		if entityMatrixAddress ~= 0 then
			local positionAddress = entityMatrixAddress + 48

			writeMemory(positionAddress + 0, 4, representFloatAsInt(destinationX), false)
			writeMemory(positionAddress + 4, 4, representFloatAsInt(destinationY), false)
			writeMemory(positionAddress + 8, 4, representFloatAsInt(destinationZ), false)
		end
	end
end

