function imguiOnDrawFrame()

	if not sampIsChatInputActive() then

		if show_main_window.v or (integrationRuntime.overlayVisible and integrationRuntime.overlayVisible.v) then
			integrationRuntime:drawMain(function()

			if statistic_window.v then
				local statisticsScreenWidth, statisticsScreenHeight = getScreenResolution()

				imgui.SetNextWindowPos(imgui.ImVec2(statisticsScreenWidth / 2, statisticsScreenHeight / 2), imgui.Cond.FirstUseEver, imgui.ImVec2(0.5, 0.5))
				imgui.SetNextWindowSize(imgui.ImVec2(330, 290), imgui.Cond.FirstUseEver)
				imgui.Begin("Статистика", statistic_window, imgui.WindowFlags.AlwaysAutoResize)

				local sessionTotalSeconds = math.floor(gameClock())
				local sessionDays = math.floor(sessionTotalSeconds / 86400)
				local sessionDayRemainder = sessionTotalSeconds - sessionDays * 86400
				local sessionHours = math.floor(sessionDayRemainder / 3600)
				local sessionHourRemainder = sessionDayRemainder - sessionHours * 3600
				local sessionMinutes = math.floor(sessionHourRemainder / 60)
				local sessionSeconds = sessionHourRemainder - sessionMinutes * 60

				if seconds_all then
					seconds_all2 = seconds_all + math.floor(gameClock())
					days_all = math.floor(seconds_all2 / 86400)
					seconds_all2 = seconds_all2 - days_all * 86400
					hours_all = math.floor(seconds_all2 / 3600)
