function event_msg_thread()
	mp_processing = true

	for _, announcementLineText in ipairs(eventsMass2) do
		sampSendChat("/msg 0 " .. announcementLineText)
		wait(2000)
	end

	mp_processing = false
end

function ShowHelpMarker(tooltipBody)
	imgui.TextDisabled("(?)")

	if imgui.IsItemHovered() then
		imgui.BeginTooltip()
		imgui.PushTextWrapPos(450)
		imgui.TextUnformatted(tooltipBody)
		imgui.PopTextWrapPos()
		imgui.EndTooltip()
	end
end

function setKeyThread(bindingKeyCount)
	wait(0)

	setKeyButtonLock = true

	message(cp1251("Нажмите клавишу, которую нужно назначить."))

	repeat
		wait(0)

		for primaryKeyCode = 0, 222 do
			if isKeyJustPressed(primaryKeyCode) then
				key1 = primaryKeyCode

				break
			end
		end
	until isKeyJustPressed(key1)

	key1 = virtualKeyNames[string.format("k0x%X", key1)]

	if bindingKeyCount == 2 then
		message(cp1251("Нажмите вторую клавишу сочетания."))
		wait(200)

		repeat
			wait(0)

			for secondaryKeyCode = 0, 222 do
				if isKeyJustPressed(secondaryKeyCode) then
					key2 = secondaryKeyCode

					break
				end
			end
		until isKeyJustPressed(key2)

		key2 = virtualKeyNames[string.format("k0x%X", key2)]
	else
		key2 = 0
	end

	local keyBindingsConfig = iniConfig.load(data, corePaths.config)

	if key_selected == 1 then
		keyBindingsConfig.menus.main_menu_key = key1
		main_menu_key = key1
	elseif key_selected == 2 then
		keyBindingsConfig.reconnect.reconnect_on_key1 = key1
		keyBindingsConfig.reconnect.reconnect_on_key2 = key2
		reconnect_on_key1 = key1
		reconnect_on_key2 = key2
	elseif key_selected == 3 then
		keyBindingsConfig.cheats.wh_on_key1 = key1
		keyBindingsConfig.cheats.wh_on_key2 = key2
		wh_on_key1 = key1
		wh_on_key2 = key2
	elseif key_selected == 4 then
		keyBindingsConfig.cheats.gm_on_key1 = key1
		keyBindingsConfig.cheats.gm_on_key2 = key2
		gm_on_key1 = key1
		gm_on_key2 = key2
	elseif key_selected == 5 then
		keyBindingsConfig.cheats.ab_on_key1 = key1
		keyBindingsConfig.cheats.ab_on_key2 = key2
		ab_on_key1 = key1
		ab_on_key2 = key2
	elseif key_selected == 6 then
		keyBindingsConfig.player_info_panel.prev_id_key = key1
		sp_prev_id_key = key1
	elseif key_selected == 7 then
		keyBindingsConfig.player_info_panel.next_id_key = key1
		sp_next_id_key = key1
	end

	iniConfig.save(keyBindingsConfig, corePaths.config)

	setKeyButtonLock = false
end

function update_player_ping(pingSampleMs)
	if ping_list[1] then
		local pingHistory = ping_list[1]

		if os.clock() > pingHistory.update_tick + 0.3 then
			if pingSampleMs > pingHistory.max then
				pingHistory.max = pingSampleMs
			end

			table.insert(pingHistory.chart, pingSampleMs)

			if #pingHistory.chart > 150 then
				table.remove(pingHistory.chart, 1)
			end

			pingHistory.update_tick = os.clock()
		end

		return pingHistory
	else
		local initialPingHistory = {
			chart = {
				pingSampleMs
			},
			max = pingSampleMs,
			update_tick = os.clock()
		}

		ping_list[1] = initialPingHistory

		return initialPingHistory
	end
end

function draw_ping_chart(chartPlayerId)
	imgui.GetStyle().WindowRounding = 5

	local pingStyleColors = imgui.GetStyle().Colors
	local pingColorIds = imgui.Col
	local pingColorValue = imgui.ImVec4

	pingStyleColors[pingColorIds.FrameBg] = pingColorValue(0.12, 0.12, 0.12, 0.94)
	pingStyleColors[pingColorIds.PlotLines] = pingColorValue(0.61, 0.61, 0.61, 1)

	local playerPingMs = sampGetPlayerPing(chartPlayerId)
	local pingWindowFlags = imgui.WindowFlags

	imgui.SetMouseCursor(imgui.MouseCursor.None)
	imgui.Begin("Ping Chart", nil, pingWindowFlags.NoTitleBar + pingWindowFlags.NoResize + pingWindowFlags.AlwaysAutoResize + pingWindowFlags.NoMove + pingWindowFlags.NoSavedSettings + pingWindowFlags.NoInputs)

	local chartHistory = update_player_ping(playerPingMs)

	imgui.PlotLines("##Ping", chartHistory.chart, 0, "ping: " .. playerPingMs .. " max: " .. chartHistory.max, 0, chartHistory.max * 2, imgui.ImVec2(200, 40))
	imgui.End()
end

