function getevents()
	local eventDefinitionsFile = io.open(corePaths.events, "r")

	if eventDefinitionsFile then
		local eventDefinitionsJson = eventDefinitionsFile:read("*a")

		io.close(eventDefinitionsFile)

		eventsMass = decodeJson(eventDefinitionsJson)
		eventsNameMass = {}

		for eventDefinitionIndex, _ in pairs(eventsMass.events) do
			table.insert(eventsNameMass, u8(eventsMass.events[eventDefinitionIndex].name))
		end
	end
end

function async_http_request(httpMethod, httpUrl, httpOptions, onHttpSuccess, onHttpFailure)
    if not lanes then
        if onHttpFailure then onHttpFailure("HTTP libraries requests/lanes are unavailable") end
        return
    end
	local requestWorkerFactory = lanes.gen("*", {
		package = {
			path = package.path,
			cpath = package.cpath
		}
	}, function()
		local workerRequests = require("requests")
		local httpRequestOk, httpResponseOrError = pcall(workerRequests.request, httpMethod, httpUrl, httpOptions)

		if httpRequestOk then
			httpResponseOrError.json, httpResponseOrError.xml = nil

			return true, httpResponseOrError
		else
			return false, httpResponseOrError
		end
	end)

	onHttpFailure = onHttpFailure or function()
		return
	end

	lua_thread.create(function()
		local requestWorker = requestWorkerFactory()

		while true do
			local requestWorkerStatus = requestWorker.status

			if requestWorkerStatus == "done" then
				local requestSucceeded = requestWorker[1]
				local requestResult = requestWorker[2]

				if requestSucceeded then
					onHttpSuccess(requestResult)
				else
					onHttpFailure(requestResult)
				end

				return
			elseif requestWorkerStatus == "error" then
				return onHttpFailure(requestWorker[1])
			elseif requestWorkerStatus == "killed" or requestWorkerStatus == "cancelled" then
				return onHttpFailure(requestWorkerStatus)
			end

			wait(0)
		end
	end)
end

function rk(capturePlayerId)
	if capturePlayerId ~= "" then
		if sampIsPlayerConnected(capturePlayerId) then
			local capturePlayerNickname = sampGetPlayerNickname(capturePlayerId)
			local wasKilledInCapture = false

			for _, killedNickname in ipairs(killedOnCapture) do
				if string.lower(capturePlayerNickname) == string.lower(killedNickname) then
					wasKilledInCapture = true

					message(capturePlayerNickname .. cp1251(" был убит ранее."))

					break
				end
			end

			if wasKilledInCapture == false then
				message(cp1251("Игрок не найден в списке погибших капта."))
			end
		else
			message(cp1251("Игрок с этим ID не подключён."))
		end
	else
		message(cp1251("Формат: /rk ID."))
	end
end

function aesEncrypt(cipherKey, plaintextValue)
	local encryptor = ECBMode.Cipher()

	encryptor.setKey(Stream.toArray(Stream.fromString(cipherKey)))
	encryptor.setBlockCipher(AES128Cipher)
	encryptor.setPadding(ZeroPadding)
	encryptor.init()
	encryptor.update(Stream.fromString("passed" .. plaintextValue))
	encryptor.finish()

	return string.lower(encryptor.asHex())
end

function aesDecrypt(decipherKey, cipherPayload)
	local decryptor = ECBMode.Decipher()

	decryptor.setKey(Stream.toArray(Stream.fromString(decipherKey)))
	decryptor.setBlockCipher(AES128Cipher)
	decryptor.setPadding(ZeroPadding)
	decryptor.init()
	decryptor.update(Stream.fromHex(cipherPayload))
	decryptor.finish()

	cipherPayload = string.char(unpack(decryptor.asBytes()))

	if string.sub(cipherPayload, 1, 6) == "passed" then
		return string.sub(cipherPayload, 7)
	else
		return cipherPayload
	end
end

function getHmac(hmacInput)
	local hmacContext = require("lockbox.mac.hmac")()
	local sha256Digest = require("lockbox.digest.sha2_256")

	hmacContext.setBlockSize(64)
	hmacContext.setDigest(sha256Digest)
	hmacContext.setKey(Stream.toArray(Stream.fromString(webpass)))
	hmacContext.init()
	hmacContext.update(Stream.fromString(hmacInput))
	hmacContext.finish()

	return string.lower(hmacContext.asHex())
end

function strpad(padInput, targetLength, padString, padDirection)
	local paddedText = padInput

	padString = padString or "0"
	padDirection = padDirection or "STR_PAD_RIGHT"

	if padDirection == "STR_PAD_BOTH" then
		local padIteration = 0

		while targetLength > string.len(paddedText) do
			paddedText = padIteration % 2 == 0 and paddedText .. padString or padString .. paddedText
			padIteration = padIteration + 1
		end
	else
		while targetLength > string.len(paddedText) do
			paddedText = padDirection == "STR_PAD_LEFT" and padString .. paddedText or paddedText .. padString
		end
	end

	return paddedText
end

function checkLen(aesKeyMaterial)
	if string.len(aesKeyMaterial) < 16 then
		return strpad(aesKeyMaterial, 16)
	elseif string.len(aesKeyMaterial) > 16 then
		return string.sub(aesKeyMaterial, 1, 16)
	else
		return aesKeyMaterial
	end
end
